function getChartTimeframeSeconds() {
  return Number(candleBuilder?.timeframe || DEFAULT_TIMEFRAME_SEC || 60);
}

function getMtfTimeframeSet(baseSeconds = getChartTimeframeSeconds()) {
  const sourceSeconds = Math.max(1, Number(baseSeconds) || DEFAULT_TIMEFRAME_SEC);
  const majorFrames = [10, 30, 60, 300, 900, 3600, 14400, 86400];
  const higher = majorFrames.filter((seconds) => seconds > sourceSeconds);
  const alignSeconds = higher[0] || Math.max(sourceSeconds * 4, sourceSeconds + 1);
  const mainSeconds = higher[1] || Math.max(alignSeconds * 4, alignSeconds + 1);
  return {
    sourceSeconds,
    entrySeconds: sourceSeconds,
    alignSeconds,
    mainSeconds,
    entryLabel: getTimeframeLabel(sourceSeconds),
    alignLabel: getTimeframeLabel(alignSeconds),
    mainLabel: getTimeframeLabel(mainSeconds),
  };
}

function getMtfFrameLabel(seconds) {
  return getTimeframeLabel(seconds).toUpperCase();
}

function getMtfSourceLabel(source) {
  return String(source || "--")
    .split("+")
    .map((part) => part.trim().toUpperCase())
    .filter(Boolean)
    .join("+") || "--";
}

function snapChartTime(timeSec) {
  const tf = Math.max(1, getChartTimeframeSeconds());
  return Math.round(Number(timeSec || 0) / tf) * tf;
}

function getChartPriceForY(y, viewport = chartViewportState) {
  if (!viewport) return null;
  const localY = clamp(y, viewport.topPad, viewport.height - viewport.bottomPad);
  return viewport.max - ((localY - viewport.topPad) / Math.max(1, viewport.plotH)) * (viewport.max - viewport.min);
}

function getChartTimeForX(x, viewport = chartViewportState) {
  if (!viewport?.points?.length) return null;
  const firstTime = viewport.points[0]?.time;
  if (!Number.isFinite(firstTime)) return null;
  const tf = getChartTimeframeSeconds();
  const localX = clamp(x, viewport.leftPad, viewport.width - viewport.rightPad);
  const slotFloat = (localX - viewport.leftPad) / Math.max(1, viewport.slotW);
  return snapChartTime(firstTime + (slotFloat * tf));
}

function getChartXForTime(timeSec, viewport = chartViewportState) {
  if (!viewport?.points?.length || !Number.isFinite(timeSec)) return null;
  const firstTime = viewport.points[0]?.time;
  if (!Number.isFinite(firstTime)) return null;
  const tf = getChartTimeframeSeconds();
  const slotIndex = (timeSec - firstTime) / Math.max(1, tf);
  return viewport.leftPad + (slotIndex * viewport.slotW) + (viewport.slotW / 2);
}

function pointToSegmentDistance(px, py, x1, y1, x2, y2) {
  const dx = x2 - x1;
  const dy = y2 - y1;
  if (dx === 0 && dy === 0) return Math.hypot(px - x1, py - y1);
  const t = clamp((((px - x1) * dx) + ((py - y1) * dy)) / ((dx * dx) + (dy * dy)), 0, 1);
  const projX = x1 + (t * dx);
  const projY = y1 + (t * dy);
  return Math.hypot(px - projX, py - projY);
}

function getChartPlotBounds(viewport = chartViewportState) {
  if (!viewport) return null;
  return {
    left: viewport.leftPad,
    right: viewport.width - viewport.rightPad,
    top: viewport.topPad,
    bottom: viewport.height - viewport.bottomPad,
  };
}

function toFiniteNumber(value) {
  const num = Number(value);
  return Number.isFinite(num) ? num : null;
}

function getTradeMarkerSymbol(contract, fallbackSymbol) {
  return contract?.underlying_symbol
    || contract?.underlying
    || contract?.symbol
    || fallbackSymbol
    || currentSymbol
    || null;
}

function scheduleTradeMarkerRedraw(delayMs = 10100) {
  clearTimeout(tradeChartMarkerRedrawTimer);
  tradeChartMarkerRedrawTimer = setTimeout(() => {
    tradeChartMarkerRedrawTimer = null;
    renderMiniChart(getBuiltCandles());
  }, delayMs);
}

function upsertTradeChartMarkerFromBuy({ contractId, symbol, direction, entryPrice, entryTime }) {
  if (!contractId || contractId === "--") return;
  const nowSec = Math.floor(Date.now() / 1000);
  const key = String(contractId);
  const marker = tradeChartMarkers.get(key) || {};
  tradeChartMarkers.set(key, {
    ...marker,
    contractId,
    symbol: symbol || marker.symbol || currentSymbol,
    direction: direction || marker.direction || currentDirection,
    entryPrice: toFiniteNumber(entryPrice) ?? marker.entryPrice ?? toFiniteNumber(lastSpot),
    entryTime: toFiniteNumber(entryTime) ?? marker.entryTime ?? nowSec,
    isClosed: marker.isClosed || false,
  });
  renderMiniChart(getBuiltCandles());
}

function upsertTradeChartMarkerFromContract(contract, previousTrade) {
  const contractId = contract?.contract_id;
  if (!contractId) return;
  const key = String(contractId);
  const existing = tradeChartMarkers.get(key) || {};
  const nowSec = Math.floor(Date.now() / 1000);
  const isClosed = Boolean(contract.is_sold ?? contract.status === "sold");
  const entryPrice = toFiniteNumber(contract.entry_spot)
    ?? toFiniteNumber(contract.entry_tick)
    ?? existing.entryPrice
    ?? toFiniteNumber(lastSpot);
  const entryTime = toFiniteNumber(contract.date_start)
    ?? toFiniteNumber(contract.purchase_time)
    ?? existing.entryTime
    ?? nowSec;
  const exitPrice = toFiniteNumber(contract.exit_tick)
    ?? toFiniteNumber(contract.sell_spot)
    ?? (isClosed ? toFiniteNumber(contract.current_spot) : null)
    ?? existing.exitPrice;
  const exitTime = toFiniteNumber(contract.date_expiry)
    ?? toFiniteNumber(contract.date_settlement)
    ?? (isClosed ? nowSec : null)
    ?? existing.exitTime;
  const profit = toFiniteNumber(contract.profit) ?? existing.profit ?? toFiniteNumber(previousTrade?.profit);
  const closedAtMs = isClosed ? (existing.closedAtMs || Date.now()) : null;
  tradeChartMarkers.set(key, {
    ...existing,
    contractId,
    symbol: getTradeMarkerSymbol(contract, previousTrade?.symbol || existing.symbol),
    direction: contract.contract_type || previousTrade?.direction || existing.direction || currentDirection,
    entryPrice,
    entryTime,
    exitPrice,
    exitTime,
    profit,
    isClosed,
    closedAtMs,
  });
  if (isClosed) scheduleTradeMarkerRedraw();
  if (tradeChartMarkers.size > 40) {
    Array.from(tradeChartMarkers.entries())
      .filter(([, marker]) => marker.isClosed)
      .sort((a, b) => (a[1].closedAtMs || 0) - (b[1].closedAtMs || 0))
      .slice(0, Math.max(0, tradeChartMarkers.size - 40))
      .forEach(([markerKey]) => tradeChartMarkers.delete(markerKey));
  }
  renderMiniChart(getBuiltCandles());
}

function renderTradeChartMarkers(ctx, viewport = chartViewportState) {
  if (!viewport || !tradeChartMarkers.size) return;
  const bounds = getChartPlotBounds(viewport);
  if (!bounds) return;
  const now = Date.now();
  const activeSymbol = currentSymbol || symbolSelect?.value || null;
  ctx.save();
  ctx.font = "700 11px Inter, Segoe UI, sans-serif";
  ctx.textBaseline = "middle";
  for (const marker of tradeChartMarkers.values()) {
    if (activeSymbol && marker.symbol && marker.symbol !== activeSymbol) continue;
    const entryPrice = toFiniteNumber(marker.entryPrice);
    const entryTime = toFiniteNumber(marker.entryTime);
    if (entryPrice == null || entryTime == null) continue;
    const entryX = getChartXForTime(entryTime, viewport);
    const entryY = viewport.toY(entryPrice);
    if (!Number.isFinite(entryX) || !Number.isFinite(entryY)) continue;
    const visibleEntryX = clamp(entryX, bounds.left, bounds.right);
    const visibleEntryY = clamp(entryY, bounds.top, bounds.bottom);
    const showEntryCross = !marker.isClosed || !marker.closedAtMs || now - marker.closedAtMs < 10000;
    if (showEntryCross) {
      ctx.strokeStyle = "rgba(45, 140, 255, 0.72)";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([6, 5]);
      ctx.beginPath();
      ctx.moveTo(visibleEntryX, bounds.top);
      ctx.lineTo(visibleEntryX, bounds.bottom);
      ctx.moveTo(Math.max(bounds.left, visibleEntryX), visibleEntryY);
      ctx.lineTo(bounds.right, visibleEntryY);
      ctx.stroke();
      ctx.setLineDash([]);
      const label = `Entry ${formatPrice(entryPrice, currentPip)}`;
      const labelW = Math.max(70, ctx.measureText(label).width + 14);
      const labelX = clamp(bounds.right - labelW - 8, bounds.left + 4, bounds.right - labelW);
      const labelY = clamp(visibleEntryY - 14, bounds.top + 12, bounds.bottom - 12);
      ctx.fillStyle = "rgba(45, 140, 255, 0.92)";
      ctx.beginPath();
      ctx.roundRect(labelX, labelY - 10, labelW, 20, 6);
      ctx.fill();
      ctx.fillStyle = "#ffffff";
      ctx.fillText(label, labelX + 7, labelY);
    }
    if (marker.isClosed && marker.exitPrice != null && marker.exitTime != null) {
      const exitX = getChartXForTime(Number(marker.exitTime), viewport);
      const exitY = viewport.toY(Number(marker.exitPrice));
      if (!Number.isFinite(exitX) || !Number.isFinite(exitY)) continue;
      const clippedExitX = clamp(exitX, bounds.left, bounds.right);
      const clippedExitY = clamp(exitY, bounds.top, bounds.bottom);
      const won = Number(marker.profit || 0) >= 0;
      const color = won ? "#10b981" : "#ef4444";
      ctx.strokeStyle = won ? "rgba(16, 185, 129, 0.75)" : "rgba(239, 68, 68, 0.75)";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([3, 5]);
      ctx.beginPath();
      ctx.moveTo(visibleEntryX, visibleEntryY);
      ctx.lineTo(clippedExitX, clippedExitY);
      ctx.stroke();
      ctx.setLineDash([]);
      const flagText = marker.profit == null ? (won ? "WIN" : "LOSS") : `${won ? "+" : ""}${Number(marker.profit).toFixed(2)}`;
      const flagW = Math.max(48, ctx.measureText(flagText).width + 16);
      const flagX = clamp(clippedExitX + 8, bounds.left + 2, bounds.right - flagW - 2);
      const flagY = clamp(clippedExitY - 14, bounds.top + 12, bounds.bottom - 12);
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(clippedExitX, clippedExitY);
      ctx.lineTo(flagX, flagY - 9);
      ctx.lineTo(flagX, flagY + 9);
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.roundRect(flagX, flagY - 10, flagW, 20, 6);
      ctx.fill();
      ctx.fillStyle = "#ffffff";
      ctx.fillText(flagText, flagX + 8, flagY);
    }
  }
  ctx.restore();
}

function renderTradeSetupLine(ctx, viewport, price, color, label, dash = [7, 5]) {
  const bounds = getChartPlotBounds(viewport);
  if (!bounds || price == null || !Number.isFinite(Number(price))) return;
  const y = viewport.toY(Number(price));
  if (!Number.isFinite(y)) return;
  const clippedY = clamp(y, bounds.top, bounds.bottom);
  const labelText = `${label} ${formatPrice(Number(price), currentPip)}`;
  ctx.save();
  ctx.strokeStyle = color;
  ctx.lineWidth = 1.4;
  ctx.setLineDash(dash);
  ctx.beginPath();
  ctx.moveTo(bounds.left, clippedY);
  ctx.lineTo(bounds.right, clippedY);
  ctx.stroke();
  ctx.setLineDash([]);
  ctx.font = "700 11px Inter, Segoe UI, sans-serif";
  ctx.textBaseline = "middle";
  const labelW = Math.max(64, ctx.measureText(labelText).width + 16);
  const labelH = 20;
  const labelX = clamp(bounds.right - labelW - 8, bounds.left + 4, bounds.right - labelW - 4);
  const labelY = clamp(clippedY - labelH / 2, bounds.top + 2, bounds.bottom - labelH - 2);
  ctx.fillStyle = color;
  ctx.beginPath();
  ctx.roundRect(labelX, labelY, labelW, labelH, 6);
  ctx.fill();
  ctx.fillStyle = "#ffffff";
  ctx.fillText(labelText, labelX + 8, labelY + labelH / 2);
  ctx.restore();
}

function getMultiplierPreviewPrices(direction = currentDirection) {
  const spot = toFiniteNumber(lastSpot);
  if (spot == null) return null;
  const stake = Math.max(0, parseTradeNumber(stakeInput?.value ?? sidebarStakeInputEl?.value, 0));
  const settings = getMultiplierSettings();
  const sensitivity = Math.max(stake * settings.multiplier, 1);
  const minDelta = Math.max(currentPip || 0.0001, Math.abs(spot) * 0.0005);
  const priceFromLimit = (amount) => {
    if (!amount || amount <= 0) return null;
    return Math.max(minDelta, Math.abs(spot) * (amount / sensitivity) * 0.01);
  };
  const tpDelta = priceFromLimit(settings.limitOrder?.take_profit);
  const slDelta = priceFromLimit(settings.limitOrder?.stop_loss);
  const isUp = direction !== "PUT";
  return {
    takeProfit: tpDelta == null ? null : spot + (isUp ? tpDelta : -tpDelta),
    stopLoss: slDelta == null ? null : spot + (isUp ? -slDelta : slDelta),
  };
}

function renderTradeSetupPreview(ctx, viewport = chartViewportState) {
  if (!viewport || !lastSpot) return;
  const tradeMode = getActiveTradeMode();
  if (tradeMode === "higher_lower") {
    const barrierInfo = getHigherLowerBarrier(currentDirection);
    if (barrierInfo?.display != null) {
      renderTradeSetupLine(ctx, viewport, barrierInfo.display, "rgba(250, 204, 21, 0.9)", `${getDirectionLabel(currentDirection)} barrier`);
    }
    return;
  }
  if (tradeMode === "touch_no_touch") {
    const barrierInfo = getAdvancedBarrierInfo();
    if (barrierInfo?.display != null) {
      renderTradeSetupLine(ctx, viewport, barrierInfo.display, "rgba(250, 204, 21, 0.9)", "Touch barrier");
    }
    return;
  }
  if (tradeMode === "multipliers") {
    const preview = getMultiplierPreviewPrices(currentDirection);
    if (!preview) return;
    if (preview.takeProfit != null) {
      renderTradeSetupLine(ctx, viewport, preview.takeProfit, "rgba(16, 185, 129, 0.88)", "TP");
    }
    if (preview.stopLoss != null) {
      renderTradeSetupLine(ctx, viewport, preview.stopLoss, "rgba(239, 68, 68, 0.88)", "SL");
    }
  }
}

function getExtendedLinePoints(x1, y1, x2, y2, viewport = chartViewportState) {
  const bounds = getChartPlotBounds(viewport);
  if (!bounds || !Number.isFinite(x1) || !Number.isFinite(y1) || !Number.isFinite(x2) || !Number.isFinite(y2)) return null;
  const dx = x2 - x1;
  const dy = y2 - y1;
  if (Math.abs(dx) < 0.001 && Math.abs(dy) < 0.001) return null;
  const candidates = [];

  if (Math.abs(dx) > 0.001) {
    const tLeft = (bounds.left - x1) / dx;
    const yLeft = y1 + (tLeft * dy);
    if (yLeft >= bounds.top - 1 && yLeft <= bounds.bottom + 1) candidates.push({ x: bounds.left, y: yLeft, t: tLeft });
    const tRight = (bounds.right - x1) / dx;
    const yRight = y1 + (tRight * dy);
    if (yRight >= bounds.top - 1 && yRight <= bounds.bottom + 1) candidates.push({ x: bounds.right, y: yRight, t: tRight });
  }

  if (Math.abs(dy) > 0.001) {
    const tTop = (bounds.top - y1) / dy;
    const xTop = x1 + (tTop * dx);
    if (xTop >= bounds.left - 1 && xTop <= bounds.right + 1) candidates.push({ x: xTop, y: bounds.top, t: tTop });
    const tBottom = (bounds.bottom - y1) / dy;
    const xBottom = x1 + (tBottom * dx);
    if (xBottom >= bounds.left - 1 && xBottom <= bounds.right + 1) candidates.push({ x: xBottom, y: bounds.bottom, t: tBottom });
  }

  if (candidates.length < 2) return null;
  candidates.sort((a, b) => a.t - b.t);
  return { start: candidates[0], end: candidates[candidates.length - 1] };
}

function getRayLinePoints(x1, y1, x2, y2, viewport = chartViewportState) {
  const extended = getExtendedLinePoints(x1, y1, x2, y2, viewport);
  if (!extended) return null;
  const dx = x2 - x1;
  const dy = y2 - y1;
  const candidates = [extended.start, extended.end]
    .map((point) => ({
      ...point,
      dot: ((point.x - x1) * dx) + ((point.y - y1) * dy),
    }))
    .filter((point) => point.dot >= -0.1);
  if (!candidates.length) return null;
  const far = candidates.reduce((best, point) => (point.dot > best.dot ? point : best), candidates[0]);
  return { start: { x: x1, y: y1 }, end: far };
}

function createDrawingPointFromPointer(event) {
  if (!miniChartCanvas || !chartViewportState) return null;
  const rect = miniChartCanvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  const viewport = chartViewportState;
  if (x < viewport.leftPad || x > viewport.width - viewport.rightPad || y < viewport.topPad || y > viewport.height - viewport.bottomPad) {
    return null;
  }
  const time = getChartTimeForX(x, viewport);
  const price = getChartPriceForY(y, viewport);
  if (!Number.isFinite(time) || !Number.isFinite(price)) return null;
  return { time, price, x, y };
}

function addChartDrawing(drawing) {
  const drawings = getChartDrawings();
  drawings.push(drawing);
  saveChartDrawingStore();
}

function updateChartDrawing(updatedDrawing) {
  if (!updatedDrawing?.id) return false;
  const drawings = getChartDrawings();
  const index = drawings.findIndex((drawing) => drawing.id === updatedDrawing.id);
  if (index === -1) return false;
  drawings[index] = updatedDrawing;
  saveChartDrawingStore();
  return true;
}

function deleteChartDrawingById(id) {
  if (!id) return false;
  const drawings = getChartDrawings();
  const next = drawings.filter((drawing) => drawing.id !== id);
  if (next.length === drawings.length) return false;
  chartDrawingStore[getDrawingSymbolKey()] = next;
  if (chartSelectedDrawingId === id) clearChartDrawingSelection();
  saveChartDrawingStore();
  renderMiniChart(getBuiltCandles());
  return true;
}

function buildDrawingFromDraft(draft) {
  if (!draft?.start || !draft.tool) return null;
  const id = `draw_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
  const base = {
    id,
    tool: draft.tool,
    symbol: currentSymbol,
    createdAt: Date.now(),
    locked: false,
    style: {
      color: DRAWING_COLOR_OPTIONS[0],
      width: 2,
      lineStyle: "solid",
    },
    start: {
      time: snapChartTime(draft.start.time),
      price: draft.start.price,
    },
  };

  if (DRAWING_SINGLE_POINT_TOOLS.has(draft.tool)) {
    return base;
  }

  if (!draft.end) return null;
  const end = {
    time: snapChartTime(draft.end.time),
    price: draft.tool === "HRAY" ? draft.start.price : draft.end.price,
  };

  if (draft.tool !== "HLINE"
    && Math.abs(end.time - base.start.time) < getChartTimeframeSeconds()
    && Math.abs(end.price - base.start.price) < ((chartViewportState?.max || 1) - (chartViewportState?.min || 0)) * 0.01) {
    return null;
  }

  if (draft.tool === "LONG_POSITION" || draft.tool === "SHORT_POSITION") {
    const isLong = draft.tool === "LONG_POSITION";
    const entryPrice = base.start.price;
    const targetDistance = Math.max(Math.abs(end.price - entryPrice), Math.abs(entryPrice) * 0.0001, 0.0001);
    return {
      ...base,
      end: {
        ...end,
        price: entryPrice,
      },
      position: {
        targetPrice: isLong ? entryPrice + targetDistance : entryPrice - targetDistance,
        stopPrice: isLong ? entryPrice - (targetDistance / 2) : entryPrice + (targetDistance / 2),
      },
    };
  }

  return { ...base, end };
}

function cloneChartDrawing(drawing) {
  if (!drawing) return null;
  const viewport = chartViewportState;
  const priceSpan = viewport ? (viewport.max - viewport.min) : 1;
  const priceShift = Math.max(priceSpan * 0.03, (Math.abs(drawing.start?.price || 1) * 0.0005), 0.0001);
  const timeShift = getChartTimeframeSeconds() * 2;
  return {
    ...drawing,
    id: `draw_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    createdAt: Date.now(),
    locked: false,
    start: {
      time: snapChartTime((drawing.start?.time || 0) + timeShift),
      price: (drawing.start?.price || 0) + priceShift,
    },
    end: drawing.end ? {
      time: snapChartTime((drawing.end.time || 0) + timeShift),
      price: (drawing.end.price || 0) + priceShift,
    } : undefined,
    position: drawing.position ? {
      ...drawing.position,
      targetPrice: Number.isFinite(drawing.position.targetPrice) ? drawing.position.targetPrice + priceShift : drawing.position.targetPrice,
      stopPrice: Number.isFinite(drawing.position.stopPrice) ? drawing.position.stopPrice + priceShift : drawing.position.stopPrice,
    } : undefined,
  };
}

function renderChartDrawings(ctx, viewport = chartViewportState) {
  if (!ctx || !viewport?.points?.length) return;
  const drawings = getChartDrawings();
  const drawLine = (x1, y1, x2, y2, color, dashed = false, widthPx = 1.5, lineStyle = "solid") => {
    ctx.save();
    ctx.strokeStyle = color;
    ctx.lineWidth = widthPx;
    if (lineStyle === "dotted") ctx.setLineDash([2, 5]);
    else if (dashed || lineStyle === "dashed") ctx.setLineDash([7, 5]);
    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(x2, y2);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.restore();
  };
  const drawOffsetLine = (x1, y1, x2, y2, offset, color, dashed = false, widthPx = 1.2, lineStyle = "solid") => {
    const dx = x2 - x1;
    const dy = y2 - y1;
    const length = Math.hypot(dx, dy);
    if (!length) return;
    const ox = (-dy / length) * offset;
    const oy = (dx / length) * offset;
    drawLine(x1 + ox, y1 + oy, x2 + ox, y2 + oy, color, dashed, widthPx, lineStyle);
  };
  const drawInfoLabel = (text, x, y, color) => {
    ctx.save();
    ctx.font = "10px Inter, Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const widthPx = ctx.measureText(text).width + 12;
    const labelX = Math.min(viewport.width - viewport.rightPad - widthPx, Math.max(viewport.leftPad, x + 8));
    const labelY = clamp(y, viewport.topPad + 12, viewport.height - viewport.bottomPad - 12);
    ctx.fillStyle = "rgba(9, 14, 24, 0.86)";
    ctx.strokeStyle = color;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(labelX, labelY - 10, widthPx, 20, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = color;
    ctx.fillText(text, labelX + 6, labelY);
    ctx.restore();
  };
  const getPositionOutcomePoint = (drawing, isLong, targetPrice, stopPrice, fallbackX, fallbackY) => {
    const startTime = Math.min(drawing.start?.time ?? 0, drawing.end?.time ?? drawing.start?.time ?? 0);
    const endTime = Math.max(drawing.start?.time ?? 0, drawing.end?.time ?? drawing.start?.time ?? 0);
    const built = getBuiltCandles()
      .filter((candle) => Number.isFinite(candle?.time) && candle.time >= startTime && candle.time <= endTime)
      .sort((a, b) => a.time - b.time);
    let latestPoint = null;

    for (const candle of built) {
      const candleX = getChartXForTime(candle.time, viewport);
      if (!Number.isFinite(candleX)) continue;
      latestPoint = {
        x: candleX,
        y: viewport.toY(Number.isFinite(candle.close) ? candle.close : drawing.start.price),
      };
      const targetHit = isLong
        ? Number.isFinite(candle.high) && candle.high >= targetPrice
        : Number.isFinite(candle.low) && candle.low <= targetPrice;
      const stopHit = isLong
        ? Number.isFinite(candle.low) && candle.low <= stopPrice
        : Number.isFinite(candle.high) && candle.high >= stopPrice;
      if (!targetHit && !stopHit) continue;

      const hitTarget = targetHit && stopHit
        ? Math.abs((candle.open ?? drawing.start.price) - targetPrice) <= Math.abs((candle.open ?? drawing.start.price) - stopPrice)
        : targetHit;
      return {
        x: candleX,
        y: viewport.toY(hitTarget ? targetPrice : stopPrice),
        outcome: hitTarget ? "target" : "stop",
      };
    }

    return latestPoint || { x: fallbackX, y: fallbackY, outcome: "open" };
  };
  const drawPositionTool = (drawing, x1, y1, x2, y2, isLong, renderStyle) => {
    if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
    const toolColor = renderStyle.color;
    const toolWidth = renderStyle.lineWidth;
    const toolLineStyle = renderStyle.lineStyle;
    const entryPrice = drawing.start.price;
    const legacyTargetDistance = Math.max(Math.abs((drawing.end?.price ?? entryPrice) - entryPrice), Math.abs(entryPrice) * 0.0001, 0.0001);
    const targetPrice = Number.isFinite(drawing.position?.targetPrice)
      ? drawing.position.targetPrice
      : isLong ? entryPrice + legacyTargetDistance : entryPrice - legacyTargetDistance;
    const stopPrice = Number.isFinite(drawing.position?.stopPrice)
      ? drawing.position.stopPrice
      : isLong ? entryPrice - (legacyTargetDistance / 2) : entryPrice + (legacyTargetDistance / 2);
    const entryY = viewport.toY(entryPrice);
    const targetY = viewport.toY(targetPrice);
    const stopY = viewport.toY(stopPrice);
    const leftX = Math.min(x1, x2);
    const rightX = Math.max(x1, x2);
    const widthPx = Math.max(26, rightX - leftX);
    const targetTop = Math.min(entryY, targetY);
    const targetHeight = Math.max(4, Math.abs(targetY - entryY));
    const stopTop = Math.min(entryY, stopY);
    const stopHeight = Math.max(4, Math.abs(stopY - entryY));
    const reward = Math.abs(targetPrice - entryPrice);
    const risk = Math.abs(entryPrice - stopPrice);
    const ratio = risk ? reward / risk : 0;

    ctx.save();
    ctx.fillStyle = "rgba(13, 183, 135, 0.26)";
    ctx.fillRect(leftX, targetTop, widthPx, targetHeight);
    ctx.fillStyle = "rgba(225, 91, 100, 0.28)";
    ctx.fillRect(leftX, stopTop, widthPx, stopHeight);
    ctx.strokeStyle = toolColor;
    ctx.lineWidth = Math.max(1, toolWidth);
    if (toolLineStyle === "dotted") ctx.setLineDash([2, 5]);
    else if (toolLineStyle === "dashed") ctx.setLineDash([7, 5]);
    ctx.strokeRect(leftX, Math.min(targetTop, stopTop), widthPx, targetHeight + stopHeight);
    ctx.setLineDash([]);
    drawLine(leftX, entryY, leftX + widthPx, entryY, toolColor, false, Math.max(1, toolWidth), toolLineStyle);
    const outcomePoint = getPositionOutcomePoint(drawing, isLong, targetPrice, stopPrice, leftX + widthPx, targetY);
    const guideEndX = clamp(outcomePoint.x, leftX, leftX + widthPx);
    const guideEndY = clamp(outcomePoint.y, viewport.topPad, viewport.height - viewport.bottomPad);
    drawLine(leftX, entryY, guideEndX, guideEndY, "rgba(205, 215, 230, 0.46)", true, 1, "dotted");
    ctx.font = "10px Inter, Segoe UI, sans-serif";
    ctx.textAlign = "center";
    ctx.textBaseline = "middle";
    const labelX = clamp(leftX + (widthPx / 2), viewport.leftPad + 46, viewport.width - viewport.rightPad - 46);
    const targetText = `Target ${formatPrice(targetPrice, currentPip)}`;
    const stopText = `Stop ${formatPrice(stopPrice, currentPip)}`;
    const pnlText = `${isLong ? "Long" : "Short"} R:R ${ratio.toFixed(2)}`;
    const drawBadge = (text, x, y, bg) => {
      const w = Math.max(78, ctx.measureText(text).width + 12);
      ctx.fillStyle = bg;
      ctx.beginPath();
      ctx.roundRect(x - (w / 2), y - 10, w, 20, 5);
      ctx.fill();
      ctx.fillStyle = "#ffffff";
      ctx.fillText(text, x, y);
    };
    drawBadge(targetText, labelX, clamp(targetY, viewport.topPad + 12, viewport.height - viewport.bottomPad - 12), "rgba(13, 183, 135, 0.92)");
    drawBadge(stopText, labelX, clamp(stopY, viewport.topPad + 12, viewport.height - viewport.bottomPad - 12), "rgba(225, 91, 100, 0.92)");
    drawBadge(pnlText, labelX, clamp(entryY, viewport.topPad + 12, viewport.height - viewport.bottomPad - 12), "rgba(12, 18, 28, 0.92)");
    ctx.restore();
  };
  const drawVolumeProfileTool = (drawing, x1, y1, x2, y2, anchored, renderStyle) => {
    const built = getBuiltCandles();
    if (!built.length || !Number.isFinite(x1) || !Number.isFinite(y1)) return;
    const startTime = Math.min(drawing.start.time, anchored ? drawing.start.time : drawing.end?.time ?? drawing.start.time);
    const endTime = anchored
      ? (viewport.points[viewport.points.length - 1]?.time ?? drawing.end?.time ?? drawing.start.time)
      : Math.max(drawing.start.time, drawing.end?.time ?? drawing.start.time);
    const sample = built.filter((candle) => candle.time >= startTime && candle.time <= endTime);
    if (!sample.length) return;
    const lows = sample.map((candle) => candle.low).filter(Number.isFinite);
    const highs = sample.map((candle) => candle.high).filter(Number.isFinite);
    const low = Math.min(...lows);
    const high = Math.max(...highs);
    if (!Number.isFinite(low) || !Number.isFinite(high) || high <= low) return;

    const rows = Math.min(24, Math.max(10, Math.round(viewport.plotH / 22)));
    const buckets = Array.from({ length: rows }, (_, index) => ({
      low: low + ((high - low) * index / rows),
      high: low + ((high - low) * (index + 1) / rows),
      bull: 0,
      bear: 0,
      total: 0,
    }));
    sample.forEach((candle) => {
      const candleLow = Math.min(candle.low, candle.high);
      const candleHigh = Math.max(candle.low, candle.high);
      const span = Math.max(candleHigh - candleLow, (high - low) / rows);
      const proxyVolume = Math.max(1, (Array.isArray(candle.ticks) ? candle.ticks.length : 0) || Math.abs(candle.close - candle.open) * 10000 || 1);
      const bullish = candle.close >= candle.open;
      buckets.forEach((bucket) => {
        const overlap = Math.max(0, Math.min(candleHigh, bucket.high) - Math.max(candleLow, bucket.low));
        if (!overlap) return;
        const amount = proxyVolume * (overlap / span);
        bucket.total += amount;
        if (bullish) bucket.bull += amount;
        else bucket.bear += amount;
      });
    });
    const maxVolume = Math.max(...buckets.map((bucket) => bucket.total), 1);
    const rangeLeft = Math.min(x1, x2 || x1);
    const rangeRight = Math.max(x1, x2 || x1);
    const plotLeft = viewport.leftPad + 8;
    const plotRight = viewport.width - viewport.rightPad - 8;
    const fixedDrawsRight = !anchored && Number.isFinite(x2) && x2 >= x1;
    const anchorX = anchored ? plotRight : (fixedDrawsRight ? rangeLeft : rangeRight);
    const availableWidth = Math.max(24, fixedDrawsRight ? plotRight - anchorX : anchorX - plotLeft);
    const desiredWidth = Math.max(54, Math.min(180, Math.abs(rangeRight - rangeLeft) || viewport.plotW * 0.18));
    const maxWidth = Math.min(desiredWidth, availableWidth);
    const profileLeft = fixedDrawsRight ? anchorX : anchorX - maxWidth;
    const profileRight = fixedDrawsRight ? anchorX + maxWidth : anchorX;

    ctx.save();
    ctx.fillStyle = hexToRgba(renderStyle.rawColor, 0.08);
    ctx.fillRect(Math.min(rangeLeft, profileLeft), viewport.toY(high), Math.abs(Math.max(rangeRight, profileRight) - Math.min(rangeLeft, profileLeft)), Math.max(4, viewport.toY(low) - viewport.toY(high)));
    buckets.forEach((bucket) => {
      if (!bucket.total) return;
      const rowTop = viewport.toY(bucket.high);
      const rowBottom = viewport.toY(bucket.low);
      const rowH = Math.max(2, rowBottom - rowTop - 1);
      const totalW = Math.max(2, (bucket.total / maxVolume) * maxWidth);
      const bullW = totalW * (bucket.bull / bucket.total);
      const bearW = totalW - bullW;
      const x = fixedDrawsRight ? profileLeft : profileRight - totalW;
      ctx.fillStyle = "rgba(13, 183, 135, 0.68)";
      ctx.fillRect(x, rowTop, bullW, rowH);
      ctx.fillStyle = "rgba(225, 91, 100, 0.66)";
      ctx.fillRect(x + bullW, rowTop, bearW, rowH);
    });
    const poc = buckets.reduce((best, bucket) => (bucket.total > best.total ? bucket : best), buckets[0]);
    if (poc) {
      const pocY = viewport.toY((poc.low + poc.high) / 2);
      drawLine(profileLeft, pocY, profileRight, pocY, renderStyle.color, false, Math.max(1, renderStyle.lineWidth), renderStyle.lineStyle);
      drawInfoLabel(anchored ? "Anchored VP" : "Fixed range VP", profileLeft, pocY - 16, renderStyle.color);
    }
    ctx.restore();
  };

  const renderSingle = (drawing, isDraft = false) => {
    const isSelected = !isDraft && drawing.id === chartSelectedDrawingId;
    const style = normalizeDrawingStyle(drawing, { isDraft, isSelected });
    const color = hexToRgba(style.color, isDraft || isSelected ? 0.98 : 0.92);
    const fill = hexToRgba(style.color, isDraft || isSelected ? 0.16 : 0.10);
    const lineWidth = style.width;
    const lineStyle = style.lineStyle;
    const x1 = getChartXForTime(drawing.start?.time, viewport);
    const y1 = viewport.toY(drawing.start?.price);
    const x2 = drawing.end ? getChartXForTime(drawing.end.time, viewport) : null;
    const y2 = drawing.end ? viewport.toY(drawing.end.price) : null;
    if (!Number.isFinite(x1) || !Number.isFinite(y1)) return;

    switch (drawing.tool) {
      case "HLINE":
        drawLine(viewport.leftPad, y1, viewport.width - viewport.rightPad, y1, color, false, lineWidth, lineStyle);
        break;
      case "VLINE":
        drawLine(x1, viewport.topPad, x1, viewport.height - viewport.bottomPad, color, false, lineWidth, lineStyle);
        break;
      case "CROSSLINE":
        drawLine(viewport.leftPad, y1, viewport.width - viewport.rightPad, y1, color, true, lineWidth, lineStyle);
        drawLine(x1, viewport.topPad, x1, viewport.height - viewport.bottomPad, color, true, lineWidth, lineStyle);
        break;
      case "HRAY":
        if (!Number.isFinite(x2)) return;
        drawLine(Math.min(x1, x2), y1, viewport.width - viewport.rightPad, y1, color, false, lineWidth, lineStyle);
        break;
      case "RAY": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const ray = getRayLinePoints(x1, y1, x2, y2, viewport);
        if (ray) drawLine(ray.start.x, ray.start.y, ray.end.x, ray.end.y, color, false, lineWidth, lineStyle);
        break;
      }
      case "EXTENDED": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const extended = getExtendedLinePoints(x1, y1, x2, y2, viewport);
        if (extended) drawLine(extended.start.x, extended.start.y, extended.end.x, extended.end.y, color, false, lineWidth, lineStyle);
        break;
      }
      case "TRENDLINE":
      case "INFOLINE":
      case "TRENDANGLE":
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        drawLine(x1, y1, x2, y2, color, false, lineWidth, lineStyle);
        if (drawing.tool === "INFOLINE") {
          const priceDelta = drawing.end.price - drawing.start.price;
          const pct = drawing.start.price ? (priceDelta / drawing.start.price) * 100 : 0;
          const bars = Math.round(Math.abs(drawing.end.time - drawing.start.time) / Math.max(1, getChartTimeframeSeconds()));
          drawInfoLabel(`${priceDelta >= 0 ? "+" : ""}${priceDelta.toFixed(4)} (${pct.toFixed(2)}%) | ${bars} bars`, x2, y2, color);
        } else if (drawing.tool === "TRENDANGLE") {
          const angle = Math.atan2(y1 - y2, x2 - x1) * (180 / Math.PI);
          drawInfoLabel(`${angle.toFixed(1)} deg`, x2, y2, color);
        }
        break;
      case "PARALLEL_CHANNEL":
      case "REGRESSION_TREND": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const extended = getExtendedLinePoints(x1, y1, x2, y2, viewport);
        const line = extended || { start: { x: x1, y: y1 }, end: { x: x2, y: y2 } };
        const offset = drawing.tool === "REGRESSION_TREND" ? 26 : 34;
        drawOffsetLine(line.start.x, line.start.y, line.end.x, line.end.y, -offset, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        drawLine(line.start.x, line.start.y, line.end.x, line.end.y, color, drawing.tool === "REGRESSION_TREND", lineWidth, lineStyle);
        drawOffsetLine(line.start.x, line.start.y, line.end.x, line.end.y, offset, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        break;
      }
      case "FLAT_TOP_BOTTOM":
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        drawLine(x1, y1, x2, y2, color, false, lineWidth, lineStyle);
        drawLine(Math.min(x1, x2), y2, Math.max(x1, x2), y2, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        break;
      case "DISJOINT_CHANNEL": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const offset = 30;
        drawOffsetLine(x1, y1, x2, y2, -offset, color, false, lineWidth, lineStyle);
        drawOffsetLine(x1, y1, x2, y2, offset, color, false, lineWidth, lineStyle);
        drawLine(x1, y1, x2, y2, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        break;
      }
      case "PITCHFORK":
      case "SCHIFF_PITCHFORK":
      case "MOD_SCHIFF_PITCHFORK":
      case "INSIDE_PITCHFORK": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const midY = drawing.tool === "SCHIFF_PITCHFORK"
          ? y1 + ((y2 - y1) * 0.35)
          : drawing.tool === "MOD_SCHIFF_PITCHFORK"
            ? y1 + ((y2 - y1) * 0.5)
            : drawing.tool === "INSIDE_PITCHFORK"
              ? y1 + ((y2 - y1) * 0.65)
              : y1;
        drawLine(x1, midY, x2, y2, color, false, lineWidth, lineStyle);
        drawOffsetLine(x1, midY, x2, y2, -36, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        drawOffsetLine(x1, midY, x2, y2, 36, color, true, Math.max(1, lineWidth - 0.5), lineStyle);
        break;
      }
      case "LONG_POSITION":
        drawPositionTool(drawing, x1, y1, x2, y2, true, { color, lineWidth, lineStyle });
        break;
      case "SHORT_POSITION":
        drawPositionTool(drawing, x1, y1, x2, y2, false, { color, lineWidth, lineStyle });
        break;
      case "FIXED_RANGE_VOLUME_PROFILE":
        drawVolumeProfileTool(drawing, x1, y1, x2, y2, false, { color, rawColor: style.color, lineWidth, lineStyle });
        break;
      case "ANCHORED_VOLUME_PROFILE":
        drawVolumeProfileTool(drawing, x1, y1, x2, y2, true, { color, rawColor: style.color, lineWidth, lineStyle });
        break;
      case "RECT":
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        ctx.save();
        ctx.fillStyle = fill;
        ctx.strokeStyle = color;
        ctx.lineWidth = lineWidth;
        if (lineStyle === "dotted") ctx.setLineDash([2, 5]);
        else if (lineStyle === "dashed") ctx.setLineDash([7, 5]);
        ctx.fillRect(Math.min(x1, x2), Math.min(y1, y2), Math.max(2, Math.abs(x2 - x1)), Math.max(2, Math.abs(y2 - y1)));
        ctx.strokeRect(Math.min(x1, x2), Math.min(y1, y2), Math.max(2, Math.abs(x2 - x1)), Math.max(2, Math.abs(y2 - y1)));
        ctx.setLineDash([]);
        ctx.restore();
        break;
      case "FIB": {
        if (!Number.isFinite(x2) || !Number.isFinite(y2)) return;
        const leftX = Math.min(x1, x2);
        const rightX = Math.max(x1, x2);
        const startPrice = drawing.start.price;
        const endPrice = drawing.end.price;
        const levels = [0, 0.382, 0.5, 0.618, 1];
        ctx.save();
        ctx.font = "9px Inter, Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "bottom";
        levels.forEach((ratio) => {
          const price = startPrice + ((endPrice - startPrice) * ratio);
          const y = viewport.toY(price);
          drawLine(leftX, y, rightX, y, color, ratio !== 0 && ratio !== 1, ratio === 0.5 ? lineWidth : Math.max(1, lineWidth - 0.5), lineStyle);
          ctx.fillStyle = color;
          ctx.fillText(`${Math.round(ratio * 100)}%`, Math.min(viewport.width - viewport.rightPad - 28, rightX + 4), y - 2);
        });
        ctx.restore();
        break;
      }
      default:
        break;
    }

    if (isSelected) {
      ctx.save();
      ctx.fillStyle = color;
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 1.4;
      const handles = getDrawingHandlePoints(drawing, viewport);
      handles.forEach((handle) => {
        ctx.beginPath();
        ctx.arc(handle.x, handle.y, 6, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
      });
      if (drawing.locked) {
        ctx.font = "10px Inter, Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "bottom";
        ctx.fillText("LOCK", x1 + 6, y1 - 4);
      }
      ctx.restore();
    }
  };

  drawings.forEach((drawing) => renderSingle(drawing, false));
  if (chartDrawingDraft) renderSingle(chartDrawingDraft, true);
  syncDrawingActionBarUI();
}

function hitTestChartDrawing(point, viewport = chartViewportState) {
  if (!point || !viewport?.points?.length) return null;
  const drawings = getChartDrawings();
  const threshold = 8;
  for (let i = drawings.length - 1; i >= 0; i -= 1) {
    const drawing = drawings[i];
    const x1 = getChartXForTime(drawing.start?.time, viewport);
    const y1 = viewport.toY(drawing.start?.price);
    const x2 = drawing.end ? getChartXForTime(drawing.end.time, viewport) : null;
    const y2 = drawing.end ? viewport.toY(drawing.end.price) : null;
    if (!Number.isFinite(x1) || !Number.isFinite(y1)) continue;

    if (drawing.tool === "HLINE") {
      if (Math.abs(point.y - y1) <= threshold) return drawing.id;
      continue;
    }

    if (drawing.tool === "VLINE") {
      if (Math.abs(point.x - x1) <= threshold) return drawing.id;
      continue;
    }

    if (drawing.tool === "CROSSLINE") {
      if (Math.abs(point.x - x1) <= threshold || Math.abs(point.y - y1) <= threshold) return drawing.id;
      continue;
    }

    if (drawing.tool === "HRAY" && Number.isFinite(x2)) {
      const startX = Math.min(x1, x2);
      const dist = pointToSegmentDistance(point.x, point.y, startX, y1, viewport.width - viewport.rightPad, y1);
      if (dist <= threshold) return drawing.id;
      continue;
    }

    if (drawing.tool === "RAY" && Number.isFinite(x2) && Number.isFinite(y2)) {
      const ray = getRayLinePoints(x1, y1, x2, y2, viewport);
      if (ray && pointToSegmentDistance(point.x, point.y, ray.start.x, ray.start.y, ray.end.x, ray.end.y) <= threshold) return drawing.id;
      continue;
    }

    if (drawing.tool === "EXTENDED" && Number.isFinite(x2) && Number.isFinite(y2)) {
      const extended = getExtendedLinePoints(x1, y1, x2, y2, viewport);
      if (extended && pointToSegmentDistance(point.x, point.y, extended.start.x, extended.start.y, extended.end.x, extended.end.y) <= threshold) return drawing.id;
      continue;
    }

    if ((drawing.tool === "TRENDLINE" || drawing.tool === "INFOLINE" || drawing.tool === "TRENDANGLE" || drawing.tool === "FLAT_TOP_BOTTOM" || DRAWING_CHANNEL_TOOLS.has(drawing.tool)) && Number.isFinite(x2) && Number.isFinite(y2)) {
      if (pointToSegmentDistance(point.x, point.y, x1, y1, x2, y2) <= threshold) return drawing.id;
      continue;
    }

    if ((drawing.tool === "RECT" || drawing.tool === "FIB" || drawing.tool === "LONG_POSITION" || drawing.tool === "SHORT_POSITION" || drawing.tool === "FIXED_RANGE_VOLUME_PROFILE" || drawing.tool === "ANCHORED_VOLUME_PROFILE") && Number.isFinite(x2) && Number.isFinite(y2)) {
      const left = Math.min(x1, x2) - threshold;
      const right = drawing.tool === "ANCHORED_VOLUME_PROFILE"
        ? viewport.width - viewport.rightPad + threshold
        : Math.max(x1, x2) + threshold;
      let top = Math.min(y1, y2) - threshold;
      let bottom = Math.max(y1, y2) + threshold;
      if (drawing.tool === "LONG_POSITION" || drawing.tool === "SHORT_POSITION") {
        const targetDistance = Math.max(Math.abs((drawing.end?.price ?? drawing.start.price) - drawing.start.price), Math.abs(drawing.start.price) * 0.0001, 0.0001);
        const targetPrice = Number.isFinite(drawing.position?.targetPrice)
          ? drawing.position.targetPrice
          : drawing.tool === "LONG_POSITION" ? drawing.start.price + targetDistance : drawing.start.price - targetDistance;
        const stopPrice = Number.isFinite(drawing.position?.stopPrice)
          ? drawing.position.stopPrice
          : drawing.tool === "LONG_POSITION" ? drawing.start.price - (targetDistance / 2) : drawing.start.price + (targetDistance / 2);
        top = Math.min(viewport.toY(targetPrice), viewport.toY(stopPrice), y1) - threshold;
        bottom = Math.max(viewport.toY(targetPrice), viewport.toY(stopPrice), y1) + threshold;
      } else if (drawing.tool === "FIXED_RANGE_VOLUME_PROFILE" || drawing.tool === "ANCHORED_VOLUME_PROFILE") {
        top = viewport.topPad - threshold;
        bottom = viewport.height - viewport.bottomPad + threshold;
      }
      if (point.x >= left && point.x <= right && point.y >= top && point.y <= bottom) return drawing.id;
    }
  }
  return null;
}

function ensureDrawingActionBar() {
  if (drawingActionBarEl || !chartBodyEl) return;
  drawingActionBarEl = document.createElement("div");
  drawingActionBarEl.className = "drawing-action-bar hidden";
  drawingActionBarEl.innerHTML = `
    <div class="drawing-toolbar-group drawing-toolbar-type">
      <select class="drawing-style-select drawing-tool-type-select" data-drawing-style="tool" aria-label="Drawing type">
        ${DRAWING_TOOL_OPTIONS.filter((tool) => tool !== "SELECT").map((tool) => `<option value="${tool}">${DRAWING_TOOL_LABELS[tool] || tool}</option>`).join("")}
      </select>
    </div>
    <div class="drawing-toolbar-group drawing-color-row" aria-label="Drawing color">
      <input class="drawing-color-input" type="color" data-drawing-style="color" value="${DRAWING_COLOR_OPTIONS[0]}" aria-label="Custom color" />
      ${DRAWING_COLOR_OPTIONS.map((color) => `<button class="drawing-color-swatch" type="button" data-drawing-color="${color}" style="--drawing-swatch:${color}" aria-label="Use ${color}"></button>`).join("")}
    </div>
    <div class="drawing-toolbar-group">
      <select class="drawing-style-select drawing-width-select" data-drawing-style="width" aria-label="Line width">
        <option value="1">1px</option>
        <option value="2">2px</option>
        <option value="3">3px</option>
        <option value="4">4px</option>
        <option value="5">5px</option>
      </select>
      <select class="drawing-style-select drawing-line-select" data-drawing-style="lineStyle" aria-label="Line style">
        <option value="solid">Solid</option>
        <option value="dashed">Dashed</option>
        <option value="dotted">Dotted</option>
      </select>
    </div>
    <div class="drawing-toolbar-group drawing-toolbar-actions">
      <button id="drawingMoveBtn" class="ghost small drawing-action-btn" type="button">Move</button>
      <button id="drawingCopyBtn" class="ghost small drawing-action-btn" type="button">Copy</button>
      <button id="drawingLockBtn" class="ghost small drawing-action-btn" type="button">Lock</button>
      <button id="drawingDeleteBtn" class="ghost small drawing-action-btn danger" type="button">Delete</button>
    </div>
  `;
  chartBodyEl.appendChild(drawingActionBarEl);
  drawingMoveBtnEl = document.getElementById("drawingMoveBtn");
  drawingCopyBtnEl = document.getElementById("drawingCopyBtn");
  drawingLockBtnEl = document.getElementById("drawingLockBtn");
  drawingDeleteBtnEl = document.getElementById("drawingDeleteBtn");

  drawingMoveBtnEl?.addEventListener("click", () => {
    const drawing = getSelectedChartDrawing();
    if (!drawing || drawing.locked) return;
    chartDrawingToolbarVisible = true;
    chartDrawingMoveMode = !chartDrawingMoveMode;
    chartDrawingMoveOrigin = null;
    syncDrawingActionBarUI();
  });

  drawingCopyBtnEl?.addEventListener("click", () => {
    const drawing = getSelectedChartDrawing();
    const clone = cloneChartDrawing(drawing);
    if (!clone) return;
    addChartDrawing(clone);
    chartSelectedDrawingId = clone.id;
    chartDrawingToolbarVisible = true;
    chartDrawingMoveMode = false;
    renderMiniChart(getBuiltCandles());
  });

  drawingLockBtnEl?.addEventListener("click", () => {
    const drawing = getSelectedChartDrawing();
    if (!drawing) return;
    updateChartDrawing({ ...drawing, locked: !drawing.locked });
    chartDrawingToolbarVisible = true;
    chartDrawingMoveMode = false;
    renderMiniChart(getBuiltCandles());
  });

  drawingDeleteBtnEl?.addEventListener("click", () => {
    const drawing = getSelectedChartDrawing();
    if (!drawing) return;
    deleteChartDrawingById(drawing.id);
  });

  drawingActionBarEl.addEventListener("input", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLInputElement) || target.getAttribute("data-drawing-style") !== "color") return;
    updateSelectedDrawing((drawing) => ({
      ...drawing,
      style: {
        ...(drawing.style || {}),
        color: target.value,
      },
    }));
  });

  drawingActionBarEl.addEventListener("change", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) return;
    const styleKey = target.getAttribute("data-drawing-style");
    if (!styleKey) return;
    if (styleKey === "tool" && target instanceof HTMLSelectElement) {
      updateSelectedDrawing((drawing) => ({
        ...drawing,
        tool: DRAWING_TOOL_OPTIONS.includes(target.value) && target.value !== "SELECT" ? target.value : drawing.tool,
      }));
      return;
    }
    if (styleKey === "width" && target instanceof HTMLSelectElement) {
      updateSelectedDrawing((drawing) => ({
        ...drawing,
        style: {
          ...(drawing.style || {}),
          width: clamp(Number(target.value) || 2, 1, 5),
        },
      }));
      return;
    }
    if (styleKey === "lineStyle" && target instanceof HTMLSelectElement) {
      updateSelectedDrawing((drawing) => ({
        ...drawing,
        style: {
          ...(drawing.style || {}),
          lineStyle: ["solid", "dashed", "dotted"].includes(target.value) ? target.value : "solid",
        },
      }));
    }
  });

  drawingActionBarEl.addEventListener("click", (event) => {
    const target = event.target;
    if (!(target instanceof HTMLElement)) return;
    const swatch = target.closest("[data-drawing-color]");
    if (!(swatch instanceof HTMLElement)) return;
    const color = swatch.getAttribute("data-drawing-color");
    if (!color) return;
    updateSelectedDrawing((drawing) => ({
      ...drawing,
      style: {
        ...(drawing.style || {}),
        color,
      },
    }));
  });
}

function calculateOBV(candles) {
  const obv = [0];
  for (let i = 1; i < candles.length; i++) {
    const prev = candles[i - 1];
    const curr = candles[i];
    const volume = Math.abs(curr.close - prev.close) * 1000;
    if (curr.close > prev.close) obv.push(obv[i - 1] + volume);
    else if (curr.close < prev.close) obv.push(obv[i - 1] - volume);
    else obv.push(obv[i - 1]);
  }
  return obv;
}

function averageRange(candles, lookback = SIGNAL_STRUCTURE_LOOKBACK) {
  const sample = candles.slice(-lookback);
  if (!sample.length) return 0;
  return sample.reduce((sum, candle) => sum + Math.abs(candle.high - candle.low), 0) / sample.length;
}

function calculateEMA(values, period) {
  if (!values.length) return null;
  const k = 2 / (period + 1);
  let ema = values[0];
  for (let i = 1; i < values.length; i++) {
    ema = (values[i] * k) + (ema * (1 - k));
  }
  return ema;
}

function calculateRSI(candles, period = 14) {
  if (candles.length < period + 1) return null;
  let gains = 0;
  let losses = 0;

  for (let i = candles.length - period; i < candles.length; i++) {
    const change = candles[i].close - candles[i - 1].close;
    if (change > 0) gains += change;
    else losses += Math.abs(change);
  }

  const avgGain = gains / period;
  const avgLoss = losses / period;
  if (avgLoss === 0) return 100;
  const rs = avgGain / avgLoss;
  return 100 - (100 / (1 + rs));
}

function getLevelThreshold(candles) {
  const avg = averageRange(candles);
  const pip = currentPip || 0;
  const fallback = candles[candles.length - 1]?.close ? candles[candles.length - 1].close * 0.0001 : 0.0001;
  return Math.max(pip * 2, avg * 0.15, fallback);
}

function detectAverageTrend(candles, length = 10) {
  if (candles.length < length) {
    return { trend: "SIDEWAYS", trendStrength: 0 };
  }
  const recent = candles.slice(-length);
  const avgClose = recent.reduce((sum, candle) => sum + candle.close, 0) / recent.length;
  const lastClose = recent[recent.length - 1].close;
  const avgRange = averageRange(recent) || Math.abs(lastClose) || 1;
  const distance = Math.abs(lastClose - avgClose);
  let trend = "SIDEWAYS";
  if (lastClose > avgClose) trend = "UP";
  else if (lastClose < avgClose) trend = "DOWN";
  return { trend, trendStrength: clamp(distance / avgRange, 0, 1) };
}

function detectEmaTrend(candles) {
  if (candles.length < 21) {
    return { trend: "SIDEWAYS", ema9: null, ema21: null, trendStrength: 0 };
  }
  const closes = candles.map((c) => c.close);
  const ema9 = calculateEMA(closes, 9);
  const ema21 = calculateEMA(closes, 21);
  const avg = averageRange(candles) || Math.abs(closes[closes.length - 1]) || 1;
  const diff = Math.abs((ema9 || 0) - (ema21 || 0));
  const trendStrength = clamp(diff / avg, 0, 1);
  let trend = "SIDEWAYS";
  if (ema9 > ema21) trend = "UP";
  else if (ema9 < ema21) trend = "DOWN";
  return { trend, ema9, ema21, trendStrength };
}

function detectObvTrend(candles) {
  if (candles.length < 21) {
    return { trend: "SIDEWAYS", trendStrength: 0 };
  }
  const emaTrend = detectEmaTrend(candles);
  const obv = calculateOBV(candles);
  const recent = obv.slice(-10);
  if (recent.length < 2) return emaTrend;
  const obvDelta = recent[recent.length - 1] - recent[0];
  const lastPrice = candles[candles.length - 1].close;
  const prevPrice = candles[Math.max(0, candles.length - 10)].close;
  const priceDelta = lastPrice - prevPrice;
  const obvBias = obvDelta > 0 ? "UP" : obvDelta < 0 ? "DOWN" : "SIDEWAYS";
  const priceBias = priceDelta > 0 ? "UP" : priceDelta < 0 ? "DOWN" : "SIDEWAYS";
  let trend = emaTrend.trend;
  if (obvBias !== "SIDEWAYS" && priceBias === obvBias) {
    trend = obvBias;
  } else if (priceBias === "SIDEWAYS" || obvBias === "SIDEWAYS") {
    trend = emaTrend.trend;
  } else if (priceBias !== obvBias) {
    trend = "SIDEWAYS";
  }
  return { trend, trendStrength: emaTrend.trendStrength };
}

function detectStructureTrend(candles) {
  if (candles.length < 5) {
    return { trend: "SIDEWAYS", trendStrength: 0, structureBias: "MIXED", modeLabel: "SMC" };
  }
  const recent = candles.slice(-5);
  let higherHighs = 0;
  let higherLows = 0;
  let lowerHighs = 0;
  let lowerLows = 0;

  for (let i = 1; i < recent.length; i++) {
    if (recent[i].high > recent[i - 1].high) higherHighs += 1;
    if (recent[i].low > recent[i - 1].low) higherLows += 1;
    if (recent[i].high < recent[i - 1].high) lowerHighs += 1;
    if (recent[i].low < recent[i - 1].low) lowerLows += 1;
  }

  const closeStructure = assessCloseStructure(candles);
  const bullishStructureScore = clamp(((higherHighs + higherLows) / 8) + (closeStructure.bullScore * 0.35), 0, 1);
  const bearishStructureScore = clamp(((lowerHighs + lowerLows) / 8) + (closeStructure.bearScore * 0.35), 0, 1);

  if (higherHighs >= 2 && higherLows >= 2 && closeStructure.bias !== "DOWN" && closeStructure.bullScore >= 0.45) {
    return {
      trend: "UP",
      trendStrength: bullishStructureScore,
      structureBias: "HH_HL",
      modeLabel: "SMC",
    };
  }
  if (lowerHighs >= 2 && lowerLows >= 2 && closeStructure.bias !== "UP" && closeStructure.bearScore >= 0.45) {
    return {
      trend: "DOWN",
      trendStrength: bearishStructureScore,
      structureBias: "LL_LH",
      modeLabel: "SMC",
    };
  }

  return { trend: "SIDEWAYS", trendStrength: 0, structureBias: "MIXED", modeLabel: "SMC" };
}

function buildHeikenAshiCandles(candles) {
  if (!candles.length) return [];
  const ha = [];
  let prevOpen = (candles[0].open + candles[0].close) / 2;
  let prevClose = (candles[0].open + candles[0].high + candles[0].low + candles[0].close) / 4;
  candles.forEach((candle, index) => {
    const haClose = (candle.open + candle.high + candle.low + candle.close) / 4;
    const haOpen = index === 0 ? prevOpen : (prevOpen + prevClose) / 2;
    const haHigh = Math.max(candle.high, haOpen, haClose);
    const haLow = Math.min(candle.low, haOpen, haClose);
    ha.push({ ...candle, open: haOpen, high: haHigh, low: haLow, close: haClose });
    prevOpen = haOpen;
    prevClose = haClose;
  });
  return ha;
}

function detectHeikenAshiTrend(candles) {
  const haCandles = buildHeikenAshiCandles(candles);
  if (haCandles.length < 5) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "HEIKEN" };
  }
  const recent = haCandles.slice(-5);
  let bull = 0;
  let bear = 0;
  recent.forEach((candle) => {
    if (candle.close > candle.open) bull += 1;
    else if (candle.close < candle.open) bear += 1;
  });
  const trend = bull >= 4 ? "UP" : bear >= 4 ? "DOWN" : "SIDEWAYS";
  return {
    trend,
    trendStrength: clamp(Math.abs(bull - bear) / recent.length, 0, 1),
    modeLabel: "HEIKEN",
  };
}

function detectRenkoTrend(candles) {
  if (candles.length < 10) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "RENKO" };
  }
  const closes = candles.map((candle) => candle.close);
  const brickSize = Math.max(averageRange(candles, 14) * 0.8, currentPip || 0.0001);
  if (!brickSize) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "RENKO" };
  }
  const bricks = [];
  let anchor = closes[0];
  for (let i = 1; i < closes.length; i += 1) {
    let diff = closes[i] - anchor;
    while (Math.abs(diff) >= brickSize) {
      const direction = diff > 0 ? 1 : -1;
      anchor += brickSize * direction;
      bricks.push(direction);
      diff = closes[i] - anchor;
    }
  }
  const recent = bricks.slice(-6);
  if (!recent.length) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "RENKO" };
  }
  const score = recent.reduce((sum, brick) => sum + brick, 0);
  return {
    trend: score >= 3 ? "UP" : score <= -3 ? "DOWN" : "SIDEWAYS",
    trendStrength: clamp(Math.abs(score) / recent.length, 0, 1),
    modeLabel: "RENKO",
  };
}

function detectMacdTrend(candles) {
  if (candles.length < 35) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "MACD" };
  }
  const closes = candles.map((c) => c.close);
  const macdLine = macdLineSeries(closes, 12, 26);
  const signalLine = emaSeries(macdLine.map((v) => Number(v ?? 0)), 9);
  const macd = macdLine[macdLine.length - 1];
  const signal = signalLine[signalLine.length - 1];
  if (!Number.isFinite(macd) || !Number.isFinite(signal)) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "MACD" };
  }
  const diff = macd - signal;
  return {
    trend: diff > 0 ? "UP" : diff < 0 ? "DOWN" : "SIDEWAYS",
    trendStrength: clamp(Math.abs(diff) / Math.max(Math.abs(macd), Math.abs(signal), 0.0001), 0, 1),
    modeLabel: "MACD",
  };
}

function detectStochTrend(candles, period = 14) {
  if (candles.length < period + 3) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "STOCH" };
  }
  const recent = candles.slice(-(period + 3));
  const stochValues = [];
  for (let i = period - 1; i < recent.length; i += 1) {
    const window = recent.slice(i - period + 1, i + 1);
    const highest = Math.max(...window.map((c) => c.high));
    const lowest = Math.min(...window.map((c) => c.low));
    const close = recent[i].close;
    const value = highest === lowest ? 50 : ((close - lowest) / (highest - lowest)) * 100;
    stochValues.push(value);
  }
  const current = stochValues[stochValues.length - 1];
  const previous = stochValues[stochValues.length - 2];
  const trend = current > previous && current >= 55 ? "UP" : current < previous && current <= 45 ? "DOWN" : "SIDEWAYS";
  return {
    trend,
    trendStrength: clamp(Math.abs(current - previous) / 20, 0, 1),
    modeLabel: "STOCH",
  };
}

function assessCandleContinuation(candles) {
  if (candles.length < 3) {
    return { bullScore: 0, bearScore: 0, bodyStrength: 0 };
  }
  const recent = candles.slice(-3);
  const avgRange = averageRange(recent, recent.length) || 1;
  let bullScore = 0;
  let bearScore = 0;
  let bodyTotal = 0;

  recent.forEach((candle) => {
    const body = Math.abs(candle.close - candle.open);
    const upperWick = candle.high - Math.max(candle.open, candle.close);
    const lowerWick = Math.min(candle.open, candle.close) - candle.low;
    const bodyRatio = clamp(body / avgRange, 0, 1);
    bodyTotal += bodyRatio;

    if (candle.close > candle.open && upperWick <= body * 0.75) {
      bullScore += 1;
    }
    if (candle.close < candle.open && lowerWick <= body * 0.75) {
      bearScore += 1;
    }
  });

  return {
    bullScore,
    bearScore,
    bodyStrength: clamp(bodyTotal / recent.length, 0, 1),
  };
}

function assessPullbackBehavior(candles, trendState) {
  if (candles.length < 8 || trendState.trend === "SIDEWAYS") {
    return { valid: false, score: 0 };
  }
  const recent = candles.slice(-8);
  const closes = recent.map((candle) => candle.close);
  const ema9 = calculateEMA(closes, Math.min(9, closes.length));
  const ema21 = calculateEMA(closes, Math.min(21, closes.length));
  const current = recent[recent.length - 1];
  const previous = recent[recent.length - 2];
  const avgRange = averageRange(recent, recent.length) || 1;

  if (trendState.trend === "UP") {
    const dip = Math.max(0, Math.max(previous.close, ema9 || previous.close) - current.low);
    const heldEmas = current.close >= (ema21 || current.close);
    return {
      valid: heldEmas && dip <= avgRange * 1.4,
      score: clamp(1 - (dip / (avgRange * 1.4 || 1)), 0, 1),
    };
  }

  const bounce = Math.max(0, current.high - Math.min(previous.close, ema9 || previous.close));
  const heldEmas = current.close <= (ema21 || current.close);
  return {
    valid: heldEmas && bounce <= avgRange * 1.4,
    score: clamp(1 - (bounce / (avgRange * 1.4 || 1)), 0, 1),
  };
}

function detectStackTrend(candles) {
  if (candles.length < 50) {
    return { trend: "SIDEWAYS", trendStrength: 0, modeLabel: "STACK" };
  }

  const closes = candles.map((c) => c.close);
  const ema9 = calculateEMA(closes, 9);
  const ema21 = calculateEMA(closes, 21);
  const ema50 = calculateEMA(closes, 50);
  const structureState = detectStructureTrend(candles);
  const rsi = calculateRSI(candles, 14);
  const candleState = assessCandleContinuation(candles);
  const emaTrend =
    ema9 > ema21 && ema21 > ema50 ? "UP" :
    ema9 < ema21 && ema21 < ema50 ? "DOWN" :
    "SIDEWAYS";
  const pullbackState = assessPullbackBehavior(candles, { trend: emaTrend });
  const momentumTrend = rsi == null ? "SIDEWAYS" : rsi > 50 ? "UP" : rsi < 50 ? "DOWN" : "SIDEWAYS";

  let trend = "SIDEWAYS";
  if (
    emaTrend === "UP" &&
    structureState.trend === "UP" &&
    momentumTrend === "UP" &&
    candleState.bullScore >= 2 &&
    pullbackState.valid
  ) {
    trend = "UP";
  } else if (
    emaTrend === "DOWN" &&
    structureState.trend === "DOWN" &&
    momentumTrend === "DOWN" &&
    candleState.bearScore >= 2 &&
    pullbackState.valid
  ) {
    trend = "DOWN";
  }

  const emaScore = emaTrend === "SIDEWAYS" ? 0 : 1;
  const structureScore = structureState.trend === "SIDEWAYS" ? 0 : structureState.trendStrength;
  const rsiScore = rsi == null ? 0 : clamp(Math.abs(rsi - 50) / 20, 0, 1);
  const candleScore =
    trend === "UP" ? clamp(candleState.bullScore / 3, 0, 1) :
    trend === "DOWN" ? clamp(candleState.bearScore / 3, 0, 1) :
    0;
  const trendStrength = trend === "SIDEWAYS"
    ? 0
    : clamp((emaScore * 0.3) + (structureScore * 0.25) + (rsiScore * 0.2) + (candleScore * 0.15) + (pullbackState.score * 0.1), 0, 1);

  return {
    trend,
    trendStrength,
    ema9,
    ema21,
    ema50,
    rsi,
    structureBias: structureState.structureBias,
    pullbackValid: pullbackState.valid,
    modeLabel: "STACK",
  };
}

function detectTrend(candles, mode = currentTrendMode) {
  if (mode === "SMC") return detectStructureTrend(candles);
  if (mode === "HEIKEN") return detectHeikenAshiTrend(candles);
  if (mode === "RENKO") return detectRenkoTrend(candles);
  if (mode === "MACD") return detectMacdTrend(candles);
  if (mode === "STOCH") return detectStochTrend(candles);
  if (mode === "AVG") return detectAverageTrend(candles);
  if (mode === "OBV") return detectObvTrend(candles);
  if (mode === "STACK") return detectStackTrend(candles);
  return detectEmaTrend(candles);
}

function findSwingPoints(candles, pivotLen = 2) {
  const highs = [];
  const lows = [];
  for (let i = pivotLen; i < candles.length - pivotLen; i += 1) {
    const high = candles[i].high;
    const low = candles[i].low;
    let isHigh = true;
    let isLow = true;
    for (let j = i - pivotLen; j <= i + pivotLen; j += 1) {
      if (j === i) continue;
      if (candles[j].high >= high) isHigh = false;
      if (candles[j].low <= low) isLow = false;
      if (!isHigh && !isLow) break;
    }
    if (isHigh) highs.push({ index: i, price: high });
    if (isLow) lows.push({ index: i, price: low });
  }
  return { highs, lows };
}

function findRecentOpposingOrderBlock(candles, direction, lookback = 10) {
  const start = Math.max(0, candles.length - 2 - lookback);
  for (let i = candles.length - 2; i >= start; i -= 1) {
    const candle = candles[i];
    const bearish = candle.close < candle.open;
    const bullish = candle.close > candle.open;
    if (direction === "UP" && bearish) {
      return { index: i, top: candle.open, bottom: candle.low, ref: candle.close };
    }
    if (direction === "DOWN" && bullish) {
      return { index: i, top: candle.high, bottom: candle.open, ref: candle.close };
    }
  }
  return null;
}

function detectSmcSetupState(candles, trendState) {
  if (candles.length < 12) return "--";
  const { highs, lows } = findSwingPoints(candles, 2);
  const current = candles[candles.length - 1];
  const avgRange = averageRange(candles, 14) || Math.max(Math.abs(current.close) * 0.001, currentPip || 0.0001);
  const threshold = avgRange * 0.35;
  const lastHigh = highs[highs.length - 1] || null;
  const prevHigh = highs[highs.length - 2] || null;
  const lastLow = lows[lows.length - 1] || null;
  const prevLow = lows[lows.length - 2] || null;

  if (trendState.trend === "UP") {
    const bosLevel = lastHigh?.price ?? prevHigh?.price ?? null;
    const bullishOb = findRecentOpposingOrderBlock(candles, "UP");
    if (bosLevel != null && current.close > bosLevel + threshold) {
      if (bullishOb && current.low <= bullishOb.top + threshold && current.low >= bullishOb.bottom - threshold) {
        return "Bullish BOS, retracing to bullish OB";
      }
      return "Bullish BOS confirmed, impulse active";
    }
    if (bosLevel != null && Math.abs(current.low - bosLevel) <= threshold) {
      return "Bullish retrace into BOS level";
    }
    if (bullishOb && current.low <= bullishOb.top + threshold && current.low >= bullishOb.bottom - threshold) {
      return "Bullish retrace into last bearish OB";
    }
    if (prevLow && lastLow && lastLow.price > prevLow.price) {
      return "Holding HL, waiting for bullish BOS";
    }
    return "Bullish structure building";
  }

  if (trendState.trend === "DOWN") {
    const bosLevel = lastLow?.price ?? prevLow?.price ?? null;
    const bearishOb = findRecentOpposingOrderBlock(candles, "DOWN");
    if (bosLevel != null && current.close < bosLevel - threshold) {
      if (bearishOb && current.high >= bearishOb.bottom - threshold && current.high <= bearishOb.top + threshold) {
        return "Bearish BOS, retracing to bearish OB";
      }
      return "Bearish BOS confirmed, impulse active";
    }
    if (bosLevel != null && Math.abs(current.high - bosLevel) <= threshold) {
      return "Bearish retrace into BOS level";
    }
    if (bearishOb && current.high >= bearishOb.bottom - threshold && current.high <= bearishOb.top + threshold) {
      return "Bearish retrace into last bullish OB";
    }
    if (prevHigh && lastHigh && lastHigh.price < prevHigh.price) {
      return "Holding LH, waiting for bearish BOS";
    }
    return "Bearish structure building";
  }

  if (lastHigh && lastLow) {
    return "Range structure, waiting for sweep or BOS";
  }
  return "Waiting for structure";
}

function detectDivergence(candles, obv, lookback = 5) {
  if (candles.length < lookback + 1 || obv.length < candles.length) return null;
  const i = candles.length - 1;
  let priceHigh = -Infinity;
  let priceLow = Infinity;
  let obvHigh = -Infinity;
  let obvLow = Infinity;

  for (let j = i - lookback; j < i; j++) {
    priceHigh = Math.max(priceHigh, candles[j].high);
    priceLow = Math.min(priceLow, candles[j].low);
    obvHigh = Math.max(obvHigh, obv[j]);
    obvLow = Math.min(obvLow, obv[j]);
  }

  const current = candles[i];
  if (current.high >= priceHigh && obv[i] < obvHigh) return "SELL";
  if (current.low <= priceLow && obv[i] > obvLow) return "BUY";
  return null;
}

function collectEqualLevels(candles, side, threshold) {
  const recent = candles.slice(-SIGNAL_EQUAL_LEVEL_LOOKBACK);
  const levels = [];
  for (let i = 1; i < recent.length; i++) {
    const current = side === "high" ? recent[i].high : recent[i].low;
    const previous = side === "high" ? recent[i - 1].high : recent[i - 1].low;
    if (Math.abs(current - previous) <= threshold) {
      levels.push((current + previous) / 2);
    }
  }
  return levels;
}

function analyzeRejection(candle) {
  const upperWick = candle.high - Math.max(candle.open, candle.close);
  const lowerWick = Math.min(candle.open, candle.close) - candle.low;
  const body = Math.abs(candle.close - candle.open);
  const safeBody = Math.max(body, currentPip || 0.0001);
  return {
    upperWick,
    lowerWick,
    body,
    safeBody,
    strongSellRejection: upperWick > safeBody * 1.5,
    strongBuyRejection: lowerWick > safeBody * 1.5,
    bullishConfirm: candle.close > candle.open,
    bearishConfirm: candle.close < candle.open,
  };
}

function assessCloseStructure(candles, options = {}) {
  if (!Array.isArray(candles) || candles.length < 4) {
    return {
      bias: "MIXED",
      bullScore: 0,
      bearScore: 0,
      bullishBreak: false,
      bearishBreak: false,
      closeLocation: 0.5,
      reclaimedLevel: false,
      lostLevel: false,
    };
  }

  const current = candles[candles.length - 1];
  const previous = candles.slice(-4, -1);
  const structureWindow = candles.slice(-6, -1);
  const avgRange = averageRange(candles, Math.min(8, candles.length)) || Math.max(Math.abs(current.close) * 0.001, currentPip || 0.0001);
  const threshold = getLevelThreshold(structureWindow.length ? structureWindow : candles.slice(0, -1));
  const range = Math.max(current.high - current.low, currentPip || 0.0001);
  const closeLocation = clamp((current.close - current.low) / range, 0, 1);
  const priorCloseHigh = Math.max(...previous.map((candle) => candle.close));
  const priorCloseLow = Math.min(...previous.map((candle) => candle.close));
  const priorHigh = Math.max(...structureWindow.map((candle) => candle.high));
  const priorLow = Math.min(...structureWindow.map((candle) => candle.low));
  const higherCloseCount = previous.filter((candle, index) => index === 0 ? false : candle.close > previous[index - 1].close).length
    + (current.close > previous[previous.length - 1].close ? 1 : 0);
  const lowerCloseCount = previous.filter((candle, index) => index === 0 ? false : candle.close < previous[index - 1].close).length
    + (current.close < previous[previous.length - 1].close ? 1 : 0);
  const body = Math.abs(current.close - current.open);
  const bodyStrength = clamp(body / avgRange, 0, 1);
  const bullishBody = current.close > current.open ? 1 : 0;
  const bearishBody = current.close < current.open ? 1 : 0;
  const bullishBreak = current.close > priorCloseHigh + (threshold * 0.2);
  const bearishBreak = current.close < priorCloseLow - (threshold * 0.2);
  const reclaimedLevel = current.close >= priorLow + (avgRange * 0.18);
  const lostLevel = current.close <= priorHigh - (avgRange * 0.18);
  const bullScore = clamp(
    (higherCloseCount / 3) * 0.28 +
    closeLocation * 0.22 +
    (bullishBreak ? 0.22 : 0) +
    bodyStrength * 0.18 +
    bullishBody * 0.1,
    0,
    1
  );
  const bearScore = clamp(
    (lowerCloseCount / 3) * 0.28 +
    ((1 - closeLocation) * 0.22) +
    (bearishBreak ? 0.22 : 0) +
    bodyStrength * 0.18 +
    bearishBody * 0.1,
    0,
    1
  );
  const bias =
    bullScore >= 0.55 && bullScore > bearScore + 0.08 ? "UP" :
    bearScore >= 0.55 && bearScore > bullScore + 0.08 ? "DOWN" :
    "MIXED";

  return {
    bias,
    bullScore,
    bearScore,
    bullishBreak,
    bearishBreak,
    closeLocation,
    reclaimedLevel,
    lostLevel,
    priorHigh,
    priorLow,
  };
}

function detectLiquiditySweepState(candles) {
  if (candles.length < MIN_SIGNAL_CANDLES) {
    return {
      sweepType: null,
      sweepLabel: "--",
      rejectionLabel: "--",
      referenceLevel: null,
      penetration: 0,
      wickStrength: 0,
      candleStrength: 0,
      levelStrength: 0,
      rejection: null,
    };
  }

  const current = candles[candles.length - 1];
  const structureCandles = candles.slice(-(SIGNAL_STRUCTURE_LOOKBACK + 1), -1);
  const previousHigh = Math.max(...structureCandles.map((c) => c.high));
  const previousLow = Math.min(...structureCandles.map((c) => c.low));
  const threshold = getLevelThreshold(structureCandles);
  const equalHighs = collectEqualLevels(structureCandles, "high", threshold);
  const equalLows = collectEqualLevels(structureCandles, "low", threshold);
  const highLiquidity = equalHighs.length ? Math.max(previousHigh, ...equalHighs) : previousHigh;
  const lowLiquidity = equalLows.length ? Math.min(previousLow, ...equalLows) : previousLow;
  const rejection = analyzeRejection(current);
  const avgRange = averageRange(structureCandles) || threshold || 1;

  let sweepType = null;
  let referenceLevel = null;
  let penetration = 0;

  if (current.high > highLiquidity && current.close < highLiquidity) {
    sweepType = "SELL";
    referenceLevel = highLiquidity;
    penetration = current.high - highLiquidity;
  } else if (current.low < lowLiquidity && current.close > lowLiquidity) {
    sweepType = "BUY";
    referenceLevel = lowLiquidity;
    penetration = lowLiquidity - current.low;
  }

  const wick = sweepType === "SELL" ? rejection.upperWick : sweepType === "BUY" ? rejection.lowerWick : 0;
  const wickStrength = sweepType ? clamp(wick / (rejection.safeBody * 3), 0, 1) : 0;
  const candleStrength = clamp(rejection.safeBody / avgRange, 0, 1);
  const levelStrength = sweepType ? clamp(penetration / avgRange, 0, 1) : 0;
  let rejectionLabel = "WEAK";
  if (sweepType === "BUY" && rejection.strongBuyRejection && rejection.bullishConfirm) rejectionLabel = "BUY REJECT";
  if (sweepType === "SELL" && rejection.strongSellRejection && rejection.bearishConfirm) rejectionLabel = "SELL REJECT";

  return {
    sweepType,
    sweepLabel: sweepType ? `SWEEP_${sweepType}` : "--",
    rejectionLabel,
    referenceLevel,
    penetration,
    wickStrength,
    candleStrength,
    levelStrength,
    rejection,
  };
}

function detectLiquiditySweepEvent(candles, index, lookback = SIGNAL_STRUCTURE_LOOKBACK) {
  if (!Array.isArray(candles) || index <= 0) return null;
  const current = candles[index];
  const structureCandles = candles.slice(Math.max(0, index - lookback), index);
  if (!current || structureCandles.length < 5) return null;

  const previousHigh = Math.max(...structureCandles.map((c) => c.high));
  const previousLow = Math.min(...structureCandles.map((c) => c.low));
  const threshold = getLevelThreshold(structureCandles);
  const equalHighs = collectEqualLevels(structureCandles, "high", threshold);
  const equalLows = collectEqualLevels(structureCandles, "low", threshold);
  const highLiquidity = equalHighs.length ? Math.max(previousHigh, ...equalHighs) : previousHigh;
  const lowLiquidity = equalLows.length ? Math.min(previousLow, ...equalLows) : previousLow;

  if (current.high > highLiquidity && current.close < highLiquidity) {
    return {
      sweepType: "SELL",
      liquidityLabel: "BSL",
      referenceLevel: highLiquidity,
      extremeLevel: current.high,
      candle: current,
      candleIndex: index,
    };
  }

  if (current.low < lowLiquidity && current.close > lowLiquidity) {
    return {
      sweepType: "BUY",
      liquidityLabel: "SSL",
      referenceLevel: lowLiquidity,
      extremeLevel: current.low,
      candle: current,
      candleIndex: index,
    };
  }

  return null;
}

function isPivotHigh(candles, index, length = 3) {
  if (index < length || index >= candles.length - length) return false;
  const value = candles[index].high;
  for (let offset = 1; offset <= length; offset += 1) {
    if (candles[index - offset].high >= value || candles[index + offset].high > value) return false;
  }
  return true;
}

function isPivotLow(candles, index, length = 3) {
  if (index < length || index >= candles.length - length) return false;
  const value = candles[index].low;
  for (let offset = 1; offset <= length; offset += 1) {
    if (candles[index - offset].low <= value || candles[index + offset].low < value) return false;
  }
  return true;
}

function isPivotHighLR(candles, index, leftLen = 3, rightLen = 3) {
  if (index < leftLen || index >= candles.length - rightLen) return false;
  const value = candles[index].high;
  for (let offset = 1; offset <= leftLen; offset += 1) {
    if (candles[index - offset].high >= value) return false;
  }
  for (let offset = 1; offset <= rightLen; offset += 1) {
    if (candles[index + offset].high > value) return false;
  }
  return true;
}

function isPivotLowLR(candles, index, leftLen = 3, rightLen = 3) {
  if (index < leftLen || index >= candles.length - rightLen) return false;
  const value = candles[index].low;
  for (let offset = 1; offset <= leftLen; offset += 1) {
    if (candles[index - offset].low <= value) return false;
  }
  for (let offset = 1; offset <= rightLen; offset += 1) {
    if (candles[index + offset].low < value) return false;
  }
  return true;
}

function buildICTStructureAnalysis(candles, pivotLength = 3) {
  const pivotHighs = [];
  const pivotLows = [];
  for (let i = pivotLength; i < candles.length - pivotLength; i += 1) {
    if (isPivotHigh(candles, i, pivotLength)) pivotHighs.push({ index: i, price: candles[i].high });
    if (isPivotLow(candles, i, pivotLength)) pivotLows.push({ index: i, price: candles[i].low });
  }

  const events = [];
  let trend = 0;
  let highPtr = 0;
  let lowPtr = 0;
  let lastHigh = null;
  let lastLow = null;
  let lastHighBroken = false;
  let lastLowBroken = false;

  for (let i = 0; i < candles.length; i += 1) {
    while (highPtr < pivotHighs.length && pivotHighs[highPtr].index <= i) {
      lastHigh = pivotHighs[highPtr];
      lastHighBroken = false;
      highPtr += 1;
    }
    while (lowPtr < pivotLows.length && pivotLows[lowPtr].index <= i) {
      lastLow = pivotLows[lowPtr];
      lastLowBroken = false;
      lowPtr += 1;
    }

    const candle = candles[i];
    if (lastHigh && !lastHighBroken && candle.close > lastHigh.price) {
      events.push({
        type: trend >= 0 ? "BOS" : "MSS",
        direction: "UP",
        pivotIndex: lastHigh.index,
        pivotPrice: lastHigh.price,
        breakIndex: i,
        breakPrice: candle.close,
        oppositePivot: lastLow,
      });
      trend = 1;
      lastHighBroken = true;
    }

    if (lastLow && !lastLowBroken && candle.close < lastLow.price) {
      events.push({
        type: trend <= 0 ? "BOS" : "MSS",
        direction: "DOWN",
        pivotIndex: lastLow.index,
        pivotPrice: lastLow.price,
        breakIndex: i,
        breakPrice: candle.close,
        oppositePivot: lastHigh,
      });
      trend = -1;
      lastLowBroken = true;
    }
  }

  return { pivotHighs, pivotLows, events };
}

function buildICTFVGs(candles, activeLimit = 3) {
  const bull = [];
  const bear = [];
  for (let i = 2; i < candles.length; i += 1) {
    if (candles[i].low > candles[i - 2].high) {
      bull.push({
        direction: "UP",
        startIndex: i - 1,
        endIndex: i,
        top: candles[i].low,
        bottom: candles[i - 2].high,
      });
    }
    if (candles[i].high < candles[i - 2].low) {
      bear.push({
        direction: "DOWN",
        startIndex: i - 1,
        endIndex: i,
        top: candles[i - 2].low,
        bottom: candles[i].high,
      });
    }
  }

  const finalizeZones = (zones, direction) => zones.map((zone) => {
    let mitigationIndex = null;
    for (let i = zone.endIndex + 1; i < candles.length; i += 1) {
      if (direction === "UP" && candles[i].low < zone.bottom) {
        mitigationIndex = i;
        break;
      }
      if (direction === "DOWN" && candles[i].high > zone.top) {
        mitigationIndex = i;
        break;
      }
    }
    return {
      ...zone,
      mitigationIndex,
      active: mitigationIndex == null,
      drawEndIndex: mitigationIndex ?? (candles.length - 1),
    };
  }).slice(-activeLimit);

  const bullish = finalizeZones(bull, "UP");
  const bearish = finalizeZones(bear, "DOWN");
  const bprs = [];

  bullish.forEach((bullZone) => {
    bearish.forEach((bearZone) => {
      const overlapEnd = Math.min(bullZone.drawEndIndex, bearZone.drawEndIndex);
      const top = Math.min(bullZone.top, bearZone.top);
      const bottom = Math.max(bullZone.bottom, bearZone.bottom);
      if (top > bottom && overlapEnd >= Math.max(bullZone.startIndex, bearZone.startIndex)) {
        bprs.push({
          startIndex: Math.min(bullZone.startIndex, bearZone.startIndex),
          endIndex: overlapEnd,
          top,
          bottom,
        });
      }
    });
  });

  return { bullish, bearish, bprs: bprs.slice(-2) };
}

function buildICTOrderBlocks(candles, structureEvents, activeLimit = 2) {
  const bullish = [];
  const bearish = [];

  structureEvents.forEach((event) => {
    const from = Math.max(0, event.pivotIndex - 6);
    if (event.direction === "UP") {
      for (let i = event.breakIndex - 1; i >= from; i -= 1) {
        if (candles[i].close < candles[i].open) {
          bullish.push({
            direction: "UP",
            index: i,
            top: candles[i].high,
            bottom: candles[i].low,
          });
          break;
        }
      }
    } else {
      for (let i = event.breakIndex - 1; i >= from; i -= 1) {
        if (candles[i].close > candles[i].open) {
          bearish.push({
            direction: "DOWN",
            index: i,
            top: candles[i].high,
            bottom: candles[i].low,
          });
          break;
        }
      }
    }
  });

  const dedupe = (zones) => {
    const seen = new Set();
    return zones.filter((zone) => {
      const key = `${zone.index}:${zone.top}:${zone.bottom}`;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  };

  const finalizeZones = (zones, direction) => dedupe(zones).map((zone) => {
    let mitigationIndex = null;
    for (let i = zone.index + 1; i < candles.length; i += 1) {
      if (direction === "UP" && candles[i].close < zone.bottom) {
        mitigationIndex = i;
        break;
      }
      if (direction === "DOWN" && candles[i].close > zone.top) {
        mitigationIndex = i;
        break;
      }
    }
    return {
      ...zone,
      mitigationIndex,
      active: mitigationIndex == null,
      drawEndIndex: mitigationIndex ?? (candles.length - 1),
    };
  }).slice(-activeLimit);

  return {
    bullish: finalizeZones(bullish, "UP"),
    bearish: finalizeZones(bearish, "DOWN"),
  };
}

function buildWeloSmartMoneyConcepts(candles, options = {}) {
  const source = Array.isArray(candles) ? candles.filter(Boolean) : [];
  const minCandles = Number(options.minCandles ?? 45);
  if (source.length < minCandles) {
    return {
      bias: "NEUTRAL",
      confidence: 0,
      swings: [],
      structureEvents: [],
      orderBlocks: [],
      breakerBlocks: [],
      fvgs: [],
      bprs: [],
      equalHighs: [],
      equalLows: [],
      sweeps: [],
      trendlines: [],
      signals: [],
      summary: "Waiting for SMC structure",
    };
  }

  const pivotLen = Math.max(2, Number(options.pivotLen ?? 4));
  const lookback = Math.max(80, Number(options.lookback ?? 260));
  const offset = Math.max(0, source.length - lookback);
  const candlesSlice = source.slice(offset);
  const addOffset = (item) => ({
    ...item,
    index: Number.isInteger(item.index) ? item.index + offset : item.index,
    startIndex: Number.isInteger(item.startIndex) ? item.startIndex + offset : item.startIndex,
    endIndex: Number.isInteger(item.endIndex) ? item.endIndex + offset : item.endIndex,
    drawEndIndex: Number.isInteger(item.drawEndIndex) ? item.drawEndIndex + offset : item.drawEndIndex,
    pivotIndex: Number.isInteger(item.pivotIndex) ? item.pivotIndex + offset : item.pivotIndex,
    breakIndex: Number.isInteger(item.breakIndex) ? item.breakIndex + offset : item.breakIndex,
    mitigationIndex: Number.isInteger(item.mitigationIndex) ? item.mitigationIndex + offset : item.mitigationIndex,
    oppositePivot: item.oppositePivot ? { ...item.oppositePivot, index: item.oppositePivot.index + offset } : item.oppositePivot,
  });

  const structureSlice = buildICTStructureAnalysis(candlesSlice, pivotLen);
  const structureEvents = structureSlice.events.map(addOffset);
  const pivotHighs = structureSlice.pivotHighs.map((point) => ({ ...point, type: "HIGH", index: point.index + offset }));
  const pivotLows = structureSlice.pivotLows.map((point) => ({ ...point, type: "LOW", index: point.index + offset }));
  const swings = [...pivotHighs, ...pivotLows].sort((a, b) => a.index - b.index).map((point, index, all) => {
    const previousSame = [...all.slice(0, index)].reverse().find((candidate) => candidate.type === point.type);
    let label = point.type === "HIGH" ? "H" : "L";
    if (previousSame) {
      label = point.type === "HIGH"
        ? (point.price > previousSame.price ? "HH" : "LH")
        : (point.price < previousSame.price ? "LL" : "HL");
    }
    return { ...point, label };
  });

  const fvgSlice = buildICTFVGs(candlesSlice, Number(options.fvgLimit ?? 8));
  const fvgs = [
    ...fvgSlice.bullish.map((zone) => ({ ...addOffset(zone), type: "FVG", direction: "UP" })),
    ...fvgSlice.bearish.map((zone) => ({ ...addOffset(zone), type: "FVG", direction: "DOWN" })),
  ].sort((a, b) => a.startIndex - b.startIndex);
  const bprs = fvgSlice.bprs.map((zone) => ({ ...addOffset(zone), type: "BPR" }));
  const orderBlockSlice = buildICTOrderBlocks(candlesSlice, structureSlice.events, Number(options.orderBlockLimit ?? 5));
  const rawOrderBlocks = [
    ...orderBlockSlice.bullish.map((zone) => ({ ...addOffset(zone), type: "OB", direction: "UP" })),
    ...orderBlockSlice.bearish.map((zone) => ({ ...addOffset(zone), type: "OB", direction: "DOWN" })),
  ].sort((a, b) => a.index - b.index);
  const orderBlocks = rawOrderBlocks.filter((zone) => zone.active);
  const breakerBlocks = rawOrderBlocks
    .filter((zone) => !zone.active && Number.isInteger(zone.mitigationIndex))
    .slice(-4)
    .map((zone) => ({
      ...zone,
      type: "BREAKER",
      direction: zone.direction === "UP" ? "DOWN" : "UP",
      index: zone.mitigationIndex,
      drawEndIndex: source.length - 1,
    }));

  const priceRange = Math.max(
    ...candlesSlice.map((candle) => candle.high),
  ) - Math.min(
    ...candlesSlice.map((candle) => candle.low),
  );
  const tolerance = Math.max(
    Number(options.equalTolerance ?? 0),
    priceRange * Number(options.equalTolerancePct ?? 0.0014),
    (currentPip || 0.0001) * 4,
  );
  const buildEqualLevels = (points, type) => {
    const levels = [];
    for (let i = 1; i < points.length; i += 1) {
      const a = points[i - 1];
      const b = points[i];
      if (Math.abs(a.price - b.price) <= tolerance) {
        levels.push({
          type,
          startIndex: a.index,
          endIndex: b.index,
          price: (a.price + b.price) / 2,
          label: type === "HIGH" ? "EQH" : "EQL",
        });
      }
    }
    return levels.slice(-5);
  };
  const equalHighs = buildEqualLevels(pivotHighs, "HIGH");
  const equalLows = buildEqualLevels(pivotLows, "LOW");

  const sweeps = [];
  for (let index = Math.max(0, source.length - 80); index < source.length; index += 1) {
    const event = detectLiquiditySweepEvent(source, index, 14);
    if (event) sweeps.push(event);
  }

  const trendlines = [];
  const recentHighs = pivotHighs.slice(-3);
  const recentLows = pivotLows.slice(-3);
  if (recentHighs.length >= 2) trendlines.push({ type: "HIGH", from: recentHighs[recentHighs.length - 2], to: recentHighs[recentHighs.length - 1] });
  if (recentLows.length >= 2) trendlines.push({ type: "LOW", from: recentLows[recentLows.length - 2], to: recentLows[recentLows.length - 1] });

  const latestStructure = structureEvents[structureEvents.length - 1] || null;
  const latestSweep = sweeps[sweeps.length - 1] || null;
  const latestFvg = fvgs.filter((zone) => zone.active).slice(-1)[0] || null;
  const latestOb = orderBlocks.slice(-1)[0] || null;
  const bias = latestStructure?.direction === "UP" ? "BUY" : latestStructure?.direction === "DOWN" ? "SELL" : "NEUTRAL";
  let confidence = bias === "NEUTRAL" ? 0 : 58;
  if (latestStructure?.type === "MSS") confidence += 9;
  if (latestSweep && ((bias === "BUY" && latestSweep.sweepType === "SELL") || (bias === "SELL" && latestSweep.sweepType === "BUY"))) confidence += 8;
  if (latestFvg && ((bias === "BUY" && latestFvg.direction === "UP") || (bias === "SELL" && latestFvg.direction === "DOWN"))) confidence += 6;
  if (latestOb && ((bias === "BUY" && latestOb.direction === "UP") || (bias === "SELL" && latestOb.direction === "DOWN"))) confidence += 6;
  confidence = clamp(Math.round(confidence), 0, 92);

  const signals = [];
  if (bias !== "NEUTRAL" && confidence >= 60) {
    signals.push({
      direction: bias,
      entryIndex: source.length - 1,
      price: source[source.length - 1]?.close,
      confidence,
      reason: [
        latestStructure ? `${latestStructure.type === "MSS" ? "CHOCH" : "BOS"} ${latestStructure.direction}` : null,
        latestSweep ? latestSweep.liquidityLabel : null,
        latestOb ? "active order block" : null,
        latestFvg ? "imbalance" : null,
      ].filter(Boolean).join(" + "),
    });
  }

  return {
    bias,
    confidence,
    swings: swings.slice(-18),
    structureEvents: structureEvents.slice(-14),
    orderBlocks: orderBlocks.slice(-6),
    breakerBlocks,
    fvgs: fvgs.filter((zone) => zone.active).slice(-7),
    bprs,
    equalHighs,
    equalLows,
    sweeps: sweeps.slice(-8),
    trendlines,
    signals,
    summary: bias === "NEUTRAL" ? "No SMC bias" : `${bias} ${confidence}% smart money confluence`,
  };
}

function getInstitutionalSmcHierarchy(baseSeconds = getChartTimeframeSeconds()) {
  const source = Math.max(1, Number(baseSeconds) || DEFAULT_TIMEFRAME_SEC);
  let htf = 900;
  let itf = 300;
  let ltf = 60;
  if (source <= 60) {
    htf = 900;
    itf = 300;
    ltf = 60;
  } else if (source <= 300) {
    htf = 3600;
    itf = 900;
    ltf = 300;
  } else if (source <= 900) {
    htf = 14400;
    itf = 3600;
    ltf = 900;
  } else {
    htf = 86400;
    itf = 14400;
    ltf = Math.min(source, 3600);
  }
  return {
    sourceSeconds: source,
    htfSeconds: htf,
    itfSeconds: itf,
    ltfSeconds: ltf,
    htfLabel: getTimeframeLabel(htf).toUpperCase(),
    itfLabel: getTimeframeLabel(itf).toUpperCase(),
    ltfLabel: getTimeframeLabel(ltf).toUpperCase(),
  };
}

function getInstitutionalSmcCandles(symbol, timeframeSeconds, fallbackCandles, fallbackSeconds) {
  const target = Math.max(1, Number(timeframeSeconds) || fallbackSeconds || getChartTimeframeSeconds());
  const base = Math.max(1, Number(fallbackSeconds) || getChartTimeframeSeconds());
  const source = Array.isArray(fallbackCandles) ? fallbackCandles.filter(Boolean) : [];
  if (!source.length) return [];
  if (target === base) return source;
  if (replayEngine?.isReplayMode?.()) {
    return target >= base ? aggregateCandlesByTimeframe(source, target) : source;
  }
  return resolveTopDownCandles(symbol, target, source, base);
}

function buildInstitutionalSmcStructureEngine(candles, label = "") {
  const source = Array.isArray(candles) ? candles.filter(Boolean) : [];
  const smc = buildWeloSmartMoneyConcepts(source, {
    pivotLen: source.length > 160 ? 5 : 4,
    lookback: 320,
    orderBlockLimit: 10,
    fvgLimit: 14,
    minCandles: 35,
  });
  const latestStructure = smc.structureEvents[smc.structureEvents.length - 1] || null;
  const recentEvents = smc.structureEvents.slice(-5);
  const upEvents = recentEvents.filter((event) => event.direction === "UP").length;
  const downEvents = recentEvents.filter((event) => event.direction === "DOWN").length;
  const bias = smc.bias === "BUY"
    ? "BULLISH"
    : smc.bias === "SELL"
      ? "BEARISH"
      : upEvents > downEvents
        ? "BULLISH"
        : downEvents > upEvents
          ? "BEARISH"
          : "RANGE";
  const majorHigh = smc.swings.filter((swing) => swing.type === "HIGH").slice(-1)[0] || null;
  const majorLow = smc.swings.filter((swing) => swing.type === "LOW").slice(-1)[0] || null;
  return {
    label,
    candles: source,
    smc,
    bias,
    confidence: smc.confidence || (bias === "RANGE" ? 35 : 55),
    latestStructure,
    latestBos: [...smc.structureEvents].reverse().find((event) => event.type === "BOS") || null,
    latestChoch: [...smc.structureEvents].reverse().find((event) => event.type === "MSS") || null,
    majorHigh,
    majorLow,
  };
}

function buildInstitutionalSmcLiquidityEngine(frame) {
  const smc = frame?.smc || {};
  const latestSweep = (smc.sweeps || [])[smc.sweeps.length - 1] || null;
  const pools = [
    ...(smc.equalHighs || []).map((zone) => ({ ...zone, side: "BSL", price: zone.price ?? zone.level })),
    ...(smc.equalLows || []).map((zone) => ({ ...zone, side: "SSL", price: zone.price ?? zone.level })),
  ].filter((zone) => Number.isFinite(zone.price));
  return {
    pools: pools.slice(-8),
    sweeps: (smc.sweeps || []).slice(-8),
    latestSweep,
    direction: latestSweep?.sweepType === "SELL" ? "BUY" : latestSweep?.sweepType === "BUY" ? "SELL" : null,
  };
}

function buildInstitutionalSmcFvgEngine(frame) {
  const zones = (frame?.smc?.fvgs || [])
    .filter((zone) => zone.active !== false && Number.isFinite(zone.top) && Number.isFinite(zone.bottom))
    .map((zone) => ({
      ...zone,
      kind: "FVG",
      score: Math.abs(zone.top - zone.bottom),
    }))
    .sort((a, b) => b.score - a.score);
  return { zones: zones.slice(0, 6), strongest: zones[0] || null };
}

function buildInstitutionalSmcOrderBlockEngine(frame) {
  const zones = [
    ...(frame?.smc?.orderBlocks || []).map((zone) => ({ ...zone, kind: "OB" })),
    ...(frame?.smc?.breakerBlocks || []).map((zone) => ({ ...zone, kind: "Breaker" })),
  ].filter((zone) => Number.isFinite(zone.top) && Number.isFinite(zone.bottom));
  const active = zones.filter((zone) => zone.active !== false).slice(-8);
  return { zones: active, strongest: active[active.length - 1] || null };
}

function isPriceInsideZone(price, zone, tolerance = 0) {
  if (!Number.isFinite(price) || !zone || !Number.isFinite(zone.top) || !Number.isFinite(zone.bottom)) return false;
  const top = Math.max(zone.top, zone.bottom) + tolerance;
  const bottom = Math.min(zone.top, zone.bottom) - tolerance;
  return price <= top && price >= bottom;
}

function buildInstitutionalSmcPoiScoringEngine({ htf, itf, ltf, currentPrice }) {
  const htfOb = buildInstitutionalSmcOrderBlockEngine(htf);
  const htfFvg = buildInstitutionalSmcFvgEngine(htf);
  const itfOb = buildInstitutionalSmcOrderBlockEngine(itf);
  const itfFvg = buildInstitutionalSmcFvgEngine(itf);
  const ltfLiquidity = buildInstitutionalSmcLiquidityEngine(ltf);
  const ltfRange = averageRange(ltf.candles || [], 24) || Math.abs((ltf.candles?.at?.(-1)?.close || 0) * 0.001);
  const tolerance = Math.max(ltfRange * 0.35, Math.abs(currentPrice || 0) * 0.00002);
  const directionalBias = htf.bias === "BULLISH" ? "BUY" : htf.bias === "BEARISH" ? "SELL" : null;
  const ltfStructureDirection = ltf.latestStructure?.direction === "UP" ? "BUY" : ltf.latestStructure?.direction === "DOWN" ? "SELL" : null;
  const direction = ltfLiquidity.direction || ltfStructureDirection || directionalBias;
  let score = 0;
  const conditions = [];
  const htfObHit = htfOb.zones.find((zone) => (!direction || zone.direction === (direction === "BUY" ? "UP" : "DOWN")) && isPriceInsideZone(currentPrice, zone, tolerance));
  const htfFvgHit = htfFvg.zones.find((zone) => (!direction || zone.direction === (direction === "BUY" ? "UP" : "DOWN")) && isPriceInsideZone(currentPrice, zone, tolerance));
  const itfPoiHit = [...itfOb.zones, ...itfFvg.zones].find((zone) => isPriceInsideZone(currentPrice, zone, tolerance * 1.2));
  const latest = ltf.candles?.[ltf.candles.length - 1] || null;
  const prev = ltf.candles?.[ltf.candles.length - 2] || null;
  const displacement = latest && Number.isFinite(ltfRange) && ltfRange > 0
    ? Math.abs(latest.close - latest.open) >= ltfRange * 0.8
    : false;
  const rangeExpansion = latest && prev && Number.isFinite(ltfRange) && ltfRange > 0
    ? Math.abs(latest.high - latest.low) >= ltfRange * 1.15
    : false;

  if (htfObHit) { score += 25; conditions.push("HTF order block"); }
  if (htfFvgHit) { score += 20; conditions.push("HTF fair value gap"); }
  if (itfPoiHit) { score += 10; conditions.push("ITF refinement POI"); }
  if (ltfLiquidity.direction && (!directionalBias || ltfLiquidity.direction === directionalBias)) { score += 20; conditions.push("liquidity sweep"); }
  if (ltf.latestChoch && (!direction || ltf.latestChoch.direction === (direction === "BUY" ? "UP" : "DOWN"))) { score += 15; conditions.push("LTF CHOCH"); }
  if (ltf.latestBos && (!direction || ltf.latestBos.direction === (direction === "BUY" ? "UP" : "DOWN"))) { score += 10; conditions.push("LTF BOS"); }
  if (displacement) { score += 10; conditions.push("displacement"); }
  if (rangeExpansion) { score += 10; conditions.push("range expansion"); }
  if (directionalBias && direction && direction === directionalBias) { score += 8; conditions.push("HTF bias aligned"); }
  if (itf.bias !== "RANGE" && direction && ((itf.bias === "BULLISH" && direction === "BUY") || (itf.bias === "BEARISH" && direction === "SELL"))) {
    score += 7;
    conditions.push("ITF structure aligned");
  }

  score = clamp(Math.round(score), 0, 100);
  const grade = score >= 90 ? "A+" : score >= 80 ? "A" : score >= 70 ? "B" : score >= 60 ? "C" : "D";
  return {
    score,
    grade,
    direction: score >= 60 && direction ? direction : null,
    conditions,
    htfObHit,
    htfFvgHit,
    itfPoiHit,
    htfOb,
    htfFvg,
    itfOb,
    itfFvg,
    ltfLiquidity,
  };
}

function buildInstitutionalSmcSignalEngine(scoreEngine, ltf, currentPrice) {
  const direction = scoreEngine.direction;
  const action = direction || (scoreEngine.score >= 45 ? "WAIT" : "NO TRADE");
  const latest = ltf.candles?.[ltf.candles.length - 1] || null;
  return {
    action,
    direction,
    entryIndex: latest ? ltf.candles.length - 1 : null,
    entryTime: latest ? Number(latest.time ?? latest.epoch) : null,
    price: Number.isFinite(currentPrice) ? currentPrice : latest?.close,
    confidence: scoreEngine.score,
    grade: scoreEngine.grade,
    reason: scoreEngine.conditions.slice(0, 5).join(" + ") || "waiting for institutional confluence",
  };
}

function buildInstitutionalSmcStatisticsEngine(signals, candles, lookahead = 5) {
  const source = Array.isArray(candles) ? candles : [];
  const completed = (signals || []).filter((signal) => Number.isInteger(signal.entryIndex) && signal.entryIndex + lookahead < source.length);
  let wins = 0;
  let losses = 0;
  completed.forEach((signal) => {
    const entry = source[signal.entryIndex];
    const future = source.slice(signal.entryIndex + 1, signal.entryIndex + 1 + lookahead);
    const risk = Math.max(averageRange(source.slice(0, signal.entryIndex + 1), 20), Math.abs(entry?.close || 0) * 0.0002);
    const target = signal.direction === "BUY" ? entry.close + risk : entry.close - risk;
    const stop = signal.direction === "BUY" ? entry.close - risk : entry.close + risk;
    const hitTarget = future.some((candle) => signal.direction === "BUY" ? candle.high >= target : candle.low <= target);
    const hitStop = future.some((candle) => signal.direction === "BUY" ? candle.low <= stop : candle.high >= stop);
    if (hitTarget && !hitStop) wins += 1;
    else if (hitStop && !hitTarget) losses += 1;
    else if (hitTarget && hitStop) losses += 1;
  });
  const total = wins + losses;
  return {
    total,
    wins,
    losses,
    winRate: total ? Math.round((wins / total) * 100) : 0,
    profitFactor: losses ? Number((wins / losses).toFixed(2)) : wins ? wins : 0,
    expectancy: total ? Number(((wins - losses) / total).toFixed(2)) : 0,
  };
}

function buildInstitutionalSmcAiAnalysisEngine(engine) {
  const signalText = engine.signal.direction
    ? `${engine.signal.direction} ${engine.signal.grade} (${engine.signal.confidence}/100)`
    : `${engine.signal.action} (${engine.score}/100)`;
  return `${signalText}. HTF ${engine.frames.htf.bias} on ${engine.hierarchy.htfLabel}, ITF ${engine.frames.itf.bias} on ${engine.hierarchy.itfLabel}, LTF ${engine.frames.ltf.bias} on ${engine.hierarchy.ltfLabel}. ${engine.signal.reason}.`;
}

function buildInstitutionalSmcEngine(candles, options = {}) {
  const source = Array.isArray(candles) ? candles.filter(Boolean) : [];
  const baseSeconds = Math.max(1, Number(options.baseSeconds) || getChartTimeframeSeconds());
  const symbol = options.symbol || currentSymbol;
  const hierarchy = getInstitutionalSmcHierarchy(baseSeconds);
  if (source.length < 50) {
    return {
      hierarchy,
      frames: {},
      score: 0,
      grade: "D",
      direction: null,
      signal: { action: "WAIT", direction: null, confidence: 0, grade: "D", reason: "waiting for candles" },
      signals: [],
      stats: buildInstitutionalSmcStatisticsEngine([], source),
      aiSummary: "Waiting for institutional SMC candles.",
      replaySafe: Boolean(replayEngine?.isReplayMode?.()),
    };
  }

  const htfCandles = getInstitutionalSmcCandles(symbol, hierarchy.htfSeconds, source, baseSeconds);
  const itfCandles = getInstitutionalSmcCandles(symbol, hierarchy.itfSeconds, source, baseSeconds);
  const ltfCandles = getInstitutionalSmcCandles(symbol, hierarchy.ltfSeconds, source, baseSeconds);
  const htf = buildInstitutionalSmcStructureEngine(htfCandles.length >= 35 ? htfCandles : source, hierarchy.htfLabel);
  const itf = buildInstitutionalSmcStructureEngine(itfCandles.length >= 35 ? itfCandles : source, hierarchy.itfLabel);
  const ltf = buildInstitutionalSmcStructureEngine(ltfCandles.length >= 35 ? ltfCandles : source, hierarchy.ltfLabel);
  const currentPrice = Number(source[source.length - 1]?.close);
  const scoring = buildInstitutionalSmcPoiScoringEngine({ htf, itf, ltf, currentPrice });
  const signal = buildInstitutionalSmcSignalEngine(scoring, ltf, currentPrice);
  const historicalSignals = (ltf.smc.signals || [])
    .filter((item) => item.confidence >= 60)
    .slice(-24)
    .map((item) => ({
      ...item,
      direction: item.direction,
      confidence: item.confidence,
      grade: item.confidence >= 90 ? "A+" : item.confidence >= 80 ? "A" : item.confidence >= 70 ? "B" : "C",
      conditions: item.reason ? item.reason.split(" + ") : [],
    }));
  if (signal.direction && Number.isInteger(signal.entryIndex)) {
    historicalSignals.push({
      direction: signal.direction,
      entryIndex: signal.entryIndex,
      price: signal.price,
      confidence: signal.confidence,
      grade: signal.grade,
      reason: signal.reason,
      conditions: scoring.conditions,
    });
  }
  const stats = buildInstitutionalSmcStatisticsEngine(historicalSignals, ltf.candles);
  const engine = {
    hierarchy,
    frames: { htf, itf, ltf },
    scoring,
    score: scoring.score,
    grade: scoring.grade,
    direction: signal.direction,
    signal,
    signals: historicalSignals,
    stats,
    poiZones: [
      ...scoring.htfOb.zones.slice(-3).map((zone) => ({ ...zone, layer: "HTF OB" })),
      ...scoring.htfFvg.zones.slice(-3).map((zone) => ({ ...zone, layer: "HTF FVG" })),
      ...scoring.itfOb.zones.slice(-2).map((zone) => ({ ...zone, layer: "ITF OB" })),
      ...scoring.itfFvg.zones.slice(-2).map((zone) => ({ ...zone, layer: "ITF FVG" })),
    ],
    heatmap: {
      active: scoring.score >= 70,
      direction: signal.direction,
      zones: [scoring.htfObHit, scoring.htfFvgHit, scoring.itfPoiHit].filter(Boolean),
    },
    replaySafe: Boolean(replayEngine?.isReplayMode?.()),
  };
  engine.aiSummary = buildInstitutionalSmcAiAnalysisEngine(engine);
  engine.summary = signal.direction
    ? `${signal.direction} ${signal.grade} ${signal.confidence}% institutional SMC`
    : `${signal.action} ${scoring.score}% institutional SMC`;
  return engine;
}

function buildICTFibLevels(structureEvents) {
  if (!Array.isArray(structureEvents) || !structureEvents.length) return null;

  const sourceEvent = [...structureEvents]
    .reverse()
    .find((event) => {
      if (!event?.oppositePivot) return false;
      if (!Number.isFinite(event.pivotPrice) || !Number.isFinite(event.oppositePivot.price)) return false;
      if (!Number.isInteger(event.breakIndex) || !Number.isInteger(event.pivotIndex)) return false;
      return Math.abs(event.pivotPrice - event.oppositePivot.price) > (currentPip || 0.0001) * 10;
    });

  if (!sourceEvent) return null;

  const bullish = sourceEvent.direction === "UP";
  const swingLow = bullish ? sourceEvent.oppositePivot.price : sourceEvent.pivotPrice;
  const swingHigh = bullish ? sourceEvent.pivotPrice : sourceEvent.oppositePivot.price;
  const range = swingHigh - swingLow;
  if (!Number.isFinite(range) || range <= 0) return null;

  const makeRetracement = (ratio) => bullish
    ? swingHigh - (range * ratio)
    : swingLow + (range * ratio);

  return {
    direction: sourceEvent.direction,
    startIndex: Math.min(sourceEvent.pivotIndex, sourceEvent.oppositePivot.index ?? sourceEvent.pivotIndex),
    endIndex: sourceEvent.breakIndex,
    swingLow,
    swingHigh,
    levels: [
      { label: "0.0", price: bullish ? swingHigh : swingLow, color: "#6b7280" },
      { label: "0.5", price: makeRetracement(0.5), color: "#9aa7b8" },
      { label: "0.618", price: makeRetracement(0.618), color: "#0db787" },
      { label: "0.705", price: makeRetracement(0.705), color: "#5ce1ff" },
      { label: "0.79", price: makeRetracement(0.79), color: "#f2c94c" },
      { label: "1.0", price: bullish ? swingLow : swingHigh, color: "#6b7280" },
    ],
  };
}

function getKillzoneKey(epochSec) {
  const shifted = new Date((epochSec - (5 * 3600)) * 1000);
  const hours = shifted.getUTCHours();
  const minutes = shifted.getUTCMinutes();
  const total = (hours * 60) + minutes;
  if (total >= 1200 || total < 0) return "ASIA";
  if (total >= 120 && total < 300) return "LONDON";
  if (total >= 510 && total < 660) return "NYAM";
  if (total >= 810 && total < 960) return "NYPM";
  return null;
}

function buildICTKillzones(points, startIndex) {
  const colors = {
    ASIA: "rgba(45, 140, 255, 0.08)",
    LONDON: "rgba(13, 183, 135, 0.08)",
    NYAM: "rgba(225, 91, 100, 0.08)",
    NYPM: "rgba(242, 201, 76, 0.08)",
  };
  const segments = [];
  let current = null;
  for (let i = 0; i < points.length; i += 1) {
    const key = getKillzoneKey(points[i].time);
    if (!key) {
      if (current) segments.push(current);
      current = null;
      continue;
    }
    const absoluteIndex = startIndex + i;
    if (!current || current.key !== key) {
      if (current) segments.push(current);
      current = { key, startIndex: absoluteIndex, endIndex: absoluteIndex, color: colors[key] };
    } else {
      current.endIndex = absoluteIndex;
    }
  }
  if (current) segments.push(current);
  return segments;
}

function getLastPivotBefore(pivots, index) {
  let result = null;
  for (let i = 0; i < pivots.length; i += 1) {
    if (pivots[i].index >= index) break;
    result = pivots[i];
  }
  return result;
}

function detectBullishFVGAt(candles, index) {
  if (index < 2) return null;
  if (candles[index].low > candles[index - 2].high) {
    return {
      index: index - 1,
      top: candles[index].low,
      bottom: candles[index - 2].high,
    };
  }
  return null;
}

function detectBearishFVGAt(candles, index) {
  if (index < 2) return null;
  if (candles[index].high < candles[index - 2].low) {
    return {
      index: index - 1,
      top: candles[index - 2].low,
      bottom: candles[index].high,
    };
  }
  return null;
}

function buildSMCSetup08(candles, swingPeriod = 5) {
  if (!Array.isArray(candles) || candles.length < Math.max(40, swingPeriod * 4)) {
    return { bullish: [], bearish: [] };
  }

  const pivotHighs = [];
  const pivotLows = [];
  for (let i = swingPeriod; i < candles.length - swingPeriod; i += 1) {
    if (isPivotHigh(candles, i, swingPeriod)) pivotHighs.push({ index: i, price: candles[i].high });
    if (isPivotLow(candles, i, swingPeriod)) pivotLows.push({ index: i, price: candles[i].low });
  }

  const bullCandidates = [];
  const bearCandidates = [];
  const bullish = [];
  const bearish = [];
  const pendingBullish = [];
  const pendingBearish = [];

  for (let i = 0; i < candles.length; i += 1) {
    const candle = candles[i];
    const lastHigh = getLastPivotBefore(pivotHighs, i);
    const lastLow = getLastPivotBefore(pivotLows, i);

    if (lastLow) {
      const age = i - lastLow.index;
      if (age >= swingPeriod + 2 && age <= 100 && candle.low < lastLow.price && candle.close > lastLow.price) {
        const chochPivot = getLastPivotBefore(pivotHighs, i);
        if (chochPivot) {
          bullCandidates.push({
            active: true,
            direction: "BULL",
            status: "TRACKING",
            swingIndex: lastLow.index,
            swingPrice: lastLow.price,
            levelIndex: chochPivot.index,
            levelPrice: chochPivot.price,
            poiIndex: i,
            poiFillIndex: null,
            poiTop: candle.high,
            poiBottom: candle.low,
            levelBreakIndex: null,
            fvg: null,
            triggerIndex: null,
          });
        }
      }
    }

    if (lastHigh) {
      const age = i - lastHigh.index;
      if (age >= swingPeriod + 2 && age <= 70 && candle.high > lastHigh.price && candle.close < lastHigh.price) {
        const chochPivot = getLastPivotBefore(pivotLows, i);
        if (chochPivot) {
          bearCandidates.push({
            active: true,
            direction: "BEAR",
            status: "TRACKING",
            swingIndex: lastHigh.index,
            swingPrice: lastHigh.price,
            levelIndex: chochPivot.index,
            levelPrice: chochPivot.price,
            poiIndex: i,
            poiFillIndex: null,
            poiTop: candle.high,
            poiBottom: candle.low,
            levelBreakIndex: null,
            fvg: null,
            triggerIndex: null,
          });
        }
      }
    }

    bullCandidates.forEach((candidate) => {
      if (!candidate.active || i <= candidate.poiIndex) return;
      if (candidate.poiBottom > candle.close) {
        candidate.active = false;
        return;
      }

      const latestHigh = getLastPivotBefore(pivotHighs, i);
      if (!candidate.levelBreakIndex && latestHigh && latestHigh.price > candidate.levelPrice) {
        candidate.levelIndex = latestHigh.index;
        candidate.levelPrice = latestHigh.price;
      }

      if (candidate.poiFillIndex == null && i >= candidate.poiIndex + swingPeriod) {
        if (candidate.poiTop > candle.low && candle.close > candidate.poiBottom) {
          candidate.poiFillIndex = i;
          candidate.status = "POI";
        }
      }

      if (candidate.levelBreakIndex == null && candle.close > candidate.levelPrice) {
        candidate.levelBreakIndex = i;
        candidate.status = "CHOCH";
      }

      if (!candidate.fvg && candidate.poiFillIndex != null) {
        const fvg = detectBullishFVGAt(candles, i);
        if (fvg) {
          candidate.fvg = fvg;
          candidate.status = "FVG";
        }
      } else if (candidate.fvg) {
        if (candle.low < candidate.fvg.top && candle.close > candidate.fvg.bottom && candidate.levelBreakIndex != null) {
          candidate.triggerIndex = i;
          candidate.status = "TRIGGERED";
          bullish.push(candidate);
          candidate.active = false;
        } else if (candle.close < candidate.fvg.bottom) {
          candidate.active = false;
        }
      }
    });

    bearCandidates.forEach((candidate) => {
      if (!candidate.active || i <= candidate.poiIndex) return;
      if (candidate.poiTop < candle.close) {
        candidate.active = false;
        return;
      }

      const latestLow = getLastPivotBefore(pivotLows, i);
      if (!candidate.levelBreakIndex && latestLow && latestLow.price < candidate.levelPrice) {
        candidate.levelIndex = latestLow.index;
        candidate.levelPrice = latestLow.price;
      }

      if (candidate.poiFillIndex == null && i >= candidate.poiIndex + swingPeriod) {
        if (candidate.poiBottom < candle.high) {
          candidate.poiFillIndex = i;
          candidate.status = "POI";
        }
      }

      if (candidate.levelBreakIndex == null && candle.close < candidate.levelPrice) {
        candidate.levelBreakIndex = i;
        candidate.status = "CHOCH";
      }

      if (!candidate.fvg && candidate.poiFillIndex != null) {
        const fvg = detectBearishFVGAt(candles, i);
        if (fvg) {
          candidate.fvg = fvg;
          candidate.status = "FVG";
        }
      } else if (candidate.fvg) {
        if (candle.high > candidate.fvg.bottom && candle.close < candidate.fvg.top && candidate.levelBreakIndex != null) {
          candidate.triggerIndex = i;
          candidate.status = "TRIGGERED";
          bearish.push(candidate);
          candidate.active = false;
        } else if (candle.close > candidate.fvg.top) {
          candidate.active = false;
        }
      }
    });
  }

  bullCandidates.forEach((candidate) => {
    if (!candidate.active) return;
    if (candidate.fvg || candidate.levelBreakIndex != null || candidate.poiFillIndex != null) {
      pendingBullish.push(candidate);
    }
  });

  bearCandidates.forEach((candidate) => {
    if (!candidate.active) return;
    if (candidate.fvg || candidate.levelBreakIndex != null || candidate.poiFillIndex != null) {
      pendingBearish.push(candidate);
    }
  });

  const mergeRecent = (completed, pending) => {
    const seen = new Set(completed.map((item) => `${item.direction}:${item.poiIndex}:${item.swingIndex}`));
    pending.forEach((item) => {
      const key = `${item.direction}:${item.poiIndex}:${item.swingIndex}`;
      if (!seen.has(key)) completed.push(item);
    });
    return completed
      .sort((a, b) => {
        const aIndex = a.triggerIndex ?? a.fvg?.index ?? a.levelBreakIndex ?? a.poiFillIndex ?? a.poiIndex;
        const bIndex = b.triggerIndex ?? b.fvg?.index ?? b.levelBreakIndex ?? b.poiFillIndex ?? b.poiIndex;
        return aIndex - bIndex;
      })
      .slice(-3);
  };

  return {
    bullish: mergeRecent(bullish, pendingBullish),
    bearish: mergeRecent(bearish, pendingBearish),
  };
}

function simpleMovingAverage(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  let sum = 0;
  for (let i = 0; i < values.length; i += 1) {
    sum += Number(values[i] || 0);
    if (i >= period) sum -= Number(values[i - period] || 0);
    if (i >= period - 1) result[i] = sum / period;
  }
  return result;
}

function rollingStdDev(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  for (let i = period - 1; i < values.length; i += 1) {
    const window = values.slice(i - period + 1, i + 1);
    const mean = window.reduce((sum, value) => sum + value, 0) / period;
    const variance = window.reduce((sum, value) => sum + ((value - mean) ** 2), 0) / period;
    result[i] = Math.sqrt(variance);
  }
  return result;
}

function rmaSeries(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  if (values.length < period) return result;
  let seed = 0;
  for (let i = 0; i < period; i += 1) seed += Number(values[i] || 0);
  let prev = seed / period;
  result[period - 1] = prev;
  for (let i = period; i < values.length; i += 1) {
    prev = ((prev * (period - 1)) + Number(values[i] || 0)) / period;
    result[i] = prev;
  }
  return result;
}

function emaSeries(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  if (values.length < period) return result;
  const k = 2 / (period + 1);
  let prev = values.slice(0, period).reduce((sum, value) => sum + Number(value || 0), 0) / period;
  result[period - 1] = prev;
  for (let i = period; i < values.length; i += 1) {
    prev = (Number(values[i] || 0) * k) + (prev * (1 - k));
    result[i] = prev;
  }
  return result;
}

function weightedMovingAverage(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  const divisor = (period * (period + 1)) / 2;
  for (let i = period - 1; i < values.length; i += 1) {
    let sum = 0;
    for (let j = 0; j < period; j += 1) {
      sum += Number(values[i - j] || 0) * (period - j);
    }
    result[i] = sum / divisor;
  }
  return result;
}

function volumeWeightedMovingAverage(values, volumes, period) {
  if (!Array.isArray(values) || !values.length || !Array.isArray(volumes) || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  for (let i = period - 1; i < values.length; i += 1) {
    let weightedSum = 0;
    let volumeSum = 0;
    for (let j = i - period + 1; j <= i; j += 1) {
      const volume = Number(volumes[j] || 0);
      weightedSum += Number(values[j] || 0) * volume;
      volumeSum += volume;
    }
    result[i] = volumeSum > 0 ? weightedSum / volumeSum : null;
  }
  return result;
}

function hullMovingAverage(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const half = Math.max(1, Math.round(period / 2));
  const sqrtLen = Math.max(1, Math.round(Math.sqrt(period)));
  const wmaFull = weightedMovingAverage(values, period);
  const wmaHalf = weightedMovingAverage(values, half);
  const diff = values.map((_, index) => {
    const full = wmaFull[index];
    const halfVal = wmaHalf[index];
    return Number.isFinite(full) && Number.isFinite(halfVal) ? (2 * halfVal) - full : null;
  });
  return weightedMovingAverage(diff.map((value) => value ?? 0), sqrtLen);
}

function superSmootherSeries(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  const a1 = Math.exp((-1.414 * Math.PI) / period);
  const b1 = 2 * a1 * Math.cos((1.414 * Math.PI) / period);
  const c2 = b1;
  const c3 = -a1 * a1;
  const c1 = 1 - c2 - c3;
  for (let i = 0; i < values.length; i += 1) {
    const src = Number(values[i] || 0);
    const prevSrc = Number(values[i - 1] ?? src);
    const prev1 = Number(result[i - 1] ?? 0);
    const prev2 = Number(result[i - 2] ?? 0);
    result[i] = (c1 * (src + prevSrc) / 2) + (c2 * prev1) + (c3 * prev2);
  }
  return result;
}

function zeroLagEmaSeries(values, period) {
  const ema1 = emaSeries(values, period);
  const ema2 = emaSeries(ema1.map((value) => value ?? 0), period);
  return values.map((_, index) => {
    const a = ema1[index];
    const b = ema2[index];
    return Number.isFinite(a) && Number.isFinite(b) ? a + (a - b) : null;
  });
}

function doubleEmaSeries(values, period) {
  const ema1 = emaSeries(values, period);
  const ema2 = emaSeries(ema1.map((value) => value ?? 0), period);
  return values.map((_, index) => {
    const a = ema1[index];
    const b = ema2[index];
    return Number.isFinite(a) && Number.isFinite(b) ? (2 * a) - b : null;
  });
}

function tripleEmaSeries(values, period) {
  const ema1 = emaSeries(values, period);
  const ema2 = emaSeries(ema1.map((value) => value ?? 0), period);
  const ema3 = emaSeries(ema2.map((value) => value ?? 0), period);
  return values.map((_, index) => {
    const a = ema1[index];
    const b = ema2[index];
    const c = ema3[index];
    return Number.isFinite(a) && Number.isFinite(b) && Number.isFinite(c) ? (3 * (a - b)) + c : null;
  });
}

function triangularMovingAverage(values, period) {
  return simpleMovingAverage(simpleMovingAverage(values, period).map((value) => value ?? 0), period);
}

function movingAverageVariant(type, values, period, volumes = []) {
  switch (type) {
    case "EMA": return emaSeries(values, period);
    case "WMA": return weightedMovingAverage(values, period);
    case "VWMA": return volumeWeightedMovingAverage(values, volumes, period);
    case "SMMA": return rmaSeries(values, period);
    case "DEMA": return doubleEmaSeries(values, period);
    case "TEMA": return tripleEmaSeries(values, period);
    case "HullMA": return hullMovingAverage(values, period);
    case "SSMA": return superSmootherSeries(values, period);
    case "ZEMA": return zeroLagEmaSeries(values, period);
    case "TMA": return triangularMovingAverage(values, period);
    case "SMA":
    default:
      return simpleMovingAverage(values, period);
  }
}

function rollingLowest(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  for (let i = period - 1; i < values.length; i += 1) {
    let low = Number.POSITIVE_INFINITY;
    for (let j = i - period + 1; j <= i; j += 1) low = Math.min(low, Number(values[j] || 0));
    result[i] = low;
  }
  return result;
}

function rollingHighest(values, period) {
  if (!Array.isArray(values) || !values.length || period <= 0) return [];
  const result = new Array(values.length).fill(null);
  for (let i = period - 1; i < values.length; i += 1) {
    let high = Number.NEGATIVE_INFINITY;
    for (let j = i - period + 1; j <= i; j += 1) high = Math.max(high, Number(values[j] || 0));
    result[i] = high;
  }
  return result;
}

function rsiSeries(values, period = 14) {
  if (!Array.isArray(values) || values.length < period + 1) return [];
  const result = new Array(values.length).fill(null);
  let gains = 0;
  let losses = 0;
  for (let i = 1; i <= period; i += 1) {
    const change = Number(values[i] || 0) - Number(values[i - 1] || 0);
    if (change >= 0) gains += change;
    else losses -= change;
  }
  let avgGain = gains / period;
  let avgLoss = losses / period;
  result[period] = avgLoss === 0 ? 100 : 100 - (100 / (1 + (avgGain / avgLoss)));
  for (let i = period + 1; i < values.length; i += 1) {
    const change = Number(values[i] || 0) - Number(values[i - 1] || 0);
    const gain = Math.max(change, 0);
    const loss = Math.max(-change, 0);
    avgGain = ((avgGain * (period - 1)) + gain) / period;
    avgLoss = ((avgLoss * (period - 1)) + loss) / period;
    result[i] = avgLoss === 0 ? 100 : 100 - (100 / (1 + (avgGain / avgLoss)));
  }
  return result;
}

function macdLineSeries(values, fast = 12, slow = 26) {
  const fastEma = emaSeries(values, fast);
  const slowEma = emaSeries(values, slow);
  return values.map((_, index) => (
    Number.isFinite(fastEma[index]) && Number.isFinite(slowEma[index])
      ? fastEma[index] - slowEma[index]
      : null
  ));
}

function zScoreSeries(values, length) {
  const ma = simpleMovingAverage(values.map((v) => Number(v ?? 0)), length);
  const sd = rollingStdDev(values.map((v) => Number(v ?? 0)), length);
  return values.map((value, index) => {
    if (!Number.isFinite(value) || !Number.isFinite(ma[index]) || !Number.isFinite(sd[index])) return null;
    return (value - ma[index]) / (sd[index] === 0 ? 1 : sd[index]);
  });
}

function tanhApprox(x) {
  const e2x = Math.exp(2 * x);
  return (e2x - 1) / (e2x + 1);
}

function buildDynamicZDivergence(candles, config = {}) {
  const lenZ = config.lenZ ?? 100;
  const smoothLen = config.smoothLen ?? 10;
  const slopeIndex = config.slopeIndex ?? 1;
  const lookbackLeft = config.lookbackLeft ?? 15;
  const lookbackRight = config.lookbackRight ?? 1;
  const rangeMin = config.rangeMin ?? 5;
  const rangeMax = config.rangeMax ?? 60;
  const saRsiLen = config.saRsiLen ?? 21;
  const saZLen = config.saZLen ?? 200;
  const saBaseLen = config.saBaseLen ?? 80;
  const saIntensity = config.saIntensity ?? 0.15;
  const saSlopeIndex = config.saSlopeIndex ?? 1;
  const saBandAtrLen = config.saBandAtrLen ?? 14;
  const saBandMult = config.saBandMult ?? 1.4;

  if (!Array.isArray(candles) || candles.length < Math.max(saZLen, lenZ, lookbackLeft + lookbackRight + 10)) {
    return { buySignals: [], sellSignals: [], bullDivs: [], bearDivs: [], saema: [], saUpper: [], saLower: [], saColor: [] };
  }

  const closes = candles.map((c) => c.close);
  const highs = candles.map((c) => c.high);
  const lows = candles.map((c) => c.low);

  const rsi14 = rsiSeries(closes, 14);
  const rZ = zScoreSeries(rsi14, lenZ);

  const rsiLow14 = rollingLowest(rsi14.map((v) => v ?? 0), 14);
  const rsiHigh14 = rollingHighest(rsi14.map((v) => v ?? 0), 14);
  const stochRsi = rsi14.map((value, index) => {
    if (!Number.isFinite(value) || !Number.isFinite(rsiLow14[index]) || !Number.isFinite(rsiHigh14[index])) return null;
    const denom = rsiHigh14[index] - rsiLow14[index];
    return denom === 0 ? 0 : ((value - rsiLow14[index]) / denom) * 100;
  });
  const kZ = zScoreSeries(stochRsi, lenZ);

  const macdLine = macdLineSeries(closes, 12, 26);
  const mZ = zScoreSeries(macdLine, lenZ);

  const avgZ = closes.map((_, index) => {
    const values = [rZ[index], kZ[index], mZ[index]].filter(Number.isFinite);
    if (!values.length) return null;
    return values.reduce((sum, value) => sum + value, 0) / values.length;
  });
  const mainLine = emaSeries(avgZ.map((v) => v ?? 0), smoothLen);

  const buySignals = [];
  const sellSignals = [];
  const bullDivs = [];
  const bearDivs = [];

  let prevPL = null;
  let prevPH = null;
  const innerUpper = 1.0;
  const innerLower = -1.0;

  for (let i = slopeIndex * 2; i < candles.length; i += 1) {
    const prevA = mainLine[i - slopeIndex];
    const prevB = mainLine[i - (slopeIndex * 2)];
    const curr = mainLine[i];
    if (Number.isFinite(prevA) && Number.isFinite(prevB) && Number.isFinite(curr)) {
      const slopePrev = prevA - prevB;
      const slopeCurr = curr - prevA;
      const slopeFlip = slopePrev * slopeCurr < 0;
      if (slopeFlip && slopePrev < 0 && slopeCurr > 0 && curr < innerLower) {
        buySignals.push({ index: i, entryIndex: i + 1 < candles.length ? i + 1 : null, value: curr });
      }
      if (slopeFlip && slopePrev > 0 && slopeCurr < 0 && curr > innerUpper) {
        sellSignals.push({ index: i, entryIndex: i + 1 < candles.length ? i + 1 : null, value: curr });
      }
    }

    const pivotIndex = i - lookbackRight;
    if (pivotIndex >= lookbackLeft && pivotIndex < candles.length - lookbackRight) {
      if (isPivotLowLR(candles.map((c, idx) => ({ ...c, low: Number.isFinite(mainLine[idx]) ? mainLine[idx] : Number.POSITIVE_INFINITY })), pivotIndex, lookbackLeft, lookbackRight)) {
        const currPivot = { z: mainLine[pivotIndex], price: lows[pivotIndex], index: pivotIndex };
        if (
          prevPL &&
          currPivot.z > prevPL.z &&
          currPivot.price < prevPL.price &&
          currPivot.index - prevPL.index >= rangeMin &&
          currPivot.index - prevPL.index <= rangeMax
        ) {
          bullDivs.push({ ...currPivot, entryIndex: i + 1 < candles.length ? i + 1 : null });
        }
        prevPL = currPivot;
      }
      if (isPivotHighLR(candles.map((c, idx) => ({ ...c, high: Number.isFinite(mainLine[idx]) ? mainLine[idx] : Number.NEGATIVE_INFINITY })), pivotIndex, lookbackLeft, lookbackRight)) {
        const currPivot = { z: mainLine[pivotIndex], price: highs[pivotIndex], index: pivotIndex };
        if (
          prevPH &&
          currPivot.z < prevPH.z &&
          currPivot.price > prevPH.price &&
          currPivot.index - prevPH.index >= rangeMin &&
          currPivot.index - prevPH.index <= rangeMax
        ) {
          bearDivs.push({ ...currPivot, entryIndex: i + 1 < candles.length ? i + 1 : null });
        }
        prevPH = currPivot;
      }
    }
  }

  const saRsi = rsiSeries(closes, saRsiLen);
  const saRsiMa = simpleMovingAverage(saRsi.map((v) => v ?? 0), saZLen);
  const saRsiSd = rollingStdDev(saRsi.map((v) => v ?? 0), saZLen);
  const zSoft = closes.map((_, index) => {
    if (!Number.isFinite(saRsi[index]) || !Number.isFinite(saRsiMa[index]) || !Number.isFinite(saRsiSd[index])) return null;
    const zRaw = (saRsi[index] - saRsiMa[index]) / (saRsiSd[index] === 0 ? 1 : saRsiSd[index]);
    return tanhApprox(zRaw * 0.4);
  });
  const baseAlpha = 2 / saBaseLen;
  const saema = new Array(candles.length).fill(null);
  for (let i = 0; i < candles.length; i += 1) {
    const src = closes[i];
    if (i === 0) {
      saema[i] = src;
      continue;
    }
    const alpha = baseAlpha + ((Math.abs(zSoft[i] ?? 0)) * saIntensity);
    saema[i] = saema[i - 1] + (alpha * (src - saema[i - 1]));
  }
  const saSlope = saema.map((value, index) => (
    index >= saSlopeIndex && Number.isFinite(value) && Number.isFinite(saema[index - saSlopeIndex])
      ? value - saema[index - saSlopeIndex]
      : null
  ));
  const saAtr = rmaSeries(candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  }), saBandAtrLen);
  const saUpper = saema.map((value, index) => Number.isFinite(value) && Number.isFinite(saAtr[index]) ? value + (saAtr[index] * saBandMult) : null);
  const saLower = saema.map((value, index) => Number.isFinite(value) && Number.isFinite(saAtr[index]) ? value - (saAtr[index] * saBandMult) : null);
  const saColor = saSlope.map((slope) => slope > 0 ? "#00fec3" : slope < 0 ? "#e600ff" : "#9aa7b8");

  return {
    buySignals,
    sellSignals,
    bullDivs,
    bearDivs,
    saema,
    saUpper,
    saLower,
    saColor,
  };
}

function buildTrendVolumeAccumulation(candles, config = {}) {
  const useMovingAverage = config.useMovingAverage ?? false;
  const maType = config.maType ?? "EMA";
  const maLen = Math.max(1, config.maLen ?? 6);
  const mode = config.mode ?? "Accumulation";

  if (!Array.isArray(candles) || candles.length < Math.max(8, maLen + 3)) {
    return { values: [], direction: [], barCount: [], ma: [] };
  }

  const closes = candles.map((candle) => candle.close);
  const volumes = candles.map((candle, index) => {
    const tickVolume = Array.isArray(candle.ticks) ? candle.ticks.length : 0;
    if (tickVolume > 0) return tickVolume;
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(1, Math.round(((candle.high - candle.low) + Math.abs(candle.close - prevClose)) * 1000));
  });
  const ma = movingAverageVariant(maType, closes, maLen, volumes);
  const values = new Array(candles.length).fill(null);
  const direction = new Array(candles.length).fill(0);
  const barCount = new Array(candles.length).fill(0);

  for (let i = 0; i < candles.length; i += 1) {
    if (useMovingAverage) {
      const now = ma[i];
      const prior1 = ma[i - 1];
      const prior3 = ma[i - 3];
      if (Number.isFinite(now) && Number.isFinite(prior1) && Number.isFinite(prior3)) {
        direction[i] = now > prior1 && prior1 > prior3 ? 1 : now < prior1 && prior1 < prior3 ? -1 : (direction[i - 1] ?? 0);
      } else {
        direction[i] = direction[i - 1] ?? 0;
      }
    } else {
      direction[i] = candles[i].close > candles[i].open ? 1 : candles[i].close < candles[i].open ? -1 : (direction[i - 1] ?? 0);
    }

    const prevBars = barCount[i - 1] ?? 0;
    if (direction[i] > 0) barCount[i] = prevBars >= 0 ? prevBars + 1 : 1;
    else if (direction[i] < 0) barCount[i] = prevBars <= 0 ? prevBars - 1 : -1;
    else barCount[i] = prevBars;

    const prevValue = values[i - 1] ?? 0;
    const rawVolume = volumes[i];
    const barMinutes = i > 0 ? Math.max(1, (Number(candles[i].time) - Number(candles[i - 1].time)) / 60) : 1;
    let deltaT = Math.max(1, Math.abs(barCount[i]) * barMinutes);
    if (!Number.isFinite(deltaT) || deltaT <= 0) deltaT = 1;
    const unitVolume = mode === "Normalised" ? rawVolume / barMinutes : rawVolume;

    if (direction[i] > 0) values[i] = prevValue >= 0 ? prevValue + unitVolume : unitVolume;
    else if (direction[i] < 0) values[i] = prevValue <= 0 ? prevValue - unitVolume : -unitVolume;
    else values[i] = prevValue;

    if (mode === "Bar Avg") {
      values[i] = barCount[i] !== 0 ? values[i] / Math.abs(barCount[i]) : null;
    } else if (mode === "Time Avg") {
      values[i] = values[i] / deltaT;
    }
  }

  return { values, direction, barCount, ma };
}

function buildVolumeProfileNodes(candles, config = {}) {
  const profileLength = Math.min(candles.length, config.profileLength ?? 360);
  const rows = config.rows ?? 60;
  const valueAreaThreshold = config.valueAreaThreshold ?? 0.7;
  const peakPercent = config.peakPercent ?? 0.09;
  const troughPercent = config.troughPercent ?? 0.07;
  const thresholdPercent = config.thresholdPercent ?? 0.01;
  const highestCount = config.highestCount ?? 2;
  const lowestCount = config.lowestCount ?? 2;

  if (!Array.isArray(candles) || candles.length < 30 || rows < 10) {
    return { rows: [], pocIndex: null, vahIndex: null, valIndex: null, highestPrice: null, lowestPrice: null };
  }

  const sample = candles.slice(-profileLength);
  const highestPrice = Math.max(...sample.map((c) => c.high));
  const lowestPrice = Math.min(...sample.map((c) => c.low));
  const priceRange = highestPrice - lowestPrice;
  if (!(priceRange > 0)) {
    return { rows: [], pocIndex: null, vahIndex: null, valIndex: null, highestPrice, lowestPrice };
  }

  const step = priceRange / rows;
  const profileRows = Array.from({ length: rows }, (_, index) => ({
    index,
    top: lowestPrice + ((index + 1) * step),
    bottom: lowestPrice + (index * step),
    total: 0,
    bullish: 0,
    bearish: 0,
    peak: false,
    trough: false,
    highest: false,
    lowest: false,
  }));

  sample.forEach((candle) => {
    const levelLow = candle.low;
    const levelHigh = candle.high;
    const candleRange = Math.max(levelHigh - levelLow, 0.0000001);
    const proxyVolume = ((levelHigh - levelLow) + Math.abs(candle.close - candle.open)) * 1000;
    const bullish = candle.close >= candle.open;
    const startSlot = Math.max(0, Math.floor((levelLow - lowestPrice) / step));
    const endSlot = Math.min(rows - 1, Math.floor((levelHigh - lowestPrice) / step));
    for (let rowIndex = startSlot; rowIndex <= endSlot; rowIndex += 1) {
      const row = profileRows[rowIndex];
      const overlapTop = Math.min(levelHigh, row.top);
      const overlapBottom = Math.max(levelLow, row.bottom);
      const overlap = Math.max(0, overlapTop - overlapBottom);
      const proportion = overlap / candleRange;
      const addVolume = proxyVolume * proportion;
      row.total += addVolume;
      if (bullish) row.bullish += addVolume;
      else row.bearish += addVolume;
    }
  });

  const totals = profileRows.map((row) => row.total);
  const maxVol = Math.max(...totals, 0);
  const pocIndex = totals.indexOf(maxVol);
  let vahIndex = pocIndex;
  let valIndex = pocIndex;
  let currentValueArea = pocIndex >= 0 ? totals[pocIndex] : 0;
  const targetValueArea = totals.reduce((sum, value) => sum + value, 0) * valueAreaThreshold;

  while (currentValueArea < targetValueArea && (valIndex > 0 || vahIndex < rows - 1)) {
    const above = vahIndex < rows - 1 ? totals[vahIndex + 1] : -1;
    const below = valIndex > 0 ? totals[valIndex - 1] : -1;
    if (above >= below) {
      vahIndex += 1;
      currentValueArea += Math.max(0, above);
    } else {
      valIndex -= 1;
      currentValueArea += Math.max(0, below);
    }
  }

  const peakN = Math.max(1, Math.round(rows * peakPercent));
  const troughN = Math.max(1, Math.round(rows * troughPercent));
  const threshold = maxVol * thresholdPercent;

  for (let i = peakN; i < rows - peakN; i += 1) {
    const current = totals[i];
    if (current < threshold) continue;
    let peak = true;
    for (let offset = 1; offset <= peakN; offset += 1) {
      if (totals[i - offset] >= current || totals[i + offset] >= current) {
        peak = false;
        break;
      }
    }
    if (peak) profileRows[i].peak = true;
  }

  for (let i = troughN; i < rows - troughN; i += 1) {
    const current = totals[i];
    if (current < threshold) continue;
    let trough = true;
    for (let offset = 1; offset <= troughN; offset += 1) {
      if (totals[i - offset] <= current || totals[i + offset] <= current) {
        trough = false;
        break;
      }
    }
    if (trough) profileRows[i].trough = true;
  }

  const sortedHigh = [...profileRows]
    .sort((a, b) => b.total - a.total)
    .slice(0, highestCount)
    .map((row) => row.index);
  const sortedLow = [...profileRows]
    .filter((row) => row.total > 0)
    .sort((a, b) => a.total - b.total)
    .slice(0, lowestCount)
    .map((row) => row.index);

  sortedHigh.forEach((index) => { profileRows[index].highest = true; });
  sortedLow.forEach((index) => { profileRows[index].lowest = true; });

  return {
    rows: profileRows,
    pocIndex,
    vahIndex,
    valIndex,
    highestPrice,
    lowestPrice,
    maxVolume: maxVol,
    startIndex: candles.length - sample.length,
  };
}

function buildLiquidityTrendlineSignals(candles, config = {}) {
  const len = config.len ?? 5;
  const space = config.space ?? 2;
  const colorUp = config.colorUp ?? "#0044ff";
  const colorDown = config.colorDown ?? "#ff2b00";

  if (!Array.isArray(candles) || candles.length < Math.max(30, len * 4)) {
    return { upperChannels: [], lowerChannels: [], signals: [] };
  }

  const tr = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  });
  const atr = rmaSeries(tr, 200);
  const padAt = (index) => Math.min((atr[index] ?? 0) * 0.1, candles[index].close * 0.001) * space;

  const pivotHighs = [];
  const pivotLows = [];
  const upperChannels = [];
  const lowerChannels = [];
  const signals = [];
  let upperBroken = false;
  let lowerBroken = false;
  let activeUpper = null;
  let activeLower = null;

  const buildChannel = (from, to, pad, direction) => {
    const dx = to.index - from.index;
    if (dx <= 0) return null;
    const slope = (to.price - from.price) / dx;
    return {
      direction,
      startIndex: from.index,
      endIndex: to.index,
      top1: direction === "UPPER" ? from.price : from.price + pad,
      top2: direction === "UPPER" ? to.price : to.price + pad,
      bottom1: direction === "UPPER" ? from.price - pad : from.price,
      bottom2: direction === "UPPER" ? to.price - pad : to.price,
      slope,
      pad,
      color: direction === "UPPER" ? colorDown : colorUp,
      liveEndIndex: to.index,
      liveTop: direction === "UPPER" ? to.price : to.price + pad,
      liveBottom: direction === "UPPER" ? to.price - pad : to.price,
    };
  };

  const lineValueAt = (startValue, slope, bars) => startValue + (slope * bars);

  for (let i = 0; i < candles.length; i += 1) {
    const pivotIndex = i - len;
    if (pivotIndex >= len && pivotIndex < candles.length - len) {
      if (isPivotHighLR(candles, pivotIndex, len, len)) {
        pivotHighs.unshift({ index: pivotIndex, price: candles[pivotIndex].high });
        if (pivotHighs.length > 4) pivotHighs.pop();
        if (pivotHighs.length > 1) {
          const current = pivotHighs[0];
          const before = pivotHighs[1];
          let valid = false;
          if (current.price < before.price) {
            if (upperBroken) valid = true;
            else if (pivotHighs.length > 3) {
              const pastOld = pivotHighs[3];
              const pastCur = pivotHighs[2];
              const now = pivotHighs[1];
              const late = pivotHighs[0];
              valid = now.price < pastCur.price && now.price < pastOld.price && late.price < pastCur.price && late.price < pastOld.price;
            }
          }
          if (valid) {
            const channel = buildChannel(before, current, padAt(i), "UPPER");
            if (channel) {
              let remove = false;
              for (let idx = before.index; idx <= i; idx += 1) {
                const projectedTop = lineValueAt(channel.top1, channel.slope, idx - before.index);
                if (candles[idx].low > projectedTop) {
                  remove = true;
                  break;
                }
              }
              if (remove) {
                activeUpper = null;
                pivotHighs.length = 0;
                upperBroken = true;
              } else {
                activeUpper = channel;
                upperChannels.push(channel);
                pivotHighs.length = 0;
                upperBroken = false;
              }
            }
          }
        }
      }

      if (isPivotLowLR(candles, pivotIndex, len, len)) {
        pivotLows.unshift({ index: pivotIndex, price: candles[pivotIndex].low });
        if (pivotLows.length > 4) pivotLows.pop();
        if (pivotLows.length > 1) {
          const current = pivotLows[0];
          const before = pivotLows[1];
          let valid = false;
          if (current.price > before.price) {
            if (lowerBroken) valid = true;
            else if (pivotLows.length > 3) {
              const pastOld = pivotLows[3];
              const pastCur = pivotLows[2];
              const now = pivotLows[1];
              const late = pivotLows[0];
              valid = now.price > pastCur.price && now.price > pastOld.price && late.price > pastCur.price && late.price > pastOld.price;
            }
          }
          if (valid) {
            const channel = buildChannel(before, current, padAt(i), "LOWER");
            if (channel) {
              let remove = false;
              for (let idx = before.index; idx <= i; idx += 1) {
                const projectedBottom = lineValueAt(channel.bottom1, channel.slope, idx - before.index);
                if (candles[idx].high < projectedBottom) {
                  remove = true;
                  break;
                }
              }
              if (remove) {
                activeLower = null;
                pivotLows.length = 0;
                lowerBroken = true;
              } else {
                activeLower = channel;
                lowerChannels.push(channel);
                pivotLows.length = 0;
                lowerBroken = false;
              }
            }
          }
        }
      }
    }

    if (activeUpper) {
      activeUpper.liveEndIndex = i;
      activeUpper.liveTop = lineValueAt(activeUpper.top1, activeUpper.slope, i - activeUpper.startIndex);
      activeUpper.liveBottom = lineValueAt(activeUpper.bottom1, activeUpper.slope, i - activeUpper.startIndex);
      if (candles[i].low > activeUpper.liveTop) {
        signals.push({
          type: "UP",
          signalIndex: i,
          entryIndex: i + 1 < candles.length ? i + 1 : null,
          price: candles[i].low,
          color: colorUp,
        });
        activeUpper = null;
        upperBroken = true;
        pivotHighs.length = 0;
      }
    }

    if (activeLower) {
      activeLower.liveEndIndex = i;
      activeLower.liveTop = lineValueAt(activeLower.top1, activeLower.slope, i - activeLower.startIndex);
      activeLower.liveBottom = lineValueAt(activeLower.bottom1, activeLower.slope, i - activeLower.startIndex);
      if (candles[i].high < activeLower.liveBottom) {
        signals.push({
          type: "DOWN",
          signalIndex: i,
          entryIndex: i + 1 < candles.length ? i + 1 : null,
          price: candles[i].high,
          color: colorDown,
        });
        activeLower = null;
        lowerBroken = true;
        pivotLows.length = 0;
      }
    }
  }

  return {
    upperChannels,
    lowerChannels,
    signals,
  };
}

function buildTickRejectionMicrostructure(candles, config = {}) {
  const ticksLookback = Math.max(3, config.ticksLookback ?? 5);
  const minRejectionRatio = config.minRejectionRatio ?? 0.5;
  const minRange = config.minRange ?? 0.0001;

  if (!Array.isArray(candles) || candles.length < 3) {
    return { signals: [], rejectionCandles: [] };
  }

  const rejectionCandles = [];
  const signals = [];

  candles.forEach((candle, index) => {
    const totalRange = candle.high - candle.low;
    if (!(totalRange >= minRange)) return;

    const bodyTop = Math.max(candle.open, candle.close);
    const bodyBottom = Math.min(candle.open, candle.close);
    const upperWick = candle.high - bodyTop;
    const lowerWick = bodyBottom - candle.low;
    const upperRatio = totalRange === 0 ? 0 : upperWick / totalRange;
    const lowerRatio = totalRange === 0 ? 0 : lowerWick / totalRange;

    let type = null;
    if (upperRatio >= minRejectionRatio && upperRatio >= lowerRatio) type = "upper";
    else if (lowerRatio >= minRejectionRatio) type = "lower";
    if (!type) return;

    const ticks = normalizeCandleTicks(candle);
    if (ticks.length < 2) return;
    const lastTicks = ticks.slice(-Math.min(ticksLookback, ticks.length));
    const prices = lastTicks.map((tick) => tick.price).filter(Number.isFinite);
    if (prices.length < 2) return;

    const rejectionCandle = {
      sourceIndex: index,
      entryIndex: index + 1 < candles.length ? index + 1 : null,
      type,
      open: prices[0],
      high: Math.max(...prices),
      low: Math.min(...prices),
      close: prices[prices.length - 1],
      upperRatio,
      lowerRatio,
      tickCount: lastTicks.length,
      usesSyntheticTicks: !Array.isArray(candle.ticks),
    };

    rejectionCandles.push(rejectionCandle);
    signals.push({
      type,
      sourceIndex: index,
      entryIndex: rejectionCandle.entryIndex,
      price: type === "lower" ? candles[index].low : candles[index].high,
      strength: type === "lower" ? lowerRatio : upperRatio,
      usesSyntheticTicks: rejectionCandle.usesSyntheticTicks,
    });
  });

  return {
    signals,
    rejectionCandles,
  };
}

function buildStructurePullbackContinuation(candles, config = {}) {
  const pivotLen = Math.max(2, config.pivotLen ?? 4);
  const pullbackLookback = Math.max(2, config.pullbackLookback ?? 4);
  const weakBodyRatio = config.weakBodyRatio ?? 0.4;
  const rejectionWickRatio = config.rejectionWickRatio ?? 0.45;
  const maxTrendFlips = config.maxTrendFlips ?? 4;
  const flipLookback = config.flipLookback ?? 30;
  const confirmedCandles = candles.slice(0, -1);

  if (!Array.isArray(candles) || confirmedCandles.length < pivotLen * 4 + 6) {
    return {
      signals: [],
      trendMarks: [],
      stats: {
        buy: { wins: 0, total: 0 },
        sell: { wins: 0, total: 0 },
      },
    };
  }

  const signals = [];
  const trendMarks = [];
  const stats = {
    buy: { wins: 0, total: 0 },
    sell: { wins: 0, total: 0 },
  };
  let prevHighPivot = null;
  let prevLowPivot = null;
  let lastHighPivot = null;
  let lastLowPivot = null;
  let lastHighType = null;
  let lastLowType = null;
  let trend = "range";
  const trendHistory = [];

  const classifyTrend = () => {
    if (lastHighType === "HH" && lastLowType === "HL") return "uptrend";
    if (lastHighType === "LH" && lastLowType === "LL") return "downtrend";
    return "range";
  };

  for (let i = 0; i < confirmedCandles.length; i += 1) {
    const pivotIndex = i - pivotLen;
    if (pivotIndex >= pivotLen && pivotIndex < confirmedCandles.length - pivotLen) {
      if (isPivotHighLR(confirmedCandles, pivotIndex, pivotLen, pivotLen)) {
        if (lastHighPivot) prevHighPivot = lastHighPivot;
        lastHighPivot = { index: pivotIndex, price: confirmedCandles[pivotIndex].high };
        if (prevHighPivot) lastHighType = lastHighPivot.price > prevHighPivot.price ? "HH" : "LH";
        const nextTrend = classifyTrend();
        if (nextTrend !== trend) trendHistory.push({ index: pivotIndex, trend: nextTrend });
        trend = nextTrend;
        trendMarks.push({ index: pivotIndex, price: lastHighPivot.price, type: lastHighType, trend });
      }

      if (isPivotLowLR(confirmedCandles, pivotIndex, pivotLen, pivotLen)) {
        if (lastLowPivot) prevLowPivot = lastLowPivot;
        lastLowPivot = { index: pivotIndex, price: confirmedCandles[pivotIndex].low };
        if (prevLowPivot) lastLowType = lastLowPivot.price > prevLowPivot.price ? "HL" : "LL";
        const nextTrend = classifyTrend();
        if (nextTrend !== trend) trendHistory.push({ index: pivotIndex, trend: nextTrend });
        trend = nextTrend;
        trendMarks.push({ index: pivotIndex, price: lastLowPivot.price, type: lastLowType, trend });
      }
    }

    if (i < 2) continue;
    const setupIndex = i;
    const entryIndex = setupIndex + 1 < candles.length ? setupIndex + 1 : null;
    if (entryIndex == null) continue;
    const setupCandle = confirmedCandles[setupIndex];
    const priorCandle = confirmedCandles[setupIndex - 1];

    const recentFlips = trendHistory.filter((item) => item.index >= setupIndex - flipLookback);
    if (recentFlips.length > maxTrendFlips) continue;

    const setupRange = Math.max(setupCandle.high - setupCandle.low, 0.0000001);
    const lowerWickRatio = (Math.min(setupCandle.open, setupCandle.close) - setupCandle.low) / setupRange;
    const upperWickRatio = (setupCandle.high - Math.max(setupCandle.open, setupCandle.close)) / setupRange;

    if (trend === "uptrend" && lastHighPivot && lastLowPivot && setupIndex > lastHighPivot.index) {
      const pullbackStart = Math.max(lastHighPivot.index + 1, setupIndex - pullbackLookback);
      const pullbackSlice = confirmedCandles.slice(pullbackStart, setupIndex);
      const recentPullbackLow = pullbackSlice.length
        ? Math.min(...pullbackSlice.map((candle) => candle.low))
        : setupCandle.low;
      const pullbackPhase = setupCandle.close < lastHighPivot.price && setupCandle.low > lastLowPivot.price;
      if (pullbackPhase) {
        const failure = setupCandle.low < recentPullbackLow && setupCandle.close > recentPullbackLow;
        const weakContinuation = priorCandle.close < priorCandle.open
          && Math.abs(priorCandle.close - priorCandle.open) / Math.max(priorCandle.high - priorCandle.low, 0.0000001) < weakBodyRatio
          && setupCandle.close > setupCandle.open
          && setupCandle.close > priorCandle.high;
        const rejection = lowerWickRatio >= rejectionWickRatio
          && setupCandle.close > setupCandle.open;

        if (failure || rejection || weakContinuation) {
          const resultCandle = entryIndex + 1 < candles.length ? candles[entryIndex + 1] : null;
          const isWin = resultCandle ? resultCandle.close > resultCandle.open : null;
          if (resultCandle) {
            stats.buy.total += 1;
            if (isWin) stats.buy.wins += 1;
          }
          signals.push({
            direction: "BUY",
            entryIndex,
            setupIndex,
            trend,
            reason: failure ? "failure" : rejection ? "rejection" : "continuation",
            reference: recentPullbackLow,
            result: isWin,
            buyStats: { ...stats.buy },
            sellStats: { ...stats.sell },
          });
        }
      }
    }

    if (trend === "downtrend" && lastHighPivot && lastLowPivot && setupIndex > lastLowPivot.index) {
      const pullbackStart = Math.max(lastLowPivot.index + 1, setupIndex - pullbackLookback);
      const pullbackSlice = confirmedCandles.slice(pullbackStart, setupIndex);
      const recentPullbackHigh = pullbackSlice.length
        ? Math.max(...pullbackSlice.map((candle) => candle.high))
        : setupCandle.high;
      const pullbackPhase = setupCandle.close > lastLowPivot.price && setupCandle.high < lastHighPivot.price;
      if (pullbackPhase) {
        const failure = setupCandle.high > recentPullbackHigh && setupCandle.close < recentPullbackHigh;
        const weakContinuation = priorCandle.close > priorCandle.open
          && Math.abs(priorCandle.close - priorCandle.open) / Math.max(priorCandle.high - priorCandle.low, 0.0000001) < weakBodyRatio
          && setupCandle.close < setupCandle.open
          && setupCandle.close < priorCandle.low;
        const rejection = upperWickRatio >= rejectionWickRatio
          && setupCandle.close < setupCandle.open;

        if (failure || rejection || weakContinuation) {
          const resultCandle = entryIndex + 1 < candles.length ? candles[entryIndex + 1] : null;
          const isWin = resultCandle ? resultCandle.close < resultCandle.open : null;
          if (resultCandle) {
            stats.sell.total += 1;
            if (isWin) stats.sell.wins += 1;
          }
          signals.push({
            direction: "SELL",
            entryIndex,
            setupIndex,
            trend,
            reason: failure ? "failure" : rejection ? "rejection" : "continuation",
            reference: recentPullbackHigh,
            result: isWin,
            buyStats: { ...stats.buy },
            sellStats: { ...stats.sell },
          });
        }
      }
    }
  }

  const dedupedSignals = [];
  let lastSignalIndex = -99;
  signals.forEach((signal) => {
    if (signal.entryIndex - lastSignalIndex < 2) return;
    dedupedSignals.push(signal);
    lastSignalIndex = signal.entryIndex;
  });

  return {
    signals: dedupedSignals,
    trendMarks,
    stats,
  };
}

function buildSupportResistanceSignalsMTF(candles, config = {}) {
  const length = Math.max(4, config.length ?? 6);
  const zoneAtrMult = config.zoneAtrMult ?? 0.5;
  const securityAtrMult = config.securityAtrMult ?? 0;
  const manipulationMult = config.manipulationMult ?? 1.3;
  const maxActive = config.maxActive ?? 5;
  const showBroken = config.showBroken ?? true;
  const extendActive = config.extendActive ?? true;

  if (!Array.isArray(candles) || candles.length < length * 4) {
    return {
      supports: [],
      resistances: [],
      manipulations: [],
      signals: [],
      stats: {
        activeSupports: 0,
        activeResistances: 0,
        totalSupports: 0,
        totalResistances: 0,
        supportSweeps: 0,
        resistanceSweeps: 0,
      },
    };
  }

  const tr = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  });
  const atr = rmaSeries(tr, 200);
  const activity = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return ((candle.high - candle.low) + Math.abs(candle.close - prevClose)) * 1000;
  });
  const activityAvg = simpleMovingAverage(activity, 17);

  const levels = [];
  const manipulations = [];
  const signals = [];
  let totalSupports = 0;
  let totalResistances = 0;
  let supportSweeps = 0;
  let resistanceSweeps = 0;

  const addLevel = (price, pivotIndex, isSupport) => {
    const currentAtr = atr[pivotIndex] ?? 0;
    const top = isSupport ? price + (currentAtr * zoneAtrMult) : price + (currentAtr * securityAtrMult);
    const bottom = isSupport ? price - (currentAtr * securityAtrMult) : price - (currentAtr * zoneAtrMult);

    for (let i = levels.length - 1; i >= 0; i -= 1) {
      const l = levels[i];
      if (l.isSupport !== isSupport || l.isMitigated || l.isUserHidden) continue;
      const overlaps = Math.max(bottom, l.bottom) < Math.min(top, l.top);
      if (overlaps) {
        l.top = Math.max(l.top, top);
        l.bottom = Math.min(l.bottom, bottom);
        l.basePrice = (l.basePrice + price) / 2;
        return;
      }
    }

    levels.unshift({
      top,
      bottom,
      basePrice: price,
      startIndex: pivotIndex,
      endIndex: pivotIndex,
      mitigationIndex: null,
      isSupport,
      isMitigated: false,
      isUserHidden: false,
      entries: 0,
      strength: 0,
      sweeps: 0,
      tradedVolume: 0,
      lastSignalIndex: -100,
    });

    if (isSupport) totalSupports += 1;
    else totalResistances += 1;
  };

  for (let i = 0; i < candles.length; i += 1) {
    const pivotIndex = i - length;
    if (pivotIndex >= length && pivotIndex < candles.length - length) {
      if (isPivotHighLR(candles, pivotIndex, length, length)) {
        addLevel(candles[pivotIndex].high, pivotIndex, false);
      }
      if (isPivotLowLR(candles, pivotIndex, length, length)) {
        addLevel(candles[pivotIndex].low, pivotIndex, true);
      }
    }

    if (levels.length > 100) levels.pop();
    if (i < 1) continue;

    const prev = candles[i - 1];
    const curr = candles[i];
    const currentAtr = atr[i - 1] ?? 0;
    const highActivity = (activity[i - 1] ?? 0) >= 1.618 * (activityAvg[i - 1] ?? Number.POSITIVE_INFINITY);

    levels.forEach((l) => {
      if (!l.isMitigated) {
        if (l.isSupport && curr.close < l.bottom) {
          l.isMitigated = true;
          l.mitigationIndex = i;
          if (showBroken) {
            signals.push({ kind: "break", direction: "SELL", sourceIndex: i - 1, entryIndex: i, price: prev.high });
          }
        } else if (!l.isSupport && curr.close > l.top) {
          l.isMitigated = true;
          l.mitigationIndex = i;
          if (showBroken) {
            signals.push({ kind: "break", direction: "BUY", sourceIndex: i - 1, entryIndex: i, price: prev.low });
          }
        }
      }

      const endIndex = l.isMitigated ? l.mitigationIndex : i;
      l.endIndex = endIndex;

      if (!l.isMitigated) {
        if (curr.high >= l.bottom && curr.low <= l.top) {
          l.tradedVolume += 1;
          l.strength += 1;
        }

        if (l.isSupport) {
          if (prev.low <= l.top && prev.close >= l.bottom) l.entries += 1;
          if (prev.low < l.bottom && Math.min(prev.close, prev.open) > l.bottom) {
            l.sweeps += 1;
            supportSweeps += 1;
            manipulations.push({
              type: "support",
              startIndex: i - 1,
              endIndex: i + 1,
              top: l.bottom,
              bottom: Math.max(prev.low, l.bottom - currentAtr * manipulationMult),
            });
          }
          const lowerWick = Math.min(prev.open, prev.close) - prev.low;
          if (lowerWick >= 1.618 * currentAtr && highActivity && i - l.lastSignalIndex > 2) {
            l.lastSignalIndex = i;
            signals.push({ kind: "rejection", direction: "BUY", sourceIndex: i - 1, entryIndex: i, price: prev.low });
          } else if (prev.low < l.top && prev.close > l.bottom && prev.close > prev.open && i - l.lastSignalIndex > 2) {
            l.lastSignalIndex = i;
            signals.push({ kind: "test", direction: "BUY", sourceIndex: i - 1, entryIndex: i, price: prev.low });
          }
        } else {
          if (prev.high >= l.bottom && prev.close <= l.top) l.entries += 1;
          if (prev.high > l.top && Math.max(prev.close, prev.open) < l.top) {
            l.sweeps += 1;
            resistanceSweeps += 1;
            manipulations.push({
              type: "resistance",
              startIndex: i - 1,
              endIndex: i + 1,
              top: Math.min(prev.high, l.top + currentAtr * manipulationMult),
              bottom: l.top,
            });
          }
          const upperWick = prev.high - Math.max(prev.open, prev.close);
          if (upperWick >= 1.618 * currentAtr && highActivity && i - l.lastSignalIndex > 2) {
            l.lastSignalIndex = i;
            signals.push({ kind: "rejection", direction: "SELL", sourceIndex: i - 1, entryIndex: i, price: prev.high });
          } else if (prev.high > l.bottom && prev.close < l.top && prev.close < prev.open && i - l.lastSignalIndex > 2) {
            l.lastSignalIndex = i;
            signals.push({ kind: "test", direction: "SELL", sourceIndex: i - 1, entryIndex: i, price: prev.high });
          }
        }
      }
    });
  }

  const supports = [];
  const resistances = [];
  let activeCount = 0;
  levels.forEach((l) => {
    if (l.isUserHidden) return;
    if (!l.isMitigated && activeCount >= maxActive) return;
    const drawLevel = {
      ...l,
      drawEndIndex: l.isMitigated ? l.mitigationIndex : (extendActive ? candles.length - 1 : l.endIndex),
    };
    if (!l.isMitigated) activeCount += 1;
    if (l.isSupport) supports.push(drawLevel);
    else resistances.push(drawLevel);
  });

  return {
    supports: supports.slice(0, maxActive),
    resistances: resistances.slice(0, maxActive),
    manipulations: manipulations.slice(-10),
    signals: signals.filter((signal) => signal.entryIndex != null).slice(-30),
    stats: {
      activeSupports: supports.filter((l) => !l.isMitigated).length,
      activeResistances: resistances.filter((l) => !l.isMitigated).length,
      totalSupports,
      totalResistances,
      supportSweeps,
      resistanceSweeps,
    },
  };
}

function aggregateCandlesByTimeframe(candles, timeframeSec) {
  if (!Array.isArray(candles) || !candles.length || !Number.isFinite(timeframeSec) || timeframeSec <= 0) return [];
  const buckets = [];
  let active = null;

  candles.forEach((candle) => {
    const time = Number(candle.time ?? candle.epoch);
    if (!Number.isFinite(time)) return;
    const bucketTime = Math.floor(time / timeframeSec) * timeframeSec;
    if (!active || active.time !== bucketTime) {
      if (active) buckets.push(active);
      active = {
        time: bucketTime,
        open: candle.open,
        high: candle.high,
        low: candle.low,
        close: candle.close,
      };
      return;
    }
    active.high = Math.max(active.high, candle.high);
    active.low = Math.min(active.low, candle.low);
    active.close = candle.close;
  });

  if (active) buckets.push(active);
  return buckets;
}

function getInstitutionalTrend(candles, period = 20) {
  if (!Array.isArray(candles) || candles.length < period) return "RANGE";
  const sample = candles.slice(-period);
  const avgClose = sample.reduce((sum, candle) => sum + candle.close, 0) / sample.length;
  const lastClose = sample[sample.length - 1].close;
  if (lastClose > avgClose) return "BULLISH";
  if (lastClose < avgClose) return "BEARISH";
  return "RANGE";
}

function getInstitutionalPoiLevels(candles, tolerance, minTouches = 3) {
  if (!Array.isArray(candles) || candles.length < minTouches || !Number.isFinite(tolerance) || tolerance <= 0) return [];
  const levels = [];

  candles.forEach((candle, index) => {
    const price = candle.close;
    if (!Number.isFinite(price)) return;
    const existing = levels.find((level) => Math.abs(level.price - price) <= tolerance);
    if (existing) {
      existing.price = ((existing.price * existing.strength) + price) / (existing.strength + 1);
      existing.strength += 1;
      existing.lastIndex = index;
      return;
    }

    const touches = candles.reduce((count, item) => count + (Math.abs(item.close - price) <= tolerance ? 1 : 0), 0);
    if (touches >= minTouches) {
      levels.push({
        price,
        strength: touches,
        firstIndex: index,
        lastIndex: index,
      });
    }
  });

  return levels
    .sort((a, b) => (b.strength - a.strength) || (b.lastIndex - a.lastIndex))
    .slice(0, 12);
}

function getInstitutionalReactionPoiLevels(candles, tolerance, config = {}) {
  const pivotLen = Math.max(2, config.pivotLen ?? 3);
  const minTouches = Math.max(2, config.minTouches ?? 2);
  const source = config.source || "1m";
  if (!Array.isArray(candles) || candles.length < (pivotLen * 2) + 3 || !Number.isFinite(tolerance) || tolerance <= 0) return [];

  const raw = [];
  for (let i = pivotLen; i < candles.length - pivotLen; i += 1) {
    if (isPivotHighLR(candles, i, pivotLen, pivotLen)) {
      raw.push({ price: candles[i].high, index: i, kind: "high" });
    }
    if (isPivotLowLR(candles, i, pivotLen, pivotLen)) {
      raw.push({ price: candles[i].low, index: i, kind: "low" });
    }
  }

  const levels = [];
  raw.forEach((point) => {
    if (!Number.isFinite(point.price)) return;
    const existing = levels.find((level) => Math.abs(level.price - point.price) <= tolerance);
    if (existing) {
      existing.price = ((existing.price * existing.strength) + point.price) / (existing.strength + 1);
      existing.strength += 1;
      existing.lastIndex = Math.max(existing.lastIndex, point.index);
      existing.kinds.add(point.kind);
      return;
    }
    const touches = raw.filter((item) => Math.abs(item.price - point.price) <= tolerance).length;
    if (touches >= minTouches) {
      levels.push({
        price: point.price,
        strength: touches,
        firstIndex: point.index,
        lastIndex: point.index,
        source,
        kinds: new Set([point.kind]),
      });
    }
  });

  return levels
    .map((level) => ({
      ...level,
      kind: level.kinds.has("high") && level.kinds.has("low")
        ? "reaction"
        : level.kinds.has("high")
          ? "resistance"
          : "support",
      kinds: undefined,
    }))
    .sort((a, b) => (b.strength - a.strength) || (b.lastIndex - a.lastIndex))
    .slice(0, 16);
}

function mergeInstitutionalPoiCandidates(groups, tolerance) {
  const merged = [];
  const safeTolerance = Math.max(tolerance || 0, currentPip || 0.0001);
  groups.flat().forEach((level) => {
    if (!Number.isFinite(level?.price)) return;
    const existing = merged.find((item) => Math.abs(item.price - level.price) <= safeTolerance);
    if (existing) {
      const totalStrength = existing.strength + level.strength;
      existing.price = ((existing.price * existing.strength) + (level.price * level.strength)) / Math.max(1, totalStrength);
      existing.strength = totalStrength;
      existing.firstIndex = Math.min(existing.firstIndex ?? level.firstIndex ?? 0, level.firstIndex ?? existing.firstIndex ?? 0);
      existing.lastIndex = Math.max(existing.lastIndex ?? level.lastIndex ?? 0, level.lastIndex ?? existing.lastIndex ?? 0);
      existing.source = [existing.source, level.source].filter(Boolean).join("+");
      return;
    }
    merged.push({ ...level });
  });

  return merged
    .sort((a, b) => (b.strength - a.strength) || (b.lastIndex - a.lastIndex))
    .slice(0, 24);
}

function findInstitutionalPoi(currentPrice, levels, tolerance) {
  let best = null;
  levels.forEach((level) => {
    const distance = Math.abs(currentPrice - level.price);
    if (distance > tolerance) return;
    if (!best || distance < best.distance || (distance === best.distance && level.strength > best.strength)) {
      best = { ...level, distance };
    }
  });
  return best;
}

function resolveStableInstitutionalPoiLevels({ candidates, currentPrice, avgRange, tolerance, stateKey, maxLevels = 6 }) {
  const source = Array.isArray(candidates)
    ? candidates.filter((level) => Number.isFinite(level?.price))
    : [];
  if (!Number.isFinite(currentPrice) || !source.length) return [];

  const safeRange = Math.max(avgRange || 0, tolerance || 0, currentPip || 0.0001, Math.abs(currentPrice) * 0.00005);
  const matchTolerance = Math.max(tolerance || 0, safeRange * 0.25);
  const retireDistance = safeRange * 7;
  const promoteDistance = safeRange * 5;
  const previous = institutionalPoiDisplayState?.key === stateKey
    ? institutionalPoiDisplayState.levels || []
    : [];

  const findCandidateFor = (level) => source.find((candidate) => Math.abs(candidate.price - level.price) <= matchTolerance);
  const active = [];
  const used = new Set();

  previous.forEach((level) => {
    const candidate = findCandidateFor(level);
    if (!candidate) return;
    const distance = Math.abs(candidate.price - currentPrice);
    if (distance > retireDistance) return;
    const merged = {
      ...candidate,
      activeSince: level.activeSince ?? candidate.firstIndex ?? candidate.lastIndex ?? 0,
      distance,
    };
    active.push(merged);
    used.add(candidate);
  });

  const ranked = source
    .filter((candidate) => !used.has(candidate))
    .map((candidate) => ({
      ...candidate,
      distance: Math.abs(candidate.price - currentPrice),
    }))
    .sort((a, b) => {
      const aNearby = a.distance <= promoteDistance ? 0 : 1;
      const bNearby = b.distance <= promoteDistance ? 0 : 1;
      return (aNearby - bNearby) || (a.distance - b.distance) || (b.strength - a.strength);
    });

  ranked.forEach((candidate) => {
    if (active.length >= maxLevels) return;
    if (candidate.distance > retireDistance && active.length >= Math.ceil(maxLevels / 2)) return;
    active.push({
      ...candidate,
      activeSince: candidate.firstIndex ?? candidate.lastIndex ?? 0,
    });
  });

  const nextLevels = active
    .sort((a, b) => b.price - a.price)
    .slice(0, maxLevels);
  institutionalPoiDisplayState = { key: stateKey, levels: nextLevels };
  return nextLevels;
}

function hasInstitutionalConfirmation(candles, direction) {
  if (!Array.isArray(candles) || candles.length < 2) return false;
  const prev = candles[candles.length - 2];
  const curr = candles[candles.length - 1];
  const prevUpperWick = prev.high - Math.max(prev.open, prev.close);
  const prevLowerWick = Math.min(prev.open, prev.close) - prev.low;
  const currRange = Math.max(curr.high - curr.low, Math.abs(curr.close) * 0.000001, currentPip || 0.0001);
  const currBody = Math.abs(curr.close - curr.open);
  const strongBody = currBody >= currRange * 0.6;
  const sweptLow = curr.low < prev.low;
  const sweptHigh = curr.high > prev.high;

  if (direction === "BUY") {
    return sweptLow && prevLowerWick > prevUpperWick && curr.close > curr.open && strongBody;
  }
  if (direction === "SELL") {
    return sweptHigh && prevUpperWick > prevLowerWick && curr.close < curr.open && strongBody;
  }
  return false;
}

function scoreInstitutionalSetup({ current, prev, direction, poi, tolerance, avgRange }) {
  if (!current || !prev || !poi || !Number.isFinite(tolerance) || tolerance <= 0) return 0;
  const range = Math.max(current.high - current.low, currentPip || 0.0001, Math.abs(current.close) * 0.000001);
  const body = Math.abs(current.close - current.open);
  const bodyScore = clamp(body / range, 0, 1);
  const distanceScore = clamp(1 - (Math.abs(current.close - poi.price) / tolerance), 0, 1);
  const poiScore = clamp((poi.strength - 2) / 8, 0, 1);
  const upperSweep = Math.max(0, current.high - prev.high);
  const lowerSweep = Math.max(0, prev.low - current.low);
  const sweepSize = direction === "BUY" ? lowerSweep : upperSweep;
  const sweepScore = clamp(sweepSize / Math.max(avgRange * 0.45, currentPip || 0.0001), 0, 1);
  const closeLocation = clamp((current.close - current.low) / range, 0, 1);
  const closeScore = direction === "BUY" ? closeLocation : 1 - closeLocation;

  return Math.round(clamp(
    25 +
    (bodyScore * 22) +
    (distanceScore * 16) +
    (poiScore * 16) +
    (sweepScore * 13) +
    (closeScore * 8),
    0,
    100,
  ));
}

function countInstitutionalLevelTouches(candles, level, tolerance) {
  if (!Array.isArray(candles) || !Number.isFinite(level?.price)) return { touches: 0, lastTouchIndex: null };
  let touches = 0;
  let lastTouchIndex = null;
  candles.forEach((candle, index) => {
    const touched = candle.high >= level.price - tolerance && candle.low <= level.price + tolerance;
    if (!touched) return;
    if (lastTouchIndex == null || index - lastTouchIndex > 2) {
      touches += 1;
    }
    lastTouchIndex = index;
  });
  return { touches, lastTouchIndex };
}

function getInstitutionalFakeBreakDirection(candle, level, tolerance) {
  if (!candle || !Number.isFinite(level?.price)) return null;
  if (candle.high > level.price + (tolerance * 0.15) && candle.close < level.price) return "SELL";
  if (candle.low < level.price - (tolerance * 0.15) && candle.close > level.price) return "BUY";
  return null;
}

function getInstitutionalStrongBreakDirection(candle, level, tolerance) {
  if (!candle || !Number.isFinite(level?.price)) return null;
  const range = Math.max(candle.high - candle.low, currentPip || 0.0001, Math.abs(candle.close) * 0.000001);
  const body = Math.abs(candle.close - candle.open);
  if (body / range < 0.7) return null;
  if (candle.close > level.price + (tolerance * 0.2) && candle.close > candle.open) return "BUY";
  if (candle.close < level.price - (tolerance * 0.2) && candle.close < candle.open) return "SELL";
  return null;
}

function buildInstitutionalPoiCandidatePool(history, alignSeconds = getMtfTimeframeSet().alignSeconds, entrySeconds = getMtfTimeframeSet().entrySeconds) {
  const entryFrame = Math.max(1, Number(entrySeconds) || getChartTimeframeSeconds());
  const alignFrame = Math.max(entryFrame, Number(alignSeconds) || entryFrame);
  const alignCandles = aggregateCandlesByTimeframe(history, alignFrame);
  const entryCandles = entryFrame === getChartTimeframeSeconds()
    ? history
    : aggregateCandlesByTimeframe(history, entryFrame);
  const latestAvgRange = averageRange(alignCandles, 30) || averageRange(entryCandles, 30) || averageRange(history, 30) || 0.0001;
  const latestTolerance = Math.max(currentPip || 0.0001, latestAvgRange * 0.28);
  const alignPoiCandidates = getInstitutionalPoiLevels(alignCandles.slice(-120), latestTolerance, 3)
    .map((level) => ({ ...level, source: getMtfFrameLabel(alignFrame), kind: "close-cluster" }));
  const entryReactionTolerance = Math.max(currentPip || 0.0001, (averageRange(entryCandles, 30) || latestAvgRange) * 0.32);
  const entryPoiCandidates = getInstitutionalReactionPoiLevels(entryCandles.slice(-360), entryReactionTolerance, {
    pivotLen: 3,
    minTouches: 2,
    source: getMtfFrameLabel(entryFrame),
  });
  return {
    candidates: mergeInstitutionalPoiCandidates(
      [alignPoiCandidates, entryPoiCandidates],
      Math.max(latestTolerance, entryReactionTolerance),
    ),
    avgRange: latestAvgRange,
    tolerance: Math.max(latestTolerance, entryReactionTolerance),
    alignCandles,
    entryCandles,
  };
}

function buildInstitutionalExecutionModel(candles, config = {}) {
  const confirmedCandles = Array.isArray(candles) ? candles.slice(0, -1) : [];
  const last = confirmedCandles[confirmedCandles.length - 1] || null;
  const executionTf = Math.max(1, Number(config.baseSeconds || candleBuilder?.timeframe || DEFAULT_TIMEFRAME_SEC));
  const mtf = getMtfTimeframeSet(executionTf);
  const cacheKey = [
    currentSymbol || "symbol",
    executionTf,
    currentPip || 0,
    baseMinutes || 1,
    config.minConfidence ?? 70,
    confirmedCandles.length,
    last?.time ?? 0,
    last?.open ?? 0,
    last?.high ?? 0,
    last?.low ?? 0,
    last?.close ?? 0,
  ].join("|");
  if (!config.noCache && institutionalExecutionModelCache?.key === cacheKey) {
    return institutionalExecutionModelCache.value;
  }
  const minCandles = Math.max(80, config.minCandles ?? 90);
  if (confirmedCandles.length < minCandles) {
    const empty = {
      signals: [],
      poiLevels: [],
      stats: { total: 0, wins: 0, losses: 0, pending: 0, winRate: null },
      trendMain: "RANGE",
      trendAlign: "RANGE",
      mainLabel: mtf.mainLabel,
      alignLabel: mtf.alignLabel,
      entryLabel: mtf.entryLabel,
    };
    institutionalExecutionModelCache = { key: cacheKey, value: empty };
    return empty;
  }

  const signals = [];
  const seenSignalKeys = new Set();
  let lastSignalIndex = -8;
  const expiryBars = Math.max(1, Math.round(((config.expirySeconds ?? (baseMinutes * 60)) || 60) / Math.max(1, executionTf)));
  const minConfidence = Math.max(0, Math.min(100, config.minConfidence ?? 70));

  for (let i = minCandles; i < confirmedCandles.length; i += 1) {
    const history = confirmedCandles.slice(0, i + 1);
    const ltfHistory = executionTf === mtf.entrySeconds ? history : aggregateCandlesByTimeframe(history, mtf.entrySeconds);
    if (ltfHistory.length < 24) continue;

    const current = history[i];
    const alignCandles = aggregateCandlesByTimeframe(history, mtf.alignSeconds);
    const mainCandles = aggregateCandlesByTimeframe(history, mtf.mainSeconds);
    const trendMain = getInstitutionalTrend(mainCandles);
    const trendAlign = getInstitutionalTrend(alignCandles);
    if (trendMain === "RANGE" || trendMain !== trendAlign) continue;

    const recentAlign = alignCandles.slice(-120);
    const poiAvgRange = averageRange(recentAlign, 30) || averageRange(history, 30) || Math.abs(current.close) * 0.0005;
    const tolerance = Math.max(currentPip || 0.0001, poiAvgRange * 0.28);
    const poiLevels = getInstitutionalPoiLevels(recentAlign, tolerance, 3);
    const poi = findInstitutionalPoi(current.close, poiLevels, tolerance);
    if (!poi) continue;

    const direction = trendMain === "BULLISH" ? "BUY" : "SELL";
    if (!hasInstitutionalConfirmation(history.slice(0, i + 1), direction)) continue;
    if (i - lastSignalIndex < Math.max(3, config.cooldownBars ?? 6)) continue;
    const prev = history[i - 1];
    const confidence = scoreInstitutionalSetup({
      current,
      prev,
      direction,
      poi,
      tolerance,
      avgRange: poiAvgRange,
    });
    if (confidence < minConfidence) continue;

    const key = `${direction}|${i}|${Math.round(poi.price / Math.max(tolerance, 0.0000001))}`;
    if (seenSignalKeys.has(key)) continue;
    seenSignalKeys.add(key);
    lastSignalIndex = i;

    const entryIndex = i + 1;
    const entryCandle = candles[entryIndex] || null;
    const entryPrice = entryCandle?.open ?? entryCandle?.close ?? current.close;
    const targetIndex = entryIndex + expiryBars;
    const target = confirmedCandles[targetIndex] || null;
    const won = target
      ? direction === "BUY"
        ? target.close > entryPrice
        : target.close < entryPrice
      : null;

    signals.push({
      confirmationIndex: i,
      entryIndex,
      targetIndex,
      direction,
      price: entryPrice,
      confirmationPrice: current.close,
      poi: poi.price,
      poiStrength: poi.strength,
      confidence,
      expiryBars,
      tolerance,
      trendMain,
      trendAlign,
      mainLabel: mtf.mainLabel,
      alignLabel: mtf.alignLabel,
      entryLabel: mtf.entryLabel,
      result: won == null ? "PENDING" : won ? "WIN" : "LOSS",
    });
  }

  const scored = signals.filter((signal) => signal.result !== "PENDING");
  const wins = scored.filter((signal) => signal.result === "WIN").length;
  const losses = scored.length - wins;
  const winRate = scored.length ? Math.round((wins / scored.length) * 100) : null;
  const latestHistory = confirmedCandles;
  const latestAlign = aggregateCandlesByTimeframe(latestHistory, mtf.alignSeconds);
  const latestMain = aggregateCandlesByTimeframe(latestHistory, mtf.mainSeconds);
  const latestAvgRange = averageRange(latestAlign, 30) || averageRange(latestHistory, 30) || 0.0001;
  const latestCurrent = latestHistory[latestHistory.length - 1] || null;
  const latestTolerance = Math.max(currentPip || 0.0001, latestAvgRange * 0.28);
  const alignPoiCandidates = getInstitutionalPoiLevels(latestAlign.slice(-120), latestTolerance, 3)
    .map((level) => ({ ...level, source: mtf.alignLabel, kind: "close-cluster" }));
  const m1ReactionTolerance = Math.max(currentPip || 0.0001, (averageRange(latestHistory, 30) || latestAvgRange) * 0.32);
  const entryPoiCandidates = getInstitutionalReactionPoiLevels(latestHistory.slice(-360), m1ReactionTolerance, {
    pivotLen: 3,
    minTouches: 2,
    source: mtf.entryLabel,
  });
  const latestPoiCandidates = mergeInstitutionalPoiCandidates(
    [alignPoiCandidates, entryPoiCandidates],
    Math.max(latestTolerance, m1ReactionTolerance),
  );
  const displayPoiLevels = resolveStableInstitutionalPoiLevels({
    candidates: latestPoiCandidates,
    currentPrice: latestCurrent?.close,
    avgRange: latestAvgRange,
    tolerance: latestTolerance,
    stateKey: `${currentSymbol || "symbol"}|${executionTf}|IEM_POI`,
    maxLevels: 6,
  });

  const result = {
    signals,
    poiLevels: displayPoiLevels,
    stats: {
      total: signals.length,
      wins,
      losses,
      pending: signals.length - scored.length,
      winRate,
      minConfidence,
      expiryBars,
    },
    trendMain: getInstitutionalTrend(latestMain),
    trendAlign: getInstitutionalTrend(latestAlign),
    mainLabel: mtf.mainLabel,
    alignLabel: mtf.alignLabel,
    entryLabel: mtf.entryLabel,
  };
  if (!config.noCache) institutionalExecutionModelCache = { key: cacheKey, value: result };
  return result;
}

function buildInstitutionalLevelBehaviorModel(candles, config = {}) {
  const confirmedCandles = Array.isArray(candles) ? candles.slice(0, -1) : [];
  const last = confirmedCandles[confirmedCandles.length - 1] || null;
  const executionTf = Math.max(1, Number(config.baseSeconds || candleBuilder?.timeframe || DEFAULT_TIMEFRAME_SEC));
  const cacheKey = [
    currentSymbol || "symbol",
    executionTf,
    currentPip || 0,
    baseMinutes || 1,
    config.minConfidence ?? 65,
    config.lookbackBars ?? 420,
    confirmedCandles.length,
    last?.time ?? 0,
    last?.open ?? 0,
    last?.high ?? 0,
    last?.low ?? 0,
    last?.close ?? 0,
  ].join("|");
  if (!config.noCache && institutionalLevelBehaviorModelCache?.key === cacheKey) {
    return institutionalLevelBehaviorModelCache.value;
  }
  const minCandles = Math.max(80, config.minCandles ?? 90);
  if (confirmedCandles.length < minCandles) {
    const mtf = getMtfTimeframeSet(executionTf);
    const empty = {
      signals: [],
      poiLevels: [],
      stats: { total: 0, wins: 0, losses: 0, pending: 0, winRate: null, minConfidence: 65 },
      mainLabel: mtf.mainLabel,
      alignLabel: mtf.alignLabel,
      entryLabel: mtf.entryLabel,
    };
    institutionalLevelBehaviorModelCache = { key: cacheKey, value: empty };
    return empty;
  }

  const mtf = getMtfTimeframeSet(executionTf);
  const expiryBars = Math.max(1, Math.round(((config.expirySeconds ?? (baseMinutes * 60)) || 60) / Math.max(1, executionTf)));
  const minConfidence = Math.max(0, Math.min(100, config.minConfidence ?? 65));
  const structureLookbackBars = Math.max(180, config.lookbackBars ?? 420);
  const signals = [];
  const seenSignalKeys = new Set();
  let lastSignalIndex = -10;

  for (let i = minCandles; i < confirmedCandles.length; i += 1) {
    const current = confirmedCandles[i];
    const historyStart = Math.max(0, i - structureLookbackBars + 1);
    const history = confirmedCandles.slice(historyStart, i + 1);
    const mainCandles = aggregateCandlesByTimeframe(history, mtf.mainSeconds);
    const trendMain = getInstitutionalTrend(mainCandles);
    const pool = buildInstitutionalPoiCandidatePool(history, mtf.alignSeconds, mtf.entrySeconds);
    const atLevelTolerance = Math.max(pool.tolerance, pool.avgRange * 0.35, currentPip || 0.0001);
    const touchedLevels = pool.candidates
      .map((level) => ({ ...level, distance: Math.min(Math.abs(current.close - level.price), Math.abs(current.high - level.price), Math.abs(current.low - level.price)) }))
      .filter((level) => level.distance <= atLevelTolerance)
      .sort((a, b) => a.distance - b.distance || b.strength - a.strength);
    const level = touchedLevels[0] || null;
    if (!level) continue;
    if (i - lastSignalIndex < Math.max(4, config.cooldownBars ?? 8)) continue;

    const touchState = countInstitutionalLevelTouches(history.slice(-180), level, atLevelTolerance);
    const touches = Math.max(touchState.touches, 1);
    const fakeBreakDirection = getInstitutionalFakeBreakDirection(current, level, atLevelTolerance);
    const strongBreakDirection = getInstitutionalStrongBreakDirection(current, level, atLevelTolerance);
    let direction = null;
    let behavior = null;

    if (fakeBreakDirection) {
      direction = fakeBreakDirection;
      behavior = "FAKE_BREAK_REVERSAL";
    } else if (touches <= 2) {
      if (hasInstitutionalConfirmation(history, "BUY") && current.close >= level.price) {
        direction = "BUY";
        behavior = touches === 1 ? "FIRST_TOUCH_REVERSAL" : "SECOND_TOUCH_REVERSAL";
      } else if (hasInstitutionalConfirmation(history, "SELL") && current.close <= level.price) {
        direction = "SELL";
        behavior = touches === 1 ? "FIRST_TOUCH_REVERSAL" : "SECOND_TOUCH_REVERSAL";
      }
    } else if (strongBreakDirection) {
      direction = strongBreakDirection;
      behavior = "MULTI_TOUCH_BREAKOUT";
    }
    if (!direction || !behavior) continue;

    const trendBonus =
      trendMain === "BULLISH" && direction === "BUY" ? 8 :
      trendMain === "BEARISH" && direction === "SELL" ? 8 :
      0;
    const touchScore = touches <= 2
      ? Math.max(0, 18 - ((touches - 1) * 7))
      : Math.min(18, (touches - 2) * 6);
    const breakScore = behavior === "MULTI_TOUCH_BREAKOUT" ? 18 : behavior === "FAKE_BREAK_REVERSAL" ? 16 : 10;
    const confidence = Math.round(clamp(
      35 +
      touchScore +
      breakScore +
      trendBonus +
      clamp(level.strength / 12, 0, 1) * 12 +
      clamp(1 - (level.distance / atLevelTolerance), 0, 1) * 9,
      0,
      100,
    ));
    if (confidence < minConfidence) continue;

    const entryIndex = i + 1;
    const entryCandle = candles[entryIndex] || null;
    const entryPrice = entryCandle?.open ?? entryCandle?.close ?? current.close;
    const targetIndex = entryIndex + expiryBars;
    const target = confirmedCandles[targetIndex] || null;
    const won = target
      ? direction === "BUY"
        ? target.close > entryPrice
        : target.close < entryPrice
      : null;
    const key = `${direction}|${behavior}|${entryIndex}|${Math.round(level.price / Math.max(atLevelTolerance, 0.0000001))}`;
    if (seenSignalKeys.has(key)) continue;
    seenSignalKeys.add(key);
    lastSignalIndex = i;

    signals.push({
      confirmationIndex: i,
      entryIndex,
      targetIndex,
      direction,
      behavior,
      price: entryPrice,
      level: level.price,
      poi: level.price,
      touches,
      levelStrength: 1 / Math.max(1, touches),
      confidence,
      mainLabel: mtf.mainLabel,
      alignLabel: mtf.alignLabel,
      entryLabel: mtf.entryLabel,
      result: won == null ? "PENDING" : won ? "WIN" : "LOSS",
    });
  }

  const latestPool = buildInstitutionalPoiCandidatePool(confirmedCandles.slice(-structureLookbackBars), mtf.alignSeconds, mtf.entrySeconds);
  const latestCurrent = confirmedCandles[confirmedCandles.length - 1] || null;
  const poiLevels = resolveStableInstitutionalPoiLevels({
    candidates: latestPool.candidates,
    currentPrice: latestCurrent?.close,
    avgRange: latestPool.avgRange,
    tolerance: latestPool.tolerance,
    stateKey: `${currentSymbol || "symbol"}|${executionTf}|ILB_POI`,
    maxLevels: 6,
  });
  const scored = signals.filter((signal) => signal.result !== "PENDING");
  const wins = scored.filter((signal) => signal.result === "WIN").length;
  const losses = scored.length - wins;

  const result = {
    signals,
    poiLevels,
    stats: {
      total: signals.length,
      wins,
      losses,
      pending: signals.length - scored.length,
      winRate: scored.length ? Math.round((wins / scored.length) * 100) : null,
      minConfidence,
      expiryBars,
    },
    mainLabel: mtf.mainLabel,
    alignLabel: mtf.alignLabel,
    entryLabel: mtf.entryLabel,
  };
  if (!config.noCache) institutionalLevelBehaviorModelCache = { key: cacheKey, value: result };
  return result;
}

function loadInstitutionalSignalDb() {
  try {
    const parsed = JSON.parse(localStorage.getItem(INSTITUTIONAL_SIGNAL_DB_KEY) || "[]");
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function saveInstitutionalSignalDb(records) {
  try {
    const trimmed = (Array.isArray(records) ? records : [])
      .slice(-INSTITUTIONAL_MAX_DB_RECORDS);
    localStorage.setItem(INSTITUTIONAL_SIGNAL_DB_KEY, JSON.stringify(trimmed));
  } catch {
    // Ignore storage failures; the signal engine still runs without learning history.
  }
}

function getInstitutionalSessionState(epochSec = Math.floor(Date.now() / 1000)) {
  const key = getKillzoneKey(epochSec);
  const active = key === "LONDON" || key === "NYAM" || key === "NYPM";
  const label =
    key === "LONDON" ? "London" :
    key === "NYAM" || key === "NYPM" ? "New York" :
    key === "ASIA" ? "Asia" :
    "Low liquidity";
  const score = key === "LONDON" ? 1 : key === "NYAM" ? 0.95 : key === "NYPM" ? 0.82 : key === "ASIA" ? 0.35 : 0.2;
  return { key, label, active, score };
}

function buildInstitutionalBias(candles) {
  if (!Array.isArray(candles) || candles.length < 18) {
    return { trend: "RANGE", strength: 0, label: "building" };
  }
  const structure = buildICTStructureAnalysis(candles, 3);
  const latestEvents = structure.events.slice(-4);
  const lastHigh = structure.pivotHighs[structure.pivotHighs.length - 1] || null;
  const prevHigh = structure.pivotHighs[structure.pivotHighs.length - 2] || null;
  const lastLow = structure.pivotLows[structure.pivotLows.length - 1] || null;
  const prevLow = structure.pivotLows[structure.pivotLows.length - 2] || null;
  const closeStructure = assessCloseStructure(candles);
  const emaTrend = detectEmaTrend(candles);
  let bull = 0;
  let bear = 0;

  latestEvents.forEach((event) => {
    const weight = event.type === "MSS" ? 1.25 : 1;
    if (event.direction === "UP") bull += weight;
    if (event.direction === "DOWN") bear += weight;
  });
  if (lastHigh && prevHigh && lastHigh.price > prevHigh.price) bull += 0.8;
  if (lastLow && prevLow && lastLow.price > prevLow.price) bull += 0.8;
  if (lastHigh && prevHigh && lastHigh.price < prevHigh.price) bear += 0.8;
  if (lastLow && prevLow && lastLow.price < prevLow.price) bear += 0.8;
  if (closeStructure.bias === "UP") bull += 0.7;
  if (closeStructure.bias === "DOWN") bear += 0.7;
  if (emaTrend.trend === "UP") bull += 0.45;
  if (emaTrend.trend === "DOWN") bear += 0.45;

  const total = bull + bear;
  const edge = total ? Math.abs(bull - bear) / total : 0;
  const trend = edge < 0.16 ? "RANGE" : bull > bear ? "UP" : "DOWN";
  const lastEvent = latestEvents[latestEvents.length - 1];
  return {
    trend,
    strength: clamp(edge, 0, 1),
    bull,
    bear,
    label: lastEvent ? `${lastEvent.type} ${lastEvent.direction}` : closeStructure.bias,
    structure,
    closeStructure,
  };
}

function enrichInstitutionalLevel(candles, level, tolerance, currentPrice) {
  const touchState = countInstitutionalLevelTouches(candles, level, tolerance);
  const recent = candles.slice(-80);
  let rejectionStrength = 0;
  let lastInteraction = touchState.lastTouchIndex;
  recent.forEach((candle, localIndex) => {
    const touched = candle.high >= level.price - tolerance && candle.low <= level.price + tolerance;
    if (!touched) return;
    const rejection = analyzeRejection(candle);
    const range = Math.max(candle.high - candle.low, currentPip || 0.0001);
    const wick = level.price >= currentPrice ? rejection.upperWick : rejection.lowerWick;
    rejectionStrength = Math.max(rejectionStrength, clamp(wick / range, 0, 1));
    lastInteraction = candles.length - recent.length + localIndex;
  });
  const touches = Math.max(touchState.touches, level.strength || 1);
  return {
    ...level,
    touches,
    rejectionStrength,
    lastInteraction,
    recentInteractionBars: lastInteraction == null ? null : candles.length - 1 - lastInteraction,
    distance: Math.abs(currentPrice - level.price),
    behavior: touches >= 3 ? "breakout risk" : "reversal zone",
  };
}

function buildInstitutionalReactionZones(entryCandles, alignCandles, currentPrice) {
  const avgRange = averageRange(entryCandles, 40) || averageRange(alignCandles, 30) || Math.max(Math.abs(currentPrice) * 0.0005, currentPip || 0.0001);
  const tolerance = Math.max(currentPip || 0.0001, avgRange * 0.35);
  const alignLevels = getInstitutionalReactionPoiLevels(alignCandles.slice(-160), Math.max(tolerance, (averageRange(alignCandles, 30) || avgRange) * 0.28), {
    pivotLen: 3,
    minTouches: 2,
    source: "5M",
  });
  const entryLevels = getInstitutionalReactionPoiLevels(entryCandles.slice(-360), tolerance, {
    pivotLen: 3,
    minTouches: 2,
    source: "1M",
  });
  const previousHighLow = [];
  const recent = entryCandles.slice(-90);
  if (recent.length) {
    previousHighLow.push({ price: Math.max(...recent.slice(0, -1).map((c) => c.high)), strength: 2, source: "1M", kind: "previous-high" });
    previousHighLow.push({ price: Math.min(...recent.slice(0, -1).map((c) => c.low)), strength: 2, source: "1M", kind: "previous-low" });
  }
  const merged = mergeInstitutionalPoiCandidates([alignLevels, entryLevels, previousHighLow], tolerance);
  const levels = merged
    .map((level) => enrichInstitutionalLevel(entryCandles.slice(-420), level, tolerance, currentPrice))
    .sort((a, b) => a.distance - b.distance || b.touches - a.touches)
    .slice(0, 10);
  const activePoi = levels.find((level) => level.distance <= tolerance * 1.6) || levels[0] || null;
  return { levels, activePoi, tolerance, avgRange };
}

function detectInstitutionalCandlePattern(candles, direction, avgRange) {
  if (!Array.isArray(candles) || candles.length < 2 || !direction) {
    return { confirmed: false, label: "--", quality: 0 };
  }
  const current = candles[candles.length - 1];
  const previous = candles[candles.length - 2];
  const range = Math.max(current.high - current.low, currentPip || 0.0001);
  const body = Math.abs(current.close - current.open);
  const upper = current.high - Math.max(current.open, current.close);
  const lower = Math.min(current.open, current.close) - current.low;
  const bodyRatio = body / range;
  const momentum = clamp(body / Math.max(avgRange || range, currentPip || 0.0001), 0, 1);
  const bullishEngulf = current.close > current.open && current.close > previous.open && current.open <= previous.close;
  const bearishEngulf = current.close < current.open && current.close < previous.open && current.open >= previous.close;
  const doji = bodyRatio <= 0.22 && Math.max(upper, lower) >= body * 1.6;
  const hammer = lower >= body * 1.8 && upper <= range * 0.35 && current.close > current.open;
  const shootingStar = upper >= body * 1.8 && lower <= range * 0.35 && current.close < current.open;
  const strongBull = current.close > current.open && bodyRatio >= 0.62 && momentum >= 0.55;
  const strongBear = current.close < current.open && bodyRatio >= 0.62 && momentum >= 0.55;

  if (direction === "BUY") {
    if (bullishEngulf) return { confirmed: true, label: "bullish engulfing", quality: 1 };
    if (hammer) return { confirmed: true, label: "hammer rejection", quality: 0.86 };
    if (strongBull) return { confirmed: true, label: "bullish momentum", quality: 0.78 };
    if (doji && lower > upper) return { confirmed: true, label: "bullish indecision reject", quality: 0.58 };
  }
  if (direction === "SELL") {
    if (bearishEngulf) return { confirmed: true, label: "bearish engulfing", quality: 1 };
    if (shootingStar) return { confirmed: true, label: "shooting star rejection", quality: 0.86 };
    if (strongBear) return { confirmed: true, label: "bearish momentum", quality: 0.78 };
    if (doji && upper > lower) return { confirmed: true, label: "bearish indecision reject", quality: 0.58 };
  }
  return { confirmed: false, label: "--", quality: 0 };
}

function getAdaptiveInstitutionalStats(features) {
  const records = loadInstitutionalSignalDb().filter((record) => record.outcome === "WIN" || record.outcome === "LOSS");
  const base = { scoreAdjustment: 0, take: true, label: "learning neutral", samples: records.length, rollingWinRate: null };
  if (!records.length) return base;
  const recent = records.slice(-80);
  const wins = recent.filter((record) => record.outcome === "WIN").length;
  const rollingWinRate = Math.round((wins / recent.length) * 100);
  const featureDirection = features.direction === "BUY" ? "CALL" : features.direction === "SELL" ? "PUT" : features.direction;
  const similar = recent.filter((record) => (
    record.direction === featureDirection &&
    record.sessionKey === features.sessionKey &&
    record.poiBehavior === features.poiBehavior &&
    record.pattern === features.pattern
  ));
  if (similar.length < 6) {
    return {
      ...base,
      scoreAdjustment: rollingWinRate >= 58 ? 3 : rollingWinRate <= 42 ? -4 : 0,
      label: `rolling ${rollingWinRate}%`,
      rollingWinRate,
    };
  }
  const similarWins = similar.filter((record) => record.outcome === "WIN").length;
  const similarRate = Math.round((similarWins / similar.length) * 100);
  return {
    scoreAdjustment: similarRate >= 62 ? 8 : similarRate >= 55 ? 4 : similarRate <= 38 ? -12 : similarRate <= 45 ? -7 : 0,
    take: similarRate >= 40,
    label: `similar ${similarRate}% (${similar.length})`,
    samples: records.length,
    rollingWinRate,
  };
}

function getInstitutionalSignalStats(symbol = currentSymbol) {
  const records = loadInstitutionalSignalDb()
    .filter((record) => !symbol || !record.symbol || record.symbol === symbol);
  const scored = records.filter((record) => record.outcome === "WIN" || record.outcome === "LOSS");
  const recent = scored.slice(-30);
  const wins = recent.filter((record) => record.outcome === "WIN").length;
  const lastSignals = records.slice(-3).reverse().map((record) => {
    const side = record.direction === "CALL" ? "BUY" : "SELL";
    return `${side} ${record.outcome || "PENDING"} ${Number.isFinite(record.confidence) ? record.confidence + "%" : ""}`.trim();
  });
  return {
    total: records.length,
    scored: scored.length,
    wins,
    losses: recent.length - wins,
    winRate: recent.length ? Math.round((wins / recent.length) * 100) : null,
    lastSignals,
  };
}

function buildInstitutionalForexSignalEngine(sourceCandles, options = {}) {
  const candles = Array.isArray(sourceCandles) ? sourceCandles.filter(Boolean) : [];
  const baseSeconds = Math.max(1, Number(options.baseSeconds || getChartTimeframeSeconds()) || DEFAULT_TIMEFRAME_SEC);
  if (candles.length < 120) {
    return {
      direction: null,
      confidence: 0,
      signal: "--",
      htfTrend: "BUILDING",
      currentPoi: "--",
      liquidityStatus: "--",
      confirmationStatus: "--",
      sessionStatus: "--",
      reason: "Need more 1m history for 15m/5m confirmation",
      rollingWinRate: null,
      entryPrice: null,
    };
  }

  const entryCandles = baseSeconds === 60 ? candles : aggregateCandlesByTimeframe(candles, 60);
  const m5 = aggregateCandlesByTimeframe(candles, 300);
  const m15 = aggregateCandlesByTimeframe(candles, 900);
  const current = entryCandles[entryCandles.length - 1];
  if (!current || entryCandles.length < 60 || m5.length < 18 || m15.length < 10) {
    return {
      direction: null,
      confidence: 0,
      signal: "--",
      htfTrend: "BUILDING",
      currentPoi: "--",
      liquidityStatus: "--",
      confirmationStatus: "--",
      sessionStatus: "--",
      reason: "Building 15m/5m/1m history",
      rollingWinRate: null,
      entryPrice: null,
    };
  }

  const bias15 = buildInstitutionalBias(m15);
  const bias5 = buildInstitutionalBias(m5);
  const htfAligned = bias15.trend !== "RANGE" && bias15.trend === bias5.trend;
  const zones = buildInstitutionalReactionZones(entryCandles, m5, current.close);
  const poi = zones.activePoi;
  const atPoi = Boolean(poi && poi.distance <= zones.tolerance * 1.6);
  const sweepState = poi
    ? {
        direction: getInstitutionalFakeBreakDirection(current, poi, zones.tolerance),
        level: poi.price,
        rejection: analyzeRejection(current),
      }
    : { direction: null, level: null, rejection: null };
  const expectedDirection = bias15.trend === "UP" ? "BUY" : bias15.trend === "DOWN" ? "SELL" : null;
  const liquidityDirection = sweepState.direction;
  const direction = htfAligned && expectedDirection && liquidityDirection === expectedDirection ? expectedDirection : null;
  const candlePattern = detectInstitutionalCandlePattern(entryCandles, direction, zones.avgRange);
  const session = getInstitutionalSessionState(current.time || Math.floor(Date.now() / 1000));
  const volatility = zones.avgRange ? clamp((current.high - current.low) / zones.avgRange, 0, 2) / 2 : 0;
  const rejectionStrength = direction === "BUY"
    ? clamp((sweepState.rejection?.lowerWick || 0) / Math.max(zones.avgRange, currentPip || 0.0001), 0, 1)
    : direction === "SELL"
      ? clamp((sweepState.rejection?.upperWick || 0) / Math.max(zones.avgRange, currentPip || 0.0001), 0, 1)
      : 0;
  const distanceScore = poi ? clamp(1 - (poi.distance / Math.max(zones.tolerance * 1.6, currentPip || 0.0001)), 0, 1) : 0;
  const poiStrength = poi ? clamp((poi.touches <= 2 ? 0.75 : 0.45) + Math.min(0.25, poi.rejectionStrength * 0.25), 0, 1) : 0;
  const momentum = direction === "BUY"
    ? assessCloseStructure(entryCandles).bullScore
    : direction === "SELL"
      ? assessCloseStructure(entryCandles).bearScore
      : 0;
  const sweepQuality = direction ? clamp((rejectionStrength * 0.65) + (distanceScore * 0.35), 0, 1) : 0;
  const rawScore = Math.round(clamp(
    (htfAligned ? 0.18 : 0) +
    (poiStrength * 0.16) +
    (sweepQuality * 0.18) +
    (candlePattern.quality * 0.16) +
    (momentum * 0.1) +
    (session.score * 0.08) +
    (volatility * 0.06) +
    (distanceScore * 0.04) +
    (rejectionStrength * 0.04),
    0,
    1,
  ) * 100);
  const adaptive = getAdaptiveInstitutionalStats({
    direction,
    sessionKey: session.key,
    poiBehavior: poi?.behavior,
    pattern: candlePattern.label,
  });
  const confidence = clamp(rawScore + adaptive.scoreAdjustment, 0, 100);
  const takeSetup = Boolean(
    direction &&
    htfAligned &&
    atPoi &&
    session.active &&
    candlePattern.confirmed &&
    confidence >= 70 &&
    adaptive.take
  );
  const expirySeconds = Number(options.expirySeconds || INSTITUTIONAL_EXPIRY_SECONDS);
  const expiryBars = Math.max(1, Math.round(expirySeconds / 60));
  const signalDirection = direction === "BUY" ? "CALL" : direction === "SELL" ? "PUT" : null;
  const signal = takeSetup ? `${direction} ${Math.round(expirySeconds / 60)}M` : "--";
  const currentPoi = poi
    ? `${formatPrice(poi.price, currentPip)} ${poi.touches}t ${poi.behavior}`
    : "--";
  const liquidityStatus = sweepState.direction
    ? `${sweepState.direction} sweep @ ${formatPrice(sweepState.level, currentPip)}`
    : poi ? "At POI, waiting sweep" : "No POI touch";
  const reasonParts = [
    htfAligned ? `15m/5m ${bias15.trend}` : `HTF mismatch 15m ${bias15.trend} / 5m ${bias5.trend}`,
    poi ? `POI ${poi.touches} touch ${poi.behavior}` : "no POI",
    sweepState.direction ? `${sweepState.direction} liquidity sweep` : "no sweep",
    candlePattern.confirmed ? candlePattern.label : "no candle confirmation",
    session.label,
    adaptive.label,
  ];

  return {
    direction: takeSetup ? signalDirection : null,
    rawDirection: signalDirection,
    tradeDirection: signalDirection,
    institutionalDirection: direction,
    confidence,
    rawScore,
    signal,
    htfTrend: htfAligned ? `${bias15.trend} 15m + 5m` : `NO TRADE ${bias15.trend}/${bias5.trend}`,
    currentPoi,
    poi,
    liquidityStatus,
    sweepDetected: Boolean(sweepState.direction),
    confirmationStatus: candlePattern.confirmed ? candlePattern.label : "--",
    sessionStatus: `${session.label}${session.active ? " active" : " avoid"}`,
    session,
    reason: reasonParts.join(" | "),
    rollingWinRate: adaptive.rollingWinRate,
    entryPrice: Number(current.close),
    entryTime: Number(current.time || Math.floor(Date.now() / 1000)),
    expirySeconds,
    expiryBars,
    expiryTime: Number(current.time || Math.floor(Date.now() / 1000)) + expirySeconds,
    features: {
      htf15: bias15.trend,
      htf5: bias5.trend,
      poiPrice: poi?.price ?? null,
      poiTouches: poi?.touches ?? null,
      poiBehavior: poi?.behavior ?? null,
      sweepDirection: sweepState.direction,
      pattern: candlePattern.label,
      sessionKey: session.key,
      sessionLabel: session.label,
      volatility,
      distanceScore,
      rejectionStrength,
      momentum,
      confidence,
    },
  };
}

function persistInstitutionalSignal(engine, symbol = currentSymbol) {
  if (!engine?.direction || !Number.isFinite(engine.entryTime) || !Number.isFinite(engine.entryPrice)) return;
  const records = loadInstitutionalSignalDb();
  const key = [
    symbol || "symbol",
    engine.direction,
    engine.entryTime,
    Math.round((engine.poi?.price || engine.entryPrice) / Math.max(currentPip || 0.0001, 0.0000001)),
  ].join("|");
  if (records.some((record) => record.key === key)) return;
  records.push({
    key,
    symbol: symbol || "",
    direction: engine.direction,
    institutionalDirection: engine.institutionalDirection,
    entryPrice: engine.entryPrice,
    entryTime: engine.entryTime,
    timeframe: "1m",
    expirySeconds: engine.expirySeconds,
    expiryTime: engine.expiryTime,
    htfTrend: engine.htfTrend,
    poi: engine.currentPoi,
    liquidity: engine.liquidityStatus,
    pattern: engine.confirmationStatus,
    confidence: engine.confidence,
    outcome: "PENDING",
    ...engine.features,
  });
  saveInstitutionalSignalDb(records);
}

function evaluateInstitutionalSignalOutcomes(candles, symbol = currentSymbol) {
  const records = loadInstitutionalSignalDb();
  if (!records.length || !Array.isArray(candles) || !candles.length) return;
  let changed = false;
  records.forEach((record) => {
    if (record.outcome !== "PENDING") return;
    if (symbol && record.symbol && record.symbol !== symbol) return;
    const expiryTime = Number(record.expiryTime);
    const expiryCandle = candles.find((candle) => Number(candle.time) >= expiryTime);
    if (!expiryCandle) return;
    const close = Number(expiryCandle.close);
    const entry = Number(record.entryPrice);
    if (!Number.isFinite(close) || !Number.isFinite(entry)) return;
    if (close === entry) {
      record.outcome = "LOSS";
    } else if (record.direction === "CALL") {
      record.outcome = close > entry ? "WIN" : "LOSS";
    } else {
      record.outcome = close < entry ? "WIN" : "LOSS";
    }
    record.exitPrice = close;
    record.evaluatedAt = Math.floor(Date.now() / 1000);
    changed = true;
  });
  if (changed) saveInstitutionalSignalDb(records);
}

function buildChartPatternsSignals(candles, config = {}) {
  const pivotLen = Math.max(2, config.pivotLen ?? 3);
  const toleranceMult = config.toleranceMult ?? 0.45;
  const maxPatternAge = config.maxPatternAge ?? 60;
  const confirmedCandles = candles.slice(0, -1);

  if (!Array.isArray(candles) || confirmedCandles.length < 30) {
    return { patterns: [], signals: [] };
  }

  const avgRange = averageRange(confirmedCandles, 30) || ((confirmedCandles[confirmedCandles.length - 1]?.close ?? 1) * 0.001);
  const tolerance = Math.max(avgRange * toleranceMult, currentPip || 0.0001);
  const pivotHighs = [];
  const pivotLows = [];
  for (let i = pivotLen; i < confirmedCandles.length - pivotLen; i += 1) {
    if (isPivotHighLR(confirmedCandles, i, pivotLen, pivotLen)) pivotHighs.push({ index: i, price: confirmedCandles[i].high });
    if (isPivotLowLR(confirmedCandles, i, pivotLen, pivotLen)) pivotLows.push({ index: i, price: confirmedCandles[i].low });
  }

  const patterns = [];
  const signals = [];
  const seenPatternKeys = new Set();
  const pushPattern = (pattern) => {
    const key = `${pattern.type}|${pattern.startIndex}|${pattern.breakIndex}|${pattern.direction}`;
    if (seenPatternKeys.has(key)) return;
    seenPatternKeys.add(key);
    patterns.push(pattern);
    if (pattern.entryIndex != null) {
      signals.push({
        type: pattern.type,
        direction: pattern.direction,
        entryIndex: pattern.entryIndex,
        breakIndex: pattern.breakIndex,
        label: pattern.label,
      });
    }
  };

  const highBetween = (from, to) => {
    let high = Number.NEGATIVE_INFINITY;
    for (let i = from; i <= to; i += 1) high = Math.max(high, confirmedCandles[i].high);
    return high;
  };

  const lowBetween = (from, to) => {
    let low = Number.POSITIVE_INFINITY;
    for (let i = from; i <= to; i += 1) low = Math.min(low, confirmedCandles[i].low);
    return low;
  };

  const findBreakAbove = (fromIndex, level) => {
    for (let i = fromIndex; i < confirmedCandles.length; i += 1) {
      if (confirmedCandles[i].close > level) return i;
    }
    return null;
  };

  const findBreakBelow = (fromIndex, level) => {
    for (let i = fromIndex; i < confirmedCandles.length; i += 1) {
      if (confirmedCandles[i].close < level) return i;
    }
    return null;
  };

  const lineValueAt = (a, b, index) => {
    const dx = b.index - a.index;
    if (dx === 0) return a.price;
    return a.price + (((b.price - a.price) / dx) * (index - a.index));
  };

  const highestPivotLowBetween = (from, to) => {
    let best = null;
    for (const pivot of pivotLows) {
      if (pivot.index <= from || pivot.index >= to) continue;
      if (!best || pivot.price > best.price) best = pivot;
    }
    return best;
  };

  const lowestPivotHighBetween = (from, to) => {
    let best = null;
    for (const pivot of pivotHighs) {
      if (pivot.index <= from || pivot.index >= to) continue;
      if (!best || pivot.price < best.price) best = pivot;
    }
    return best;
  };

  for (let i = 1; i < pivotLows.length; i += 1) {
    const a = pivotLows[i - 1];
    const b = pivotLows[i];
    const spacing = b.index - a.index;
    if (spacing < 6 || spacing > maxPatternAge) continue;
    if (Math.abs(a.price - b.price) > tolerance) continue;
    const midHighPivot = lowestPivotHighBetween(a.index, b.index);
    if (!midHighPivot) continue;
    const neckline = midHighPivot.price;
    const valleyDepth = neckline - Math.min(a.price, b.price);
    if (valleyDepth < tolerance * 1.5) continue;
    if (Math.abs(a.index - midHighPivot.index) < 2 || Math.abs(b.index - midHighPivot.index) < 2) continue;
    const breakIndex = findBreakAbove(b.index + 1, neckline);
    if (breakIndex == null || breakIndex + 1 >= candles.length) continue;
    pushPattern({
      type: "DOUBLE_BOTTOM",
      label: "Double Bottom",
      direction: "BUY",
      startIndex: a.index,
      breakIndex,
      entryIndex: breakIndex + 1,
      lines: [
        { a, b, kind: "base" },
        { a: { index: midHighPivot.index, price: neckline }, b: { index: breakIndex, price: neckline }, kind: "neck" },
      ],
      pivotPoints: [a, midHighPivot, b],
    });
  }

  for (let i = 1; i < pivotHighs.length; i += 1) {
    const a = pivotHighs[i - 1];
    const b = pivotHighs[i];
    const spacing = b.index - a.index;
    if (spacing < 6 || spacing > maxPatternAge) continue;
    if (Math.abs(a.price - b.price) > tolerance) continue;
    const midLowPivot = highestPivotLowBetween(a.index, b.index);
    if (!midLowPivot) continue;
    const neckline = midLowPivot.price;
    const peakHeight = Math.max(a.price, b.price) - neckline;
    if (peakHeight < tolerance * 1.5) continue;
    if (Math.abs(a.index - midLowPivot.index) < 2 || Math.abs(b.index - midLowPivot.index) < 2) continue;
    const breakIndex = findBreakBelow(b.index + 1, neckline);
    if (breakIndex == null || breakIndex + 1 >= candles.length) continue;
    pushPattern({
      type: "DOUBLE_TOP",
      label: "Double Top",
      direction: "SELL",
      startIndex: a.index,
      breakIndex,
      entryIndex: breakIndex + 1,
      lines: [
        { a, b, kind: "base" },
        { a: { index: midLowPivot.index, price: neckline }, b: { index: breakIndex, price: neckline }, kind: "neck" },
      ],
      pivotPoints: [a, midLowPivot, b],
    });
  }

  for (let i = 2; i < pivotHighs.length; i += 1) {
    const ls = pivotHighs[i - 2];
    const hd = pivotHighs[i - 1];
    const rs = pivotHighs[i];
    if (!(ls.index < hd.index && hd.index < rs.index)) continue;
    if (rs.index - ls.index > maxPatternAge) continue;
    const shoulderTol = Math.max(tolerance, hd.price * 0.002);
    if (!(hd.price > ls.price + tolerance && hd.price > rs.price + tolerance)) continue;
    if (Math.abs(ls.price - rs.price) > shoulderTol) continue;
    const leftNeck = lowBetween(ls.index, hd.index);
    const rightNeck = lowBetween(hd.index, rs.index);
    const neckline = (leftNeck + rightNeck) / 2;
    const breakIndex = findBreakBelow(rs.index + 1, neckline);
    if (breakIndex == null || breakIndex + 1 >= candles.length) continue;
    pushPattern({
      type: "HEAD_SHOULDERS",
      label: "Head & Shoulders",
      direction: "SELL",
      startIndex: ls.index,
      breakIndex,
      entryIndex: breakIndex + 1,
      lines: [
        { a: ls, b: hd, kind: "shape" },
        { a: hd, b: rs, kind: "shape" },
        { a: { index: ls.index, price: neckline }, b: { index: breakIndex, price: neckline }, kind: "neck" },
      ],
      pivotPoints: [ls, hd, rs],
    });
  }

  for (let i = 2; i < pivotLows.length; i += 1) {
    const ls = pivotLows[i - 2];
    const hd = pivotLows[i - 1];
    const rs = pivotLows[i];
    if (!(ls.index < hd.index && hd.index < rs.index)) continue;
    if (rs.index - ls.index > maxPatternAge) continue;
    const shoulderTol = Math.max(tolerance, hd.price * 0.002);
    if (!(hd.price < ls.price - tolerance && hd.price < rs.price - tolerance)) continue;
    if (Math.abs(ls.price - rs.price) > shoulderTol) continue;
    const leftNeck = highBetween(ls.index, hd.index);
    const rightNeck = highBetween(hd.index, rs.index);
    const neckline = (leftNeck + rightNeck) / 2;
    const breakIndex = findBreakAbove(rs.index + 1, neckline);
    if (breakIndex == null || breakIndex + 1 >= candles.length) continue;
    pushPattern({
      type: "INV_HEAD_SHOULDERS",
      label: "Inverse H&S",
      direction: "BUY",
      startIndex: ls.index,
      breakIndex,
      entryIndex: breakIndex + 1,
      lines: [
        { a: ls, b: hd, kind: "shape" },
        { a: hd, b: rs, kind: "shape" },
        { a: { index: ls.index, price: neckline }, b: { index: breakIndex, price: neckline }, kind: "neck" },
      ],
      pivotPoints: [ls, hd, rs],
    });
  }

  const recentHighs = pivotHighs.slice(-3);
  const recentLows = pivotLows.slice(-3);
  if (recentHighs.length >= 2 && recentLows.length >= 2) {
    const h1 = recentHighs[recentHighs.length - 2];
    const h2 = recentHighs[recentHighs.length - 1];
    const l1 = recentLows[recentLows.length - 2];
    const l2 = recentLows[recentLows.length - 1];
    const startIndex = Math.min(h1.index, l1.index);
    const lastPivotIndex = Math.max(h2.index, l2.index);
    if (lastPivotIndex - startIndex <= maxPatternAge && Math.max(h1.index, l1.index) < lastPivotIndex) {
      const highsFlat = Math.abs(h1.price - h2.price) <= tolerance;
      const lowsFlat = Math.abs(l1.price - l2.price) <= tolerance;
      const highsRising = h2.price > h1.price + tolerance * 0.3;
      const highsFalling = h2.price < h1.price - tolerance * 0.3;
      const lowsRising = l2.price > l1.price + tolerance * 0.3;
      const lowsFalling = l2.price < l1.price - tolerance * 0.3;
      const converging = Math.abs(h2.price - l2.price) < Math.abs(h1.price - l1.price);

      const addBreakPattern = (type, label, direction, breakIndex, topLine, bottomLine) => {
        if (breakIndex == null || breakIndex + 1 >= candles.length) return;
        pushPattern({
          type,
          label,
          direction,
          startIndex,
          breakIndex,
          entryIndex: breakIndex + 1,
          lines: [
            { a: topLine[0], b: topLine[1], kind: "upper" },
            { a: bottomLine[0], b: bottomLine[1], kind: "lower" },
          ],
          pivotPoints: [h1, h2, l1, l2],
        });
      };

      if (highsFlat && lowsRising) {
        const resistance = (h1.price + h2.price) / 2;
        addBreakPattern("ASC_TRIANGLE", "Ascending Triangle", "BUY", findBreakAbove(lastPivotIndex + 1, resistance), [h1, h2], [l1, l2]);
      }
      if (lowsFlat && highsFalling) {
        const support = (l1.price + l2.price) / 2;
        addBreakPattern("DESC_TRIANGLE", "Descending Triangle", "SELL", findBreakBelow(lastPivotIndex + 1, support), [h1, h2], [l1, l2]);
      }
      if (highsFalling && lowsRising && converging) {
        let breakIndex = null;
        let direction = null;
        for (let i = lastPivotIndex + 1; i < confirmedCandles.length; i += 1) {
          const upper = lineValueAt(h1, h2, i);
          const lower = lineValueAt(l1, l2, i);
          if (confirmedCandles[i].close > upper) {
            breakIndex = i;
            direction = "BUY";
            break;
          }
          if (confirmedCandles[i].close < lower) {
            breakIndex = i;
            direction = "SELL";
            break;
          }
        }
        if (direction) addBreakPattern("SYM_TRIANGLE", "Sym Triangle", direction, breakIndex, [h1, h2], [l1, l2]);
      }
      if (highsFalling && lowsFalling && converging) {
        let breakIndex = null;
        for (let i = lastPivotIndex + 1; i < confirmedCandles.length; i += 1) {
          const upper = lineValueAt(h1, h2, i);
          if (confirmedCandles[i].close > upper) {
            breakIndex = i;
            break;
          }
        }
        addBreakPattern("FALL_WEDGE", "Falling Wedge", "BUY", breakIndex, [h1, h2], [l1, l2]);
      }
      if (highsRising && lowsRising && converging) {
        let breakIndex = null;
        for (let i = lastPivotIndex + 1; i < confirmedCandles.length; i += 1) {
          const lower = lineValueAt(l1, l2, i);
          if (confirmedCandles[i].close < lower) {
            breakIndex = i;
            break;
          }
        }
        addBreakPattern("RISE_WEDGE", "Rising Wedge", "SELL", breakIndex, [h1, h2], [l1, l2]);
      }
    }
  }

  const impulseLookback = 12;
  for (let i = impulseLookback + 5; i < confirmedCandles.length - 1; i += 1) {
    const impulse = confirmedCandles.slice(i - impulseLookback, i - 4);
    const pullback = confirmedCandles.slice(i - 4, i + 1);
    const impulseMove = impulse[impulse.length - 1].close - impulse[0].open;
    const pullbackHighs = pullback.map((c) => c.high);
    const pullbackLows = pullback.map((c) => c.low);
    const pullbackTop1 = { index: i - 4, price: pullbackHighs[0] };
    const pullbackTop2 = { index: i, price: pullbackHighs[pullbackHighs.length - 1] };
    const pullbackBottom1 = { index: i - 4, price: pullbackLows[0] };
    const pullbackBottom2 = { index: i, price: pullbackLows[pullbackLows.length - 1] };
    const pullbackRange = Math.max(...pullbackHighs) - Math.min(...pullbackLows);
    if (Math.abs(impulseMove) < avgRange * 5 || pullbackRange > Math.abs(impulseMove) * 0.65) continue;

    if (impulseMove > 0) {
      const descendingPullback = pullbackTop2.price < pullbackTop1.price && pullbackBottom2.price <= pullbackBottom1.price + tolerance;
      if (descendingPullback && confirmedCandles[i].close > Math.max(...pullbackHighs.slice(0, -1))) {
        const breakIndex = i;
        if (breakIndex + 1 < candles.length) {
          pushPattern({
            type: "BULL_FLAG",
            label: "Bull Flag",
            direction: "BUY",
            startIndex: i - impulseLookback,
            breakIndex,
            entryIndex: breakIndex + 1,
            lines: [
              { a: pullbackTop1, b: pullbackTop2, kind: "upper" },
              { a: pullbackBottom1, b: pullbackBottom2, kind: "lower" },
            ],
            pivotPoints: [],
          });
        }
      }
    } else if (impulseMove < 0) {
      const ascendingPullback = pullbackBottom2.price > pullbackBottom1.price && pullbackTop2.price >= pullbackTop1.price - tolerance;
      if (ascendingPullback && confirmedCandles[i].close < Math.min(...pullbackLows.slice(0, -1))) {
        const breakIndex = i;
        if (breakIndex + 1 < candles.length) {
          pushPattern({
            type: "BEAR_FLAG",
            label: "Bear Flag",
            direction: "SELL",
            startIndex: i - impulseLookback,
            breakIndex,
            entryIndex: breakIndex + 1,
            lines: [
              { a: pullbackTop1, b: pullbackTop2, kind: "upper" },
              { a: pullbackBottom1, b: pullbackBottom2, kind: "lower" },
            ],
            pivotPoints: [],
          });
        }
      }
    }
  }

  const dedupedSignals = [];
  const seenSignalIndex = new Set();
  signals
    .sort((a, b) => a.entryIndex - b.entryIndex)
    .forEach((signal) => {
      const key = `${signal.entryIndex}|${signal.direction}`;
      if (seenSignalIndex.has(key)) return;
      seenSignalIndex.add(key);
      dedupedSignals.push(signal);
    });

  return {
    patterns: patterns.slice(-10),
    signals: dedupedSignals.slice(-20),
  };
}

function buildChannelsWithPatterns(candles, config = {}) {
  const settings = {
    style: config.style || "Wick",
    breakStyle: Boolean(config.breakStyle),
    instant: config.instant ?? true,
    offset: config.offset ?? 0.625,
    atrLength: Math.max(1, config.atrLength ?? 10),
    atrMultiplier: config.atrMultiplier ?? 4,
    padding: config.padding ?? 50,
    pivotLen: Math.max(1, config.pivotLen ?? 10),
    lookForward: Math.max(1, config.lookForward ?? 15),
    avgLength: Math.max(1, config.avgLength ?? 18),
    history: Math.max(1, config.history ?? 5),
  };
  if (!Array.isArray(candles) || candles.length < settings.pivotLen + settings.lookForward + settings.avgLength + 5) {
    return { channels: [], labels: [], breaks: [] };
  }

  const pickTop = candles.map((c) => settings.style === "Body" ? Math.max(c.open, c.close) : c.high);
  const pickBottom = candles.map((c) => settings.style === "Body" ? Math.min(c.open, c.close) : c.low);
  const pivotHighSource = pickTop.map((high) => ({ high }));
  const pivotLowSource = pickBottom.map((low) => ({ low }));
  const highsAvg = simpleMovingAverage(pickTop, settings.avgLength);
  const lowsAvg = simpleMovingAverage(pickBottom, settings.avgLength);
  const trueRanges = candles.map((c, i) => {
    const prevClose = candles[i - 1]?.close ?? c.close;
    return Math.max(c.high - c.low, Math.abs(c.high - prevClose), Math.abs(c.low - prevClose));
  });
  const atrValues = rmaSeries(trueRanges, settings.atrLength);
  const catrValues = emaSeries(trueRanges, Math.max(2, settings.atrLength)).map((value) => Number.isFinite(value) ? value / 8.71875 : null);
  const bodyRanges = candles.map((c) => Math.abs(c.close - c.open));
  const topWicks = candles.map((c) => c.high - Math.max(c.open, c.close));
  const bottomWicks = candles.map((c) => Math.min(c.open, c.close) - c.low);
  const avgBodies = emaSeries(bodyRanges, 14);
  const avgTopWicks = emaSeries(topWicks, 14);
  const avgBottomWicks = emaSeries(bottomWicks, 14);
  const channels = [];
  const labels = [];
  const breaks = [];
  let active = null;
  let lastPolarity = null;
  let lastHighPivot = null;
  let lastLowPivot = null;

  const candlePatternAt = (i) => {
    const c = candles[i];
    const prev = candles[i - 1];
    if (!c || !prev) return {};
    const bodyTop = Math.max(c.open, c.close);
    const bodyBottom = Math.min(c.open, c.close);
    const prevBodyTop = Math.max(prev.open, prev.close);
    const prevBodyBottom = Math.min(prev.open, prev.close);
    const body = bodyTop - bodyBottom;
    const upper = c.high - bodyTop;
    const lower = bodyBottom - c.low;
    const polarity = c.open < c.close;
    const prevPolarity = prev.open < prev.close;
    const aboveBody = Number.isFinite(avgBodies[i]) && body > avgBodies[i];
    const prevAboveBody = Number.isFinite(avgBodies[i - 1]) && Math.abs(prev.close - prev.open) > avgBodies[i - 1];
    const aboveTopWick = Number.isFinite(avgTopWicks[i]) && upper > avgTopWicks[i];
    const aboveBottomWick = Number.isFinite(avgBottomWicks[i]) && lower > avgBottomWicks[i];
    const hl2 = (c.high + c.low) / 2;
    const safeBody = Math.max(body, currentPip || Math.abs(c.close) * 0.000001 || 0.0000001);
    return {
      hammer: bodyTop >= hl2 && upper <= safeBody * 0.08 && lower / safeBody >= 2 && !aboveBody && aboveBottomWick,
      ihammer: bodyTop <= hl2 && lower <= safeBody * 0.08 && upper / safeBody >= 2 && !aboveBody && aboveTopWick,
      bullishEngulfing: polarity && !prevPolarity && bodyTop > prevBodyTop && bodyBottom <= prevBodyBottom && aboveBody && !prevAboveBody && !aboveBottomWick,
      bearishEngulfing: !polarity && prevPolarity && bodyTop >= prevBodyTop && bodyBottom < prevBodyBottom && aboveBody && !prevAboveBody && !aboveTopWick,
    };
  };

  const channelValue = (channel, key, index) => {
    const dx = Math.max(1, channel.end - channel.start);
    return channel[`${key}1`] + (((channel[`${key}2`] - channel[`${key}1`]) / dx) * (index - channel.start));
  };

  const makeChannel = (i, polarity, pivot) => {
    const atr = (atrValues[i] || averageRange(candles.slice(Math.max(0, i - settings.atrLength), i + 1), settings.atrLength) || Math.abs(candles[i].close) * 0.001) * settings.atrMultiplier;
    const buffer = atr / 7;
    const offset = (atrValues[i] || 0) * 4 / 7 * settings.offset;
    const padding = settings.padding / 100 * 4;
    const avgH = highsAvg[i];
    const avgL = lowsAvg[i];
    const catr = catrValues[i] || 0;
    if (!Number.isFinite(atr) || !Number.isFinite(avgH) || !Number.isFinite(avgL)) return null;
    let top1;
    let top2;
    let bottom1;
    let bottom2;
    let delta;
    if (polarity) {
      top1 = pivot.price + atr + buffer - offset;
      top2 = avgL - catr + atr + buffer - offset;
      bottom1 = pivot.price - buffer - offset;
      bottom2 = avgL - catr - buffer - offset;
      delta = (avgL - catr - pivot.price) / Math.max(1, settings.lookForward + (i - pivot.confirmIndex));
    } else {
      top1 = pivot.price + buffer + offset;
      top2 = avgH + catr + buffer + offset;
      bottom1 = pivot.price - atr - buffer + offset;
      bottom2 = avgH + catr - atr - buffer + offset;
      delta = (avgH + catr - pivot.price) / Math.max(1, settings.lookForward + (i - pivot.confirmIndex));
    }
    const midTop1 = top1 - buffer * padding;
    const midTop2 = top2 - buffer * padding;
    const center1 = (top1 + bottom1) / 2;
    const center2 = (top2 + bottom2) / 2;
    const midBottom1 = bottom1 + buffer * padding;
    const midBottom2 = bottom2 + buffer * padding;
    return {
      polarity,
      start: pivot.index,
      end: i,
      top1,
      top2,
      midTop1,
      midTop2,
      center1,
      center2,
      midBottom1,
      midBottom2,
      bottom1,
      bottom2,
      delta: Number.isFinite(delta) ? delta : 0,
      breakIndex: null,
      breakDirection: null,
    };
  };

  for (let i = 0; i < candles.length; i += 1) {
    const pivotIndex = i - settings.lookForward;
    if (pivotIndex >= settings.pivotLen && pivotIndex < candles.length - settings.lookForward) {
      if (isPivotLowLR(pivotLowSource, pivotIndex, settings.pivotLen, settings.lookForward)) {
        lastLowPivot = { index: pivotIndex, confirmIndex: i, price: pickBottom[pivotIndex] };
      }
      if (isPivotHighLR(pivotHighSource, pivotIndex, settings.pivotLen, settings.lookForward)) {
        lastHighPivot = { index: pivotIndex, confirmIndex: i, price: pickTop[pivotIndex] };
      }
    }

    if (!active) {
      const goingUp = lastLowPivot && lastLowPivot.price < candles[i].low;
      const goingDown = lastHighPivot && lastHighPivot.price > candles[i].high;
      const newUp = lastLowPivot?.confirmIndex === i;
      const newDown = lastHighPivot?.confirmIndex === i;
      const instantUp = settings.instant && lastLowPivot && lastHighPivot && lastLowPivot.index > lastHighPivot.index && lastPolarity === false;
      const instantDown = settings.instant && lastLowPivot && lastHighPivot && lastLowPivot.index < lastHighPivot.index && lastPolarity === true;
      if ((newUp || instantUp) && goingUp) {
        active = makeChannel(i, true, lastLowPivot);
        if (active) {
          channels.push(active);
          lastPolarity = true;
        }
      } else if ((newDown || instantDown) && goingDown) {
        active = makeChannel(i, false, lastHighPivot);
        if (active) {
          channels.push(active);
          lastPolarity = false;
        }
      }
    } else {
      if (i > active.end) {
        active.top2 += active.delta;
        active.midTop2 += active.delta;
        active.center2 += active.delta;
        active.midBottom2 += active.delta;
        active.bottom2 += active.delta;
        active.end = i;
      }
      const top = channelValue(active, "top", i);
      const midTop = channelValue(active, "midTop", i);
      const center = channelValue(active, "center", i);
      const midBottom = channelValue(active, "midBottom", i);
      const bottom = channelValue(active, "bottom", i);
      const breakUpSource = settings.breakStyle ? candles[i].close : candles[i].low;
      const breakDownSource = settings.breakStyle ? candles[i].close : candles[i].high;
      const highCondition = candles[i].high >= midTop && candles[i].low >= center && ((candles[i].high + candles[i].low) / 2) <= top;
      const lowCondition = candles[i].low <= midBottom && candles[i].high <= center && ((candles[i].high + candles[i].low) / 2) >= bottom;
      const patterns = candlePatternAt(i);
      if (highCondition && patterns.ihammer) labels.push({ index: i, price: candles[i].high, side: "top", text: "iH", kind: "ihammer" });
      if (highCondition && patterns.bearishEngulfing) labels.push({ index: i, price: candles[i].high, side: "top", text: "EG", kind: "bearish_engulfing" });
      if (lowCondition && patterns.hammer) labels.push({ index: i, price: candles[i].low, side: "bottom", text: "H", kind: "hammer" });
      if (lowCondition && patterns.bullishEngulfing) labels.push({ index: i, price: candles[i].low, side: "bottom", text: "EG", kind: "bullish_engulfing" });
      if (breakUpSource > top || breakDownSource < bottom) {
        active.breakIndex = i;
        active.breakDirection = breakUpSource > top ? "UP" : "DOWN";
        breaks.push({ index: i, direction: active.breakDirection, price: active.breakDirection === "UP" ? candles[i].low : candles[i].high });
        active = null;
      }
    }
  }

  return {
    channels: channels.slice(-settings.history),
    labels: labels.slice(-80),
    breaks: breaks.slice(-40),
  };
}

function buildLiquiditySweepOrderBlockSystem(candles, config = {}) {
  const pivotLen = Math.max(2, config.pivotLen ?? 3);
  const sweepLookahead = Math.max(4, config.sweepLookahead ?? 10);
  const pullbackLookahead = Math.max(4, config.pullbackLookahead ?? 12);
  const confirmedCandles = candles.slice(0, -1);

  if (!Array.isArray(candles) || confirmedCandles.length < 40) {
    return { pools: [], setups: [] };
  }

  const avgRange = averageRange(confirmedCandles, 20) || ((confirmedCandles[confirmedCandles.length - 1]?.close ?? 1) * 0.001);
  const tolerance = Math.max(avgRange * 0.25, currentPip || 0.0001);
  const structure = buildICTStructureAnalysis(confirmedCandles, pivotLen);
  const orderBlocks = buildICTOrderBlocks(confirmedCandles, structure.events, 12);
  const pools = [];
  const setups = [];
  const seenSetupKeys = new Set();

  const pushPool = (pool) => {
    const key = `${pool.kind}|${pool.side}|${pool.startIndex}|${pool.endIndex ?? pool.startIndex}`;
    if (pools.some((item) => `${item.kind}|${item.side}|${item.startIndex}|${item.endIndex ?? item.startIndex}` === key)) return;
    pools.push(pool);
  };

  structure.pivotHighs.forEach((pivot, index) => {
    pushPool({
      kind: "swingHigh",
      side: "high",
      level: pivot.price,
      startIndex: pivot.index,
      endIndex: pivot.index,
      strength: 1,
    });
    if (index > 0) {
      const prev = structure.pivotHighs[index - 1];
      if (Math.abs(prev.price - pivot.price) <= tolerance) {
        pushPool({
          kind: "equalHigh",
          side: "high",
          level: (prev.price + pivot.price) / 2,
          startIndex: prev.index,
          endIndex: pivot.index,
          strength: 2,
        });
      }
    }
  });

  structure.pivotLows.forEach((pivot, index) => {
    pushPool({
      kind: "swingLow",
      side: "low",
      level: pivot.price,
      startIndex: pivot.index,
      endIndex: pivot.index,
      strength: 1,
    });
    if (index > 0) {
      const prev = structure.pivotLows[index - 1];
      if (Math.abs(prev.price - pivot.price) <= tolerance) {
        pushPool({
          kind: "equalLow",
          side: "low",
          level: (prev.price + pivot.price) / 2,
          startIndex: prev.index,
          endIndex: pivot.index,
          strength: 2,
        });
      }
    }
  });

  for (let i = 1; i < structure.pivotHighs.length; i += 1) {
    const a = structure.pivotHighs[i - 1];
    const b = structure.pivotHighs[i];
    if (b.index - a.index < 6 || b.price >= a.price) continue;
    pushPool({
      kind: "trendlineHigh",
      side: "high",
      startIndex: a.index,
      endIndex: b.index,
      level: b.price,
      a,
      b,
      strength: 2,
    });
  }

  for (let i = 1; i < structure.pivotLows.length; i += 1) {
    const a = structure.pivotLows[i - 1];
    const b = structure.pivotLows[i];
    if (b.index - a.index < 6 || b.price <= a.price) continue;
    pushPool({
      kind: "trendlineLow",
      side: "low",
      startIndex: a.index,
      endIndex: b.index,
      level: b.price,
      a,
      b,
      strength: 2,
    });
  }

  const lineValueAt = (a, b, index) => {
    const dx = b.index - a.index;
    if (dx === 0) return a.price;
    return a.price + (((b.price - a.price) / dx) * (index - a.index));
  };

  const detectSweep = (pool, index) => {
    const candle = confirmedCandles[index];
    const level = pool.a && pool.b ? lineValueAt(pool.a, pool.b, index) : pool.level;
    if (!Number.isFinite(level)) return null;
    if (pool.side === "high") {
      const swept = candle.high > level + (tolerance * 0.1) && candle.close < level;
      if (!swept) return null;
      return { direction: "SELL", level, pool };
    }
    const swept = candle.low < level - (tolerance * 0.1) && candle.close > level;
    if (!swept) return null;
    return { direction: "BUY", level, pool };
  };

  const nearestOrderBlock = (direction, breakIndex) => {
    const source = direction === "BUY" ? orderBlocks.bullish : orderBlocks.bearish;
    let best = null;
    source.forEach((zone) => {
      if (zone.index > breakIndex) return;
      if (!best || zone.index > best.index) best = zone;
    });
    return best;
  };

  for (let i = pivotLen + 3; i < confirmedCandles.length - 1; i += 1) {
    const candidatePools = pools
      .filter((pool) => pool.startIndex < i && i - pool.startIndex <= 60)
      .sort((a, b) => b.strength - a.strength);

    let sweep = null;
    for (const pool of candidatePools) {
      sweep = detectSweep(pool, i);
      if (sweep) break;
    }
    if (!sweep) continue;

    const structureEvent = structure.events.find((event) => (
      event.breakIndex > i &&
      event.breakIndex <= i + sweepLookahead &&
      event.direction === (sweep.direction === "BUY" ? "UP" : "DOWN")
    ));
    if (!structureEvent) continue;

    const ob = nearestOrderBlock(sweep.direction, structureEvent.breakIndex);
    if (!ob) continue;

    for (let j = structureEvent.breakIndex + 1; j < Math.min(confirmedCandles.length, structureEvent.breakIndex + pullbackLookahead); j += 1) {
      const pullback = confirmedCandles[j];
      const touched = pullback.high >= ob.bottom && pullback.low <= ob.top;
      if (!touched) continue;

      const rejection = sweep.direction === "BUY"
        ? pullback.close > pullback.open && pullback.close >= ob.bottom
        : pullback.close < pullback.open && pullback.close <= ob.top;
      if (!rejection) continue;

      const entryIndex = j + 1 < candles.length ? j + 1 : null;
      if (entryIndex == null) continue;
      const key = `${sweep.direction}|${entryIndex}|${sweep.pool.kind}`;
      if (seenSetupKeys.has(key)) break;
      seenSetupKeys.add(key);
      setups.push({
        direction: sweep.direction,
        sweepIndex: i,
        sweepLevel: sweep.level,
        liquidityKind: sweep.pool.kind,
        structureEvent,
        orderBlock: ob,
        pullbackIndex: j,
        entryIndex,
      });
      break;
    }
  }

  return {
    pools: pools.slice(-12),
    setups: setups.slice(-10),
  };
}

function buildLiquidityDrivenMarketStructureSystem(candles, config = {}) {
  const confirmedCandles = candles.slice(0, -1);
  const pivotLen = Math.max(2, config.pivotLen ?? 3);
  const sweepLookahead = Math.max(4, config.sweepLookahead ?? 10);
  const pullbackLookahead = Math.max(4, config.pullbackLookahead ?? 12);

  if (!Array.isArray(candles) || confirmedCandles.length < 40) {
    return {
      trend: "RANGE",
      trendLabel: "RANGE",
      sessionActive: false,
      sessionLabel: "Outside Session",
      confidence: 0,
      setupText: "--",
      pools: [],
      setups: [],
      activeSetup: null,
      latestSweep: null,
    };
  }

  const avgRange = averageRange(confirmedCandles, 20) || ((confirmedCandles[confirmedCandles.length - 1]?.close ?? 1) * 0.001);
  const tolerance = Math.max(avgRange * 0.25, currentPip || 0.0001);
  const structure = buildICTStructureAnalysis(confirmedCandles, pivotLen);
  const fvg = buildICTFVGs(confirmedCandles, 12);
  const orderFlow = buildLiquiditySweepOrderBlockSystem(candles, {
    pivotLen,
    sweepLookahead,
    pullbackLookahead,
  });

  const lastHigh = structure.pivotHighs[structure.pivotHighs.length - 1] || null;
  const prevHigh = structure.pivotHighs[structure.pivotHighs.length - 2] || null;
  const lastLow = structure.pivotLows[structure.pivotLows.length - 1] || null;
  const prevLow = structure.pivotLows[structure.pivotLows.length - 2] || null;

  let trend = "RANGE";
  if (lastHigh && prevHigh && lastLow && prevLow) {
    if (lastHigh.price > prevHigh.price && lastLow.price > prevLow.price) trend = "UP";
    else if (lastHigh.price < prevHigh.price && lastLow.price < prevLow.price) trend = "DOWN";
  }

  const current = confirmedCandles[confirmedCandles.length - 1];
  const sessionKey = getKillzoneKey(current.time);
  const sessionActive = sessionKey === "LONDON" || sessionKey === "NYAM" || sessionKey === "NYPM";
  const sessionLabel =
    sessionKey === "LONDON" ? "London" :
    sessionKey === "NYAM" || sessionKey === "NYPM" ? "New York" :
    "Outside Session";

  const pools = [...orderFlow.pools];
  const seenPoolKeys = new Set(pools.map((pool) => `${pool.kind}|${pool.side}|${pool.startIndex}|${pool.endIndex ?? pool.startIndex}`));
  const addPool = (pool) => {
    const key = `${pool.kind}|${pool.side}|${pool.startIndex}|${pool.endIndex ?? pool.startIndex}`;
    if (seenPoolKeys.has(key)) return;
    seenPoolKeys.add(key);
    pools.push(pool);
  };

  const dailySessions = [];
  let currentDayKey = null;
  let currentSession = null;
  confirmedCandles.forEach((candle, index) => {
    const date = new Date(candle.time * 1000);
    const dayKey = `${date.getUTCFullYear()}-${date.getUTCMonth()}-${date.getUTCDate()}`;
    if (dayKey !== currentDayKey) {
      if (currentSession) dailySessions.push(currentSession);
      currentDayKey = dayKey;
      currentSession = {
        key: dayKey,
        startIndex: index,
        endIndex: index,
        high: candle.high,
        low: candle.low,
      };
      return;
    }
    currentSession.endIndex = index;
    currentSession.high = Math.max(currentSession.high, candle.high);
    currentSession.low = Math.min(currentSession.low, candle.low);
  });
  if (currentSession) dailySessions.push(currentSession);

  const previousSession = dailySessions[dailySessions.length - 2] || null;
  if (previousSession) {
    addPool({
      kind: "prevSessionHigh",
      side: "high",
      level: previousSession.high,
      startIndex: previousSession.startIndex,
      endIndex: previousSession.endIndex,
      strength: 2,
    });
    addPool({
      kind: "prevSessionLow",
      side: "low",
      level: previousSession.low,
      startIndex: previousSession.startIndex,
      endIndex: previousSession.endIndex,
      strength: 2,
    });
  }

  const lineValueAt = (a, b, index) => {
    const dx = b.index - a.index;
    if (dx === 0) return a.price;
    return a.price + (((b.price - a.price) / dx) * (index - a.index));
  };

  const recentPools = pools
    .filter((pool) => pool.startIndex < confirmedCandles.length - 1)
    .sort((a, b) => (b.strength ?? 0) - (a.strength ?? 0));

  let latestSweep = null;
  for (let i = Math.max(pivotLen + 3, confirmedCandles.length - 14); i < confirmedCandles.length; i += 1) {
    const candle = confirmedCandles[i];
    for (const pool of recentPools) {
      const level = pool.a && pool.b ? lineValueAt(pool.a, pool.b, i) : pool.level;
      if (!Number.isFinite(level)) continue;
      if (pool.side === "high" && candle.high > level + (tolerance * 0.1) && candle.close < level) {
        latestSweep = {
          index: i,
          direction: "SELL",
          side: "buy-side",
          label: "Buy-side liquidity taken",
          level,
          kind: pool.kind,
        };
      } else if (pool.side === "low" && candle.low < level - (tolerance * 0.1) && candle.close > level) {
        latestSweep = {
          index: i,
          direction: "BUY",
          side: "sell-side",
          label: "Sell-side liquidity taken",
          level,
          kind: pool.kind,
        };
      }
    }
  }

  const mapZoneLabel = (setup) => {
    if (setup.entryModel === "FVG") return setup.direction === "BUY" ? "bullish FVG" : "bearish FVG";
    return setup.direction === "BUY" ? "bullish OB" : "bearish OB";
  };

  const findFvgForSetup = (setup) => {
    const source = setup.direction === "BUY" ? fvg.bullish : fvg.bearish;
    let best = null;
    source.forEach((zone) => {
      if (zone.startIndex > setup.structureEvent.breakIndex) return;
      if (!best || zone.startIndex > best.startIndex) best = zone;
    });
    return best;
  };

  const setups = orderFlow.setups.map((setup) => {
    const entryCandle = candles[setup.entryIndex] || candles[setup.pullbackIndex] || current;
    const entryPrice = entryCandle?.open ?? entryCandle?.close ?? setup.orderBlock.top;
    const stopLoss = setup.direction === "BUY"
      ? Math.min(candles[setup.sweepIndex]?.low ?? setup.orderBlock.bottom, setup.orderBlock.bottom) - tolerance
      : Math.max(candles[setup.sweepIndex]?.high ?? setup.orderBlock.top, setup.orderBlock.top) + tolerance;
    const risk = Math.max(Math.abs(entryPrice - stopLoss), tolerance);
    const takeProfit = setup.direction === "BUY" ? entryPrice + (risk * 2) : entryPrice - (risk * 2);
    const sessionForEntry = getKillzoneKey((candles[setup.entryIndex]?.time ?? current.time));
    const sessionAllowed = sessionForEntry === "LONDON" || sessionForEntry === "NYAM" || sessionForEntry === "NYPM";
    const matchingFvg = findFvgForSetup(setup);
    const confidence = Math.round(clamp(
      0.3 +
      ((trend === (setup.direction === "BUY" ? "UP" : "DOWN")) ? 0.2 : 0) +
      ((setup.liquidityKind.startsWith("equal") || setup.liquidityKind.startsWith("prevSession")) ? 0.2 : 0.1) +
      (sessionAllowed ? 0.15 : 0) +
      (matchingFvg ? 0.1 : 0.05) +
      ((setup.structureEvent.type === "BOS") ? 0.05 : 0.1),
      0,
      1,
    ) * 100);
    return {
      ...setup,
      entryModel: "OB",
      fallbackFvg: matchingFvg,
      entryPrice,
      stopLoss,
      takeProfit,
      rr: 2,
      confidence,
      sessionAllowed,
      setupText: `${setup.direction === "BUY" ? "Bullish" : "Bearish"} sweep -> ${setup.structureEvent.type} -> retest ${mapZoneLabel({ ...setup, entryModel: "OB" })}`,
    };
  });

  const activeSetup = [...setups]
    .reverse()
    .find((setup) => setup.entryIndex >= candles.length - 2 || setup.pullbackIndex >= confirmedCandles.length - 2) || null;

  let setupText = "--";
  if (!sessionActive) {
    setupText = `${trend === "UP" ? "Bullish" : trend === "DOWN" ? "Bearish" : "Range"} structure, waiting for London/New York`;
  } else if (activeSetup) {
    setupText = activeSetup.setupText;
  } else if (latestSweep) {
    const awaited = latestSweep.direction === "BUY" ? "bullish BOS / OB retest" : "bearish BOS / OB retest";
    setupText = `${latestSweep.label}, waiting for ${awaited}`;
  } else if (trend === "UP") {
    setupText = "Bullish structure, waiting for sell-side sweep";
  } else if (trend === "DOWN") {
    setupText = "Bearish structure, waiting for buy-side sweep";
  } else {
    setupText = "Range structure, waiting for liquidity sweep";
  }

  const confidence = activeSetup?.confidence ?? Math.round(clamp(
    0.2 +
    (trend === "RANGE" ? 0.05 : 0.25) +
    (sessionActive ? 0.15 : 0) +
    (latestSweep ? 0.2 : 0),
    0,
    1,
  ) * 100);

  return {
    trend,
    trendLabel: trend === "UP" ? "UP" : trend === "DOWN" ? "DOWN" : "RANGE",
    structure,
    pools: pools.slice(-16),
    setups: setups.slice(-10),
    activeSetup,
    latestSweep,
    sessionActive,
    sessionLabel,
    confidence,
    setupText,
  };
}

function buildPriceActionToolkit(candles, config = {}) {
  const confirmedCandles = candles.slice(0, -1);
  if (!Array.isArray(candles) || confirmedCandles.length < 30) {
    return {
      structure: null,
      fib: null,
      trendlines: { upperChannels: [], lowerChannels: [], signals: [] },
      sr: {
        supports: [],
        resistances: [],
        manipulations: [],
        signals: [],
        stats: {},
      },
      bias: "RANGE",
      setupText: "--",
      actionableSignals: [],
    };
  }

  const pivotLen = Math.max(3, config.pivotLen ?? 4);
  const structure = buildICTStructureAnalysis(confirmedCandles, pivotLen);
  const fib = buildICTFibLevels(structure.events);
  const trendlines = buildLiquidityTrendlineSignals(confirmedCandles, {
    len: Math.max(4, config.trendlineLen ?? 5),
    space: 2,
    colorUp: "#089981",
    colorDown: "#f23645",
  });
  const sr = buildSupportResistanceSignalsMTF(confirmedCandles, {
    length: Math.max(4, config.srLen ?? 6),
    zoneAtrMult: 0.5,
    securityAtrMult: 0,
    manipulationMult: 1.3,
    maxActive: 5,
    showBroken: true,
    extendActive: true,
  });

  const lastEvent = structure.events[structure.events.length - 1] || null;
  const bias = lastEvent?.direction === "UP"
    ? "BULLISH"
    : lastEvent?.direction === "DOWN"
      ? "BEARISH"
      : "RANGE";

  const nearestSupport = sr.supports[sr.supports.length - 1] || null;
  const nearestResistance = sr.resistances[sr.resistances.length - 1] || null;
  const latestTrendlineSignal = trendlines.signals[trendlines.signals.length - 1] || null;
  const latestSrSignal = sr.signals[sr.signals.length - 1] || null;

  let setupText = "--";
  if (bias === "BULLISH") {
    if (latestTrendlineSignal?.type === "UP") {
      setupText = "Bullish structure with trendline breakout";
    } else if (latestSrSignal?.direction === "BUY") {
      setupText = `Bullish reaction from support ${formatPrice(latestSrSignal.price, currentPip)}`;
    } else if (fib?.direction === "UP") {
      const fib705 = fib.levels.find((level) => level.label === "0.705");
      setupText = fib705
        ? `Bullish structure, watch fib retrace near ${formatPrice(fib705.price, currentPip)}`
        : "Bullish structure, watch retrace into support";
    } else {
      setupText = "Bullish structure, watch support and pullback";
    }
  } else if (bias === "BEARISH") {
    if (latestTrendlineSignal?.type === "DOWN") {
      setupText = "Bearish structure with trendline breakdown";
    } else if (latestSrSignal?.direction === "SELL") {
      setupText = `Bearish reaction from resistance ${formatPrice(latestSrSignal.price, currentPip)}`;
    } else if (fib?.direction === "DOWN") {
      const fib705 = fib.levels.find((level) => level.label === "0.705");
      setupText = fib705
        ? `Bearish structure, watch fib retrace near ${formatPrice(fib705.price, currentPip)}`
        : "Bearish structure, watch retrace into resistance";
    } else {
      setupText = "Bearish structure, watch resistance and pullback";
    }
  } else {
    const supportPrice = nearestSupport ? formatPrice(nearestSupport.basePrice, currentPip) : "--";
    const resistancePrice = nearestResistance ? formatPrice(nearestResistance.basePrice, currentPip) : "--";
    setupText = `Range price action between ${supportPrice} and ${resistancePrice}`;
  }

  const actionableSignals = [];
  sr.signals.forEach((signal) => {
    actionableSignals.push({
      entryIndex: signal.entryIndex,
      direction: signal.direction,
      kind: `sr-${signal.kind}`,
      price: signal.price,
    });
  });
  trendlines.signals.forEach((signal) => {
    actionableSignals.push({
      entryIndex: signal.entryIndex,
      direction: signal.type === "UP" ? "BUY" : "SELL",
      kind: "trendline-break",
      price: signal.price,
    });
  });

  return {
    structure,
    fib,
    trendlines,
    sr,
    bias,
    setupText,
    actionableSignals: actionableSignals
      .filter((signal) => Number.isInteger(signal.entryIndex))
      .sort((a, b) => a.entryIndex - b.entryIndex)
      .slice(-20),
  };
}

function buildAlgoBehaviorEngine(candles, config = {}) {
  const confirmedCandles = Array.isArray(candles) ? candles.slice(0, -1) : [];
  const minCandles = Math.max(30, config.minCandles ?? 36);
  if (confirmedCandles.length < minCandles) {
    return {
      trend: "RANGE",
      regime: "BUILDING",
      phase: "BUILDING",
      score: 0,
      confidence: 0,
      setupText: "--",
      expirySuggestion: "--",
      trapLabel: "--",
      sweepLabel: "--",
      focusPrice: null,
      microLiquidity: [],
      activeSetup: null,
      signals: [],
    };
  }

  const structure = buildICTStructureAnalysis(confirmedCandles, Math.max(3, config.pivotLen ?? 3));
  const lastEvent = structure.events[structure.events.length - 1] || null;
  const trend = lastEvent?.direction === "UP"
    ? "UP"
    : lastEvent?.direction === "DOWN"
      ? "DOWN"
      : "RANGE";

  const recent = confirmedCandles.slice(-20);
  const recent5 = confirmedCandles.slice(-5);
  const current = confirmedCandles[confirmedCandles.length - 1];
  const prev = confirmedCandles[confirmedCandles.length - 2];
  const avgRange20 = averageRange(confirmedCandles, 20) || ((current?.close ?? 1) * 0.001);
  const avgRange8 = averageRange(confirmedCandles, 8) || avgRange20;
  const threshold = getLevelThreshold(recent) || Math.max((currentPip || 0.0001) * 4, avgRange20 * 0.08);
  const bullishCount = recent5.filter((c) => c.close > c.open).length;
  const bearishCount = recent5.filter((c) => c.close < c.open).length;
  const sequenceExtreme = bullishCount >= 4 || bearishCount >= 4;

  const directionalShare = trend === "UP"
    ? bullishCount / Math.max(1, recent5.length)
    : trend === "DOWN"
      ? bearishCount / Math.max(1, recent5.length)
      : 0.5;

  let regime = "CHOPPY";
  if (avgRange8 > avgRange20 * 1.35) regime = "EXPANSION";
  else if (avgRange8 < avgRange20 * 0.75) regime = "COMPRESSION";
  if (trend !== "RANGE" && directionalShare >= 0.6) regime = `TRENDING ${trend}`;

  const pullbackWindow = confirmedCandles.slice(-4, -1);
  const avgBodyPullback = pullbackWindow.length
    ? pullbackWindow.reduce((sum, candle) => sum + Math.abs(candle.close - candle.open), 0) / pullbackWindow.length
    : 0;
  const bullishPullbackCount = pullbackWindow.filter((c) => c.close > c.open).length;
  const bearishPullbackCount = pullbackWindow.filter((c) => c.close < c.open).length;
  const currentBody = Math.abs(current.close - current.open);

  let phase = "NEUTRAL";
  let pushResume = false;
  if (trend === "UP") {
    if (bearishPullbackCount >= 2 && avgBodyPullback < avgRange20 * 0.8) phase = "PULLBACK";
    if (bullishCount >= 3 && currentBody > avgRange20 * 0.45) phase = "PUSH";
    pushResume = phase === "PULLBACK" && current.close > current.open && currentBody >= avgRange20 * 0.45;
  } else if (trend === "DOWN") {
    if (bullishPullbackCount >= 2 && avgBodyPullback < avgRange20 * 0.8) phase = "PULLBACK";
    if (bearishCount >= 3 && currentBody > avgRange20 * 0.45) phase = "PUSH";
    pushResume = phase === "PULLBACK" && current.close < current.open && currentBody >= avgRange20 * 0.45;
  }

  const equalHighs = [];
  const equalLows = [];
  for (let i = Math.max(2, confirmedCandles.length - 12); i < confirmedCandles.length; i += 1) {
    const sample = confirmedCandles.slice(Math.max(0, i - 2), i + 1);
    if (sample.length < 3) continue;
    const highs = sample.map((c) => c.high);
    const lows = sample.map((c) => c.low);
    if (Math.max(...highs) - Math.min(...highs) <= threshold) {
      equalHighs.push({
        side: "high",
        level: highs.reduce((a, b) => a + b, 0) / highs.length,
        startIndex: i - sample.length + 1,
        endIndex: i,
      });
    }
    if (Math.max(...lows) - Math.min(...lows) <= threshold) {
      equalLows.push({
        side: "low",
        level: lows.reduce((a, b) => a + b, 0) / lows.length,
        startIndex: i - sample.length + 1,
        endIndex: i,
      });
    }
  }

  const microLiquidity = [...equalHighs.slice(-2), ...equalLows.slice(-2)];
  const sweep = detectLiquiditySweepEvent(confirmedCandles, confirmedCandles.length - 1, 12)
    || detectLiquiditySweepEvent(confirmedCandles, confirmedCandles.length - 2, 12);
  const rejection = analyzeRejection(current);
  const volatilitySpike = (current.high - current.low) > avgRange20 * 1.5;

  let trapDirection = null;
  let trapLabel = "--";
  let focusPrice = sweep?.referenceLevel ?? null;
  if (sweep?.sweepType === "BUY" && rejection.lowerWick > rejection.safeBody * 2 && current.close > sweep.referenceLevel) {
    trapDirection = "BUY";
    trapLabel = "BULL TRAP RECLAIM";
    focusPrice = sweep.referenceLevel;
  } else if (sweep?.sweepType === "SELL" && rejection.upperWick > rejection.safeBody * 2 && current.close < sweep.referenceLevel) {
    trapDirection = "SELL";
    trapLabel = "BEAR TRAP REJECT";
    focusPrice = sweep.referenceLevel;
  }

  const trendAligned = trend !== "RANGE" && sweep && trapDirection === sweep.sweepType && (
    (trend === "UP" && trapDirection === "BUY") ||
    (trend === "DOWN" && trapDirection === "SELL")
  );

  let score = 0;
  if (trend !== "RANGE") score += 2;
  if (phase === "PULLBACK" || pushResume) score += 1;
  if (microLiquidity.length) score += 2;
  if (sweep) score += 2;
  if (trapDirection) score += 3;
  if (volatilitySpike) score += 2;
  if (sequenceExtreme) score += 1;
  if (regime === "CHOPPY") score -= 2;
  const confidence = Math.round(clamp(score / 11, 0, 1) * 100);

  let expirySuggestion = "2-3m";
  if (volatilitySpike || regime === "EXPANSION") expirySuggestion = "1m";
  else if (regime === "COMPRESSION") expirySuggestion = "2m";

  const activeSetup = trendAligned && (phase === "PULLBACK" || pushResume) && trapDirection && score >= 7
    ? {
        direction: trapDirection,
        entryIndex: confirmedCandles.length - 1,
        score,
        confidence,
        focusPrice: focusPrice ?? current.close,
        expirySuggestion,
        setupText: `${trend} ${phase === "PULLBACK" ? "pullback" : "resume"} after ${sweep?.liquidityLabel || "micro liquidity"} sweep at ${formatPrice(focusPrice ?? current.close, currentPip)}`,
      }
    : null;

  const focusText = focusPrice != null ? formatPrice(focusPrice, currentPip) : "liquidity";
  const trapText = trapDirection
    ? `${trapLabel} @ ${focusText}`
    : focusPrice != null
      ? `WATCH @ ${focusText}`
      : "--";
  const setupText = activeSetup
    ? `${activeSetup.setupText}; trap confirmed, ${volatilitySpike ? "volatility spike" : "normal volatility"}, expiry ${expirySuggestion}`
    : trend === "RANGE"
      ? "Range regime, wait for micro liquidity sweep and trap candle"
      : `${regime}; ${phase === "PULLBACK" ? "watch pullback resume" : "wait for pullback"} near ${focusText}${focusPrice != null ? ` | trap ${trapText}` : ""}`;

  const sweepText = sweep
    ? `${sweep.sweepType === "BUY" ? "Sell-side liquidity taken" : "Buy-side liquidity taken"}${focusPrice != null ? ` @ ${focusText}` : ""}`
    : "--";
  const entryPrice = activeSetup?.focusPrice ?? focusPrice;

  return {
    trend,
    regime,
    phase,
    sequenceExtreme,
    bullishCount,
    bearishCount,
    volatilitySpike,
    microLiquidity,
    sweep,
    sweepLabel: sweepText,
    trapLabel: trapText,
    focusPrice,
    entryPrice,
    score,
    confidence,
    expirySuggestion,
    setupText,
    activeSetup,
    signals: activeSetup ? [activeSetup] : [],
  };
}

function buildBreakoutTargets(candles, config = {}) {
  const len = config.len ?? 99;
  const preventOverlap = config.preventOverlap ?? true;
  const atrPeriod = config.atrPeriod ?? 14;
  const slMultiplier = config.slMultiplier ?? 5;
  const tp1Multiplier = config.tp1Multiplier ?? 0.5;
  const tp2Multiplier = config.tp2Multiplier ?? 1.0;
  const tp3Multiplier = config.tp3Multiplier ?? 1.5;
  const lenHalf = Math.max(2, Math.floor(len / 2));

  if (!Array.isArray(candles) || candles.length < Math.max(len, atrPeriod, lenHalf * 2 + 5)) {
    return { channels: [], breakouts: [], trades: [] };
  }

  const bodyAbs = candles.map((candle) => Math.abs(candle.close - candle.open));
  const v1 = weightedMovingAverage(bodyAbs, len);
  const v2 = emaSeries(bodyAbs, len);
  const tr = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  });
  const atr = rmaSeries(tr, atrPeriod);
  const rangeAtr = rmaSeries(tr, len).map((value) => Number.isFinite(value) ? value / 2 : null);

  let lastPivotHigh = null;
  let lastPivotLow = null;
  let lastChannelRight = -1;
  const channels = [];
  const activeChannels = [];
  const breakouts = [];
  const trades = [];
  let activeTrade = null;

  for (let i = 1; i < candles.length; i += 1) {
    const pivotIndex = i - lenHalf;
    if (pivotIndex >= lenHalf && pivotIndex < candles.length - lenHalf) {
      if (isPivotHighLR(candles, pivotIndex, lenHalf, lenHalf)) {
        lastPivotHigh = { index: pivotIndex, price: candles[pivotIndex].high };
      }
      if (isPivotLowLR(candles, pivotIndex, lenHalf, lenHalf)) {
        lastPivotLow = { index: pivotIndex, price: candles[pivotIndex].low };
      }
    }

    const crossedUnder = Number.isFinite(v1[i - 1]) && Number.isFinite(v2[i - 1]) && Number.isFinite(v1[i]) && Number.isFinite(v2[i])
      && v1[i - 1] >= v2[i - 1]
      && v1[i] < v2[i];

    if (crossedUnder && lastPivotHigh && lastPivotLow) {
      let top = null;
      let bottom = null;
      let startIndex = null;
      if (lastPivotHigh.index > lastPivotLow.index) {
        top = lastPivotHigh.price;
        startIndex = lastPivotHigh.index;
        if (i - startIndex > 0) {
          let minLow = candles[i].high;
          for (let j = startIndex; j <= i; j += 1) minLow = Math.min(minLow, candles[j].low);
          bottom = minLow;
        }
      } else {
        bottom = lastPivotLow.price;
        startIndex = lastPivotLow.index;
        if (i - startIndex > 0) {
          let maxHigh = candles[i].low;
          for (let j = startIndex; j <= i; j += 1) maxHigh = Math.max(maxHigh, candles[j].high);
          top = maxHigh;
        }
      }

      const vola = rangeAtr[i] ?? 0;
      if (
        Number.isFinite(top) &&
        Number.isFinite(bottom) &&
        candles[i].close <= top &&
        candles[i].close >= bottom &&
        (!preventOverlap || startIndex > lastChannelRight)
      ) {
        const channel = {
          startIndex,
          endIndex: i,
          top,
          bottom,
          upperBandBottom: top - vola,
          lowerBandTop: bottom + vola,
        };
        channels.push(channel);
        activeChannels.push(channel);
        lastChannelRight = i;
      }
    }

    for (let channelIndex = activeChannels.length - 1; channelIndex >= 0; channelIndex -= 1) {
      const channel = activeChannels[channelIndex];
      if (candles[i].close > channel.top) {
        channel.endIndex = i;
        const entryIndex = i + 1 < candles.length ? i + 1 : null;
        breakouts.push({ index: i, entryIndex, direction: "UP", price: channel.bottom });
        activeChannels.splice(channelIndex, 1);
        const volatility = atr[i] ?? 0;
        const entry = entryIndex != null ? candles[entryIndex].open : candles[i].close;
        const stop = candles[i].low - (volatility * slMultiplier);
        const risk = Math.abs(entry - stop);
        activeTrade = {
          direction: "UP",
          signalIndex: i,
          startIndex: entryIndex ?? i,
          endIndex: entryIndex ?? i,
          entry,
          sl: stop,
          tp1: entry + (risk * tp1Multiplier),
          tp2: entry + (risk * tp2Multiplier),
          tp3: entry + (risk * tp3Multiplier),
          tp3Hit: false,
        };
        trades.push(activeTrade);
      } else if (candles[i].close < channel.bottom) {
        channel.endIndex = i;
        const entryIndex = i + 1 < candles.length ? i + 1 : null;
        breakouts.push({ index: i, entryIndex, direction: "DOWN", price: channel.top });
        activeChannels.splice(channelIndex, 1);
        const volatility = atr[i] ?? 0;
        const entry = entryIndex != null ? candles[entryIndex].open : candles[i].close;
        const stop = candles[i].high + (volatility * slMultiplier);
        const risk = Math.abs(entry - stop);
        activeTrade = {
          direction: "DOWN",
          signalIndex: i,
          startIndex: entryIndex ?? i,
          endIndex: entryIndex ?? i,
          entry,
          sl: stop,
          tp1: entry - (risk * tp1Multiplier),
          tp2: entry - (risk * tp2Multiplier),
          tp3: entry - (risk * tp3Multiplier),
          tp3Hit: false,
        };
        trades.push(activeTrade);
      } else {
        channel.endIndex = i;
      }
    }

    if (activeTrade && !activeTrade.tp3Hit) {
      activeTrade.endIndex = i;
      if (activeTrade.direction === "UP" && candles[i].high >= activeTrade.tp3) {
        activeTrade.tp3Hit = true;
      } else if (activeTrade.direction === "DOWN" && candles[i].low <= activeTrade.tp3) {
        activeTrade.tp3Hit = true;
      }
    }
  }

  return {
    channels,
    breakouts,
    trades,
  };
}

function buildADXVolatilityWaves(candles, config = {}) {
  const bbLength = config.bbLength ?? 20;
  const bbMult = config.bbMult ?? 1.5;
  const adxLength = config.adxLength ?? 14;
  const adxSmooth = config.adxSmooth ?? 14;
  const adxInfluence = config.adxInfluence ?? 0.8;
  const zoneOffset = config.zoneOffset ?? 1;
  const zoneExpansion = config.zoneExpansion ?? 1;
  const smoothLength = config.smoothLength ?? 50;
  const signalCooldown = config.signalCooldown ?? 20;

  if (!Array.isArray(candles) || candles.length < Math.max(60, smoothLength)) {
    return { topBands: [], bottomBands: [], signals: [] };
  }

  const closes = candles.map((c) => c.close);
  const highs = candles.map((c) => c.high);
  const lows = candles.map((c) => c.low);
  const bbBasis = simpleMovingAverage(closes, bbLength);
  const bbStd = rollingStdDev(closes, bbLength);

  const tr = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  });
  const plusDM = candles.map((candle, index) => {
    if (index === 0) return 0;
    const upMove = candle.high - highs[index - 1];
    const downMove = lows[index - 1] - candle.low;
    return upMove > downMove && upMove > 0 ? upMove : 0;
  });
  const minusDM = candles.map((candle, index) => {
    if (index === 0) return 0;
    const upMove = candle.high - highs[index - 1];
    const downMove = lows[index - 1] - candle.low;
    return downMove > upMove && downMove > 0 ? downMove : 0;
  });

  const trRma = rmaSeries(tr, adxLength);
  const plusRma = rmaSeries(plusDM, adxLength);
  const minusRma = rmaSeries(minusDM, adxLength);
  const diPlus = candles.map((_, index) => {
    const denom = trRma[index];
    return denom ? (100 * (plusRma[index] ?? 0)) / denom : null;
  });
  const diMinus = candles.map((_, index) => {
    const denom = trRma[index];
    return denom ? (100 * (minusRma[index] ?? 0)) / denom : null;
  });
  const dx = candles.map((_, index) => {
    const plus = diPlus[index];
    const minus = diMinus[index];
    if (!Number.isFinite(plus) || !Number.isFinite(minus) || plus + minus === 0) return null;
    return (100 * Math.abs(plus - minus)) / (plus + minus);
  });
  const adx = rmaSeries(dx.map((value) => value ?? 0), adxSmooth);

  const bbUpper = candles.map((_, index) => {
    if (!Number.isFinite(bbBasis[index]) || !Number.isFinite(bbStd[index])) return null;
    const adxNormalized = (adx[index] ?? 0) / 100;
    const adxMultiplier = 1 + (adxNormalized * adxInfluence);
    return bbBasis[index] + (bbMult * bbStd[index] * adxMultiplier);
  });
  const bbLower = candles.map((_, index) => {
    if (!Number.isFinite(bbBasis[index]) || !Number.isFinite(bbStd[index])) return null;
    const adxNormalized = (adx[index] ?? 0) / 100;
    const adxMultiplier = 1 + (adxNormalized * adxInfluence);
    return bbBasis[index] - (bbMult * bbStd[index] * adxMultiplier);
  });

  const bbUpperSmooth = simpleMovingAverage(bbUpper.map((value) => value ?? 0), smoothLength);
  const bbLowerSmooth = simpleMovingAverage(bbLower.map((value) => value ?? 0), smoothLength);
  const topBands = Array.from({ length: 11 }, () => new Array(candles.length).fill(null));
  const bottomBands = Array.from({ length: 11 }, () => new Array(candles.length).fill(null));
  const signals = [];
  let lastBuySignalBar = -999;
  let lastSellSignalBar = -999;

  for (let i = 0; i < candles.length; i += 1) {
    const upperSmooth = bbUpperSmooth[i];
    const lowerSmooth = bbLowerSmooth[i];
    if (!Number.isFinite(upperSmooth) || !Number.isFinite(lowerSmooth)) continue;
    const range = upperSmooth - lowerSmooth;
    const offsetDistance = range * zoneOffset;
    const topZoneBottom = upperSmooth + offsetDistance;
    const topZoneTop = topZoneBottom + (range * zoneExpansion);
    const bottomZoneTop = lowerSmooth - offsetDistance;
    const bottomZoneBottom = bottomZoneTop - (range * zoneExpansion);

    for (let level = 0; level <= 10; level += 1) {
      const ratio = level / 10;
      topBands[level][i] = topZoneBottom + ((topZoneTop - topZoneBottom) * ratio);
      bottomBands[level][i] = bottomZoneTop - ((bottomZoneTop - bottomZoneBottom) * ratio);
    }

    const priceInTopZone = closes[i] > topZoneBottom;
    const priceInBottomZone = closes[i] < bottomZoneTop;
    const prevPriceInTopZone = i > 0 && Number.isFinite(topBands[0][i - 1]) ? closes[i - 1] > topBands[0][i - 1] : false;
    const prevPriceInBottomZone = i > 0 && Number.isFinite(bottomBands[0][i - 1]) ? closes[i - 1] < bottomBands[0][i - 1] : false;

    const enterTopZone = priceInTopZone && !prevPriceInTopZone && (i - lastSellSignalBar >= signalCooldown);
    const enterBottomZone = priceInBottomZone && !prevPriceInBottomZone && (i - lastBuySignalBar >= signalCooldown);

    if (enterBottomZone) {
      lastBuySignalBar = i;
      signals.push({ index: i, entryIndex: i + 1 < candles.length ? i + 1 : null, type: "BUY" });
    }
    if (enterTopZone) {
      lastSellSignalBar = i;
      signals.push({ index: i, entryIndex: i + 1 < candles.length ? i + 1 : null, type: "SELL" });
    }
  }

  return {
    topBands,
    bottomBands,
    signals,
  };
}

function buildSMCProCombo(candles, config = {}) {
  const leftLen = config.leftLen ?? 5;
  const rightLen = config.rightLen ?? 5;
  const atrLen = config.atrLen ?? 14;
  const atrMult = config.atrMult ?? 0.1;
  const volLen = config.volLen ?? 20;
  const minBodyPct = config.minBodyPct ?? 55;
  const useAtrBuffer = config.useAtrBuffer ?? true;
  const useBodyFilter = config.useBodyFilter ?? true;

  if (!Array.isArray(candles) || candles.length < Math.max(30, leftLen + rightLen + 5)) {
    return {
      support: null,
      resistance: null,
      signals: [],
      board: null,
    };
  }

  const trueRanges = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return Math.max(
      candle.high - candle.low,
      Math.abs(candle.high - prevClose),
      Math.abs(candle.low - prevClose),
    );
  });
  const atrValues = simpleMovingAverage(trueRanges, atrLen);
  const activityValues = candles.map((candle, index) => {
    const prevClose = candles[index - 1]?.close ?? candle.close;
    return ((candle.high - candle.low) + Math.abs(candle.close - prevClose)) * 1000;
  });
  const avgActivity = simpleMovingAverage(activityValues, volLen);

  let support = null;
  let resistance = null;
  const signals = [];
  const supportHistory = [];
  const resistanceHistory = [];
  const stats = {
    buy: { wins: 0, total: 0 },
    sell: { wins: 0, total: 0 },
  };

  for (let i = 0; i < candles.length; i += 1) {
    const pivotIndex = i - rightLen;
    if (pivotIndex >= leftLen && pivotIndex < candles.length - rightLen) {
      if (isPivotLowLR(candles, pivotIndex, leftLen, rightLen)) {
        support = {
          index: pivotIndex,
          confirmIndex: i,
          price: candles[pivotIndex].low,
          direction: "SUPPORT",
        };
        supportHistory.push(support);
      }
      if (isPivotHighLR(candles, pivotIndex, leftLen, rightLen)) {
        resistance = {
          index: pivotIndex,
          confirmIndex: i,
          price: candles[pivotIndex].high,
          direction: "RESISTANCE",
        };
        resistanceHistory.push(resistance);
      }
    }

    const candle = candles[i];
    const atr = atrValues[i] ?? 0;
    const buffer = useAtrBuffer ? atr * atrMult : 0;
    const range = Math.max(candle.high - candle.low, 0.0000001);
    const body = Math.abs(candle.close - candle.open);
    const bodyPct = (body / range) * 100;
    const bodyOK = !useBodyFilter || bodyPct >= minBodyPct;
    const highActivity = (activityValues[i] ?? 0) > (avgActivity[i] ?? Number.POSITIVE_INFINITY);

    const bullTrap = support
      && i > support.confirmIndex
      && candle.low < (support.price - buffer)
      && candle.close > support.price
      && candle.close > candle.open
      && bodyOK;

    const bearTrap = resistance
      && i > resistance.confirmIndex
      && candle.high > (resistance.price + buffer)
      && candle.close < resistance.price
      && candle.close < candle.open
      && bodyOK;

    if (bullTrap) {
      const entryIndex = i + 1 < candles.length ? i + 1 : null;
      const entryCandle = entryIndex != null ? candles[entryIndex] : null;
      const isWin = entryCandle ? entryCandle.close > entryCandle.open : null;
      if (entryCandle) {
        stats.buy.total += 1;
        if (isWin) stats.buy.wins += 1;
      }
      signals.push({
        index: i,
        entryIndex,
        type: highActivity ? "STRONG_BUY" : "WEAK_BUY",
        reference: support.price,
        levelIndex: support.index,
        confirmIndex: support.confirmIndex,
        bodyPct,
        result: isWin,
        buyStats: { ...stats.buy },
        sellStats: { ...stats.sell },
      });
    } else if (bearTrap) {
      const entryIndex = i + 1 < candles.length ? i + 1 : null;
      const entryCandle = entryIndex != null ? candles[entryIndex] : null;
      const isWin = entryCandle ? entryCandle.close < entryCandle.open : null;
      if (entryCandle) {
        stats.sell.total += 1;
        if (isWin) stats.sell.wins += 1;
      }
      signals.push({
        index: i,
        entryIndex,
        type: highActivity ? "STRONG_SELL" : "WEAK_SELL",
        reference: resistance.price,
        levelIndex: resistance.index,
        confirmIndex: resistance.confirmIndex,
        bodyPct,
        result: isWin,
        buyStats: { ...stats.buy },
        sellStats: { ...stats.sell },
      });
    }
  }

  const lastSignal = signals[signals.length - 1] ?? null;
  let board = null;
  if (lastSignal) {
    const barsAgo = (candles.length - 1) - lastSignal.index;
    if (lastSignal.type === "STRONG_BUY") {
      board = {
        title: "STRONG BUY",
        status: "BEAR TRAP",
        bias: "BULLISH",
        barsAgo,
        headerColor: "#006400",
        statusColor: "#00e676",
        lines: ["Sellers trapped", "Smart money in"],
      };
    } else if (lastSignal.type === "STRONG_SELL") {
      board = {
        title: "STRONG SELL",
        status: "BULL TRAP",
        bias: "BEARISH",
        barsAgo,
        headerColor: "#8b0000",
        statusColor: "#ff5252",
        lines: ["Buyers trapped", "Smart money rejection"],
      };
    } else if (lastSignal.type === "WEAK_BUY") {
      board = {
        title: "WEAK BUY",
        status: "BEAR TRAP",
        bias: "BULLISH",
        barsAgo,
        headerColor: "#355c7d",
        statusColor: "#6c8ebf",
        lines: ["Trap detected", "Low activity confirmation"],
      };
    } else {
      board = {
        title: "WEAK SELL",
        status: "BULL TRAP",
        bias: "BEARISH",
        barsAgo,
        headerColor: "#6b3e3e",
        statusColor: "#9a6666",
        lines: ["Trap detected", "Low activity confirmation"],
      };
    }
  } else {
    board = {
      title: "SMC SYSTEM",
      status: "WAITING...",
      bias: "NEUTRAL",
      barsAgo: null,
      headerColor: "#1e222d",
      statusColor: "#2a2e39",
      lines: ["System running", "Waiting for first signal"],
    };
  }

  return {
    support,
    resistance,
    supportHistory: supportHistory.slice(-4),
    resistanceHistory: resistanceHistory.slice(-4),
    signals,
    stats,
    board,
  };
}

function calculateConfidence({ trendStrength, wickStrength, candleStrength, levelStrength }) {
  const score =
    (trendStrength * 0.3) +
    (wickStrength * 0.3) +
    (candleStrength * 0.2) +
    (levelStrength * 0.2);
  return Math.round(clamp(score, 0, 1) * 100);
}

function getTopDownCacheKey(symbol, timeframeSeconds) {
  return `${symbol || ""}|${Number(timeframeSeconds) || 0}`;
}

function setCachedCandles(symbol, timeframeSeconds, candles) {
  if (!symbol || !Number.isFinite(Number(timeframeSeconds)) || !Array.isArray(candles) || !candles.length) return;
  topDownCandleCache.set(getTopDownCacheKey(symbol, timeframeSeconds), {
    candles: candles.slice(-MAX_CANDLES),
    updatedAt: Date.now(),
  });
}

function getCachedCandles(symbol, timeframeSeconds, options = {}) {
  if (!symbol || !Number.isFinite(Number(timeframeSeconds))) return [];
  const entry = topDownCandleCache.get(getTopDownCacheKey(symbol, timeframeSeconds));
  if (!entry?.candles?.length) return [];
  const maxAgeMs = Number(options.maxAgeMs ?? TOP_DOWN_CACHE_MAX_AGE_MS);
  if (options.freshOnly && Date.now() - Number(entry.updatedAt || 0) > maxAgeMs) return [];
  return entry.candles;
}

function buildCandlesFromTickSeries(prices, times, timeframeSeconds = 30) {
  const builder = new CandleBuilder(timeframeSeconds);
  const len = Math.min(Array.isArray(prices) ? prices.length : 0, Array.isArray(times) ? times.length : 0);
  for (let i = 0; i < len; i += 1) {
    builder.update({ epoch: Number(times[i]), quote: Number(prices[i]) });
  }
  return builder.currentCandle
    ? [...builder.candles, builder.currentCandle]
    : builder.candles;
}

async function loadAggregatedTickHistoryForGranularity(symbol, timeframeSeconds = 30, maxCandles = MAX_CANDLES) {
  let end = "latest";
  let prices = [];
  let times = [];

  for (let batch = 0; batch < MAX_TICK_HISTORY_BATCHES; batch += 1) {
    const res = await wsRequest({
      ticks_history: symbol,
      end,
      style: "ticks",
      count: MAX_TICK_HISTORY_BATCH,
    });

    const history = res.history || {};
    const batchPrices = Array.isArray(history.prices) ? history.prices : [];
    const batchTimes = Array.isArray(history.times) ? history.times : [];
    if (!batchPrices.length || !batchTimes.length) break;

    prices = [...batchPrices, ...prices];
    times = [...batchTimes, ...times];

    const built = buildCandlesFromTickSeries(prices, times, timeframeSeconds);
    if (built.length >= maxCandles) {
      return built.slice(-maxCandles);
    }

    const earliestBatchTime = Number(batchTimes[0]);
    if (!Number.isFinite(earliestBatchTime)) break;
    end = earliestBatchTime - 1;

    if (batchPrices.length < MAX_TICK_HISTORY_BATCH) break;
  }

  return buildCandlesFromTickSeries(prices, times, timeframeSeconds).slice(-maxCandles);
}

async function fetchCandlesForGranularity(symbol, timeframeSeconds = 60, count = MAX_CANDLES) {
  if (!NATIVE_CANDLE_GRANULARITIES.has(Number(timeframeSeconds))) {
    return loadAggregatedTickHistoryForGranularity(symbol, timeframeSeconds, count);
  }
  return fetchHistoricalCandles(symbol, timeframeSeconds, count);
}

function getAvailableTopDownSourceCandles(symbol, timeframeSeconds, fallbackCandles, fallbackSeconds) {
  const sourceCandidates = [];
  const currentSeconds = getChartTimeframeSeconds();
  const currentCandles = currentSymbol === symbol ? getBuiltCandles() : [];

  if (Array.isArray(currentCandles) && currentCandles.length) {
    sourceCandidates.push({ seconds: currentSeconds, candles: currentCandles });
  }
  if (Array.isArray(fallbackCandles) && fallbackCandles.length) {
    sourceCandidates.push({ seconds: fallbackSeconds, candles: fallbackCandles });
  }

  const mtf = getMtfTimeframeSet(fallbackSeconds || currentSeconds);
  [mtf.entrySeconds, mtf.alignSeconds, mtf.mainSeconds, timeframeSeconds].forEach((seconds) => {
    const cached = getCachedCandles(symbol, seconds);
    if (cached.length) {
      sourceCandidates.push({ seconds, candles: cached });
    }
  });

  const unique = new Map();
  sourceCandidates.forEach((candidate) => {
    if (!candidate?.candles?.length || !Number.isFinite(candidate.seconds)) return;
    if (!unique.has(candidate.seconds) || candidate.candles.length > unique.get(candidate.seconds).candles.length) {
      unique.set(candidate.seconds, candidate);
    }
  });
  return Array.from(unique.values()).sort((a, b) => a.seconds - b.seconds);
}

function resolveTopDownCandles(symbol, timeframeSeconds, fallbackCandles = [], fallbackSeconds = getChartTimeframeSeconds()) {
  const targetSeconds = Math.max(1, Number(timeframeSeconds) || fallbackSeconds || DEFAULT_TIMEFRAME_SEC);
  const exactCurrent = currentSymbol === symbol && targetSeconds === getChartTimeframeSeconds() ? getBuiltCandles() : [];
  if (exactCurrent.length) return exactCurrent;

  const exactCached = getCachedCandles(symbol, targetSeconds);
  if (exactCached.length) return exactCached;

  const candidates = getAvailableTopDownSourceCandles(symbol, targetSeconds, fallbackCandles, fallbackSeconds);
  const aggregateSource = candidates.find((candidate) => candidate.seconds < targetSeconds);
  if (aggregateSource?.candles?.length) {
    return aggregateCandlesByTimeframe(aggregateSource.candles, targetSeconds);
  }

  if (targetSeconds === fallbackSeconds && Array.isArray(fallbackCandles) && fallbackCandles.length) {
    return fallbackCandles;
  }

  return [];
}

function maybePrimeTopDownTimeframeCache(symbol, baseSeconds = getChartTimeframeSeconds(), options = {}) {
  if (!symbol) return;
  const force = Boolean(options.force);
  const refreshKey = `${symbol}|${Number(baseSeconds) || 0}`;
  if (topDownCacheLoadState.get(refreshKey)) return;
  const targets = getMtfTimeframeSet(baseSeconds);
  const required = Array.from(new Set([
    targets.entrySeconds,
    targets.alignSeconds,
    targets.mainSeconds,
    Math.max(1, Number(baseSeconds) || DEFAULT_TIMEFRAME_SEC),
  ]));
  const missing = required.some((seconds) => !getCachedCandles(symbol, seconds, { freshOnly: !force }).length);
  if (!force && !missing) return;

  topDownCacheLoadState.set(refreshKey, true);
  Promise.all(required.map(async (seconds) => {
    try {
      const candles = await fetchCandlesForGranularity(symbol, seconds, Math.min(MAX_CANDLES, 240));
      if (candles.length) setCachedCandles(symbol, seconds, candles);
    } catch {}
  }))
    .finally(() => {
      topDownCacheLoadState.delete(refreshKey);
    });
}

function getTopDownTimeframeTargets(baseSeconds = getChartTimeframeSeconds()) {
  return getMtfTimeframeSet(baseSeconds);
}

function aggregateCandlesToTimeframe(candles, sourceSeconds = 60, targetSeconds = 300) {
  const source = Math.max(1, Number(sourceSeconds) || 60);
  const target = Math.max(source, Number(targetSeconds) || source);
  const step = Math.max(1, Math.round(target / source));
  if (!Array.isArray(candles) || candles.length < step) return [];
  const grouped = [];
  for (let i = 0; i < candles.length; i += step) {
    const slice = candles.slice(i, i + step);
    if (slice.length < step) continue;
    grouped.push({
      time: slice[0].time,
      open: slice[0].open,
      high: Math.max(...slice.map((c) => c.high)),
      low: Math.min(...slice.map((c) => c.low)),
      close: slice[slice.length - 1].close,
    });
  }
  return grouped;
}

function assessEntryTrigger(candles, direction, referenceLevel = null) {
  const recent = Array.isArray(candles) ? candles.slice(-6) : [];
  if (!direction || direction === "SIDEWAYS" || recent.length < 4) {
    return { ready: false, score: 0, reason: "waiting for entry candles" };
  }

  const current = recent[recent.length - 1];
  const previous = recent[recent.length - 2];
  const continuation = assessCandleContinuation(recent);
  const closeStructure = assessCloseStructure(recent);
  const sweepState = detectLiquiditySweepState(recent);
  const avgRange = averageRange(recent, recent.length) || Math.max(Math.abs(current.close) * 0.001, currentPip || 0.0001);
  const recentHigh = Math.max(...recent.slice(0, -1).map((candle) => candle.high));
  const recentLow = Math.min(...recent.slice(0, -1).map((candle) => candle.low));
  const tolerance = Math.max(avgRange * 0.15, currentPip || 0.0001);
  let score = 0;
  const reasons = [];

  if (direction === "UP") {
    if (closeStructure.bias === "UP") {
      score += 1.6;
      reasons.push("entry closes bullish");
    }
    if (continuation.bullScore >= 2) {
      score += 1.2;
      reasons.push("recent candles continue up");
    }
    if (current.close > previous.high - tolerance) {
      score += 1.2;
      reasons.push("last candle closed through prior high");
    }
    if (Number.isFinite(referenceLevel) && current.close >= referenceLevel) {
      score += 0.9;
      reasons.push("holding above setup level");
    }
    if (
      sweepState.sweepType === "BUY" &&
      sweepState.rejection?.strongBuyRejection &&
      sweepState.rejection?.bullishConfirm
    ) {
      score += 1.1;
      reasons.push("micro sweep confirmed");
    }
    if (current.close >= recentHigh - tolerance) {
      score += 0.8;
      reasons.push("near range high expansion");
    }
  } else if (direction === "DOWN") {
    if (closeStructure.bias === "DOWN") {
      score += 1.6;
      reasons.push("entry closes bearish");
    }
    if (continuation.bearScore >= 2) {
      score += 1.2;
      reasons.push("recent candles continue down");
    }
    if (current.close < previous.low + tolerance) {
      score += 1.2;
      reasons.push("last candle closed through prior low");
    }
    if (Number.isFinite(referenceLevel) && current.close <= referenceLevel) {
      score += 0.9;
      reasons.push("holding below setup level");
    }
    if (
      sweepState.sweepType === "SELL" &&
      sweepState.rejection?.strongSellRejection &&
      sweepState.rejection?.bearishConfirm
    ) {
      score += 1.1;
      reasons.push("micro sweep confirmed");
    }
    if (current.close <= recentLow + tolerance) {
      score += 0.8;
      reasons.push("near range low expansion");
    }
  }

  return {
    ready: score >= 3.3,
    score,
    reason: reasons.join(" + ") || "waiting for entry candles",
    closeStructure,
    continuation,
    sweepState,
  };
}

function buildTopDownAnalysis(candles, baseSeconds = getChartTimeframeSeconds()) {
  const targets = getTopDownTimeframeTargets(baseSeconds);
  maybePrimeTopDownTimeframeCache(currentSymbol, baseSeconds);
  const entryCandles = resolveTopDownCandles(currentSymbol, targets.entrySeconds, candles, targets.sourceSeconds);
  const alignCandles = resolveTopDownCandles(currentSymbol, targets.alignSeconds, candles, targets.sourceSeconds);
  const mainCandles = resolveTopDownCandles(currentSymbol, targets.mainSeconds, candles, targets.sourceSeconds);
  const mainTrendState = detectTrend(mainCandles);
  const alignTrendState = detectTrend(alignCandles);
  const alignCloseStructure = assessCloseStructure(alignCandles);
  const entryCloseStructure = assessCloseStructure(entryCandles);
  const mainDirection = mainTrendState.trend === "UP" || mainTrendState.trend === "DOWN" ? mainTrendState.trend : null;
  const alignmentDirection = alignTrendState.trend === "UP" || alignTrendState.trend === "DOWN"
    ? alignTrendState.trend
    : alignCloseStructure.bias === "UP" || alignCloseStructure.bias === "DOWN"
      ? alignCloseStructure.bias
      : null;
  const aligned = Boolean(mainDirection && alignmentDirection && mainDirection === alignmentDirection);
  const entryTrigger = assessEntryTrigger(entryCandles.length ? entryCandles : candles, mainDirection);

  return {
    ...targets,
    entryCandles,
    alignCandles,
    mainCandles,
    mainTrendState,
    alignTrendState,
    alignCloseStructure,
    entryCloseStructure,
    mainDirection,
    alignmentDirection,
    aligned,
    entryTrigger,
    summary: `${getTimeframeLabel(targets.mainSeconds)} ${mainTrendState.trend} -> ${getTimeframeLabel(targets.alignSeconds)} ${alignmentDirection || "MIXED"} -> ${getTimeframeLabel(targets.entrySeconds)} ${entryTrigger.ready ? "entry ready" : "wait"}`,
  };
}

function getSignalState(candles) {
  const hasAlgoBehaviorEngine = activeChartIndicators.has("ALGO_BEHAVIOR_ENGINE");
  if (hasAlgoBehaviorEngine) {
    const abe = buildAlgoBehaviorEngine(candles, {});
    const allowEntry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND;
    let signal = "--";
    let tradeDirection = null;

    if (abe.activeSetup) {
      const isBuy = abe.activeSetup.direction === "BUY";
      signal = allowEntry ? `ENTER NOW ${isBuy ? "BUY" : "SELL"}` : `WAIT ${isBuy ? "BUY" : "SELL"}`;
      tradeDirection = isBuy ? "CALL" : "PUT";
    } else if (abe.score >= 5 && abe.trend !== "RANGE") {
      const isBuy = abe.trend === "UP";
      signal = `WATCH ${isBuy ? "BUY" : "SELL"}`;
      tradeDirection = isBuy ? "CALL" : "PUT";
    }

    return {
      trend: abe.trend === "RANGE" ? "RANGE" : `${abe.trend} (${abe.regime})`,
      divergence: abe.phase === "NEUTRAL" ? "WAITING" : abe.phase,
      sweep: abe.sweepLabel,
      confidence: abe.confidence,
      signal,
      tradeDirection,
      setup: `${abe.setupText} | expiry ${abe.expirySuggestion}`,
      time: Date.now(),
    };
  }

  const hasPriceActionToolkit = activeChartIndicators.has("PRICE_ACTION_TOOLKIT");
  if (hasPriceActionToolkit) {
    const pa = buildPriceActionToolkit(candles, {});
    const latestSignal = pa.actionableSignals[pa.actionableSignals.length - 1] || null;
    const allowEntry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND;
    let signal = "--";
    let tradeDirection = null;
    let confidence = pa.bias === "RANGE" ? 42 : 58;

    if (latestSignal && latestSignal.entryIndex >= candles.length - 2) {
      const isBuy = latestSignal.direction === "BUY";
      signal = allowEntry ? `ENTER NOW ${isBuy ? "BUY" : "SELL"}` : `WAIT ${isBuy ? "BUY" : "SELL"}`;
      tradeDirection = isBuy ? "CALL" : "PUT";
      confidence = Math.min(100, confidence + 18);
    } else if (pa.bias !== "RANGE") {
      signal = `WAIT ${pa.bias === "BULLISH" ? "BUY" : "SELL"}`;
    }

    return {
      trend: pa.bias === "BULLISH" ? "UP" : pa.bias === "BEARISH" ? "DOWN" : "RANGE",
      divergence: "--",
      sweep: latestSignal ? latestSignal.kind.toUpperCase() : "--",
      confidence,
      signal,
      setup: pa.setupText,
      time: Date.now(),
      allowEntry,
      tradeDirection,
    };
  }

  const hasLDMSS = activeChartIndicators.has("LDMSS");
  if (hasLDMSS) {
    const ldmss = buildLiquidityDrivenMarketStructureSystem(candles, {
      pivotLen: 3,
      sweepLookahead: 10,
      pullbackLookahead: 12,
    });
    const allowEntry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND;
    const activeSetup = ldmss.activeSetup && ldmss.activeSetup.sessionAllowed ? ldmss.activeSetup : null;
    let signal = "--";
    let tradeDirection = null;

    if (activeSetup) {
      const buySide = activeSetup.direction === "BUY";
      signal = allowEntry
        ? `ENTER NOW ${buySide ? "BUY" : "SELL"}`
        : `WAIT ${buySide ? "BUY" : "SELL"}`;
      tradeDirection = buySide ? "CALL" : "PUT";
    }

    return {
      trend: ldmss.trendLabel,
      divergence: "--",
      sweep: ldmss.latestSweep ? `${ldmss.latestSweep.label} (${ldmss.sessionLabel})` : `-- (${ldmss.sessionLabel})`,
      confidence: ldmss.confidence,
      signal,
      setup: ldmss.setupText,
      time: Date.now(),
      allowEntry,
      tradeDirection,
    };
  }

  const institutionalEngine = buildInstitutionalForexSignalEngine(candles, {
    baseSeconds: getChartTimeframeSeconds(),
    expirySeconds: INSTITUTIONAL_EXPIRY_SECONDS,
  });
  const institutionalAllowEntry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND;
  const engineSignal = institutionalEngine.direction
    ? (institutionalAllowEntry
        ? `ENTER NOW ${institutionalEngine.direction === "CALL" ? "BUY" : "SELL"}`
        : `WAIT ${institutionalEngine.direction === "CALL" ? "BUY" : "SELL"}`)
    : "--";
  if (institutionalEngine.direction) persistInstitutionalSignal(institutionalEngine, currentSymbol);
  return {
    trend: institutionalEngine.htfTrend,
    divergence: institutionalEngine.rollingWinRate == null ? "Learning --" : `Learning ${institutionalEngine.rollingWinRate}%`,
    sweep: institutionalEngine.liquidityStatus,
    confidence: institutionalEngine.confidence,
    signal: engineSignal,
    setup: institutionalEngine.reason,
    time: Date.now(),
    allowEntry: institutionalAllowEntry,
    tradeDirection: institutionalEngine.direction,
    institutionalEngine,
  };

  const trendState = detectTrend(candles);
  const obv = calculateOBV(candles);
  const divergence = detectDivergence(candles, obv);
  const sweepState = detectLiquiditySweepState(candles);
  const closeStructure = assessCloseStructure(candles);
  const topDown = buildTopDownAnalysis(candles, getChartTimeframeSeconds());
  const current = candles[candles.length - 1];
  let confidence = calculateConfidence({
    trendStrength: trendState.trendStrength,
    wickStrength: sweepState.wickStrength,
    candleStrength: sweepState.candleStrength,
    levelStrength: sweepState.levelStrength,
  });
  if (divergence && divergence === sweepState.sweepType) {
    confidence = Math.min(100, confidence + 15);
  }
  if (sweepState.sweepType === "BUY") {
    if (closeStructure.bias === "UP") confidence = Math.min(100, confidence + 12);
    else confidence = Math.max(0, confidence - 18);
  } else if (sweepState.sweepType === "SELL") {
    if (closeStructure.bias === "DOWN") confidence = Math.min(100, confidence + 12);
    else confidence = Math.max(0, confidence - 18);
  }
  if (topDown.aligned) confidence = Math.min(100, confidence + 14);
  else if (topDown.mainDirection) confidence = Math.max(0, confidence - 20);
  if (topDown.entryTrigger.ready) confidence = Math.min(100, confidence + 10);
  else if (topDown.mainDirection) confidence = Math.max(0, confidence - 8);
  const allowEntry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND;

  let signal = "--";
  let tradeDirection = null;
  const rejection = sweepState.rejection;
  const buyReady =
    topDown.mainDirection === "UP" &&
    topDown.aligned &&
    topDown.entryTrigger.ready &&
    trendState.trend === "UP" &&
    sweepState.sweepType === "BUY" &&
    rejection?.strongBuyRejection &&
    rejection?.bullishConfirm &&
    closeStructure.bias === "UP" &&
    closeStructure.reclaimedLevel &&
    current.close > (sweepState.referenceLevel ?? current.close);
  const sellReady =
    topDown.mainDirection === "DOWN" &&
    topDown.aligned &&
    topDown.entryTrigger.ready &&
    trendState.trend === "DOWN" &&
    sweepState.sweepType === "SELL" &&
    rejection?.strongSellRejection &&
    rejection?.bearishConfirm &&
    closeStructure.bias === "DOWN" &&
    closeStructure.lostLevel &&
    current.close < (sweepState.referenceLevel ?? current.close);

  if (buyReady) {
    signal = allowEntry ? "ENTER NOW BUY" : "WAIT BUY";
    tradeDirection = "CALL";
  } else if (sellReady) {
    signal = allowEntry ? "ENTER NOW SELL" : "WAIT SELL";
    tradeDirection = "PUT";
  }

  const setup = currentTrendMode === "SMC"
    ? detectSmcSetupState(candles, trendState)
    : trendState.modeLabel ? `${trendState.modeLabel} active` : "--";
  const setupWithCloseStructure = `${setup} | ${topDown.summary} | entry ${topDown.entryTrigger.reason}`;

  return {
    trend: topDown.mainDirection ? `${topDown.mainTrendState.trend} / ${topDown.alignmentDirection || "MIXED"}` : trendState.trend,
    divergence: divergence || "--",
    sweep: sweepState.sweepType ? `${sweepState.sweepLabel} ${sweepState.rejectionLabel}` : "--",
    confidence,
    signal,
    setup: setupWithCloseStructure,
    time: Date.now(),
    allowEntry,
    tradeDirection,
  };
}

function updateSignalUI({ trend, divergence, sweep, confidence, signal, setup, time }) {
  if (sigTrendEl) sigTrendEl.textContent = trend || "--";
  if (sigDivEl) sigDivEl.textContent = divergence || "--";
  if (sigSweepEl) sigSweepEl.textContent = sweep || "--";
  if (sigConfEl) sigConfEl.textContent = Number.isFinite(confidence) ? `${confidence}%` : "--";
  if (sigSignalEl) sigSignalEl.textContent = signal || "--";
  if (sigSetupEl) sigSetupEl.textContent = setup || "--";
  if (sigTimeEl) sigTimeEl.textContent = time ? new Date(time).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit", second: "2-digit" }) : "--";
}

function updateFrameSignalUI(signalState) {
  if (!phoneEl) return;
  phoneEl.classList.remove("frame-neutral", "frame-buy", "frame-sell");

  const hasBuySignal = signalState?.tradeDirection === "CALL" && typeof signalState?.signal === "string" && signalState.signal !== "--";
  const hasSellSignal = signalState?.tradeDirection === "PUT" && typeof signalState?.signal === "string" && signalState.signal !== "--";

  if (hasBuySignal) {
    phoneEl.classList.add("frame-buy");
    return;
  }
  if (hasSellSignal) {
    phoneEl.classList.add("frame-sell");
    return;
  }
  phoneEl.classList.add("frame-neutral");
}

function updateVisibleCandleCountUI(blueCount, whiteCount) {
  if (sigBlueEl) sigBlueEl.textContent = Number.isFinite(blueCount) ? String(blueCount) : "--";
  if (sigWhiteEl) sigWhiteEl.textContent = Number.isFinite(whiteCount) ? String(whiteCount) : "--";
}

function getLiquidityPanelState(candles) {
  if (activeChartIndicators.has("ALGO_BEHAVIOR_ENGINE")) {
    const abe = buildAlgoBehaviorEngine(candles, {});
    return {
      trend: abe.trend === "RANGE" ? "RANGE" : `${abe.trend} ${abe.regime}`,
      sweep: abe.sweepLabel,
      rejection: abe.trapLabel,
      confidence: abe.confidence ? `${abe.confidence}%` : "--",
      entry: abe.expirySuggestion || "--",
      level: abe.focusPrice != null ? formatPrice(abe.focusPrice, currentPip) : "--",
    };
  }

  if (candles.length < MIN_SIGNAL_CANDLES) {
    return {
      trend: `BUILDING ${Math.min(100, Math.floor((candles.length / MIN_SIGNAL_CANDLES) * 100))}%`,
      sweep: "--",
      rejection: "--",
      confidence: "--",
      entry: "--",
      level: "--",
    };
  }

  const institutionalEngine = buildInstitutionalForexSignalEngine(candles, {
    baseSeconds: getChartTimeframeSeconds(),
    expirySeconds: INSTITUTIONAL_EXPIRY_SECONDS,
  });
  const institutionalEntry = institutionalEngine.direction
    ? new Date().getSeconds() >= SIGNAL_ENTRY_SECOND
      ? `ENTER NOW ${institutionalEngine.direction === "CALL" ? "BUY" : "SELL"}`
      : `WAIT ${institutionalEngine.direction === "CALL" ? "BUY" : "SELL"}`
    : "WAIT";
  return {
    trend: institutionalEngine.htfTrend,
    sweep: institutionalEngine.liquidityStatus,
    rejection: `${institutionalEngine.confirmationStatus} | ${institutionalEngine.sessionStatus}`,
    confidence: institutionalEngine.confidence,
    entry: institutionalEntry,
    level: institutionalEngine.currentPoi,
  };

  const trendState = detectTrend(candles);
  const sweepState = detectLiquiditySweepState(candles);
  const closeStructure = assessCloseStructure(candles);
  const topDown = buildTopDownAnalysis(candles, getChartTimeframeSeconds());
  let confidence = calculateConfidence({
    trendStrength: trendState.trendStrength,
    wickStrength: sweepState.wickStrength,
    candleStrength: sweepState.candleStrength,
    levelStrength: sweepState.levelStrength,
  });
  if (sweepState.sweepType === "BUY") {
    confidence = closeStructure.bias === "UP" ? Math.min(100, confidence + 12) : Math.max(0, confidence - 18);
  } else if (sweepState.sweepType === "SELL") {
    confidence = closeStructure.bias === "DOWN" ? Math.min(100, confidence + 12) : Math.max(0, confidence - 18);
  }
  if (topDown.aligned) confidence = Math.min(100, confidence + 14);
  else if (topDown.mainDirection) confidence = Math.max(0, confidence - 20);
  if (topDown.entryTrigger.ready) confidence = Math.min(100, confidence + 10);
  else if (topDown.mainDirection) confidence = Math.max(0, confidence - 8);
  const level = sweepState.referenceLevel != null ? formatPrice(sweepState.referenceLevel, currentPip) : "--";
  let entry = "WAIT";
  if (
    topDown.mainDirection === "UP" &&
    topDown.aligned &&
    topDown.entryTrigger.ready &&
    sweepState.sweepType === "BUY" &&
    sweepState.rejection?.strongBuyRejection &&
    sweepState.rejection?.bullishConfirm &&
    closeStructure.bias === "UP" &&
    closeStructure.reclaimedLevel
  ) {
    entry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND ? "ENTER NOW BUY" : "WAIT BUY";
  } else if (
    topDown.mainDirection === "DOWN" &&
    topDown.aligned &&
    topDown.entryTrigger.ready &&
    sweepState.sweepType === "SELL" &&
    sweepState.rejection?.strongSellRejection &&
    sweepState.rejection?.bearishConfirm &&
    closeStructure.bias === "DOWN" &&
    closeStructure.lostLevel
  ) {
    entry = new Date().getSeconds() >= SIGNAL_ENTRY_SECOND ? "ENTER NOW SELL" : "WAIT SELL";
  }

  return {
    trend: topDown.mainDirection ? `${topDown.mainTrendState.trend} / ${topDown.alignmentDirection || "MIXED"}` : trendState.trend,
    sweep: sweepState.sweepLabel,
    rejection: `${sweepState.rejectionLabel} | ${topDown.entryTrigger.reason}`,
    confidence,
    entry,
    level,
  };
}

function updateSignalFromCandles(candles, { live = false } = {}) {
  const allCandles = candles;
  const buildPct = Math.min(100, Math.floor((allCandles.length / MIN_SIGNAL_CANDLES) * 100));
  evaluateInstitutionalSignalOutcomes(allCandles, currentSymbol);

  if (allCandles.length >= MIN_SIGNAL_CANDLES) {
    lastSignalState = getSignalState(allCandles);
  } else {
    lastSignalState = {
      ...lastSignalState,
      trend: `BUILDING ${buildPct}%`,
      divergence: "--",
      sweep: "--",
      confidence: "--",
      signal: "--",
      setup: "--",
      allowEntry: false,
      tradeDirection: null,
    };
  }

  if (mainSignalLockedState && mainSignalSchedule && Date.now() <= mainSignalSchedule.entryAt + 10000) {
    lastSignalState = mainSignalLockedState;
  } else if (mainSignalLockedState && mainSignalSchedule && Date.now() > mainSignalSchedule.entryAt + 10000) {
    mainSignalLockedState = null;
  }

  updateSignalUI(lastSignalState);
  updateFrameSignalUI(lastSignalState);
  lastSweepState = getLiquidityPanelState(allCandles);
  if (sigRejectEl) sigRejectEl.textContent = lastSweepState.rejection || "--";
  if (sigEntryEl) sigEntryEl.textContent = lastSweepState.entry || "--";
  if (sigLevelEl) sigLevelEl.textContent = lastSweepState.level || "--";
  renderMiniChart(candles);
  if (lastSignalState?.institutionalEngine) {
    const stats = getInstitutionalSignalStats(currentSymbol);
    if (sigBlueEl) sigBlueEl.textContent = stats.winRate == null ? "--" : `${stats.winRate}%`;
    if (sigWhiteEl) sigWhiteEl.textContent = stats.lastSignals.length ? stats.lastSignals.join(" | ") : "--";
  }
  if (live) maybeNotifyIndicatorSignals(candles);

  if (autoTradeEnabled && lastSignalState.signal !== "--" && candles.length >= MIN_SIGNAL_CANDLES) {
    const candleTime = candleBuilder.currentCandle?.time || candles[candles.length - 1]?.time;
    if (candleTime && candleTime !== lastAutoTradeCandle) {
      tryAutoTrade();
      lastAutoTradeCandle = candleTime;
    }
  }
}

function setDirection(direction, { refresh = true } = {}) {
  currentDirection = direction === "PUT" ? "PUT" : "CALL";
  directionButtons.forEach((btn) => {
    const btnDirection = btn.dataset.direction === "PUT" ? "PUT" : "CALL";
    btn.classList.toggle("active", currentDirection === btnDirection);
  });
  renderTradeList();
  if (refresh) scheduleProposalRefresh(true);
}

function getAutoTradeStake() {
  const value = Number(autoStakeInputEl?.value || autoTradeStake || "1");
  return Number.isFinite(value) && value > 0 ? value : 1;
}

function getAutoTradeTimeframeSeconds() {
  const value = Number(autoTimeframeSelectEl?.value || autoTradeTimeframeSeconds || DEFAULT_TIMEFRAME_SEC);
  return TIMEFRAME_OPTIONS.some((option) => option.seconds === value) ? value : DEFAULT_TIMEFRAME_SEC;
}

function setAutoTradeStatus(message, isError = false) {
  setStatus(`Auto scanner: ${message}`, isError);
}

function clearAutoScanTimer() {
  if (autoScanTimer) {
    clearTimeout(autoScanTimer);
    autoScanTimer = null;
  }
}

function clearAutoScannerWatchdog() {
  if (autoScannerWatchdogTimer) {
    clearInterval(autoScannerWatchdogTimer);
    autoScannerWatchdogTimer = null;
  }
}

function ensureAutoScannerWatchdog() {
  if (autoScannerWatchdogTimer) return;
  autoScannerWatchdogTimer = setInterval(() => {
    if (!autoTradeEnabled) {
      clearAutoScannerWatchdog();
      return;
    }
    if (!autoOpenContractId && !autoScannerInFlight && !autoScanTimer) {
      scheduleAutoScanner(0);
    }
  }, 5000);
}

function clearAutoContractCloseTimer() {
  if (autoContractCloseTimer) {
    clearTimeout(autoContractCloseTimer);
    autoContractCloseTimer = null;
  }
}

function scheduleAutoScanner(delayMs = AUTO_SCANNER_RETRY_MS) {
  if (!autoTradeEnabled || autoOpenContractId) return;
  if (autoScanTimer) return;
  autoScanTimer = setTimeout(() => {
    autoScanTimer = null;
    runAutoScannerCycle().catch((err) => {
      setAutoTradeStatus(err?.message || "scan failed", true);
      scheduleAutoScanner(AUTO_SCANNER_RETRY_MS);
    });
  }, Math.max(0, delayMs));
}

function scheduleAutoContractCloseCheck(contractId, expiry) {
  clearAutoContractCloseTimer();
  if (!contractId || !expiry) return;
  const delayMs = Math.max(1500, ((Number(expiry) || 0) - Math.floor(Date.now() / 1000) + 3) * 1000);
  autoContractCloseTimer = setTimeout(() => {
    autoContractCloseTimer = null;
    checkAutoOpenContractClosed(contractId).catch(() => {
      if (String(autoOpenContractId || "") === String(contractId)) {
        scheduleAutoContractCloseCheck(contractId, Math.floor(Date.now() / 1000) + 5);
      }
    });
  }, delayMs);
}

async function checkAutoOpenContractClosed(contractId) {
  if (!contractId || String(autoOpenContractId || "") !== String(contractId)) return;
  const res = await privateWsRequest({ proposal_open_contract: 1, contract_id: contractId });
  const contract = res.proposal_open_contract;
  if (contract) {
    handleOpenContractUpdate(contract, null);
  }
  if (String(autoOpenContractId || "") === String(contractId)) {
    const autoTrade = autoTradeResults.find((item) => String(item.contractId || "") === String(contractId));
    const expiry = Number(autoTrade?.expiry || 0);
    const nowSec = Math.floor(Date.now() / 1000);
    if (expiry && nowSec >= expiry + 8) {
      autoOpenContractId = null;
      renderAutoTradeResults();
      if (autoTradeEnabled) scheduleAutoScanner(AUTO_SCANNER_AFTER_CLOSE_MS);
    } else {
      scheduleAutoContractCloseCheck(contractId, nowSec + 5);
    }
  }
}

function getCurrentCandleEndDuration(timeframeSeconds, durationLimits = null) {
  const nowSec = Math.floor(Date.now() / 1000);
  const step = Math.max(1, Number(timeframeSeconds) || DEFAULT_TIMEFRAME_SEC);
  let expiry = Math.ceil(nowSec / step) * step;
  if (expiry <= nowSec) expiry += step;
  const durationSec = expiry - nowSec;
  const minSec = Number(durationLimits?.minSec ?? minDurationSec);
  const maxSec = Number(durationLimits?.maxSec ?? Infinity);
  if (durationSec < minSec) return null;
  if (Number.isFinite(maxSec) && durationSec > maxSec) return null;
  return { expiry, durationSec };
}

function extractRiseFallDurationLimits(contracts) {
  const list = Array.isArray(contracts) ? contracts : [];
  let minSec = Infinity;
  let maxSec = 0;
  list.forEach((item) => {
    if (item?.contract_type !== "CALL" && item?.contract_type !== "PUT") return;
    const min = parseApiDuration(item.min_contract_duration ?? item.min_duration ?? item.minimum_duration);
    const max = parseApiDuration(item.max_contract_duration ?? item.max_duration ?? item.maximum_duration);
    if (min?.unit !== "t" && Number.isFinite(min?.seconds)) {
      minSec = Math.min(minSec, min.seconds);
    }
    if (max?.unit !== "t" && Number.isFinite(max?.seconds)) {
      maxSec = Math.max(maxSec, max.seconds);
    }
  });
  return {
    minSec: Number.isFinite(minSec) ? minSec : minDurationSec,
    maxSec: maxSec > 0 ? maxSec : Infinity,
  };
}

async function getAutoContractDurationLimits(symbol) {
  if (!symbol) return { minSec: minDurationSec, maxSec: Infinity };
  const cached = autoContractDurationCache.get(symbol);
  if (cached && Date.now() - cached.updatedAt < AUTO_CONTRACT_DURATION_CACHE_MS) {
    return cached.limits;
  }
  const res = await wsRequest({ contracts_for: symbol });
  const list = res.contracts_for?.available || res.contracts_for?.contracts || res.contracts_for?.available_contracts || [];
  const limits = extractRiseFallDurationLimits(list);
  autoContractDurationCache.set(symbol, { limits, updatedAt: Date.now() });
  return limits;
}

async function scoreAutoScannerSymbol(symbolInfo, indicators, timeframeSeconds) {
  const durationLimits = await getAutoContractDurationLimits(symbolInfo.symbol);
  const tradeWindow = getCurrentCandleEndDuration(timeframeSeconds, durationLimits);
  if (!tradeWindow) return null;
  const candles = await getMainSignalCandles(symbolInfo.symbol, timeframeSeconds);
  const readiness = getScannerHistoryReadiness(candles, timeframeSeconds);
  if (!readiness.ready) return null;
  const score = scoreMarketWithIndicators(indicators, candles, timeframeSeconds);
  if (!score || score.confidence < AUTO_SCANNER_MIN_CONFIDENCE) return null;
  return {
    ...score,
    symbol: symbolInfo.symbol,
    displayName: symbolInfo.display_name || symbolInfo.symbol,
    market: symbolInfo.market_display_name || symbolInfo.market || "Market",
    durationLimits,
  };
}

async function findAutoScannerBestMarket(indicators, timeframeSeconds) {
  const symbols = getAutoScannerSymbols();
  const scopeLabel = getAutoScannerScopeLabel();
  const results = [];
  const batchSize = 4;
  if (!symbols.length) {
    setAutoTradeStatus(`no markets loaded for ${scopeLabel}`, true);
    return null;
  }
  for (let i = 0; i < symbols.length; i += batchSize) {
    const batch = symbols.slice(i, i + batchSize);
    const batchResults = await Promise.all(batch.map(async (symbolInfo) => {
      try {
        return await scoreAutoScannerSymbol(symbolInfo, indicators, timeframeSeconds);
      } catch {
        return null;
      }
    }));
    batchResults.filter(Boolean).forEach((item) => results.push(item));
    results.sort((a, b) => b.score - a.score || b.confidence - a.confidence);
    setAutoTradeStatus(`scanned ${Math.min(i + batch.length, symbols.length)}/${symbols.length} ${scopeLabel}. Best ${results[0]?.displayName || "--"}`);
  }
  return results[0] || null;
}

async function confirmAutoScannerMarket(candidate, indicators, timeframeSeconds) {
  if (!candidate?.symbol) return null;
  const symbolInfo = getAutoScannerSymbols().find((item) => item.symbol === candidate.symbol) || {
    symbol: candidate.symbol,
    display_name: candidate.displayName,
    market_display_name: candidate.market,
  };
  const confirmed = await scoreAutoScannerSymbol(symbolInfo, indicators, timeframeSeconds);
  if (!confirmed) return null;
  if (confirmed.direction !== candidate.direction) return null;
  return confirmed;
}

async function buyAutoScannerProposal(signal, account, stake, timeframeSeconds) {
  const durationLimits = signal.durationLimits || await getAutoContractDurationLimits(signal.symbol);
  const currentCandle = getCurrentCandleEndDuration(timeframeSeconds, durationLimits);
  if (!currentCandle) {
    throw new Error(`current candle end is below this market's minimum duration (${formatDurationLabel(durationLimits.minSec)})`);
  }
  await activateDerivAccount(account, { silent: true, subscribeBalance: false });
  const proposal = await getProposal({
    symbol: signal.symbol,
    contractType: signal.direction,
    barrier: null,
    stake,
    durationSec: currentCandle.durationSec,
    durationUnit: "s",
  });
  const askPrice = Number(proposal.ask_price ?? proposal.buy_price ?? stake);
  const res = await privateWsRequest({ buy: proposal.id, price: askPrice });
  const buy = res.buy;
  const contractId = buy?.contract_id ?? null;
  const buyPrice = buy?.buy_price ?? askPrice;
  if (!contractId) throw new Error("buy did not return a contract id");
  autoOpenContractId = contractId;
  autoTradeResults.unshift({
    time: Date.now(),
    success: true,
    contractId,
    price: buyPrice,
    profit: null,
    direction: signal.direction,
    isSold: false,
    expiry: currentCandle.expiry,
    symbol: signal.displayName || signal.symbol,
  });
  autoTradeResults = autoTradeResults.slice(0, 100);
  upsertTradeChartMarkerFromBuy({
    contractId,
    symbol: signal.symbol,
    direction: signal.direction,
    entryPrice: null,
    entryTime: Math.floor(Date.now() / 1000),
  });
  renderAutoTradeResults();
  subscribeOpenContract(contractId);
  scheduleAutoContractCloseCheck(contractId, currentCandle.expiry);
  autoTradeSessionCount += 1;
  setAutoTradeStatus(`opened ${signal.displayName || signal.symbol} ${signal.direction === "CALL" ? "Rise" : "Fall"} until candle end`);
}

async function runAutoScannerCycle() {
  if (!autoTradeEnabled || autoScannerInFlight || autoOpenContractId) return;
  if (!autoTradeLoginId) {
    setAutoTradeStatus("select an account first", true);
    return;
  }
  const account = storedAccounts.find((acc) => acc.loginid === autoTradeLoginId);
  if (!account) {
    setAutoTradeStatus("account not found", true);
    return;
  }
  const indicators = getMarketScannerIndicators();
  if (!indicators.length) {
    setAutoTradeStatus("attach a chart signal indicator first", true);
    return;
  }

  autoScannerInFlight = true;
  try {
    const stake = getAutoTradeStake();
    const timeframeSeconds = getAutoTradeTimeframeSeconds();
    const candidate = await findAutoScannerBestMarket(indicators, timeframeSeconds);
    if (!candidate) {
      setAutoTradeStatus("no valid scanner signal yet");
      autoScanTimer = setTimeout(() => {
        autoScanTimer = null;
        runAutoScannerCycle().catch((err) => {
          setAutoTradeStatus(err?.message || "scan failed", true);
        });
      }, AUTO_SCANNER_RETRY_MS);
      return;
    }
    setAutoTradeStatus(`confirming ${candidate.displayName || candidate.symbol}`);
    const confirmed = await confirmAutoScannerMarket(candidate, indicators, timeframeSeconds);
    if (!confirmed) {
      setAutoTradeStatus("best signal changed on confirmation; waiting");
      autoScanTimer = setTimeout(() => {
        autoScanTimer = null;
        runAutoScannerCycle().catch((err) => {
          setAutoTradeStatus(err?.message || "scan failed", true);
        });
      }, AUTO_SCANNER_RETRY_MS);
      return;
    }
    await buyAutoScannerProposal(confirmed, account, stake, timeframeSeconds);
  } catch (err) {
    setAutoTradeStatus(err?.message || "trade failed", true);
    autoScanTimer = setTimeout(() => {
      autoScanTimer = null;
      runAutoScannerCycle().catch((scanErr) => {
        setAutoTradeStatus(scanErr?.message || "scan failed", true);
      });
    }, AUTO_SCANNER_RETRY_MS);
  } finally {
    autoScannerInFlight = false;
  }
}

async function tryAutoTrade() {
  if (!autoTradeEnabled) return;
  scheduleAutoScanner(0);
}

function getRobustChartPriceRange(points) {
  const candles = (Array.isArray(points) ? points : []).filter((candle) => (
    candle
    && [candle.open, candle.high, candle.low, candle.close].every(Number.isFinite)
    && candle.high >= candle.low
  ));
  if (!candles.length) return null;

  const lows = candles.map((candle) => candle.low).sort((a, b) => a - b);
  const highs = candles.map((candle) => candle.high).sort((a, b) => a - b);
  const trim = candles.length >= 20 ? Math.max(1, Math.floor(candles.length * 0.05)) : 0;
  const rawMin = Math.min(...lows);
  const rawMax = Math.max(...highs);
  const trimmedMin = lows[Math.min(trim, lows.length - 1)];
  const trimmedMax = highs[Math.max(0, highs.length - 1 - trim)];
  const bodyValues = candles.flatMap((candle) => [candle.open, candle.close]);
  const bodyMin = Math.min(...bodyValues);
  const bodyMax = Math.max(...bodyValues);
  const latestClose = candles[candles.length - 1].close;
  const bodyRange = Math.max(bodyMax - bodyMin, Math.abs(latestClose) * 0.00001, 0.0000001);
  const rawRange = rawMax - rawMin;
  const hasDistortingWick = rawRange > bodyRange * 12 && candles.length >= 8;
  const min = hasDistortingWick ? Math.min(trimmedMin, bodyMin, latestClose) : rawMin;
  const max = hasDistortingWick ? Math.max(trimmedMax, bodyMax, latestClose) : rawMax;
  return max > min ? { min, max } : { min: latestClose - bodyRange / 2, max: latestClose + bodyRange / 2 };
}

function formatChartAxisTime(candle, previousCandle = null) {
  const seconds = Number(candle?.time);
  if (!Number.isFinite(seconds)) return "";
  const date = new Date(seconds * 1000);
  const previousSeconds = Number(previousCandle?.time);
  const previousDate = Number.isFinite(previousSeconds) ? new Date(previousSeconds * 1000) : null;
  const isNewDay = !previousDate || date.toDateString() !== previousDate.toDateString();
  if (isNewDay) {
    return date.toLocaleDateString([], { month: "short", day: "2-digit" });
  }
  return date.toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

function drawMainChartAxes(ctx, viewport) {
  if (!ctx || !viewport) return;
  const {
    width,
    height,
    leftPad,
    rightPad,
    topPad,
    bottomPad,
    plotW,
    plotH,
    slotW,
    points,
    visibleSlotCount,
    min,
    max,
    toY,
  } = viewport;
  const axisX = width - rightPad;
  const plotBottom = height - bottomPad;
  const priceRange = max - min;
  if (!Number.isFinite(priceRange) || priceRange <= 0) return;

  ctx.save();
  ctx.lineWidth = 1;
  ctx.strokeStyle = "rgba(44, 55, 73, 0.72)";
  ctx.fillStyle = "#738197";
  ctx.font = "11px Inter, Segoe UI, sans-serif";
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";

  ctx.beginPath();
  ctx.moveTo(axisX + 0.5, topPad);
  ctx.lineTo(axisX + 0.5, plotBottom);
  ctx.moveTo(leftPad, plotBottom + 0.5);
  ctx.lineTo(axisX, plotBottom + 0.5);
  ctx.stroke();

  const priceTicks = Math.max(3, Math.min(7, Math.floor(plotH / 82)));
  for (let i = 0; i <= priceTicks; i += 1) {
    const price = max - ((priceRange * i) / priceTicks);
    const y = toY(price);
    if (!Number.isFinite(y) || y < topPad - 1 || y > plotBottom + 1) continue;
    ctx.strokeStyle = i === priceTicks ? "rgba(44, 55, 73, 0.88)" : "rgba(44, 55, 73, 0.34)";
    ctx.beginPath();
    ctx.moveTo(leftPad, y + 0.5);
    ctx.lineTo(axisX, y + 0.5);
    ctx.stroke();
    ctx.fillStyle = "#75839a";
    ctx.fillText(formatPrice(price, currentPip), axisX + 8, y);
  }

  const targetLabels = Math.max(2, Math.floor(plotW / 105));
  const step = Math.max(1, Math.ceil(Math.max(1, visibleSlotCount) / targetLabels));
  let lastLabelX = -Infinity;
  ctx.textAlign = "center";
  ctx.textBaseline = "top";
  points.forEach((candle, index) => {
    if (index !== 0 && index !== points.length - 1 && index % step !== 0) return;
    const x = leftPad + (index * slotW) + (slotW / 2);
    if (x < leftPad + 8 || x > axisX - 8 || x - lastLabelX < 58) return;
    const label = formatChartAxisTime(candle, points[index - 1]);
    if (!label) return;
    ctx.strokeStyle = "rgba(44, 55, 73, 0.30)";
    ctx.beginPath();
    ctx.moveTo(x + 0.5, topPad);
    ctx.lineTo(x + 0.5, plotBottom);
    ctx.stroke();
    ctx.fillStyle = "#75839a";
    ctx.fillText(label, x, plotBottom + 9);
    lastLabelX = x;
  });
  ctx.restore();
}

function renderMiniChart(candles) {
  if (!miniChartCanvas) return;
  if (!replayEngine.isReplayMode()) hideReplayAxisDateBadge();
  const ctx = miniChartCanvas.getContext("2d");
  if (!ctx) return;
  const width = miniChartCanvas.clientWidth;
  const height = miniChartCanvas.clientHeight;
  if (width > 0 && height > 0 && (miniChartCanvas.width !== width || miniChartCanvas.height !== height)) {
    miniChartCanvas.width = width;
    miniChartCanvas.height = height;
  }
  ctx.clearRect(0, 0, miniChartCanvas.width, miniChartCanvas.height);
  if (!candles.length) {
    updateVisibleCandleCountUI(null, null);
    return;
  }

  const { points, start, end, visibleSlotCount } = getVisibleChartWindow(candles);
  if (!points.length) {
    updateVisibleCandleCountUI(null, null);
    return;
  }
  const barrierOffset = getBarrierOffsetValue();
  let blueCount = 0;
  let whiteCount = 0;
  points.forEach((candle) => {
    const bodySize = Math.abs(candle.close - candle.open);
    const isLarge = barrierOffset > 0 && bodySize >= barrierOffset;
    if (!isLarge) return;
    if (candle.close >= candle.open) blueCount += 1;
    else whiteCount += 1;
  });
  updateVisibleCandleCountUI(blueCount, whiteCount);
  const priceRange = getRobustChartPriceRange(points);
  if (!priceRange) return;
  const rawMin = priceRange.min;
  const rawMax = priceRange.max;
  const leftPad = 6;
  const rightPad = 88;
  const topPad = 6;
  const bottomPad = 34;

  if (width === 0 || height === 0) return;
  ctx.strokeStyle = "#1f2735";
  ctx.lineWidth = 1;
  ctx.beginPath();
  ctx.moveTo(leftPad, height - bottomPad - 0.5);
  ctx.lineTo(width - rightPad, height - bottomPad - 0.5);
  ctx.stroke();

  const range = rawMax - rawMin;
  if (range === 0) return;
  const rangePadding = Math.max(range * 0.08, Math.abs(rawMax) * 0.0002, 0.0000001);
  const baseSpan = range + (rangePadding * 2);
  chartVerticalScale = clamp(chartVerticalScale, 0.25, 12);
  const scaledSpan = baseSpan / chartVerticalScale;
  const baseCenter = (rawMax + rawMin) / 2;
  const maxVerticalShift = Math.max(baseSpan * 3, rangePadding * 4);
  chartVerticalOffset = Math.max(-maxVerticalShift, Math.min(chartVerticalOffset, maxVerticalShift));
  const center = baseCenter + chartVerticalOffset;
  const min = center - (scaledSpan / 2);
  const max = center + (scaledSpan / 2);
  // Candlesticks
  const plotW = width - leftPad - rightPad;
  const plotH = height - topPad - bottomPad;
  const candleGap = 2;
  const slotW = plotW / Math.max(1, visibleSlotCount);
  const candleW = Math.max(2, Math.floor(slotW) - candleGap);
  const toY = (price) => height - bottomPad - ((price - min) / (max - min)) * plotH;
  chartViewportState = {
    width,
    height,
    leftPad,
    rightPad,
    topPad,
    bottomPad,
    plotW,
    plotH,
    slotW,
    start,
    end,
    points,
    visibleSlotCount,
    min,
    max,
    toY,
  };
  if (isDesktopPointerLayout()) {
    chartCrosshairEnabled = true;
    updateCrosshairToggleUI();
  }
  if (chartCrosshairEnabled && !chartCrosshairState?.active) {
    const centerX = leftPad + (plotW * 0.5);
    const centerY = topPad + (plotH * 0.5);
    const slotIndex = Math.max(0, Math.min(points.length - 1, Math.floor((centerX - leftPad) / Math.max(1, slotW))));
    chartCrosshairState = {
      active: true,
      x: centerX,
      y: centerY,
      candleIndex: points.length ? start + slotIndex : null,
    };
  }

  drawMainChartAxes(ctx, chartViewportState);

  const hasICTKillzones = activeChartIndicators.has("ICT_KILLZONES") && isChartIndicatorNativeTimeframe("ICT_KILLZONES");
  const hasICTFVG = activeChartIndicators.has("ICT_FVG") && isChartIndicatorNativeTimeframe("ICT_FVG");
  const hasICTBPR = activeChartIndicators.has("ICT_BPR") && isChartIndicatorNativeTimeframe("ICT_BPR");
  const hasICTOB = activeChartIndicators.has("ICT_OB") && isChartIndicatorNativeTimeframe("ICT_OB");
  const hasICTStructure = activeChartIndicators.has("ICT_STRUCTURE") && isChartIndicatorNativeTimeframe("ICT_STRUCTURE");
  const hasICTFib = activeChartIndicators.has("ICT_FIB") && isChartIndicatorNativeTimeframe("ICT_FIB");
  const hasICTLiquidity = activeChartIndicators.has("ICT_LIQUIDITY") && isChartIndicatorNativeTimeframe("ICT_LIQUIDITY");
  const hasAnyICT = hasICTKillzones || hasICTFVG || hasICTBPR || hasICTOB || hasICTStructure || hasICTFib || hasICTLiquidity;
  const hasInstitutionalForexEngine = activeChartIndicators.has("INSTITUTIONAL_FOREX_ENGINE") && isChartIndicatorNativeTimeframe("INSTITUTIONAL_FOREX_ENGINE");
  const hasInstitutionalExecutionModel = activeChartIndicators.has("INST_EXECUTION_MODEL") && isChartIndicatorNativeTimeframe("INST_EXECUTION_MODEL");
  const hasInstitutionalLevelBehavior = activeChartIndicators.has("INST_LEVEL_BEHAVIOR") && isChartIndicatorNativeTimeframe("INST_LEVEL_BEHAVIOR");
  const hasAlgoBehaviorEngine = activeChartIndicators.has("ALGO_BEHAVIOR_ENGINE") && isChartIndicatorNativeTimeframe("ALGO_BEHAVIOR_ENGINE");
  const hasPriceActionToolkit = activeChartIndicators.has("PRICE_ACTION_TOOLKIT") && isChartIndicatorNativeTimeframe("PRICE_ACTION_TOOLKIT");
  const hasLiquiditySweepOB = activeChartIndicators.has("LIQ_SWEEP_OB") && isChartIndicatorNativeTimeframe("LIQ_SWEEP_OB");
  const hasLDMSS = activeChartIndicators.has("LDMSS") && isChartIndicatorNativeTimeframe("LDMSS");
  const hasInstitutionalSMCEngine = activeChartIndicators.has("INSTITUTIONAL_SMC_ENGINE");
  const hasWeloSMC = activeChartIndicators.has("SMC_WELO_TRADES");
  const hasSMCSetup08 = activeChartIndicators.has("SMC_SETUP_08") && isChartIndicatorNativeTimeframe("SMC_SETUP_08");
  const hasSMCProCombo = activeChartIndicators.has("SMC_PRO_COMBO") && isChartIndicatorNativeTimeframe("SMC_PRO_COMBO");
  const hasADXVolWaves = activeChartIndicators.has("ADX_VOL_WAVES") && isChartIndicatorNativeTimeframe("ADX_VOL_WAVES");
  const hasBreakoutTargets = activeChartIndicators.has("BREAKOUT_TARGETS") && isChartIndicatorNativeTimeframe("BREAKOUT_TARGETS");
  const hasDynamicZDivergence = activeChartIndicators.has("DYNAMIC_Z_DIVERGENCE") && isChartIndicatorNativeTimeframe("DYNAMIC_Z_DIVERGENCE");
  const hasVolumeProfileNodes = activeChartIndicators.has("VOLUME_PROFILE_NODES") && isChartIndicatorNativeTimeframe("VOLUME_PROFILE_NODES");
  const hasLiquidityTrendline = activeChartIndicators.has("LIQUIDITY_TRENDLINE") && isChartIndicatorNativeTimeframe("LIQUIDITY_TRENDLINE");
  const hasStructurePullback = activeChartIndicators.has("STRUCTURE_PULLBACK") && isChartIndicatorNativeTimeframe("STRUCTURE_PULLBACK");
  const hasSRSignalsMTF = activeChartIndicators.has("SR_SIGNALS_MTF") && isChartIndicatorNativeTimeframe("SR_SIGNALS_MTF");
  const hasTickRejection = activeChartIndicators.has("TICK_REJECTION") && isChartIndicatorNativeTimeframe("TICK_REJECTION");
  const hasTrendVolumeAccum = activeChartIndicators.has("TREND_VOLUME_ACCUM") && isChartIndicatorNativeTimeframe("TREND_VOLUME_ACCUM");
  const hasChartPatterns = activeChartIndicators.has("CHART_PATTERNS") && isChartIndicatorNativeTimeframe("CHART_PATTERNS");
  const hasChannelsPatterns = activeChartIndicators.has("CHANNELS_PATTERNS") && isChartIndicatorNativeTimeframe("CHANNELS_PATTERNS");

  const mtfIndicatorBadges = Array.from(activeChartIndicators)
    .filter((value) => !isChartIndicatorNativeTimeframe(value) && !["SMC_WELO_TRADES", "INSTITUTIONAL_SMC_ENGINE"].includes(value))
    .map((value) => {
      const tf = getChartIndicatorTimeframe(value);
      const source = getChartIndicatorAnalysisCandles(value, candles);
      const votes = MARKET_SCANNER_INDICATORS.includes(value)
        ? scanMainSignalIndicator(value, source, getTimeframeLabel(tf), 1, tf)
        : [];
      const best = votes
        .sort((a, b) => Math.abs(b.weight || 0) - Math.abs(a.weight || 0))[0] || null;
      return {
        value,
        label: getChartIndicatorLabel(value),
        timeframe: getTimeframeLabel(tf),
        direction: best?.direction || null,
        reason: best?.reason || (source === candles ? "loading selected TF" : "analysis ready"),
        loading: source === candles && tf < getChartTimeframeSeconds() && !replayEngine.isReplayMode(),
      };
    });

  if (mtfIndicatorBadges.length) {
    ctx.save();
    ctx.font = "bold 10px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    const badgeW = Math.min(250, Math.max(150, plotW * 0.32));
    const badgeH = 26;
    const startX = Math.max(leftPad + 4, width - rightPad - badgeW - 6);
    let y = topPad + 4;
    mtfIndicatorBadges.slice(0, 5).forEach((badge) => {
      const buy = badge.direction === "CALL";
      const sell = badge.direction === "PUT";
      const color = buy ? "#10b981" : sell ? "#ef4444" : "#94a3b8";
      ctx.fillStyle = "rgba(12, 17, 25, 0.86)";
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(startX, y, badgeW, badgeH, 7);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = color;
      const directionText = badge.loading ? "loading" : buy ? "BUY" : sell ? "SELL" : "watch";
      ctx.fillText(`${badge.timeframe} ${directionText}`, startX + 8, y + 6);
      ctx.fillStyle = "#cbd5e1";
      ctx.font = "9px Segoe UI, sans-serif";
      const shortLabel = badge.label.length > 24 ? `${badge.label.slice(0, 23)}...` : badge.label;
      ctx.fillText(shortLabel, startX + 82, y + 7);
      ctx.font = "bold 10px Segoe UI, sans-serif";
      y += badgeH + 5;
    });
    ctx.restore();
  }

  if (hasICTKillzones) {
    const killzones = buildICTKillzones(points, start);
    killzones.forEach((segment) => {
      const localStart = segment.startIndex - start;
      const localEnd = segment.endIndex - start;
      const x = leftPad + (localStart * slotW);
      const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
      ctx.save();
      ctx.fillStyle = segment.color;
      ctx.fillRect(x, topPad, w, plotH);
      ctx.restore();
    });
  }

  if (hasLiquiditySweepOB) {
    const lq = buildLiquiditySweepOrderBlockSystem(candles, {
      pivotLen: 3,
      sweepLookahead: 10,
      pullbackLookahead: 12,
    });

    lq.pools.forEach((pool) => {
      const x1 = leftPad + ((Math.max(start, pool.startIndex) - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((Math.min(end - 1, (pool.endIndex ?? pool.startIndex) + 10) - start) * slotW) + (slotW / 2);
      const level = pool.a && pool.b
        ? pool.b.price
        : pool.level;
      const y = toY(level);
      if (!Number.isFinite(y)) return;
      ctx.save();
      ctx.strokeStyle = pool.side === "high" ? "rgba(242, 54, 69, 0.50)" : "rgba(8, 153, 129, 0.50)";
      ctx.lineWidth = 1;
      ctx.setLineDash(pool.kind.startsWith("trendline") ? [5, 3] : [3, 3]);
      if (pool.a && pool.b) {
        const xa = leftPad + ((Math.max(start, pool.a.index) - start) * slotW) + (slotW / 2);
        const xb = leftPad + ((Math.min(end - 1, pool.b.index) - start) * slotW) + (slotW / 2);
        ctx.beginPath();
        ctx.moveTo(xa, toY(pool.a.price));
        ctx.lineTo(xb, toY(pool.b.price));
        ctx.stroke();
      } else {
        ctx.beginPath();
        ctx.moveTo(x1, y);
        ctx.lineTo(x2, y);
        ctx.stroke();
      }
      ctx.setLineDash([]);
      ctx.restore();
    });

    lq.setups.forEach((setup) => {
      const isBuy = setup.direction === "BUY";
      const sweepCandle = candles[setup.sweepIndex];
      const sweepX = leftPad + ((setup.sweepIndex - start) * slotW) + (slotW / 2);
      const sweepY = isBuy ? toY(sweepCandle.low) + 8 : toY(sweepCandle.high) - 8;
      const breakX1 = leftPad + ((setup.structureEvent.pivotIndex - start) * slotW) + (slotW / 2);
      const breakX2 = leftPad + ((setup.structureEvent.breakIndex - start) * slotW) + (slotW / 2);
      const breakY = toY(setup.structureEvent.pivotPrice);
      const obStart = Math.max(start, setup.orderBlock.index);
      const obEnd = Math.min(end - 1, setup.pullbackIndex);
      const obX = leftPad + ((obStart - start) * slotW);
      const obW = Math.max(slotW, ((obEnd - obStart) + 1) * slotW);
      const obTopY = toY(setup.orderBlock.top);
      const obBottomY = toY(setup.orderBlock.bottom);
      const entryX = leftPad + ((setup.entryIndex - start) * slotW) + (slotW / 2);
      const entryY = isBuy ? toY(candles[setup.entryIndex].low) + 12 : toY(candles[setup.entryIndex].high) - 12;
      const color = isBuy ? "#18d89f" : "#ff6a4d";

      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = isBuy ? "rgba(24, 216, 159, 0.14)" : "rgba(255, 106, 77, 0.14)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(breakX1, breakY);
      ctx.lineTo(breakX2, breakY);
      ctx.stroke();
      ctx.fillRect(obX, obTopY, obW, Math.max(2, obBottomY - obTopY));
      ctx.strokeRect(obX, obTopY, obW, Math.max(2, obBottomY - obTopY));

      ctx.beginPath();
      ctx.arc(sweepX, sweepY, 4, 0, Math.PI * 2);
      ctx.stroke();
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillStyle = color;
      ctx.fillText(setup.liquidityKind, sweepX, isBuy ? sweepY + 8 : sweepY - 8);
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(entryX, entryY - 7);
        ctx.lineTo(entryX - 5, entryY + 3);
        ctx.lineTo(entryX + 5, entryY + 3);
      } else {
        ctx.moveTo(entryX, entryY + 7);
        ctx.lineTo(entryX - 5, entryY - 3);
        ctx.lineTo(entryX + 5, entryY - 3);
      }
      ctx.closePath();
      ctx.fill();
      ctx.fillText(isBuy ? "LQ BUY" : "LQ SELL", entryX, isBuy ? entryY + 6 : entryY - 6);
      ctx.restore();
    });
  }

  if (hasInstitutionalForexEngine) {
    const engine = buildInstitutionalForexSignalEngine(candles, {
      baseSeconds: getChartTimeframeSeconds(),
      expirySeconds: INSTITUTIONAL_EXPIRY_SECONDS,
    });
    const levels = engine.poi ? [engine.poi] : [];
    levels.forEach((level) => {
      const y = toY(level.price);
      if (!Number.isFinite(y)) return;
      const isResistance = level.price >= (candles[candles.length - 1]?.close ?? level.price);
      ctx.save();
      ctx.strokeStyle = isResistance ? "rgba(255, 138, 76, 0.85)" : "rgba(125, 255, 136, 0.85)";
      ctx.fillStyle = isResistance ? "rgba(255, 138, 76, 0.12)" : "rgba(125, 255, 136, 0.12)";
      ctx.lineWidth = 1.5;
      ctx.setLineDash([7, 4]);
      ctx.fillRect(leftPad, y - 5, width - leftPad - rightPad, 10);
      ctx.beginPath();
      ctx.moveTo(leftPad, y);
      ctx.lineTo(width - rightPad, y);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.font = "bold 9px Segoe UI, sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "bottom";
      ctx.fillStyle = isResistance ? "#ffb07c" : "#7dff88";
      ctx.fillText(`15m IFE POI ${level.touches || level.strength || 1}t`, width - rightPad - 4, y - 6);
      ctx.restore();
    });

    if (engine.entryPrice && engine.rawDirection) {
      const x = leftPad + ((points.length - 1) * slotW) + (slotW / 2);
      const y = toY(engine.entryPrice);
      const isBuy = engine.rawDirection === "CALL";
      const color = engine.direction ? (isBuy ? "#7dff88" : "#ff8a4c") : "rgba(190, 198, 210, 0.75)";
      ctx.save();
      ctx.fillStyle = color;
      ctx.strokeStyle = "#0f1218";
      ctx.lineWidth = 2;
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, y - 14);
        ctx.lineTo(x - 8, y + 2);
        ctx.lineTo(x + 8, y + 2);
      } else {
        ctx.moveTo(x, y + 14);
        ctx.lineTo(x - 8, y - 2);
        ctx.lineTo(x + 8, y - 2);
      }
      ctx.closePath();
      ctx.stroke();
      ctx.fill();
      ctx.font = "bold 9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(engine.direction ? `${isBuy ? "BUY" : "SELL"} ${engine.confidence}%` : "WAIT", x, isBuy ? y + 6 : y - 6);
      ctx.restore();
    }

    const statLines = [
      `IFE ${engine.confidence}% ${engine.sessionStatus || "--"}`,
      engine.htfTrend || "--",
      engine.confirmationStatus === "--" ? engine.liquidityStatus : engine.confirmationStatus,
    ];
    const boxW = 150;
    const boxH = 42;
    const boxX = leftPad + 4;
    const boxY = topPad + 4;
    ctx.save();
    ctx.fillStyle = "rgba(12, 16, 22, 0.80)";
    ctx.strokeStyle = "rgba(125, 255, 136, 0.38)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, boxW, boxH, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#d9e2ee";
    ctx.font = "bold 9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    statLines.forEach((line, index) => {
      ctx.fillText(String(line || "--").slice(0, 28), boxX + 7, boxY + 6 + (index * 12));
    });
    ctx.restore();
  }

  if (hasLDMSS) {
    const ldmss = buildLiquidityDrivenMarketStructureSystem(candles, {
      pivotLen: 3,
      sweepLookahead: 10,
      pullbackLookahead: 12,
    });

    ldmss.pools.forEach((pool) => {
      const x1 = leftPad + ((Math.max(start, pool.startIndex) - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((Math.min(end - 1, (pool.endIndex ?? pool.startIndex) + 14) - start) * slotW) + (slotW / 2);
      const level = pool.a && pool.b ? pool.b.price : pool.level;
      const y = toY(level);
      if (!Number.isFinite(y)) return;
      ctx.save();
      ctx.strokeStyle = pool.side === "high"
        ? (pool.kind.startsWith("prevSession") ? "rgba(242, 201, 76, 0.68)" : "rgba(242, 54, 69, 0.52)")
        : (pool.kind.startsWith("prevSession") ? "rgba(242, 201, 76, 0.68)" : "rgba(8, 153, 129, 0.52)");
      ctx.lineWidth = pool.kind.startsWith("prevSession") ? 1.2 : 1;
      ctx.setLineDash(pool.kind.startsWith("trendline") ? [6, 3] : pool.kind.startsWith("prevSession") ? [2, 2] : [3, 3]);
      if (pool.a && pool.b) {
        const xa = leftPad + ((Math.max(start, pool.a.index) - start) * slotW) + (slotW / 2);
        const xb = leftPad + ((Math.min(end - 1, pool.b.index) - start) * slotW) + (slotW / 2);
        ctx.beginPath();
        ctx.moveTo(xa, toY(pool.a.price));
        ctx.lineTo(xb, toY(pool.b.price));
      } else {
        ctx.beginPath();
        ctx.moveTo(x1, y);
        ctx.lineTo(x2, y);
      }
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    });

    ldmss.setups.slice(-3).forEach((setup) => {
      const isBuy = setup.direction === "BUY";
      const sweepCandle = candles[setup.sweepIndex];
      const sweepX = leftPad + ((setup.sweepIndex - start) * slotW) + (slotW / 2);
      const sweepY = isBuy ? toY(sweepCandle.low) + 8 : toY(sweepCandle.high) - 8;
      const breakX1 = leftPad + ((setup.structureEvent.pivotIndex - start) * slotW) + (slotW / 2);
      const breakX2 = leftPad + ((setup.structureEvent.breakIndex - start) * slotW) + (slotW / 2);
      const breakY = toY(setup.structureEvent.pivotPrice);
      const obStart = Math.max(start, setup.orderBlock.index);
      const obEnd = Math.min(end - 1, setup.pullbackIndex);
      const obX = leftPad + ((obStart - start) * slotW);
      const obW = Math.max(slotW, ((obEnd - obStart) + 1) * slotW);
      const obTopY = toY(setup.orderBlock.top);
      const obBottomY = toY(setup.orderBlock.bottom);
      const entryX = leftPad + ((setup.entryIndex - start) * slotW) + (slotW / 2);
      const entryY = toY(setup.entryPrice);
      const slY = toY(setup.stopLoss);
      const tpY = toY(setup.takeProfit);
      const color = isBuy ? "#18d89f" : "#ff6a4d";

      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = isBuy ? "rgba(24, 216, 159, 0.12)" : "rgba(255, 106, 77, 0.12)";
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(breakX1, breakY);
      ctx.lineTo(breakX2, breakY);
      ctx.stroke();
      ctx.fillRect(obX, obTopY, obW, Math.max(2, obBottomY - obTopY));
      ctx.strokeRect(obX, obTopY, obW, Math.max(2, obBottomY - obTopY));

      ctx.setLineDash([4, 3]);
      ctx.strokeStyle = "rgba(255, 106, 77, 0.85)";
      ctx.beginPath();
      ctx.moveTo(leftPad, slY);
      ctx.lineTo(width - rightPad, slY);
      ctx.stroke();
      ctx.strokeStyle = "rgba(24, 216, 159, 0.85)";
      ctx.beginPath();
      ctx.moveTo(leftPad, tpY);
      ctx.lineTo(width - rightPad, tpY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.beginPath();
      ctx.arc(sweepX, sweepY, 4, 0, Math.PI * 2);
      ctx.strokeStyle = color;
      ctx.stroke();
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillStyle = color;
      ctx.fillText(setup.liquidityKind, sweepX, isBuy ? sweepY + 8 : sweepY - 8);
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(entryX, entryY - 8);
        ctx.lineTo(entryX - 5, entryY + 2);
        ctx.lineTo(entryX + 5, entryY + 2);
      } else {
        ctx.moveTo(entryX, entryY + 8);
        ctx.lineTo(entryX - 5, entryY - 2);
        ctx.lineTo(entryX + 5, entryY - 2);
      }
      ctx.closePath();
      ctx.fill();
      ctx.fillText(isBuy ? "LDMSS BUY" : "LDMSS SELL", entryX, isBuy ? entryY + 6 : entryY - 6);
      ctx.restore();
    });
  }

  if (hasAlgoBehaviorEngine) {
    const abe = buildAlgoBehaviorEngine(candles, {});
    ctx.save();

    abe.microLiquidity.forEach((zone) => {
      const localStart = Math.max(0, (zone.startIndex ?? 0) - start);
      const localEnd = Math.min(points.length - 1, (zone.endIndex ?? zone.startIndex ?? 0) - start);
      if (localEnd < 0 || localStart > points.length - 1) return;
      const x1 = leftPad + (localStart * slotW);
      const x2 = leftPad + ((localEnd + 1) * slotW);
      const y = toY(zone.level);
      if (!Number.isFinite(y)) return;
      ctx.strokeStyle = zone.side === "high" ? "rgba(242, 54, 69, 0.75)" : "rgba(8, 153, 129, 0.75)";
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
    });

    if (abe.activeSetup) {
      const localIndex = Math.max(0, Math.min(points.length - 1, abe.activeSetup.entryIndex - start));
      const x = leftPad + ((localIndex + 0.5) * slotW);
      const fallbackPrice = points[localIndex]?.close ?? points[points.length - 1]?.close ?? candles[candles.length - 1]?.close;
      const y = toY(abe.activeSetup.focusPrice ?? fallbackPrice);
      if (Number.isFinite(x) && Number.isFinite(y)) {
        ctx.fillStyle = abe.activeSetup.direction === "BUY" ? "#0db787" : "#f23645";
        ctx.strokeStyle = "#ffffff";
        ctx.lineWidth = 1.2;
        ctx.beginPath();
        ctx.arc(x, y, 5, 0, Math.PI * 2);
        ctx.fill();
        ctx.stroke();
        ctx.fillStyle = ctx.strokeStyle = abe.activeSetup.direction === "BUY" ? "#0db787" : "#f23645";
        ctx.font = "10px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "bottom";
        ctx.fillText(`ABE ${abe.activeSetup.direction} ${abe.score}`, x + 8, y - 6);
      }
    }

    const drawAbeRay = (price, color, label, dashed = false) => {
      if (!Number.isFinite(price)) return;
      const y = toY(price);
      if (!Number.isFinite(y)) return;
      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 1.2;
      ctx.setLineDash(dashed ? [5, 4] : []);
      ctx.beginPath();
      ctx.moveTo(leftPad, y);
      ctx.lineTo(width - rightPad - 78, y);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.font = "10px Segoe UI, sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "bottom";
      ctx.fillText(label, leftPad + 6, y - 4);
      ctx.restore();
    };

    if (abe.sweep?.referenceLevel != null) {
      const sweepLabel = abe.sweep.sweepType === "BUY" ? "SSL" : "BSL";
      const sweepColor = abe.sweep.sweepType === "BUY" ? "#18d89f" : "#f23645";
      drawAbeRay(abe.sweep.referenceLevel, sweepColor, `${sweepLabel} ${formatPrice(abe.sweep.referenceLevel, currentPip)}`);
    }

    if (abe.entryPrice != null) {
      const entryDirection = abe.activeSetup?.direction ?? abe.trend;
      const entryIsBuy = entryDirection === "BUY" || entryDirection === "UP";
      const entryColor = entryIsBuy ? "#5be660" : "#ffb84d";
      drawAbeRay(abe.entryPrice, entryColor, `ENTRY ${formatPrice(abe.entryPrice, currentPip)}`, true);
    }

    ctx.restore();
  }

  if (hasPriceActionToolkit) {
    const pa = buildPriceActionToolkit(candles, {});

    pa.sr.supports.forEach((level) => {
      const x1 = leftPad + ((Math.max(start, level.startIndex) - start) * slotW);
      const x2 = leftPad + ((Math.min(end - 1, level.drawEndIndex ?? level.endIndex) - start + 1) * slotW);
      const topY = toY(level.top);
      const bottomY = toY(level.bottom);
      ctx.save();
      ctx.fillStyle = "rgba(8, 153, 129, 0.10)";
      ctx.strokeStyle = "rgba(8, 153, 129, 0.45)";
      ctx.fillRect(x1, topY, Math.max(slotW, x2 - x1), Math.max(2, bottomY - topY));
      ctx.strokeRect(x1, topY, Math.max(slotW, x2 - x1), Math.max(2, bottomY - topY));
      ctx.restore();
    });

    pa.sr.resistances.forEach((level) => {
      const x1 = leftPad + ((Math.max(start, level.startIndex) - start) * slotW);
      const x2 = leftPad + ((Math.min(end - 1, level.drawEndIndex ?? level.endIndex) - start + 1) * slotW);
      const topY = toY(level.top);
      const bottomY = toY(level.bottom);
      ctx.save();
      ctx.fillStyle = "rgba(242, 54, 69, 0.10)";
      ctx.strokeStyle = "rgba(242, 54, 69, 0.45)";
      ctx.fillRect(x1, topY, Math.max(slotW, x2 - x1), Math.max(2, bottomY - topY));
      ctx.strokeRect(x1, topY, Math.max(slotW, x2 - x1), Math.max(2, bottomY - topY));
      ctx.restore();
    });

    pa.trendlines.upperChannels.forEach((channel) => {
      const startIndex = channel.startIndex;
      const endIndex = channel.liveEndIndex ?? channel.endIndex;
      if (!Number.isInteger(startIndex) || !Number.isInteger(endIndex)) return;
      if (endIndex < start || startIndex > end - 1) return;
      const x1 = leftPad + ((Math.max(start, startIndex) - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((Math.min(end - 1, endIndex) - start) * slotW) + (slotW / 2);
      const upperA = channel.top1;
      const upperB = channel.liveTop ?? channel.top2;
      const lowerA = channel.bottom1;
      const lowerB = channel.liveBottom ?? channel.bottom2;
      ctx.save();
      ctx.strokeStyle = "rgba(242, 54, 69, 0.70)";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(x1, toY(upperA));
      ctx.lineTo(x2, toY(upperB));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x1, toY(lowerA));
      ctx.lineTo(x2, toY(lowerB));
      ctx.stroke();
      ctx.restore();
    });

    pa.trendlines.lowerChannels.forEach((channel) => {
      const startIndex = channel.startIndex;
      const endIndex = channel.liveEndIndex ?? channel.endIndex;
      if (!Number.isInteger(startIndex) || !Number.isInteger(endIndex)) return;
      if (endIndex < start || startIndex > end - 1) return;
      const x1 = leftPad + ((Math.max(start, startIndex) - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((Math.min(end - 1, endIndex) - start) * slotW) + (slotW / 2);
      const upperA = channel.top1;
      const upperB = channel.liveTop ?? channel.top2;
      const lowerA = channel.bottom1;
      const lowerB = channel.liveBottom ?? channel.bottom2;
      ctx.save();
      ctx.strokeStyle = "rgba(8, 153, 129, 0.70)";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(x1, toY(upperA));
      ctx.lineTo(x2, toY(upperB));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(x1, toY(lowerA));
      ctx.lineTo(x2, toY(lowerB));
      ctx.stroke();
      ctx.restore();
    });

    if (pa.fib?.levels?.length) {
      pa.fib.levels.forEach((level) => {
        const y = toY(level.price);
        if (!Number.isFinite(y)) return;
        ctx.save();
        ctx.strokeStyle = level.color;
        ctx.setLineDash([4, 4]);
        ctx.beginPath();
        ctx.moveTo(leftPad, y);
        ctx.lineTo(width - rightPad, y);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.font = "8px Segoe UI, sans-serif";
        ctx.textAlign = "right";
        ctx.textBaseline = "bottom";
        ctx.fillStyle = level.color;
        ctx.fillText(level.label, width - rightPad - 2, y - 2);
        ctx.restore();
      });
    }

    const lastStructureEvent = pa.structure?.events?.[pa.structure.events.length - 1] || null;
    if (lastStructureEvent) {
      const x1 = leftPad + ((lastStructureEvent.pivotIndex - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((lastStructureEvent.breakIndex - start) * slotW) + (slotW / 2);
      const y = toY(lastStructureEvent.pivotPrice);
      ctx.save();
      ctx.strokeStyle = lastStructureEvent.direction === "UP" ? "#18d89f" : "#ff6a4d";
      ctx.lineWidth = 1.1;
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      ctx.fillStyle = ctx.strokeStyle;
      ctx.fillText(lastStructureEvent.type, x2, y - 4);
      ctx.restore();
    }

    pa.actionableSignals.slice(-6).forEach((signal) => {
      const isBuy = signal.direction === "BUY";
      const candle = candles[signal.entryIndex];
      if (!candle) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const y = isBuy ? toY(candle.low) + 10 : toY(candle.high) - 10;
      ctx.save();
      ctx.fillStyle = isBuy ? "#18d89f" : "#ff6a4d";
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, y - 7);
        ctx.lineTo(x - 5, y + 3);
        ctx.lineTo(x + 5, y + 3);
      } else {
        ctx.moveTo(x, y + 7);
        ctx.lineTo(x - 5, y - 3);
        ctx.lineTo(x + 5, y - 3);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });
  }

  points.forEach((c, i) => {
    const x = leftPad + i * slotW + candleGap / 2;
    const openY = toY(c.open);
    const closeY = toY(c.close);
    const highY = toY(c.high);
    const lowY = toY(c.low);
    const up = c.close >= c.open;
    const bodySize = Math.abs(c.close - c.open);
    const isLarge = barrierOffset > 0 && bodySize >= barrierOffset;
    ctx.strokeStyle = "#3a465a";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(x + candleW / 2, highY);
    ctx.lineTo(x + candleW / 2, lowY);
    ctx.stroke();

    if (isLarge) {
      ctx.fillStyle = up ? "#2d8cff" : "#f2f2e9";
    } else {
      ctx.fillStyle = up ? "#0db787" : "#e15b64";
    }
    const bodyY = Math.min(openY, closeY);
    const bodyH = Math.max(2, Math.abs(closeY - openY));
    ctx.fillRect(x, bodyY, candleW, bodyH);
  });

  if (hasInstitutionalExecutionModel) {
    const iem = buildInstitutionalExecutionModel(candles, {});

    iem.poiLevels.slice(0, 6).forEach((level) => {
      const y = toY(level.price);
      if (!Number.isFinite(y)) return;
      ctx.save();
      ctx.strokeStyle = "rgba(242, 201, 76, 0.54)";
      ctx.fillStyle = "rgba(242, 201, 76, 0.10)";
      ctx.lineWidth = 1;
      ctx.setLineDash([4, 3]);
      ctx.beginPath();
      ctx.moveTo(leftPad, y);
      ctx.lineTo(width - rightPad, y);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "bottom";
      ctx.fillStyle = "#f2c94c";
      const sourceLabel = getMtfSourceLabel(level.source);
      ctx.fillText(`${sourceLabel} POI ${level.strength}`, width - rightPad - 4, y - 2);
      ctx.restore();
    });

    iem.signals.forEach((signal) => {
      if (signal.entryIndex < start || signal.entryIndex >= end) return;
      const candle = candles[signal.entryIndex];
      if (!candle) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isBuy = signal.direction === "BUY";
      const anchorY = isBuy ? toY(candle.low) + 16 : toY(candle.high) - 16;
      const color = isBuy ? "#18d89f" : "#ff6a4d";
      const resultText = signal.result === "WIN" ? "W" : signal.result === "LOSS" ? "L" : "";

      ctx.save();
      ctx.fillStyle = color;
      ctx.strokeStyle = "#0f1218";
      ctx.lineWidth = 2;
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, anchorY - 10);
        ctx.lineTo(x - 7, anchorY + 4);
        ctx.lineTo(x + 7, anchorY + 4);
      } else {
        ctx.moveTo(x, anchorY + 10);
        ctx.lineTo(x - 7, anchorY - 4);
        ctx.lineTo(x + 7, anchorY - 4);
      }
      ctx.closePath();
      ctx.stroke();
      ctx.fill();
      ctx.font = "bold 8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(isBuy ? "BUY" : "SELL", x, isBuy ? anchorY + 7 : anchorY - 7);
      if (resultText) {
        ctx.fillStyle = signal.result === "WIN" ? "#7dff88" : "#ff8a8a";
        ctx.fillText(resultText, x + 12, isBuy ? anchorY + 7 : anchorY - 7);
      }
      ctx.restore();
    });

    const statLines = [
      `IEM ${iem.stats.winRate == null ? "--" : `${iem.stats.winRate}%`} ${baseMinutes}m`,
      `${iem.stats.wins}W/${iem.stats.losses}L`,
      `Min ${iem.stats.minConfidence}% ${getMtfSourceLabel(iem.mainLabel)} ${iem.trendMain}`,
    ];
    const boxW = 112;
    const boxH = 42;
    const boxX = width - rightPad - boxW - 8;
    const boxY = topPad + 4;
    ctx.save();
    ctx.fillStyle = "rgba(12, 16, 22, 0.78)";
    ctx.strokeStyle = "rgba(242, 201, 76, 0.42)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, boxW, boxH, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#f2c94c";
    ctx.font = "bold 9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    statLines.forEach((line, index) => {
      ctx.fillText(line, boxX + 7, boxY + 6 + (index * 12));
    });
    ctx.restore();
  }

  if (hasInstitutionalLevelBehavior) {
    const ilb = buildInstitutionalLevelBehaviorModel(candles, {});

    ilb.poiLevels.slice(0, 6).forEach((level) => {
      const y = toY(level.price);
      if (!Number.isFinite(y)) return;
      ctx.save();
      ctx.strokeStyle = "rgba(80, 210, 255, 0.52)";
      ctx.lineWidth = 1;
      ctx.setLineDash([6, 3]);
      ctx.beginPath();
      ctx.moveTo(leftPad, y);
      ctx.lineTo(width - rightPad, y);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "right";
      ctx.textBaseline = "top";
      ctx.fillStyle = "#50d2ff";
      const sourceLabel = getMtfSourceLabel(level.source);
      ctx.fillText(`${sourceLabel} LB ${level.strength}`, width - rightPad - 4, y + 2);
      ctx.restore();
    });

    for (const signal of ilb.signals) {
      if (signal.entryIndex < start) continue;
      if (signal.entryIndex >= end) break;
      const candle = candles[signal.entryIndex];
      if (!candle) continue;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isBuy = signal.direction === "BUY";
      const isBreakout = signal.behavior === "MULTI_TOUCH_BREAKOUT";
      const anchorY = isBuy ? toY(candle.low) + 18 : toY(candle.high) - 18;
      const color = isBreakout ? "#50d2ff" : isBuy ? "#7dff88" : "#ff8a4c";
      const tag = isBreakout ? "BRK" : signal.behavior === "FAKE_BREAK_REVERSAL" ? "FK" : `T${Math.min(9, signal.touches)}`;
      const resultText = signal.result === "WIN" ? "W" : signal.result === "LOSS" ? "L" : "";

      ctx.save();
      ctx.fillStyle = color;
      ctx.strokeStyle = "#0f1218";
      ctx.lineWidth = 2;
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, anchorY - 11);
        ctx.lineTo(x - 8, anchorY + 5);
        ctx.lineTo(x + 8, anchorY + 5);
      } else {
        ctx.moveTo(x, anchorY + 11);
        ctx.lineTo(x - 8, anchorY - 5);
        ctx.lineTo(x + 8, anchorY - 5);
      }
      ctx.closePath();
      ctx.stroke();
      ctx.fill();
      ctx.font = "bold 8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(`${isBuy ? "BUY" : "SELL"} ${tag}`, x, isBuy ? anchorY + 8 : anchorY - 8);
      if (resultText) {
        ctx.fillStyle = signal.result === "WIN" ? "#7dff88" : "#ff8a8a";
        ctx.fillText(resultText, x + 16, isBuy ? anchorY + 8 : anchorY - 8);
      }
      ctx.restore();
    }

    const statLines = [
      `ILB ${ilb.stats.winRate == null ? "--" : `${ilb.stats.winRate}%`} ${baseMinutes}m`,
      `${ilb.stats.wins}W/${ilb.stats.losses}L`,
      `Min ${ilb.stats.minConfidence}% touch logic`,
    ];
    const boxW = 126;
    const boxH = 42;
    const boxX = leftPad + 4;
    const boxY = hasInstitutionalExecutionModel ? topPad + 52 : topPad + 4;
    ctx.save();
    ctx.fillStyle = "rgba(12, 16, 22, 0.78)";
    ctx.strokeStyle = "rgba(80, 210, 255, 0.42)";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(boxX, boxY, boxW, boxH, 6);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = "#50d2ff";
    ctx.font = "bold 9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    statLines.forEach((line, index) => {
      ctx.fillText(line, boxX + 7, boxY + 6 + (index * 12));
    });
    ctx.restore();
  }

  if (activeChartIndicators.has("EMA") && isChartIndicatorNativeTimeframe("EMA")) {
    const emaValues = calculateChartEMA(points, 9);
    ctx.save();
    ctx.strokeStyle = "#f2c94c";
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    let started = false;
    emaValues.forEach((value, index) => {
      if (!Number.isFinite(value)) return;
      const x = leftPad + index * slotW + (slotW / 2);
      const y = toY(value);
      if (!started) {
        ctx.moveTo(x, y);
        started = true;
      } else {
        ctx.lineTo(x, y);
      }
    });
    if (started) ctx.stroke();
    ctx.restore();
  }

  if (hasAnyICT) {
    const structure = buildICTStructureAnalysis(candles);
    const fvgs = buildICTFVGs(candles);
    const orderBlocks = buildICTOrderBlocks(candles, structure.events);
    const fib = buildICTFibLevels(structure.events);

    if (hasICTFVG) {
      [...fvgs.bullish, ...fvgs.bearish].forEach((zone) => {
        const localStart = Math.max(0, zone.startIndex - start);
        const localEnd = Math.min(points.length - 1, zone.drawEndIndex - start);
        if (localEnd < 0 || localStart > points.length - 1) return;
        const x = leftPad + (localStart * slotW);
        const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
        ctx.save();
        ctx.fillStyle = zone.direction === "UP" ? "rgba(13, 183, 135, 0.12)" : "rgba(225, 91, 100, 0.12)";
        ctx.strokeStyle = zone.direction === "UP" ? "rgba(13, 183, 135, 0.35)" : "rgba(225, 91, 100, 0.35)";
        ctx.lineWidth = 1;
        const topY = toY(zone.top);
        const bottomY = toY(zone.bottom);
        ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
        ctx.strokeRect(x, topY, w, Math.max(2, bottomY - topY));
        const ceY = toY((zone.top + zone.bottom) / 2);
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(x, ceY);
        ctx.lineTo(x + w, ceY);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.restore();
      });
    }

    if (hasICTBPR) {
      fvgs.bprs.forEach((zone) => {
        const localStart = Math.max(0, zone.startIndex - start);
        const localEnd = Math.min(points.length - 1, zone.endIndex - start);
        if (localEnd < 0 || localStart > points.length - 1) return;
        const x = leftPad + (localStart * slotW);
        const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
        ctx.save();
        ctx.fillStyle = "rgba(155, 89, 182, 0.12)";
        ctx.strokeStyle = "rgba(155, 89, 182, 0.35)";
        const topY = toY(zone.top);
        const bottomY = toY(zone.bottom);
        ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
        ctx.strokeRect(x, topY, w, Math.max(2, bottomY - topY));
        ctx.fillStyle = "#c39bd3";
        ctx.font = "9px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "top";
        ctx.fillText("BPR", x + 3, topY + 2);
        ctx.restore();
      });
    }

    if (hasICTOB) {
      [...orderBlocks.bullish, ...orderBlocks.bearish].forEach((zone) => {
        const localIndex = zone.index - start;
        const localEnd = zone.drawEndIndex - start;
        if (localEnd < 0 || localIndex > points.length - 1) return;
        const x = leftPad + (Math.max(0, localIndex) * slotW);
        const w = Math.max(slotW, ((Math.min(points.length - 1, localEnd) - Math.max(0, localIndex)) + 1) * slotW);
        ctx.save();
        ctx.fillStyle = zone.direction === "UP" ? "rgba(45, 140, 255, 0.10)" : "rgba(242, 242, 233, 0.10)";
        ctx.strokeStyle = zone.direction === "UP" ? "rgba(45, 140, 255, 0.30)" : "rgba(242, 242, 233, 0.25)";
        const topY = toY(zone.top);
        const bottomY = toY(zone.bottom);
        ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
        ctx.strokeRect(x, topY, w, Math.max(2, bottomY - topY));
        const midY = toY((zone.top + zone.bottom) / 2);
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(x, midY);
        ctx.lineTo(x + w, midY);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = zone.direction === "UP" ? "#5ca8ff" : "#d6d6ce";
        ctx.font = "9px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "top";
        ctx.fillText(zone.direction === "UP" ? "Bull OB" : "Bear OB", x + 3, topY + 2);
        ctx.restore();
      });
    }

    if (hasICTStructure) {
      structure.events.slice(-8).forEach((event) => {
        if (event.breakIndex < start || event.pivotIndex > end - 1) return;
        const x1 = leftPad + ((event.pivotIndex - start) * slotW) + (slotW / 2);
        const x2 = leftPad + ((Math.min(end - 1, event.breakIndex) - start) * slotW) + (slotW / 2);
        const y = toY(event.pivotPrice);
        const color = event.direction === "UP" ? "#0db787" : "#e15b64";
        ctx.save();
        ctx.strokeStyle = color;
        ctx.lineWidth = 1.2;
        if (event.type === "MSS") ctx.setLineDash([5, 4]);
        ctx.beginPath();
        ctx.moveTo(x1, y);
        ctx.lineTo(x2, y);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = color;
        ctx.font = "9px Segoe UI, sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = "bottom";
        ctx.fillText(event.type, (x1 + x2) / 2, y - 3);
        ctx.restore();
      });
    }

    if (hasICTFib && fib?.levels?.length) {
      const fibStartX = leftPad + (Math.max(0, fib.startIndex - start) * slotW);
      const fibEndX = leftPad + ((Math.min(end - 1, fib.endIndex ?? (candles.length - 1)) - start) * slotW) + slotW;
      fib.levels.forEach((level) => {
        const y = toY(level.price);
        if (!Number.isFinite(y)) return;
        ctx.save();
        ctx.strokeStyle = level.color;
        ctx.lineWidth = 1;
        ctx.setLineDash([3, 3]);
        ctx.beginPath();
        ctx.moveTo(fibStartX, y);
        ctx.lineTo(Math.max(fibStartX + slotW, fibEndX), y);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = level.color;
        ctx.font = "9px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "middle";
        ctx.fillText(level.label, Math.max(fibStartX + 4, fibEndX + 4), y);
        ctx.restore();
      });
    }

    if (hasICTLiquidity) {
      const visibleSweepEvents = [];
      for (let globalIndex = start; globalIndex < end; globalIndex += 1) {
        const event = detectLiquiditySweepEvent(candles, globalIndex);
        if (event) visibleSweepEvents.push(event);
      }

      visibleSweepEvents.slice(-6).forEach((event) => {
        const visibleIndex = event.candleIndex - start;
        if (visibleIndex < 0 || visibleIndex >= points.length) return;
        const x = leftPad + visibleIndex * slotW + candleGap / 2;
        const centerX = x + candleW / 2;
        const refY = toY(event.referenceLevel);
        const extremeY = toY(event.extremeLevel);
        const isBuySweep = event.sweepType === "BUY";
        const sweepColor = isBuySweep ? "#2d8cff" : "#e15b64";
        const fillColor = isBuySweep ? "rgba(45, 140, 255, 0.18)" : "rgba(225, 91, 100, 0.18)";
        const lineHalf = Math.max(10, slotW * 0.8);

        ctx.save();
        ctx.strokeStyle = sweepColor;
        ctx.fillStyle = fillColor;
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 3]);
        ctx.beginPath();
        ctx.moveTo(Math.max(leftPad, centerX - lineHalf), refY);
        ctx.lineTo(Math.min(width - rightPad, centerX + lineHalf), refY);
        ctx.stroke();
        ctx.setLineDash([]);

        const topY = Math.min(refY, extremeY);
        const zoneH = Math.max(3, Math.abs(refY - extremeY));
        ctx.fillRect(centerX - Math.max(3, candleW * 0.35), topY, Math.max(6, candleW * 0.7), zoneH);

        ctx.fillStyle = sweepColor;
        ctx.beginPath();
        if (isBuySweep) {
          ctx.moveTo(centerX, extremeY + 1);
          ctx.lineTo(centerX - 4, extremeY + 7);
          ctx.lineTo(centerX + 4, extremeY + 7);
        } else {
          ctx.moveTo(centerX, extremeY - 1);
          ctx.lineTo(centerX - 4, extremeY - 7);
          ctx.lineTo(centerX + 4, extremeY - 7);
        }
        ctx.closePath();
        ctx.fill();

        ctx.fillStyle = sweepColor;
        ctx.font = "9px Segoe UI, sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = isBuySweep ? "top" : "bottom";
        ctx.fillText(event.liquidityLabel, centerX, isBuySweep ? extremeY + 9 : extremeY - 9);
        ctx.restore();
      });
    }
  }

  if (hasInstitutionalSMCEngine) {
    const engine = buildInstitutionalSmcEngine(candles, {
      symbol: currentSymbol,
      baseSeconds: getChartTimeframeSeconds(),
    });
    const visibleStartTime = Number(candles[start]?.time ?? candles[start]?.epoch ?? 0);
    const visibleEndTime = Number(candles[Math.max(start, end - 1)]?.time ?? candles[Math.max(start, end - 1)]?.epoch ?? visibleStartTime) + getChartTimeframeSeconds();
    const xForTime = (time, center = true) => {
      const value = Number(time);
      if (!Number.isFinite(value) || !Number.isFinite(visibleStartTime)) return NaN;
      return leftPad + (((value - visibleStartTime) / Math.max(1, getChartTimeframeSeconds())) * slotW) + (center ? slotW / 2 : 0);
    };
    const xForFrameIndex = (frame, index, fallbackX = null) => {
      const candle = frame?.candles?.[index];
      const time = Number(candle?.time ?? candle?.epoch);
      const x = xForTime(time, true);
      return Number.isFinite(x) ? x : fallbackX;
    };
    const htfBias = engine.frames?.htf?.bias || "RANGE";
    const biasFill = htfBias === "BULLISH"
      ? "rgba(16, 185, 129, 0.045)"
      : htfBias === "BEARISH"
        ? "rgba(239, 68, 68, 0.045)"
        : "rgba(148, 163, 184, 0.035)";
    ctx.save();
    ctx.fillStyle = biasFill;
    ctx.fillRect(leftPad, topPad, plotW, plotH);
    ctx.restore();

    engine.poiZones.slice(-8).forEach((zone) => {
      if (!Number.isFinite(zone.top) || !Number.isFinite(zone.bottom)) return;
      const frame = String(zone.layer || "").startsWith("ITF") ? engine.frames.itf : engine.frames.htf;
      const sourceSeconds = String(zone.layer || "").startsWith("ITF") ? engine.hierarchy.itfSeconds : engine.hierarchy.htfSeconds;
      const startTime = Number(frame?.candles?.[Number.isInteger(zone.index) ? zone.index : zone.startIndex]?.time);
      const endIndexValue = Number.isInteger(zone.drawEndIndex) ? zone.drawEndIndex : Number.isInteger(zone.endIndex) ? zone.endIndex : frame?.candles?.length - 1;
      const endTime = Number(frame?.candles?.[endIndexValue]?.time) + sourceSeconds;
      if (Number.isFinite(startTime) && Number.isFinite(endTime) && (endTime < visibleStartTime || startTime > visibleEndTime)) return;
      const x1 = Number.isFinite(startTime) ? clamp(xForTime(startTime, false), leftPad, width - rightPad) : leftPad;
      const x2 = Number.isFinite(endTime) ? clamp(xForTime(endTime, false), leftPad, width - rightPad) : width - rightPad;
      const topY = toY(Math.max(zone.top, zone.bottom));
      const bottomY = toY(Math.min(zone.top, zone.bottom));
      if (!Number.isFinite(topY) || !Number.isFinite(bottomY)) return;
      const isBull = zone.direction === "UP";
      const color = isBull ? "#10b981" : "#ef4444";
      const isItf = String(zone.layer || "").startsWith("ITF");
      ctx.save();
      ctx.fillStyle = isBull
        ? (isItf ? "rgba(16, 185, 129, 0.14)" : "rgba(6, 95, 70, 0.18)")
        : (isItf ? "rgba(239, 68, 68, 0.14)" : "rgba(127, 29, 29, 0.18)");
      ctx.strokeStyle = color;
      ctx.lineWidth = isItf ? 1.2 : 1;
      ctx.setLineDash(isItf ? [4, 3] : []);
      ctx.fillRect(x1, topY, Math.max(4, x2 - x1), Math.max(3, bottomY - topY));
      ctx.strokeRect(x1, topY, Math.max(4, x2 - x1), Math.max(3, bottomY - topY));
      ctx.setLineDash([]);
      ctx.fillStyle = color;
      ctx.font = "bold 9px Segoe UI, sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText(zone.layer || zone.kind || "POI", clamp(x1 + 4, leftPad + 4, width - rightPad - 80), clamp(topY + 3, topPad + 3, topPad + plotH - 14));
      ctx.restore();
    });

    const ltfFrame = engine.frames?.ltf || {};
    engine.signals.slice(-12).forEach((signal) => {
      if (!Number.isInteger(signal.entryIndex)) return;
      const x = xForFrameIndex(ltfFrame, signal.entryIndex);
      if (!Number.isFinite(x) || x < leftPad || x > width - rightPad) return;
      const price = Number(signal.price ?? ltfFrame.candles?.[signal.entryIndex]?.close);
      const y = toY(price);
      if (!Number.isFinite(y)) return;
      const buy = signal.direction === "BUY";
      const color = buy ? "#10b981" : "#ef4444";
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      if (buy) {
        ctx.moveTo(x, y - 11);
        ctx.lineTo(x - 5, y - 2);
        ctx.lineTo(x + 5, y - 2);
      } else {
        ctx.moveTo(x, y + 11);
        ctx.lineTo(x - 5, y + 2);
        ctx.lineTo(x + 5, y + 2);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });

    ctx.save();
    const panelW = Math.min(330, Math.max(235, plotW * 0.24));
    const panelH = 82;
    const panelX = Math.max(leftPad + 8, width - rightPad - panelW - 8);
    const panelY = topPad + 10;
    ctx.fillStyle = "rgba(12, 17, 25, 0.88)";
    ctx.strokeStyle = engine.direction === "BUY" ? "#10b981" : engine.direction === "SELL" ? "#ef4444" : "#475569";
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.roundRect(panelX, panelY, panelW, panelH, 8);
    ctx.fill();
    ctx.stroke();
    ctx.fillStyle = engine.direction === "BUY" ? "#10b981" : engine.direction === "SELL" ? "#ef4444" : "#cbd5e1";
    ctx.font = "bold 12px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(`${engine.signal.action} ${engine.grade} ${engine.score}/100`, panelX + 10, panelY + 8);
    ctx.fillStyle = "#9fb6d4";
    ctx.font = "10px Segoe UI, sans-serif";
    ctx.fillText(`HTF ${engine.hierarchy.htfLabel}: ${engine.frames.htf?.bias || "--"}`, panelX + 10, panelY + 29);
    ctx.fillText(`ITF ${engine.hierarchy.itfLabel}: ${engine.frames.itf?.bias || "--"} • LTF ${engine.hierarchy.ltfLabel}: ${engine.frames.ltf?.bias || "--"}`, panelX + 10, panelY + 45);
    ctx.fillText(`Stats ${engine.stats.winRate}% WR • ${engine.stats.total} tested`, panelX + 10, panelY + 61);
    ctx.restore();
  }

  if (hasWeloSMC) {
    const weloTfSeconds = getChartIndicatorTimeframe("SMC_WELO_TRADES");
    const chartTfSeconds = getChartTimeframeSeconds();
    const weloCandles = getChartIndicatorAnalysisCandles("SMC_WELO_TRADES", candles);
    const weloNative = weloCandles === candles || weloTfSeconds === chartTfSeconds;
    const smc = buildWeloSmartMoneyConcepts(weloCandles, {
      pivotLen: 4,
      lookback: 260,
      orderBlockLimit: 7,
      fvgLimit: 10,
    });
    const visibleStartTime = Number(candles[start]?.time ?? candles[start]?.epoch ?? 0);
    const visibleEndTime = Number(candles[Math.max(start, end - 1)]?.time ?? candles[Math.max(start, end - 1)]?.epoch ?? visibleStartTime) + chartTfSeconds;
    const sourceTimeAt = (index) => Number(weloCandles[index]?.time ?? weloCandles[index]?.epoch);
    const xForTime = (time, center = true) => {
      const value = Number(time);
      if (!Number.isFinite(value) || !Number.isFinite(visibleStartTime)) return NaN;
      return leftPad + (((value - visibleStartTime) / Math.max(1, chartTfSeconds)) * slotW) + (center ? slotW / 2 : 0);
    };
    const xForIndex = (index, center = true) => {
      if (weloNative) return leftPad + ((index - start) * slotW) + (center ? slotW / 2 : 0);
      return xForTime(sourceTimeAt(index), center);
    };
    const xForIndexEnd = (index) => {
      if (weloNative) return leftPad + ((index - start) * slotW) + slotW;
      return xForTime(sourceTimeAt(index) + weloTfSeconds, false);
    };
    const clampX = (x) => clamp(x, leftPad, width - rightPad);
    const indexVisible = (index) => {
      if (weloNative) return index >= start && index < end;
      const time = sourceTimeAt(index);
      return Number.isFinite(time) && time + weloTfSeconds >= visibleStartTime && time <= visibleEndTime;
    };
    const rangeVisible = (startIndex, endIndex) => {
      if (weloNative) return endIndex >= start && startIndex < end;
      const startTime = sourceTimeAt(startIndex);
      const endTime = sourceTimeAt(endIndex) + weloTfSeconds;
      return Number.isFinite(startTime) && Number.isFinite(endTime) && endTime >= visibleStartTime && startTime <= visibleEndTime;
    };
    const zoneVisible = (zone) => {
      const zoneStart = Number.isInteger(zone.startIndex) ? zone.startIndex : zone.index;
      const zoneEnd = Number.isInteger(zone.drawEndIndex) ? zone.drawEndIndex : Number.isInteger(zone.endIndex) ? zone.endIndex : weloCandles.length - 1;
      return rangeVisible(zoneStart, zoneEnd);
    };
    const drawTag = (text, x, y, color, align = "center") => {
      const label = String(text || "");
      if (!label) return;
      ctx.save();
      ctx.font = "bold 9px Segoe UI, sans-serif";
      const padX = 5;
      const textW = ctx.measureText(label).width;
      const boxW = textW + padX * 2;
      const boxH = 16;
      const boxX = clamp(align === "right" ? x - boxW : align === "left" ? x : x - boxW / 2, leftPad, width - rightPad - boxW);
      const boxY = clamp(y - boxH / 2, topPad, topPad + plotH - boxH);
      ctx.fillStyle = "rgba(12, 17, 25, 0.88)";
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.beginPath();
      ctx.roundRect(boxX, boxY, boxW, boxH, 5);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(label, boxX + boxW / 2, boxY + boxH / 2);
      ctx.restore();
    };
    const drawZone = (zone, label, color, fill) => {
      if (!zoneVisible(zone)) return;
      const zoneStart = Number.isInteger(zone.startIndex) ? zone.startIndex : zone.index;
      const zoneEnd = Number.isInteger(zone.drawEndIndex) ? zone.drawEndIndex : Number.isInteger(zone.endIndex) ? zone.endIndex : weloCandles.length - 1;
      const x = clampX(weloNative ? xForIndex(Math.max(start, zoneStart), false) : xForIndex(zoneStart, false));
      const x2 = clampX(weloNative ? xForIndexEnd(Math.min(end - 1, zoneEnd)) : xForIndexEnd(zoneEnd));
      const y1 = toY(zone.top);
      const y2 = toY(zone.bottom);
      if (!Number.isFinite(y1) || !Number.isFinite(y2)) return;
      const topY = Math.min(y1, y2);
      const h = Math.max(3, Math.abs(y2 - y1));
      ctx.save();
      ctx.fillStyle = fill;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      if (zone.type === "BREAKER") ctx.setLineDash([5, 4]);
      ctx.fillRect(x, topY, Math.max(3, x2 - x), h);
      ctx.strokeRect(x, topY, Math.max(3, x2 - x), h);
      ctx.setLineDash([]);
      ctx.font = "bold 9px Segoe UI, sans-serif";
      ctx.fillStyle = color;
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText(label, x + 4, topY + 3);
      ctx.restore();
    };

    smc.orderBlocks.forEach((zone) => {
      const bullish = zone.direction === "UP";
      drawZone(
        zone,
        bullish ? "Bullish OB" : "Bearish OB",
        bullish ? "rgba(35, 211, 139, 0.95)" : "rgba(255, 91, 107, 0.95)",
        bullish ? "rgba(35, 211, 139, 0.13)" : "rgba(255, 91, 107, 0.13)",
      );
    });
    smc.breakerBlocks.forEach((zone) => {
      const bullish = zone.direction === "UP";
      drawZone(
        zone,
        bullish ? "Bull Breaker" : "Bear Breaker",
        bullish ? "rgba(67, 170, 255, 0.9)" : "rgba(250, 204, 21, 0.95)",
        bullish ? "rgba(67, 170, 255, 0.10)" : "rgba(250, 204, 21, 0.10)",
      );
    });
    smc.fvgs.forEach((zone) => {
      const bullish = zone.direction === "UP";
      drawZone(
        zone,
        bullish ? "FVG+" : "FVG-",
        bullish ? "rgba(94, 234, 212, 0.85)" : "rgba(248, 113, 113, 0.85)",
        bullish ? "rgba(94, 234, 212, 0.08)" : "rgba(248, 113, 113, 0.08)",
      );
    });
    smc.bprs.forEach((zone) => drawZone(zone, "BPR", "rgba(168, 85, 247, 0.9)", "rgba(168, 85, 247, 0.10)"));

    [...smc.equalHighs, ...smc.equalLows].forEach((level) => {
      if (!rangeVisible(level.startIndex, level.endIndex)) return;
      const x1 = clampX(weloNative ? xForIndex(Math.max(start, level.startIndex)) : xForIndex(level.startIndex));
      const x2 = clampX(weloNative ? xForIndex(Math.min(end - 1, level.endIndex)) : xForIndex(level.endIndex));
      const y = toY(level.price);
      if (!Number.isFinite(y)) return;
      const color = level.type === "HIGH" ? "#ff5570" : "#14b8a6";
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 4]);
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
      ctx.restore();
      drawTag(level.label, (x1 + x2) / 2, y - (level.type === "HIGH" ? 10 : -10), color);
    });

    smc.structureEvents.forEach((event) => {
      if (!rangeVisible(event.pivotIndex, event.breakIndex)) return;
      const x1 = clampX(weloNative ? xForIndex(Math.max(start, event.pivotIndex)) : xForIndex(event.pivotIndex));
      const x2 = clampX(weloNative ? xForIndex(Math.min(end - 1, event.breakIndex)) : xForIndex(event.breakIndex));
      const y = toY(event.pivotPrice);
      if (!Number.isFinite(y)) return;
      const isUp = event.direction === "UP";
      const color = isUp ? "#10b981" : "#ef4444";
      const label = event.type === "MSS" ? (isUp ? "CHOCH+" : "CHOCH-") : `BOS ${isUp ? "UP" : "DOWN"}`;
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.15;
      ctx.setLineDash(event.type === "MSS" ? [5, 3] : []);
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
      ctx.restore();
      drawTag(label, (x1 + x2) / 2, y + (isUp ? -12 : 12), color);
    });

    smc.swings.forEach((swing) => {
      if (!indexVisible(swing.index)) return;
      const x = clampX(xForIndex(swing.index));
      const y = toY(swing.price);
      if (!Number.isFinite(y)) return;
      const high = swing.type === "HIGH";
      drawTag(swing.label, x, y + (high ? -12 : 12), high ? "#fca5a5" : "#67e8f9");
    });

    smc.sweeps.forEach((event) => {
      if (!indexVisible(event.candleIndex)) return;
      const x = clampX(xForIndex(event.candleIndex));
      const refY = toY(event.referenceLevel);
      const extremeY = toY(event.extremeLevel);
      if (!Number.isFinite(refY) || !Number.isFinite(extremeY)) return;
      const buySide = event.sweepType === "BUY";
      const color = buySide ? "#ef4444" : "#10b981";
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.setLineDash([2, 3]);
      ctx.beginPath();
      ctx.moveTo(Math.max(leftPad, x - slotW), refY);
      ctx.lineTo(Math.min(width - rightPad, x + slotW), refY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = color;
      ctx.beginPath();
      if (buySide) {
        ctx.moveTo(x, extremeY - 7);
        ctx.lineTo(x - 5, extremeY + 2);
        ctx.lineTo(x + 5, extremeY + 2);
      } else {
        ctx.moveTo(x, extremeY + 7);
        ctx.lineTo(x - 5, extremeY - 2);
        ctx.lineTo(x + 5, extremeY - 2);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      drawTag(buySide ? "BSL sweep" : "SSL sweep", x, extremeY + (buySide ? -12 : 12), color);
    });

    smc.trendlines.forEach((line) => {
      const from = line.from;
      const to = line.to;
      if (!from || !to || !rangeVisible(from.index, to.index)) return;
      const x1 = xForIndex(from.index);
      const y1 = toY(from.price);
      const x2Base = xForIndex(to.index);
      const y2Base = toY(to.price);
      if (![x1, y1, x2Base, y2Base].every(Number.isFinite)) return;
      const projectedIndex = Math.min(weloCandles.length - 1, to.index + 20);
      const slope = (to.price - from.price) / Math.max(1, to.index - from.index);
      const projectedPrice = to.price + slope * (projectedIndex - to.index);
      const x2 = clampX(weloNative ? xForIndex(Math.min(end - 1, projectedIndex)) : xForIndex(projectedIndex));
      const y2 = toY(projectedPrice);
      ctx.save();
      ctx.strokeStyle = line.type === "LOW" ? "rgba(16, 185, 129, 0.7)" : "rgba(239, 68, 68, 0.7)";
      ctx.lineWidth = 1.25;
      ctx.setLineDash([7, 5]);
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, Number.isFinite(y2) ? y2 : y2Base);
      ctx.stroke();
      ctx.restore();
    });

    const signal = smc.signals[0];
    if (signal && indexVisible(signal.entryIndex)) {
      const x = clampX(xForIndex(signal.entryIndex));
      const candle = weloCandles[signal.entryIndex];
      const buy = signal.direction === "BUY";
      const y = toY(buy ? candle.low : candle.high) + (buy ? 16 : -16);
      const color = buy ? "#10b981" : "#ef4444";
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      if (buy) {
        ctx.moveTo(x, y - 8);
        ctx.lineTo(x - 6, y + 4);
        ctx.lineTo(x + 6, y + 4);
      } else {
        ctx.moveTo(x, y + 8);
        ctx.lineTo(x - 6, y - 4);
        ctx.lineTo(x + 6, y - 4);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
      drawTag(`${signal.direction} ${signal.confidence}%`, x, y + (buy ? 16 : -16), color);
    }

    ctx.save();
    ctx.font = "bold 10px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillStyle = smc.bias === "BUY" ? "#10b981" : smc.bias === "SELL" ? "#ef4444" : "#94a3b8";
    ctx.fillText(`SMC Welo ${getTimeframeLabel(weloTfSeconds)}: ${smc.summary}`, leftPad + 4, topPad + 4);
    ctx.restore();
  }

  if (hasSMCSetup08) {
    const smc = buildSMCSetup08(candles, 5);
    [...smc.bullish, ...smc.bearish].forEach((setup) => {
      const isBull = setup.direction === "BULL";
      const swingX1 = leftPad + ((Math.max(start, setup.swingIndex) - start) * slotW) + (slotW / 2);
      const swingX2 = leftPad + ((Math.min(end - 1, setup.poiIndex) - start) * slotW) + (slotW / 2);
      const swingY = toY(setup.swingPrice);
      const chochX1 = leftPad + ((Math.max(start, setup.levelIndex) - start) * slotW) + (slotW / 2);
      const chochX2 = leftPad + ((Math.min(end - 1, setup.levelBreakIndex ?? setup.poiIndex) - start) * slotW) + (slotW / 2);
      const chochY = toY(setup.levelPrice);
      const poiStart = Math.max(0, setup.poiIndex - start);
      const poiEnd = Math.max(poiStart, Math.min(points.length - 1, (setup.poiFillIndex ?? setup.poiIndex) - start));
      const poiX = leftPad + (poiStart * slotW);
      const poiW = Math.max(slotW, (poiEnd - poiStart + 1) * slotW);
      const poiTopY = toY(setup.poiTop);
      const poiBottomY = toY(setup.poiBottom);
      const color = isBull ? "#5be660" : "#e65b5b";
      const zoneColor = isBull ? "rgba(80, 159, 255, 0.18)" : "rgba(255, 235, 80, 0.18)";

      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 1;
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(swingX1, swingY);
      ctx.lineTo(swingX2, swingY);
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(chochX1, chochY);
      ctx.lineTo(chochX2, chochY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = color;
      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      ctx.fillText(isBull ? "SSL" : "BSL", (swingX1 + swingX2) / 2, swingY - 3);
      ctx.fillText("ChoCh", (chochX1 + chochX2) / 2, chochY - 3);

      ctx.fillStyle = zoneColor;
      ctx.strokeStyle = isBull ? "#509fff" : "#ffeb50";
      ctx.fillRect(poiX, poiTopY, poiW, Math.max(2, poiBottomY - poiTopY));
      ctx.strokeRect(poiX, poiTopY, poiW, Math.max(2, poiBottomY - poiTopY));
      ctx.fillStyle = "#dadada";
      ctx.textBaseline = "middle";
      ctx.fillText("POI", poiX + (poiW / 2), (poiTopY + poiBottomY) / 2);

      if (setup.fvg) {
        const fvgStart = Math.max(0, setup.fvg.index - start);
        const fvgEnd = Math.max(fvgStart, Math.min(points.length - 1, (setup.triggerIndex ?? setup.fvg.index) - start));
        const fvgX = leftPad + (fvgStart * slotW);
        const fvgW = Math.max(slotW, (fvgEnd - fvgStart + 1) * slotW);
        const fvgTopY = toY(setup.fvg.top);
        const fvgBottomY = toY(setup.fvg.bottom);
        ctx.strokeStyle = isBull ? "#68ff6d" : "#ff6868";
        ctx.fillStyle = isBull ? "rgba(104, 255, 109, 0.14)" : "rgba(255, 104, 104, 0.14)";
        ctx.setLineDash([4, 3]);
        ctx.strokeRect(fvgX, fvgTopY, fvgW, Math.max(2, fvgBottomY - fvgTopY));
        ctx.setLineDash([]);
        ctx.fillRect(fvgX, fvgTopY, fvgW, Math.max(2, fvgBottomY - fvgTopY));
        ctx.fillStyle = "#dadada";
        ctx.fillText("Imbalance", fvgX + (fvgW / 2), (fvgTopY + fvgBottomY) / 2);
      }

      const setupEntryIndex = setup.triggerIndex != null && setup.triggerIndex + 1 < candles.length
        ? setup.triggerIndex + 1
        : setup.triggerIndex;
      if (setupEntryIndex != null && setupEntryIndex >= start && setupEntryIndex < end) {
        const triggerX = leftPad + ((setupEntryIndex - start) * slotW) + (slotW / 2);
        const triggerY = isBull ? toY(candles[setupEntryIndex].low) + 10 : toY(candles[setupEntryIndex].high) - 10;
        ctx.fillStyle = isBull ? "#5be660" : "#e65b5b";
        ctx.beginPath();
        if (isBull) {
          ctx.moveTo(triggerX, triggerY - 6);
          ctx.lineTo(triggerX - 5, triggerY + 4);
          ctx.lineTo(triggerX + 5, triggerY + 4);
        } else {
          ctx.moveTo(triggerX, triggerY + 6);
          ctx.lineTo(triggerX - 5, triggerY - 4);
          ctx.lineTo(triggerX + 5, triggerY - 4);
        }
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    });
  }

  if (hasSMCProCombo) {
    const smc = buildSMCProCombo(candles, {
      leftLen: 5,
      rightLen: 5,
      atrLen: 14,
      atrMult: 0.1,
      volLen: 20,
      minBodyPct: 55,
      useAtrBuffer: true,
      useBodyFilter: true,
    });

    const drawLevel = (level, color, label) => {
      if (!level) return;
      const localStart = Math.max(0, level.index - start);
      const x1 = leftPad + (localStart * slotW) + (slotW / 2);
      const x2 = width - rightPad;
      const y = toY(level.price);
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.6;
      ctx.setLineDash([5, 3]);
      ctx.beginPath();
      ctx.moveTo(x1, y);
      ctx.lineTo(x2, y);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = color;
      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "bottom";
      ctx.fillText(label, Math.min(x1 + 4, x2 - 24), y - 3);
      ctx.restore();
    };

    drawLevel(smc.support, "rgba(88, 156, 255, 0.88)", "Support");
    drawLevel(smc.resistance, "rgba(231, 91, 100, 0.88)", "Resistance");

    smc.signals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const visibleIndex = signal.entryIndex - start;
      const candle = candles[signal.entryIndex];
      const x = leftPad + visibleIndex * slotW + candleGap / 2;
      const centerX = x + candleW / 2;
      const isBuy = signal.type.endsWith("BUY");
      const isStrong = signal.type.startsWith("STRONG");
      const markerColor = isBuy
        ? (isStrong ? "#20d07a" : "#9aa7b8")
        : (isStrong ? "#ff5b6b" : "#9aa7b8");
      const refY = toY(signal.reference);
      const wickY = isBuy ? toY(candle.low) : toY(candle.high);
      const bodyTopY = toY(Math.max(candle.open, candle.close));
      const bodyBottomY = toY(Math.min(candle.open, candle.close));
      const topY = Math.min(refY, wickY);
      const zoneH = Math.max(3, Math.abs(refY - wickY));

      ctx.save();
      ctx.fillStyle = isStrong
        ? (isBuy ? "rgba(32, 208, 122, 0.10)" : "rgba(255, 91, 107, 0.10)")
        : "rgba(154, 167, 184, 0.08)";
      ctx.fillRect(x - 1, topY, candleW + 2, zoneH);

      ctx.strokeStyle = markerColor;
      ctx.lineWidth = 1;
      ctx.setLineDash(isStrong ? [4, 2] : [2, 3]);
      ctx.beginPath();
      ctx.moveTo(Math.max(leftPad, centerX - 10), refY);
      ctx.lineTo(Math.min(width - rightPad, centerX + 10), refY);
      ctx.stroke();
      ctx.setLineDash([]);

      ctx.fillStyle = markerColor;
      ctx.beginPath();
      if (isBuy) {
        const triangleY = bodyBottomY + 10;
        ctx.moveTo(centerX, triangleY - 7);
        ctx.lineTo(centerX - 5, triangleY + 3);
        ctx.lineTo(centerX + 5, triangleY + 3);
      } else {
        const triangleY = bodyTopY - 10;
        ctx.moveTo(centerX, triangleY + 7);
        ctx.lineTo(centerX - 5, triangleY - 3);
        ctx.lineTo(centerX + 5, triangleY - 3);
      }
      ctx.closePath();
      ctx.fill();

      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "bottom" : "top";
      const textY = isBuy ? bodyBottomY + 1 : bodyTopY - 1;
      ctx.fillText(
        isStrong ? (isBuy ? "SM BUY" : "SM SELL") : (isBuy ? "Weak Buy" : "Weak Sell"),
        centerX,
        textY,
      );
      ctx.restore();
    });

    ctx.save();
    ctx.fillStyle = "#c4ccd7";
    ctx.font = "9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(`B ${smc.stats.buy.wins}/${smc.stats.buy.total}`, leftPad + 4, topPad + 4);
    ctx.fillText(`S ${smc.stats.sell.wins}/${smc.stats.sell.total}`, leftPad + 4, topPad + 16);
    ctx.restore();

  }

  if (hasADXVolWaves) {
    const waves = buildADXVolatilityWaves(candles, {
      bbLength: 20,
      bbMult: 1.5,
      adxLength: 14,
      adxSmooth: 14,
      adxInfluence: 0.8,
      zoneOffset: 1,
      zoneExpansion: 1,
      smoothLength: 50,
      signalCooldown: 20,
    });
    const topColors = [
      "rgba(255, 229, 229, 0.20)",
      "rgba(255, 204, 204, 0.22)",
      "rgba(255, 179, 179, 0.24)",
      "rgba(255, 153, 153, 0.26)",
      "rgba(255, 128, 128, 0.28)",
      "rgba(255, 102, 102, 0.30)",
      "rgba(255, 77, 77, 0.32)",
      "rgba(255, 51, 51, 0.34)",
      "rgba(255, 26, 26, 0.36)",
      "rgba(255, 0, 0, 0.38)",
    ];
    const bottomColors = [
      "rgba(229, 255, 229, 0.20)",
      "rgba(204, 255, 204, 0.22)",
      "rgba(179, 255, 179, 0.24)",
      "rgba(153, 255, 153, 0.26)",
      "rgba(128, 255, 128, 0.28)",
      "rgba(102, 255, 102, 0.30)",
      "rgba(77, 255, 77, 0.32)",
      "rgba(51, 255, 51, 0.34)",
      "rgba(26, 255, 26, 0.36)",
      "rgba(0, 255, 0, 0.38)",
    ];
    const drawBandFill = (lowerSeries, upperSeries, color) => {
      ctx.save();
      ctx.fillStyle = color;
      for (let i = start; i < end; i += 1) {
        const lowerA = lowerSeries[i];
        const upperA = upperSeries[i];
        const lowerB = i + 1 < candles.length ? lowerSeries[i + 1] : null;
        const upperB = i + 1 < candles.length ? upperSeries[i + 1] : null;
        if (![lowerA, upperA, lowerB, upperB].every(Number.isFinite)) continue;
        const x1 = leftPad + ((i - start) * slotW);
        const x2 = leftPad + ((i - start + 1) * slotW);
        ctx.beginPath();
        ctx.moveTo(x1, toY(upperA));
        ctx.lineTo(x2, toY(upperB));
        ctx.lineTo(x2, toY(lowerB));
        ctx.lineTo(x1, toY(lowerA));
        ctx.closePath();
        ctx.fill();
      }
      ctx.restore();
    };

    for (let band = 0; band < 10; band += 1) {
      drawBandFill(waves.topBands[band], waves.topBands[band + 1], topColors[band]);
      drawBandFill(waves.bottomBands[band + 1], waves.bottomBands[band], bottomColors[band]);
    }

    waves.signals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const visibleIndex = signal.entryIndex - start;
      const candle = candles[signal.entryIndex];
      const centerX = leftPad + (visibleIndex * slotW) + (slotW / 2);
      const isBuy = signal.type === "BUY";
      const anchorY = isBuy ? toY(candle.low) : toY(candle.high);
      const labelY = isBuy ? anchorY + 14 : anchorY - 14;
      const bg = isBuy ? "#00ff88" : "#ff3366";
      const fg = isBuy ? "#111111" : "#ffffff";

      ctx.save();
      ctx.font = "bold 8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      const text = signal.type;
      const textW = ctx.measureText(text).width;
      const boxW = textW + 10;
      const boxH = 14;
      const boxX = centerX - (boxW / 2);
      const boxY = isBuy ? labelY : labelY - boxH;
      ctx.fillStyle = bg;
      ctx.strokeStyle = bg;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(centerX, isBuy ? boxY : boxY + boxH);
      ctx.lineTo(centerX, isBuy ? anchorY + 2 : anchorY - 2);
      ctx.stroke();
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(centerX, anchorY + 2);
        ctx.lineTo(centerX - 4, anchorY + 8);
        ctx.lineTo(centerX + 4, anchorY + 8);
      } else {
        ctx.moveTo(centerX, anchorY - 2);
        ctx.lineTo(centerX - 4, anchorY - 8);
        ctx.lineTo(centerX + 4, anchorY - 8);
      }
      ctx.closePath();
      ctx.fill();
      ctx.beginPath();
      ctx.roundRect(boxX, boxY, boxW, boxH, 6);
      ctx.fill();
      ctx.fillStyle = fg;
      ctx.fillText(text, centerX, boxY + (boxH / 2));
      ctx.restore();
    });
  }

  if (hasBreakoutTargets) {
    const breakout = buildBreakoutTargets(candles, {
      len: 99,
      preventOverlap: true,
      atrPeriod: 14,
      slMultiplier: 5,
      tp1Multiplier: 0.5,
      tp2Multiplier: 1.0,
      tp3Multiplier: 1.5,
    });

    breakout.channels.slice(-6).forEach((channel) => {
      const localStart = Math.max(0, channel.startIndex - start);
      const localEnd = Math.min(points.length - 1, channel.endIndex - start);
      if (localEnd < 0 || localStart > points.length - 1) return;
      const x = leftPad + (localStart * slotW);
      const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
      const topY = toY(channel.top);
      const bottomY = toY(channel.bottom);
      const upperBandY = toY(channel.upperBandBottom);
      const lowerBandY = toY(channel.lowerBandTop);
      const centerY = toY((channel.top + channel.bottom) / 2);

      ctx.save();
      ctx.fillStyle = "rgba(200, 205, 214, 0.10)";
      ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
      ctx.fillStyle = "rgba(255, 17, 0, 0.18)";
      ctx.fillRect(x, topY, w, Math.max(2, upperBandY - topY));
      ctx.fillStyle = "rgba(0, 255, 187, 0.18)";
      ctx.fillRect(x, lowerBandY, w, Math.max(2, bottomY - lowerBandY));
      ctx.strokeStyle = "rgba(200, 205, 214, 0.22)";
      ctx.lineWidth = 1;
      ctx.strokeRect(x, topY, w, Math.max(2, bottomY - topY));
      ctx.setLineDash([4, 3]);
      ctx.beginPath();
      ctx.moveTo(x, centerY);
      ctx.lineTo(x + w, centerY);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.restore();
    });

    breakout.breakouts.forEach((event) => {
      const renderIndex = event.entryIndex ?? event.index;
      if (renderIndex < start || renderIndex >= end) return;
      const centerX = leftPad + ((renderIndex - start) * slotW) + (slotW / 2);
      const y = toY(event.price);
      const isBull = event.direction === "UP";
      ctx.save();
      ctx.fillStyle = isBull ? "#00ffbb" : "#ff1100";
      ctx.font = "bold 10px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(isBull ? "▲" : "▼", centerX, y);
      ctx.restore();
    });

    breakout.trades.slice(-3).forEach((trade) => {
      const localStart = Math.max(0, trade.startIndex - start);
      const localEnd = Math.min(points.length - 1, trade.endIndex - start);
      if (localEnd < 0 || localStart > points.length - 1) return;
      const x1 = leftPad + (localStart * slotW);
      const x2 = leftPad + ((localEnd + 1) * slotW);
      const levels = [
        { key: "entry", value: trade.entry, color: trade.direction === "UP" ? "#00ffbb" : "#ff1100", label: "Entry" },
        { key: "sl", value: trade.sl, color: "rgba(255, 17, 0, 0.75)", label: "SL" },
        { key: "tp1", value: trade.tp1, color: "rgba(0, 255, 187, 0.50)", label: "TP1" },
        { key: "tp2", value: trade.tp2, color: "rgba(0, 255, 187, 0.65)", label: "TP2" },
        { key: "tp3", value: trade.tp3, color: "rgba(0, 255, 187, 0.85)", label: "TP3" },
      ];

      ctx.save();
      levels.forEach((level) => {
        const y = toY(level.value);
        ctx.strokeStyle = level.color;
        ctx.lineWidth = level.key === "entry" ? 2 : 1.5;
        ctx.beginPath();
        ctx.moveTo(x1, y);
        ctx.lineTo(x2, y);
        ctx.stroke();
        ctx.fillStyle = level.color;
        ctx.font = "8px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "middle";
        ctx.fillText(level.label, Math.min(width - rightPad + 4, x2 + 4), y);
      });
      ctx.fillStyle = trade.direction === "UP" ? "rgba(0, 255, 187, 0.06)" : "rgba(255, 17, 0, 0.06)";
      const topFill = toY(Math.max(trade.entry, trade.sl, trade.tp3));
      const bottomFill = toY(Math.min(trade.entry, trade.sl, trade.tp3));
      ctx.fillRect(x1, Math.min(topFill, bottomFill), Math.max(2, x2 - x1), Math.max(2, Math.abs(bottomFill - topFill)));
      ctx.restore();
    });
  }

  if (hasDynamicZDivergence) {
    const dzd = buildDynamicZDivergence(candles, {
      lenZ: 100,
      smoothLen: 10,
      slopeIndex: 1,
      lookbackLeft: 15,
      lookbackRight: 1,
      rangeMin: 5,
      rangeMax: 60,
      saRsiLen: 21,
      saZLen: 200,
      saBaseLen: 80,
      saIntensity: 0.15,
      saSlopeIndex: 1,
      saBandAtrLen: 14,
      saBandMult: 1.4,
    });

    const drawSeries = (values, colors, widthPx = 1.5) => {
      ctx.save();
      ctx.lineWidth = widthPx;
      let started = false;
      for (let i = start; i < end; i += 1) {
        const value = values[i];
        if (!Number.isFinite(value)) {
          started = false;
          continue;
        }
        const x = leftPad + ((i - start) * slotW) + (slotW / 2);
        const y = toY(value);
        ctx.strokeStyle = Array.isArray(colors) ? (colors[i] || "#9aa7b8") : colors;
        if (!started) {
          ctx.beginPath();
          ctx.moveTo(x, y);
          started = true;
        } else {
          ctx.lineTo(x, y);
        }
        const nextValue = i + 1 < end ? values[i + 1] : null;
        if (!Number.isFinite(nextValue)) {
          ctx.stroke();
          started = false;
        }
      }
      if (started) ctx.stroke();
      ctx.restore();
    };

    ctx.save();
    for (let i = start; i < end - 1; i += 1) {
      const mainA = dzd.saema[i];
      const mainB = dzd.saema[i + 1];
      const upperA = dzd.saUpper[i];
      const upperB = dzd.saUpper[i + 1];
      const lowerA = dzd.saLower[i];
      const lowerB = dzd.saLower[i + 1];
      const bullSlope = dzd.saColor[i] === "#00fec3";
      const bearSlope = dzd.saColor[i] === "#e600ff";
      const x1 = leftPad + ((i - start) * slotW) + (slotW / 2);
      const x2 = leftPad + ((i - start + 1) * slotW) + (slotW / 2);

      if (bullSlope && [mainA, mainB, lowerA, lowerB].every(Number.isFinite)) {
        ctx.fillStyle = "rgba(0, 254, 195, 0.14)";
        ctx.beginPath();
        ctx.moveTo(x1, toY(mainA));
        ctx.lineTo(x2, toY(mainB));
        ctx.lineTo(x2, toY(lowerB));
        ctx.lineTo(x1, toY(lowerA));
        ctx.closePath();
        ctx.fill();
      }
      if (bearSlope && [mainA, mainB, upperA, upperB].every(Number.isFinite)) {
        ctx.fillStyle = "rgba(230, 0, 255, 0.14)";
        ctx.beginPath();
        ctx.moveTo(x1, toY(mainA));
        ctx.lineTo(x2, toY(mainB));
        ctx.lineTo(x2, toY(upperB));
        ctx.lineTo(x1, toY(upperA));
        ctx.closePath();
        ctx.fill();
      }
    }
    ctx.restore();

    drawSeries(dzd.saUpper, dzd.saColor.map((c) => c === "#e600ff" ? "#e600ff" : "rgba(230,0,255,0.15)"), 1);
    drawSeries(dzd.saLower, dzd.saColor.map((c) => c === "#00fec3" ? "#00fec3" : "rgba(0,254,195,0.15)"), 1);
    drawSeries(dzd.saema, dzd.saColor, 1.6);

    dzd.buySignals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const y = toY(candles[signal.entryIndex].low) + 10;
      ctx.save();
      ctx.fillStyle = "#00fec3";
      ctx.beginPath();
      ctx.moveTo(x, y - 6);
      ctx.lineTo(x - 5, y + 3);
      ctx.lineTo(x + 5, y + 3);
      ctx.closePath();
      ctx.fill();
      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "bottom";
      ctx.fillText("✘", x, y - 8);
      ctx.restore();
    });

    dzd.sellSignals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const y = toY(candles[signal.entryIndex].high) - 10;
      ctx.save();
      ctx.fillStyle = "#e600ff";
      ctx.beginPath();
      ctx.moveTo(x, y + 6);
      ctx.lineTo(x - 5, y - 3);
      ctx.lineTo(x + 5, y - 3);
      ctx.closePath();
      ctx.fill();
      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "top";
      ctx.fillText("✘", x, y + 8);
      ctx.restore();
    });

    dzd.bullDivs.forEach((div) => {
      if (div.entryIndex == null || div.entryIndex < start || div.entryIndex >= end) return;
      const x = leftPad + ((div.entryIndex - start) * slotW) + (slotW / 2);
      const y = toY(candles[div.entryIndex].low) + 20;
      ctx.save();
      ctx.fillStyle = "#5cf0d7";
      ctx.font = "10px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("Up", x, y);
      ctx.restore();
    });

    dzd.bearDivs.forEach((div) => {
      if (div.entryIndex == null || div.entryIndex < start || div.entryIndex >= end) return;
      const x = leftPad + ((div.entryIndex - start) * slotW) + (slotW / 2);
      const y = toY(candles[div.entryIndex].high) - 20;
      ctx.save();
      ctx.fillStyle = "#b32ac3";
      ctx.font = "10px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("Down", x, y);
      ctx.restore();
    });
  }

  if (hasVolumeProfileNodes) {
    const vp = buildVolumeProfileNodes(candles, {
      profileLength: 360,
      rows: 60,
      valueAreaThreshold: 0.7,
      peakPercent: 0.09,
      troughPercent: 0.07,
      thresholdPercent: 0.01,
      highestCount: 2,
      lowestCount: 2,
    });

    if (vp.rows.length && vp.maxVolume > 0) {
      const profileWidth = Math.max(36, Math.floor((width - rightPad - leftPad) * 0.18));
      const profileRight = width - rightPad - 4;
      const profileLeft = profileRight - profileWidth;

      vp.rows.forEach((row) => {
        const rowTopY = toY(row.top);
        const rowBottomY = toY(row.bottom);
        const rowH = Math.max(1, rowBottomY - rowTopY);
        const bullWidth = Math.max(0, Math.round((row.bullish / vp.maxVolume) * profileWidth));
        const bearWidth = Math.max(0, Math.round((row.bearish / vp.maxVolume) * profileWidth));
        const totalWidth = Math.max(1, Math.round((row.total / vp.maxVolume) * profileWidth));
        const inValueArea = vp.valIndex != null && vp.vahIndex != null && row.index >= vp.valIndex && row.index <= vp.vahIndex;

        ctx.save();
        if (inValueArea) {
          ctx.fillStyle = "rgba(41, 98, 255, 0.10)";
          ctx.fillRect(profileLeft, rowTopY, profileWidth, rowH);
        }
        ctx.fillStyle = row.index === vp.pocIndex
          ? "rgba(251, 192, 45, 0.38)"
          : row.peak
            ? "rgba(0, 123, 255, 0.25)"
            : row.trough
              ? "rgba(120, 120, 120, 0.18)"
              : "rgba(93, 96, 107, 0.14)";
        ctx.fillRect(profileRight - totalWidth, rowTopY, totalWidth, rowH);

        if (bullWidth > 0) {
          ctx.fillStyle = inValueArea ? "rgba(41, 98, 255, 0.28)" : "rgba(93, 96, 107, 0.24)";
          ctx.fillRect(profileRight - bullWidth, rowTopY, bullWidth, rowH);
        }
        if (bearWidth > 0) {
          ctx.fillStyle = inValueArea ? "rgba(251, 192, 45, 0.26)" : "rgba(209, 212, 220, 0.20)";
          ctx.fillRect(profileRight - totalWidth, rowTopY, Math.min(totalWidth, bearWidth), rowH);
        }

        if (row.highest) {
          ctx.fillStyle = "rgba(255, 165, 0, 0.18)";
          ctx.fillRect(profileLeft, rowTopY, profileWidth, rowH);
        }
        if (row.lowest) {
          ctx.fillStyle = "rgba(0, 0, 128, 0.16)";
          ctx.fillRect(profileLeft, rowTopY, profileWidth, rowH);
        }
        ctx.restore();
      });

      if (vp.pocIndex != null && vp.pocIndex >= 0) {
        const pocRow = vp.rows[vp.pocIndex];
        const pocY = toY((pocRow.top + pocRow.bottom) / 2);
        ctx.save();
        ctx.strokeStyle = "#fbc02d";
        ctx.lineWidth = 1.6;
        ctx.beginPath();
        ctx.moveTo(profileLeft - 8, pocY);
        ctx.lineTo(profileRight, pocY);
        ctx.stroke();
        ctx.fillStyle = "#fbc02d";
        ctx.font = "8px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "bottom";
        ctx.fillText("POC", Math.max(leftPad + 2, profileLeft - 26), pocY - 2);
        ctx.restore();
      }

      const drawVaLine = (index, color, label) => {
        if (index == null || index < 0 || index >= vp.rows.length) return;
        const row = vp.rows[index];
        const y = toY(label === "VAL" ? row.bottom : row.top);
        ctx.save();
        ctx.strokeStyle = color;
        ctx.lineWidth = 1;
        ctx.setLineDash([4, 3]);
        ctx.beginPath();
        ctx.moveTo(profileLeft - 8, y);
        ctx.lineTo(profileRight, y);
        ctx.stroke();
        ctx.setLineDash([]);
        ctx.fillStyle = color;
        ctx.font = "8px Segoe UI, sans-serif";
        ctx.textAlign = "left";
        ctx.textBaseline = "bottom";
        ctx.fillText(label, Math.max(leftPad + 2, profileLeft - 26), y - 2);
        ctx.restore();
      };

      drawVaLine(vp.vahIndex, "#2962ff", "VAH");
      drawVaLine(vp.valIndex, "#2962ff", "VAL");
    }
  }

  if (hasLiquidityTrendline) {
    const lt = buildLiquidityTrendlineSignals(candles, {
      len: 5,
      space: 2,
      colorUp: "#0044ff",
      colorDown: "#ff2b00",
    });

    const drawChannel = (channel) => {
      const renderEnd = channel.liveEndIndex ?? channel.endIndex;
      if (renderEnd < start || channel.startIndex > end - 1) return;
      const levelAt = (base, bars) => base + (channel.slope * bars);
      const startX = leftPad + ((Math.max(start, channel.startIndex) - start) * slotW) + (slotW / 2);
      const endX = leftPad + ((Math.min(end - 1, renderEnd) - start) * slotW) + (slotW / 2);
      const topStartPrice = levelAt(channel.top1, Math.max(start, channel.startIndex) - channel.startIndex);
      const topEndPrice = levelAt(channel.top1, Math.min(end - 1, renderEnd) - channel.startIndex);
      const bottomStartPrice = levelAt(channel.bottom1, Math.max(start, channel.startIndex) - channel.startIndex);
      const bottomEndPrice = levelAt(channel.bottom1, Math.min(end - 1, renderEnd) - channel.startIndex);
      ctx.save();
      ctx.strokeStyle = channel.color;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(startX, toY(topStartPrice));
      ctx.lineTo(endX, toY(topEndPrice));
      ctx.stroke();
      ctx.beginPath();
      ctx.moveTo(startX, toY(bottomStartPrice));
      ctx.lineTo(endX, toY(bottomEndPrice));
      ctx.stroke();
      ctx.fillStyle = channel.direction === "UPPER" ? "rgba(255,43,0,0.18)" : "rgba(0,68,255,0.18)";
      ctx.beginPath();
      ctx.moveTo(startX, toY(topStartPrice));
      ctx.lineTo(endX, toY(topEndPrice));
      ctx.lineTo(endX, toY(bottomEndPrice));
      ctx.lineTo(startX, toY(bottomStartPrice));
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    };

    lt.upperChannels.slice(-3).forEach(drawChannel);
    lt.lowerChannels.slice(-3).forEach(drawChannel);

    lt.signals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isUp = signal.type === "UP";
      const y = isUp ? toY(candles[signal.entryIndex].low) + 10 : toY(candles[signal.entryIndex].high) - 10;
      ctx.save();
      ctx.fillStyle = signal.color;
      ctx.beginPath();
      if (isUp) {
        ctx.moveTo(x, y - 6);
        ctx.lineTo(x - 5, y + 4);
        ctx.lineTo(x + 5, y + 4);
      } else {
        ctx.moveTo(x, y + 6);
        ctx.lineTo(x - 5, y - 4);
        ctx.lineTo(x + 5, y - 4);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });
  }

  if (hasStructurePullback) {
    const spc = buildStructurePullbackContinuation(candles, {
      pivotLen: 4,
      pullbackLookback: 4,
      weakBodyRatio: 0.4,
      rejectionWickRatio: 0.45,
      maxTrendFlips: 4,
      flipLookback: 30,
    });

    spc.trendMarks.slice(-10).forEach((mark) => {
      if (mark.index < start || mark.index >= end || !mark.type) return;
      const x = leftPad + ((mark.index - start) * slotW) + (slotW / 2);
      const y = toY(mark.price);
      const color = mark.type === "HH" || mark.type === "HL" ? "#18d89f" : "#ff6a4d";
      ctx.save();
      ctx.fillStyle = color;
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = mark.type === "HH" || mark.type === "LH" ? "bottom" : "top";
      ctx.fillText(mark.type, x, mark.type === "HH" || mark.type === "LH" ? y - 4 : y + 4);
      ctx.restore();
    });

    spc.signals.forEach((signal) => {
      if (signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isBuy = signal.direction === "BUY";
      const anchorY = isBuy ? toY(candles[signal.entryIndex].low) + 14 : toY(candles[signal.entryIndex].high) - 14;
      const color = isBuy ? "#18d89f" : "#ff6a4d";
      const boxW = 16;
      const boxH = 12;
      const boxX = x - (boxW / 2);
      const boxY = isBuy ? anchorY + 8 : anchorY - boxH - 8;

      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = "rgba(15, 18, 24, 0.95)";
      ctx.lineWidth = 1.4;
      ctx.beginPath();
      ctx.moveTo(x, isBuy ? anchorY + 3 : anchorY - 3);
      ctx.lineTo(x, isBuy ? boxY : boxY + boxH);
      ctx.stroke();
      ctx.beginPath();
      ctx.roundRect(boxX, boxY, boxW, boxH, 4);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = color;
      ctx.font = "bold 9px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(isBuy ? "PB" : "PS", x, boxY + (boxH / 2) + 0.5);

      ctx.font = "8px Segoe UI, sans-serif";
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, anchorY - 3);
        ctx.lineTo(x - 5, anchorY + 5);
        ctx.lineTo(x + 5, anchorY + 5);
      } else {
        ctx.moveTo(x, anchorY + 3);
        ctx.lineTo(x - 5, anchorY - 5);
        ctx.lineTo(x + 5, anchorY - 5);
      }
      ctx.closePath();
      ctx.fill();
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(
        signal.reason === "failure" ? "F" : signal.reason === "rejection" ? "R" : "C",
        x,
        isBuy ? boxY + boxH + 2 : boxY - 2,
      );
      ctx.restore();
    });

    ctx.save();
    ctx.fillStyle = "#c4ccd7";
    ctx.font = "9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(`B ${spc.stats.buy.wins}/${spc.stats.buy.total}`, leftPad + 4, topPad + 4);
    ctx.fillText(`S ${spc.stats.sell.wins}/${spc.stats.sell.total}`, leftPad + 4, topPad + 16);
    ctx.restore();
  }

  if (hasSRSignalsMTF) {
    const sr = buildSupportResistanceSignalsMTF(candles, {
      length: 6,
      zoneAtrMult: 0.5,
      securityAtrMult: 0,
      manipulationMult: 1.3,
      maxActive: 5,
      showBroken: true,
      extendActive: true,
    });

    const drawZone = (zone, lineColor, fillColor) => {
      const localStart = Math.max(0, zone.startIndex - start);
      const localEnd = Math.min(points.length - 1, zone.drawEndIndex - start);
      if (localEnd < 0 || localStart > points.length - 1) return;
      const x = leftPad + (localStart * slotW);
      const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
      const topY = toY(zone.top);
      const bottomY = toY(zone.bottom);
      const lineY = toY(zone.linePrice);
      ctx.save();
      ctx.fillStyle = fillColor;
      ctx.strokeStyle = lineColor;
      ctx.lineWidth = 1.2;
      ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
      ctx.beginPath();
      ctx.moveTo(x, lineY);
      ctx.lineTo(x + w, lineY);
      ctx.stroke();
      ctx.restore();
    };

    sr.resistances.slice(-4).forEach((zone) => drawZone(zone, "rgba(242, 54, 69, 0.70)", "rgba(242, 54, 69, 0.18)"));
    sr.supports.slice(-4).forEach((zone) => drawZone(zone, "rgba(8, 153, 129, 0.70)", "rgba(8, 153, 129, 0.18)"));

    sr.manipulations.forEach((zone) => {
      const localStart = Math.max(0, zone.startIndex - start);
      const localEnd = Math.min(points.length - 1, zone.endIndex - start);
      if (localEnd < 0 || localStart > points.length - 1) return;
      const x = leftPad + (localStart * slotW);
      const w = Math.max(slotW, (localEnd - localStart + 1) * slotW);
      const topY = toY(zone.top);
      const bottomY = toY(zone.bottom);
      ctx.save();
      ctx.fillStyle = zone.type === "support" ? "rgba(41, 98, 255, 0.22)" : "rgba(255, 152, 0, 0.22)";
      ctx.fillRect(x, topY, w, Math.max(2, bottomY - topY));
      ctx.restore();
    });

    sr.signals.forEach((signal) => {
      if (signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isBuy = signal.direction === "BUY";
      const anchorY = isBuy ? toY(candles[signal.entryIndex].low) + 12 : toY(candles[signal.entryIndex].high) - 12;
      const color = isBuy ? "#089981" : "#f23645";
      const label = signal.kind === "break" ? "B" : signal.kind === "test" ? "T" : signal.kind === "retest" ? "R" : "P";

      ctx.save();
      ctx.fillStyle = color;
      ctx.strokeStyle = color;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, anchorY - 7);
        ctx.lineTo(x - 5, anchorY + 3);
        ctx.lineTo(x + 5, anchorY + 3);
      } else {
        ctx.moveTo(x, anchorY + 7);
        ctx.lineTo(x - 5, anchorY - 3);
        ctx.lineTo(x + 5, anchorY - 3);
      }
      ctx.closePath();
      ctx.fill();
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(label, x, isBuy ? anchorY + 6 : anchorY - 6);
      ctx.restore();
    });

    ctx.save();
    ctx.fillStyle = "#c4ccd7";
    ctx.font = "9px Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "top";
    ctx.fillText(`Sup ${sr.stats.activeSupports}/${sr.stats.totalSupports}`, leftPad + 4, topPad + 4);
    ctx.fillText(`Res ${sr.stats.activeResistances}/${sr.stats.totalResistances}`, leftPad + 4, topPad + 16);
    ctx.fillText(`Sw ${sr.stats.supportSweeps + sr.stats.resistanceSweeps}`, leftPad + 4, topPad + 28);
    ctx.restore();
  }

  if (hasTickRejection) {
    const rejection = buildTickRejectionMicrostructure(candles, {
      ticksLookback: 5,
      minRejectionRatio: 0.5,
      minRange: Math.max(currentPip || 0.0001, 0.0001),
    });

    rejection.rejectionCandles.forEach((micro) => {
      if (micro.sourceIndex < start || micro.sourceIndex >= end) return;
      const visibleIndex = micro.sourceIndex - start;
      const centerX = leftPad + (visibleIndex * slotW) + (slotW / 2);
      const bodyWidth = Math.max(4, Math.min(candleW - 1, Math.floor(slotW * 0.38)));
      const wickX = centerX;
      const openY = toY(micro.open);
      const closeY = toY(micro.close);
      const highY = toY(micro.high);
      const lowY = toY(micro.low);
      const topY = Math.min(openY, closeY);
      const bodyH = Math.max(2, Math.abs(closeY - openY));
      const isBull = micro.type === "lower";
      const stroke = isBull ? "#18d89f" : "#ff5b6b";
      const fill = isBull ? "rgba(24, 216, 159, 0.20)" : "rgba(255, 91, 107, 0.20)";

      ctx.save();
      ctx.strokeStyle = stroke;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(wickX, highY);
      ctx.lineTo(wickX, lowY);
      ctx.stroke();

      ctx.fillStyle = fill;
      ctx.strokeStyle = stroke;
      ctx.fillRect(centerX - (bodyWidth / 2), topY, bodyWidth, bodyH);
      ctx.strokeRect(centerX - (bodyWidth / 2), topY, bodyWidth, bodyH);

      ctx.fillStyle = stroke;
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBull ? "top" : "bottom";
      ctx.fillText(isBull ? "R↑" : "R↓", centerX, isBull ? lowY + 6 : highY - 6);
      ctx.restore();
    });

    rejection.signals.forEach((signal) => {
      if (signal.entryIndex == null || signal.entryIndex < start || signal.entryIndex >= end) return;
      const visibleIndex = signal.entryIndex - start;
      const centerX = leftPad + (visibleIndex * slotW) + (slotW / 2);
      const isBull = signal.type === "lower";
      const anchorY = isBull ? toY(candles[signal.entryIndex].low) + 11 : toY(candles[signal.entryIndex].high) - 11;
      const color = isBull ? "#18d89f" : "#ff5b6b";

      ctx.save();
      ctx.strokeStyle = color;
      ctx.fillStyle = color;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(centerX, isBull ? anchorY - 12 : anchorY + 12);
      ctx.lineTo(centerX, isBull ? anchorY - 2 : anchorY + 2);
      ctx.stroke();
      ctx.beginPath();
      if (isBull) {
        ctx.moveTo(centerX, anchorY - 12);
        ctx.lineTo(centerX - 5, anchorY - 4);
        ctx.lineTo(centerX + 5, anchorY - 4);
      } else {
        ctx.moveTo(centerX, anchorY + 12);
        ctx.lineTo(centerX - 5, anchorY + 4);
        ctx.lineTo(centerX + 5, anchorY + 4);
      }
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    });
  }

  if (hasTrendVolumeAccum) {
    const tva = buildTrendVolumeAccumulation(candles, {
      useMovingAverage: false,
      maType: "EMA",
      maLen: 6,
      mode: "Accumulation",
    });
    const visibleValues = [];
    for (let i = start; i < end; i += 1) {
      const value = tva.values[i];
      if (Number.isFinite(value)) visibleValues.push(value);
    }
    if (visibleValues.length) {
      const maxAbs = Math.max(1, ...visibleValues.map((value) => Math.abs(value)));
      const paneH = Math.max(42, Math.min(70, plotH * 0.26));
      const paneBottom = height - bottomPad - 2;
      const paneTop = paneBottom - paneH;
      const zeroY = paneTop + (paneH / 2);

      ctx.save();
      ctx.fillStyle = "rgba(12, 16, 22, 0.68)";
      ctx.fillRect(leftPad, paneTop, plotW, paneH);
      ctx.strokeStyle = "rgba(52, 62, 78, 0.85)";
      ctx.lineWidth = 1;
      ctx.strokeRect(leftPad, paneTop, plotW, paneH);
      ctx.setLineDash([4, 3]);
      ctx.beginPath();
      ctx.moveTo(leftPad, zeroY);
      ctx.lineTo(leftPad + plotW, zeroY);
      ctx.stroke();
      ctx.setLineDash([]);

      for (let i = start; i < end; i += 1) {
        const value = tva.values[i];
        if (!Number.isFinite(value)) continue;
        const x = leftPad + ((i - start) * slotW) + candleGap / 2;
        const barHeight = Math.max(1, (Math.abs(value) / maxAbs) * ((paneH / 2) - 4));
        const y = value >= 0 ? zeroY - barHeight : zeroY;
        ctx.fillStyle = value >= 0 ? "rgba(13, 183, 135, 0.82)" : "rgba(225, 91, 100, 0.82)";
        ctx.fillRect(x, y, Math.max(2, candleW), barHeight);
      }

      ctx.fillStyle = "#c4ccd7";
      ctx.font = "9px Segoe UI, sans-serif";
      ctx.textAlign = "left";
      ctx.textBaseline = "top";
      ctx.fillText("TVA", leftPad + 4, paneTop + 4);
      const lastValue = tva.values[end - 1];
      if (Number.isFinite(lastValue)) {
        ctx.textAlign = "right";
        ctx.fillText(`${lastValue >= 0 ? "+" : ""}${Math.round(lastValue)}`, leftPad + plotW - 4, paneTop + 4);
      }
      ctx.restore();
    }
  }

  if (hasChartPatterns) {
    const cp = buildChartPatternsSignals(candles, {
      pivotLen: 3,
      toleranceMult: 0.45,
      maxPatternAge: 60,
    });

    cp.patterns.forEach((pattern) => {
      ctx.save();
      pattern.lines.forEach((segment) => {
        const x1 = leftPad + ((segment.a.index - start) * slotW) + (slotW / 2);
        const x2 = leftPad + ((segment.b.index - start) * slotW) + (slotW / 2);
        if (x1 < leftPad - slotW || x2 > width - rightPad + slotW) return;
        const y1 = toY(segment.a.price);
        const y2 = toY(segment.b.price);
        ctx.strokeStyle = segment.kind === "neck"
          ? "rgba(240, 240, 245, 0.85)"
          : pattern.direction === "BUY"
            ? "rgba(24, 216, 159, 0.80)"
            : "rgba(255, 106, 77, 0.80)";
        ctx.lineWidth = segment.kind === "neck" ? 1 : 1.2;
        if (segment.kind === "neck") ctx.setLineDash([4, 3]);
        ctx.beginPath();
        ctx.moveTo(x1, y1);
        ctx.lineTo(x2, y2);
        ctx.stroke();
        ctx.setLineDash([]);
      });

      if (pattern.breakIndex >= start && pattern.breakIndex < end) {
        const labelX = leftPad + ((pattern.breakIndex - start) * slotW) + (slotW / 2);
        const labelY = pattern.direction === "BUY"
          ? toY(candles[pattern.breakIndex].low) - 10
          : toY(candles[pattern.breakIndex].high) + 10;
        ctx.fillStyle = pattern.direction === "BUY" ? "#18d89f" : "#ff6a4d";
        ctx.font = "8px Segoe UI, sans-serif";
        ctx.textAlign = "center";
        ctx.textBaseline = pattern.direction === "BUY" ? "bottom" : "top";
        ctx.fillText(pattern.label, labelX, labelY);
      }
      ctx.restore();
    });

    cp.signals.forEach((signal) => {
      if (signal.entryIndex < start || signal.entryIndex >= end) return;
      const x = leftPad + ((signal.entryIndex - start) * slotW) + (slotW / 2);
      const isBuy = signal.direction === "BUY";
      const anchorY = isBuy ? toY(candles[signal.entryIndex].low) + 12 : toY(candles[signal.entryIndex].high) - 12;
      const color = isBuy ? "#18d89f" : "#ff6a4d";
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      if (isBuy) {
        ctx.moveTo(x, anchorY - 7);
        ctx.lineTo(x - 5, anchorY + 3);
        ctx.lineTo(x + 5, anchorY + 3);
      } else {
        ctx.moveTo(x, anchorY + 7);
        ctx.lineTo(x - 5, anchorY - 3);
        ctx.lineTo(x + 5, anchorY - 3);
      }
      ctx.closePath();
      ctx.fill();
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isBuy ? "top" : "bottom";
      ctx.fillText(signal.label, x, isBuy ? anchorY + 6 : anchorY - 6);
      ctx.restore();
    });
  }

  if (hasChannelsPatterns) {
    const cwp = buildChannelsWithPatterns(candles, {});
    const xForIndex = (index) => leftPad + ((index - start) * slotW) + (slotW / 2);
    const channelY = (channel, key, index) => {
      const dx = Math.max(1, channel.end - channel.start);
      const value = channel[`${key}1`] + (((channel[`${key}2`] - channel[`${key}1`]) / dx) * (index - channel.start));
      return toY(value);
    };
    const strokeChannelLine = (channel, key, color, widthValue = 1, dash = []) => {
      const visibleStart = Math.max(start, channel.start);
      const visibleEnd = Math.min(end - 1, channel.end);
      if (visibleEnd <= visibleStart) return;
      const x1 = xForIndex(visibleStart);
      const x2 = xForIndex(visibleEnd);
      const y1 = channelY(channel, key, visibleStart);
      const y2 = channelY(channel, key, visibleEnd);
      if (!Number.isFinite(y1) || !Number.isFinite(y2)) return;
      ctx.save();
      ctx.strokeStyle = color;
      ctx.lineWidth = widthValue;
      ctx.setLineDash(dash);
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
      ctx.restore();
    };
    const fillChannelBand = (channel, upperKey, lowerKey, color) => {
      const visibleStart = Math.max(start, channel.start);
      const visibleEnd = Math.min(end - 1, channel.end);
      if (visibleEnd <= visibleStart) return;
      const x1 = xForIndex(visibleStart);
      const x2 = xForIndex(visibleEnd);
      const upperY1 = channelY(channel, upperKey, visibleStart);
      const upperY2 = channelY(channel, upperKey, visibleEnd);
      const lowerY1 = channelY(channel, lowerKey, visibleStart);
      const lowerY2 = channelY(channel, lowerKey, visibleEnd);
      if (![upperY1, upperY2, lowerY1, lowerY2].every(Number.isFinite)) return;
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.moveTo(x1, upperY1);
      ctx.lineTo(x2, upperY2);
      ctx.lineTo(x2, lowerY2);
      ctx.lineTo(x1, lowerY1);
      ctx.closePath();
      ctx.fill();
      ctx.restore();
    };

    cwp.channels.forEach((channel) => {
      fillChannelBand(channel, "top", "midTop", "rgba(51, 124, 79, 0.18)");
      fillChannelBand(channel, "midBottom", "bottom", "rgba(165, 45, 45, 0.18)");
      strokeChannelLine(channel, "top", "rgba(51, 124, 79, 0.88)", 1.1);
      strokeChannelLine(channel, "midTop", "rgba(51, 124, 79, 0.62)", 1);
      strokeChannelLine(channel, "center", "rgba(185, 190, 200, 0.72)", 1, [5, 4]);
      strokeChannelLine(channel, "midBottom", "rgba(165, 45, 45, 0.62)", 1);
      strokeChannelLine(channel, "bottom", "rgba(165, 45, 45, 0.88)", 1.1);
    });

    cwp.breaks.forEach((signal) => {
      if (signal.index < start || signal.index >= end) return;
      const x = xForIndex(signal.index);
      const isUp = signal.direction === "UP";
      const y = isUp ? toY(candles[signal.index].low) + 12 : toY(candles[signal.index].high) - 12;
      ctx.save();
      ctx.fillStyle = isUp ? "#337c4f" : "#a52d2d";
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = isUp ? "top" : "bottom";
      ctx.fillText(isUp ? "Break Up" : "Break Down", x, y);
      ctx.restore();
    });

    cwp.labels.forEach((label) => {
      if (label.index < start || label.index >= end) return;
      const x = xForIndex(label.index);
      const isBottom = label.side === "bottom";
      const y = isBottom ? toY(candles[label.index].low) + 12 : toY(candles[label.index].high) - 12;
      const color = label.kind === "ihammer"
        ? "rgba(45, 63, 165, 0.88)"
        : isBottom
          ? "rgba(51, 124, 79, 0.88)"
          : "rgba(165, 45, 45, 0.88)";
      const boxW = Math.max(16, ctx.measureText(label.text).width + 8);
      const boxH = 14;
      const boxX = x - (boxW / 2);
      const boxY = isBottom ? y : y - boxH;
      ctx.save();
      ctx.fillStyle = color;
      ctx.beginPath();
      ctx.roundRect(boxX, boxY, boxW, boxH, 4);
      ctx.fill();
      ctx.fillStyle = "#efefef";
      ctx.font = "8px Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText(label.text, x, boxY + (boxH / 2));
      ctx.restore();
    });
  }

  renderTradeChartMarkers(ctx, chartViewportState);
  renderTradeSetupPreview(ctx, chartViewportState);
  renderChartDrawings(ctx, chartViewportState);

  // Current price dot and right-side labels
  if (points.length >= 2) {
    const last = points[points.length - 1];
    const prev = points[points.length - 2];
    const lastY = height - bottomPad - ((last.close - min) / (max - min)) * (height - topPad - bottomPad);
    const lastX = width - rightPad;

    let dotColor = "#0db787";
    if (last.close > prev.high) dotColor = "#2d8cff";
    else if (last.close < prev.low) dotColor = "#e15b64";

    ctx.strokeStyle = dotColor;
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.moveTo(leftPad, lastY);
    ctx.lineTo(width - rightPad, lastY);
    ctx.stroke();

    ctx.fillStyle = dotColor;
    ctx.beginPath();
    ctx.arc(lastX, lastY, 2.2, 0, Math.PI * 2);
    ctx.fill();

    const highY = height - bottomPad - ((prev.high - min) / (max - min)) * (height - topPad - bottomPad);
    const lowY = height - bottomPad - ((prev.low - min) / (max - min)) * (height - topPad - bottomPad);
    const axisLeft = width - rightPad + 6;
    const labelX = axisLeft + 8;
    ctx.fillStyle = "#9aa7b8";
    ctx.font = "10px Inter, Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const diff =
      last.close > prev.high ? last.close - prev.high :
      last.close < prev.low ? prev.low - last.close : 0;
    const priceLabel = `${formatPrice(last.close, currentPip)}`;
    const diffLabel = diff > 0 ? `Δ ${formatPrice(diff, currentPip)}` : "Δ 0";
    const candleEndTime = Number(last.time) + Math.max(1, Number(candleBuilder?.timeframe || DEFAULT_TIMEFRAME_SEC || 60));
    const candleEndLabel = Number.isFinite(candleEndTime) ? `end ${formatCountdown(candleEndTime)}` : "";
    const priceW = Math.max(54, ctx.measureText(priceLabel).width + 16);
    const priceH = 18;
    const priceBoxX = axisLeft;
    const priceBoxY = clamp(lastY - priceH / 2, topPad, height - bottomPad - priceH - (candleEndLabel ? 28 : 0));

    ctx.save();
    ctx.fillStyle = dotColor;
    ctx.beginPath();
    ctx.roundRect(priceBoxX, priceBoxY, priceW, priceH, 6);
    ctx.fill();
    ctx.fillStyle = "#ffffff";
    ctx.fillText(priceLabel, priceBoxX + 8, priceBoxY + priceH / 2);
    ctx.restore();

    ctx.fillStyle = dotColor;
    const diffY = clamp(priceBoxY + priceH + 10, topPad + 8, height - bottomPad - (candleEndLabel ? 22 : 8));
    let activeDiffY = diffY;
    if (Math.abs(diffY - highY) < 10 || Math.abs(diffY - lowY) < 10) {
      activeDiffY = clamp(lastY + 24, topPad + 8, height - bottomPad - (candleEndLabel ? 22 : 8));
    } else {
      activeDiffY = diffY;
    }
    ctx.fillText(diffLabel, labelX, activeDiffY);
    if (candleEndLabel) {
      ctx.fillStyle = "#9aa7b8";
      ctx.fillText(candleEndLabel, labelX, clamp(activeDiffY + 14, topPad + 20, height - bottomPad - 8));
    }
  }

  if (chartCrosshairEnabled && chartCrosshairState?.active && chartViewportState) {
    const crossX = clamp(chartCrosshairState.x, leftPad, width - rightPad);
    const crossY = clamp(chartCrosshairState.y, topPad, height - bottomPad);
    const crossPrice = max - ((crossY - topPad) / Math.max(1, plotH)) * (max - min);

    ctx.save();
    ctx.strokeStyle = "rgba(168, 180, 201, 0.42)";
    ctx.lineWidth = 1;
    ctx.setLineDash([4, 4]);
    ctx.beginPath();
    ctx.moveTo(leftPad, crossY);
    ctx.lineTo(width - rightPad, crossY);
    ctx.moveTo(crossX, topPad);
    ctx.lineTo(crossX, height - bottomPad);
    ctx.stroke();
    ctx.setLineDash([]);

    const axisLeft = width - rightPad + 6;
    const crossPriceLabel = formatPrice(crossPrice, currentPip);
    ctx.font = "10px Inter, Segoe UI, sans-serif";
    ctx.textAlign = "left";
    ctx.textBaseline = "middle";
    const boxW = Math.max(56, ctx.measureText(crossPriceLabel).width + 16);
    const boxH = 18;
    const boxY = clamp(crossY - boxH / 2, topPad, height - bottomPad - boxH);
    ctx.fillStyle = "#2d333d";
    ctx.beginPath();
    ctx.roundRect(axisLeft, boxY, boxW, boxH, 6);
    ctx.fill();
    ctx.fillStyle = "#ffffff";
    ctx.fillText(crossPriceLabel, axisLeft + 8, boxY + boxH / 2);

    if (Number.isInteger(chartCrosshairState.candleIndex)) {
      const candle = candles[chartCrosshairState.candleIndex];
      if (candle?.time) {
        const crossTimeLabel = new Date(candle.time * 1000).toLocaleString([], {
          month: "short",
          day: "2-digit",
          hour: "2-digit",
          minute: "2-digit",
        });
        const timeW = Math.max(86, ctx.measureText(crossTimeLabel).width + 16);
        const timeX = clamp(crossX - (timeW / 2), leftPad, width - rightPad - timeW);
        const timeY = height - bottomPad + 6;
        ctx.fillStyle = "#2d333d";
        ctx.beginPath();
        ctx.roundRect(timeX, timeY, timeW, 18, 6);
        ctx.fill();
        ctx.fillStyle = "#ffffff";
        ctx.textAlign = "center";
        ctx.fillText(crossTimeLabel, timeX + timeW / 2, timeY + 9);
      }
    }
    ctx.restore();
  }

  if (replayEngine.isSelectingCandle() && chartViewportState) {
    const selectionIndex = Number.isInteger(replaySelectionState?.index)
      ? replaySelectionState.index
      : start + Math.floor(points.length / 2);
    if (selectionIndex >= start && selectionIndex < end) {
      const selectionX = leftPad + ((selectionIndex - start) * slotW) + (slotW / 2);
      const candle = candles[selectionIndex];
      const timeLabel = candle?.time
        ? new Date(candle.time * 1000).toLocaleString([], { month: "short", day: "2-digit", hour: "2-digit", minute: "2-digit" })
        : "Select bar";
      updateReplayAxisDateBadge(timeLabel);
      ctx.save();
      ctx.strokeStyle = "#2f6dff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.moveTo(selectionX, topPad);
      ctx.lineTo(selectionX, height - bottomPad);
      ctx.stroke();
      ctx.fillStyle = "#0f141c";
      ctx.strokeStyle = "#ffffff";
      ctx.lineWidth = 2;
      ctx.beginPath();
      ctx.arc(selectionX, topPad + (plotH * 0.52), 9, 0, Math.PI * 2);
      ctx.fill();
      ctx.stroke();
      ctx.fillStyle = "#ffffff";
      ctx.font = "bold 12px Inter, Segoe UI, sans-serif";
      ctx.textAlign = "center";
      ctx.textBaseline = "middle";
      ctx.fillText("R", selectionX, topPad + (plotH * 0.52) + 0.5);
      ctx.restore();
    }
  }

  const current = points[points.length - 1];
  const candleSize = current ? Math.abs(current.close - current.open) : 0;
  const sizeLabel = `Body ${formatPrice(candleSize, currentPip)}`;
  ctx.fillStyle = "#9aa7b8";
  ctx.font = "10px Inter, Segoe UI, sans-serif";
  ctx.textAlign = "right";
  ctx.textBaseline = "bottom";
  ctx.fillText(sizeLabel, width - rightPad - 8, height - bottomPad - 8);
}

function getLiveBuiltCandles() {
  return candleBuilder.currentCandle
    ? [...candleBuilder.candles, candleBuilder.currentCandle]
    : candleBuilder.candles;
}

function getBuiltCandles() {
  return replayEngine.isReplayMode() ? replayEngine.getVisibleCandles() : getLiveBuiltCandles();
}

function pauseLiveTicksForReplay() {
  if (!tickStreamId || !ws || ws.readyState !== WebSocket.OPEN) return;
  try {
    ws.send(JSON.stringify({ forget: tickStreamId }));
  } catch {
    // Ignore forget failures; the tick handler still blocks replay updates.
  }
  tickStreamId = null;
  lastTickAt = 0;
}

function formatReplayCandleTime(candle) {
  const seconds = Number(candle?.time);
  if (!Number.isFinite(seconds)) return "--";
  return new Date(seconds * 1000).toLocaleString([], {
    month: "short",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
  });
}

function hideReplayAxisDateBadge() {
  if (!replayAxisDateEl) return;
  replayAxisDateEl.classList.add("hidden");
  replayAxisDateEl.setAttribute("aria-hidden", "true");
}

function updateReplayAxisDateBadge(label) {
  if (!replayAxisDateEl || !label) return;
  replayAxisDateEl.textContent = label;
  replayAxisDateEl.classList.remove("hidden");
  replayAxisDateEl.setAttribute("aria-hidden", "false");
}

function syncReplayUI(statusText = "") {
  const enabled = replayEngine.isReplayMode();
  replayToolbarEl?.classList.toggle("hidden", !enabled);
  replayToggleBtn?.classList.toggle("replay-active", enabled);
  replayToggleBtn?.classList.toggle("active", enabled);
  replayToggleBtn?.setAttribute("aria-pressed", enabled ? "true" : "false");
  if (replayPlayPauseBtn) {
    replayPlayPauseBtn.textContent = replayEngine.playing ? "Pause" : "Play";
    replayPlayPauseBtn.setAttribute("aria-label", replayEngine.playing ? "Pause replay" : "Play replay");
  }
  if (replaySpeedSelectEl) replaySpeedSelectEl.value = String(replayEngine.speed);
  if (replaySelectAgainBtn) replaySelectAgainBtn.disabled = !enabled;
  if (replayPrevBtn) replayPrevBtn.disabled = !enabled || replayEngine.currentIndex <= 0;
  if (replayNextBtn) replayNextBtn.disabled = !enabled || replayEngine.currentIndex >= replayEngine.fullCandles.length - 1;
  const selectedIndex = replayEngine.isSelectingCandle() && Number.isInteger(replaySelectionState?.index)
    ? replaySelectionState.index
    : replayEngine.currentIndex;
  const current = replayEngine.fullCandles[selectedIndex];
  if (enabled) updateReplayAxisDateBadge(formatReplayCandleTime(current));
  else hideReplayAxisDateBadge();
  if (replayStatusEl) {
    const selectText = replayEngine.isSelectingCandle() ? "Select candle on chart" : statusText;
    replayStatusEl.textContent = enabled
      ? `${selectText || "Replay"} • ${selectedIndex + 1}/${replayEngine.fullCandles.length} • ${formatReplayCandleTime(current)}`
      : "Replay off";
  }
}

function getReplayIndexFromPointer(localX) {
  if (!chartViewportState || !replayEngine.isReplayMode()) return null;
  const relativeX = localX - chartViewportState.leftPad;
  const slot = Math.floor(relativeX / Math.max(1, chartViewportState.slotW));
  if (!Number.isFinite(slot)) return null;
  const index = chartViewportState.start + slot;
  return clamp(index, 0, Math.max(0, replayEngine.fullCandles.length - 1));
}

function updateReplaySelectionFromPointer(event) {
  if (!miniChartCanvas || !replayEngine.isSelectingCandle()) return null;
  const rect = miniChartCanvas.getBoundingClientRect();
  const axisThreshold = Math.max(58, miniChartCanvas.clientWidth - 88);
  const localX = event.clientX - rect.left;
  if (localX >= axisThreshold) return null;
  const replayIndex = getReplayIndexFromPointer(localX);
  if (replayIndex == null) return null;
  replaySelectionState = { index: replayIndex, x: localX };
  miniChartCanvas.style.cursor = "crosshair";
  renderMiniChart(getBuiltCandles());
  return replayIndex;
}

function commitReplaySelectionFromPointer(event) {
  const replayIndex = updateReplaySelectionFromPointer(event);
  if (replayIndex == null && Number.isInteger(replaySelectionState?.index)) {
    replayEngine.jumpToIndex(replaySelectionState.index);
    return true;
  }
  if (replayIndex != null) {
    replayEngine.jumpToIndex(replayIndex);
    return true;
  }
  return false;
}

function getChartOffsetBounds(candles) {
  const built = Array.isArray(candles) ? candles : getBuiltCandles();
  return {
    min: -MAX_FUTURE_BARS,
    max: Math.max(0, built.length - chartPoints),
  };
}

function getVisibleChartWindow(candles) {
  const built = Array.isArray(candles) ? candles : getBuiltCandles();
  const { min, max } = getChartOffsetBounds(built);
  chartOffset = clamp(chartOffset, min, max);

  const futureBars = Math.max(0, -chartOffset);
  const historicalOffset = Math.max(0, chartOffset);
  const visibleBars = Math.max(1, chartPoints - futureBars);
  const end = built.length - historicalOffset;
  const start = Math.max(0, end - visibleBars);
  const points = built.slice(start, end);
  const visibleSlotCount = Math.max(chartPoints, points.length + futureBars, 1);

  return { points, start, end, futureBars, visibleSlotCount };
}

function updateCrosshairToggleUI() {
  if (!toggleCrosshairBtn) return;
  toggleCrosshairBtn.classList.toggle("active", chartCrosshairEnabled);
  toggleCrosshairBtn.setAttribute("aria-pressed", chartCrosshairEnabled ? "true" : "false");
  syncChart2MobileToolbar();
}

function ensureCrosshairVisible() {
  const built = getBuiltCandles();
  const viewport = chartViewportState;
  if (!built.length) return;
  if (!viewport) {
    renderMiniChart(built);
  }
  const nextViewport = chartViewportState;
  if (!nextViewport || chartCrosshairState?.active) return;
  const centerX = nextViewport.leftPad + (nextViewport.plotW * 0.5);
  const centerY = nextViewport.topPad + (nextViewport.plotH * 0.5);
  const slotIndex = Math.max(0, Math.min(nextViewport.points.length - 1, Math.floor((centerX - nextViewport.leftPad) / Math.max(1, nextViewport.slotW))));
  chartCrosshairState = {
    active: true,
    x: centerX,
    y: centerY,
    candleIndex: nextViewport.points.length ? nextViewport.start + slotIndex : null,
  };
}

function setCrosshairEnabled(enabled) {
  chartCrosshairEnabled = isDesktopPointerLayout() ? true : !!enabled;
  if (!chartCrosshairEnabled) chartCrosshairState = null;
  else ensureCrosshairVisible();
  updateCrosshairToggleUI();
  renderMiniChart(getBuiltCandles());
}

function clearChartLongPressTimer() {
  if (!chartLongPressTimer) return;
  clearTimeout(chartLongPressTimer);
  chartLongPressTimer = null;
}

function resetChartTouchGestureState() {
  chartTouchPointers.clear();
  chartPinchStartDistance = null;
  chartPinchStartPoints = null;
  clearChartLongPressTimer();
}

function getChartTouchDistance() {
  const touches = Array.from(chartTouchPointers.values());
  if (touches.length < 2) return null;
  return Math.hypot(touches[0].x - touches[1].x, touches[0].y - touches[1].y);
}

function updateChartPinchZoom() {
  const distance = getChartTouchDistance();
  if (!Number.isFinite(distance) || !Number.isFinite(chartPinchStartDistance) || !Number.isFinite(chartPinchStartPoints) || chartPinchStartDistance < 8) return;
  const ratio = distance / chartPinchStartDistance;
  if (!Number.isFinite(ratio) || ratio <= 0) return;
  setChartHorizontalPoints(chartPinchStartPoints / ratio);
}

function updateChartCrosshairFromPointer(event) {
  if (!miniChartCanvas || !chartViewportState) return;
  const rect = miniChartCanvas.getBoundingClientRect();
  const { leftPad, rightPad, topPad, bottomPad, slotW, start, points, width, height } = chartViewportState;
  const localX = clamp(event.clientX - rect.left, leftPad, width - rightPad);
  const localY = clamp(event.clientY - rect.top, topPad, height - bottomPad);
  const slotIndex = Math.max(0, Math.floor((localX - leftPad) / Math.max(1, slotW)));
  const candleIndex = slotIndex < points.length ? start + slotIndex : null;
  chartCrosshairState = {
    active: true,
    x: localX,
    y: localY,
    candleIndex,
  };
  renderMiniChart(getBuiltCandles());
}

function moveSelectedDrawingToPoint(point) {
  const drawing = getSelectedChartDrawing();
  if (!drawing || drawing.locked || !point) return false;
  if (!chartDrawingMoveOrigin) {
    chartDrawingMoveOrigin = {
      pointerTime: point.time,
      pointerPrice: point.price,
      drawing,
    };
  }
  const origin = chartDrawingMoveOrigin;
  const timeDelta = snapChartTime(point.time - origin.pointerTime);
  const priceDelta = point.price - origin.pointerPrice;
  const next = {
    ...origin.drawing,
    start: {
      ...origin.drawing.start,
      time: snapChartTime(origin.drawing.start.time + timeDelta),
      price: origin.drawing.start.price + priceDelta,
    },
  };
  if (origin.drawing.end) {
    next.end = {
      ...origin.drawing.end,
      time: snapChartTime(origin.drawing.end.time + timeDelta),
      price: origin.drawing.end.price + priceDelta,
    };
  }
  if (origin.drawing.position) {
    next.position = {
      ...origin.drawing.position,
      targetPrice: Number.isFinite(origin.drawing.position.targetPrice) ? origin.drawing.position.targetPrice + priceDelta : origin.drawing.position.targetPrice,
      stopPrice: Number.isFinite(origin.drawing.position.stopPrice) ? origin.drawing.position.stopPrice + priceDelta : origin.drawing.position.stopPrice,
    };
  }
  return updateChartDrawing(next);
}

function getDrawingHandlePoints(drawing, viewport = chartViewportState) {
  if (!drawing || !viewport) return [];
  const x1 = getChartXForTime(drawing.start?.time, viewport);
  const y1 = viewport.toY(drawing.start?.price);
  if (!Number.isFinite(x1) || !Number.isFinite(y1)) return [];
  const handles = [{ key: "start", x: x1, y: y1 }];
  if (drawing.end) {
    const x2 = getChartXForTime(drawing.end.time, viewport);
    const y2 = viewport.toY(drawing.end.price);
    if (Number.isFinite(x2) && Number.isFinite(y2)) {
      if (drawing.tool === "LONG_POSITION" || drawing.tool === "SHORT_POSITION") {
        const isLong = drawing.tool === "LONG_POSITION";
        const legacyTargetDistance = Math.max(Math.abs((drawing.end?.price ?? drawing.start.price) - drawing.start.price), Math.abs(drawing.start.price) * 0.0001, 0.0001);
        const targetPrice = Number.isFinite(drawing.position?.targetPrice)
          ? drawing.position.targetPrice
          : isLong ? drawing.start.price + legacyTargetDistance : drawing.start.price - legacyTargetDistance;
        const stopPrice = Number.isFinite(drawing.position?.stopPrice)
          ? drawing.position.stopPrice
          : isLong ? drawing.start.price - (legacyTargetDistance / 2) : drawing.start.price + (legacyTargetDistance / 2);
        const leftX = Math.min(x1, x2);
        const rightX = Math.max(x1, x2);
        const entryY = viewport.toY(drawing.start.price);
        const targetY = viewport.toY(targetPrice);
        const stopY = viewport.toY(stopPrice);
        handles.length = 0;
        handles.push({ key: "positionEntry", x: leftX, y: entryY });
        handles.push({ key: "positionTarget", x: rightX, y: targetY });
        handles.push({ key: "positionStop", x: rightX, y: stopY });
        handles.push({ key: "positionWidth", x: rightX, y: entryY });
        return handles;
      }
      handles.push({ key: "end", x: x2, y: y2 });
      if (drawing.tool === "RECT") {
        handles.push({ key: "topRight", x: Math.max(x1, x2), y: Math.min(y1, y2) });
        handles.push({ key: "bottomLeft", x: Math.min(x1, x2), y: Math.max(y1, y2) });
      }
    }
  }
  return handles;
}

function hitTestSelectedDrawingHandle(point, viewport = chartViewportState) {
  const drawing = getSelectedChartDrawing();
  if (!drawing || drawing.locked) return null;
  const handles = getDrawingHandlePoints(drawing, viewport);
  const threshold = 18;
  for (const handle of handles) {
    if (Math.hypot(point.x - handle.x, point.y - handle.y) <= threshold) {
      return handle.key;
    }
  }
  return null;
}

function adjustSelectedDrawingHandle(point) {
  const drawing = getSelectedChartDrawing();
  if (!drawing || !chartDrawingAdjustHandle || drawing.locked || !point) return false;
  const next = { ...drawing, start: { ...drawing.start }, end: drawing.end ? { ...drawing.end } : undefined };

  if (drawing.tool === "HLINE") {
    next.start.price = point.price;
  } else if (drawing.tool === "VLINE") {
    next.start.time = snapChartTime(point.time);
  } else if (drawing.tool === "CROSSLINE") {
    next.start.time = snapChartTime(point.time);
    next.start.price = point.price;
  } else if ((drawing.tool === "LONG_POSITION" || drawing.tool === "SHORT_POSITION") && next.end) {
    const currentPosition = drawing.position || {};
    const legacyTargetDistance = Math.max(Math.abs((drawing.end?.price ?? drawing.start.price) - drawing.start.price), Math.abs(drawing.start.price) * 0.0001, 0.0001);
    const fallbackTarget = drawing.tool === "LONG_POSITION" ? drawing.start.price + legacyTargetDistance : drawing.start.price - legacyTargetDistance;
    const fallbackStop = drawing.tool === "LONG_POSITION" ? drawing.start.price - (legacyTargetDistance / 2) : drawing.start.price + (legacyTargetDistance / 2);
    next.position = {
      ...currentPosition,
      targetPrice: Number.isFinite(currentPosition.targetPrice) ? currentPosition.targetPrice : fallbackTarget,
      stopPrice: Number.isFinite(currentPosition.stopPrice) ? currentPosition.stopPrice : fallbackStop,
    };
    if (chartDrawingAdjustHandle === "positionEntry") {
      next.start.time = snapChartTime(point.time);
      next.start.price = point.price;
      next.end.price = point.price;
    } else if (chartDrawingAdjustHandle === "positionTarget") {
      next.position.targetPrice = point.price;
      next.end.time = snapChartTime(point.time);
    } else if (chartDrawingAdjustHandle === "positionStop") {
      next.position.stopPrice = point.price;
      next.end.time = snapChartTime(point.time);
    } else if (chartDrawingAdjustHandle === "positionWidth") {
      next.end.time = snapChartTime(point.time);
      next.end.price = next.start.price;
    }
  } else if (drawing.tool === "RECT" && next.end) {
    if (chartDrawingAdjustHandle === "topRight") {
      next.end.time = snapChartTime(point.time);
      next.start.price = point.price;
    } else if (chartDrawingAdjustHandle === "bottomLeft") {
      next.start.time = snapChartTime(point.time);
      next.end.price = point.price;
    } else if (chartDrawingAdjustHandle === "start") {
      next.start.time = snapChartTime(point.time);
      next.start.price = point.price;
    } else if (chartDrawingAdjustHandle === "end") {
      next.end.time = snapChartTime(point.time);
      next.end.price = point.price;
    }
  } else if (chartDrawingAdjustHandle === "start") {
    next.start.time = snapChartTime(point.time);
    next.start.price = point.price;
    if (drawing.tool === "HRAY" && next.end) {
      next.end.price = next.start.price;
    }
  } else if (next.end) {
    next.end.time = snapChartTime(point.time);
    next.end.price = drawing.tool === "HRAY" ? next.start.price : point.price;
  }

  return updateChartDrawing(next);
}

function panChartByPixels(deltaX, options = {}) {
  const built = getBuiltCandles();
  if (!miniChartCanvas || !built.length) {
    renderMiniChart(built);
    return false;
  }
  const plotWidth = Math.max(1, chartViewportState?.plotW || miniChartCanvas.clientWidth - 94);
  const slotPixels = plotWidth / Math.max(1, chartPoints);
  const pixelsPerCandle = clamp(slotPixels, 1, 22);
  const rawShiftPixels = chartPanDragRemainderX + deltaX;
  const candleShift = rawShiftPixels > 0
    ? Math.floor(rawShiftPixels / Math.max(1, pixelsPerCandle))
    : Math.ceil(rawShiftPixels / Math.max(1, pixelsPerCandle));
  chartPanDragRemainderX = rawShiftPixels - (candleShift * Math.max(1, pixelsPerCandle));
  if (!candleShift) return false;
  const { min, max } = getChartOffsetBounds(built);
  chartOffset = clamp(chartOffset + candleShift, min, max);
  if (options.render !== false) renderMiniChart(built);
  return true;
}

function getChartHorizontalZoomAnchor(clientX = null) {
  const viewport = chartViewportState;
  if (!miniChartCanvas || !viewport) return null;
  if (isTouchChartContext()) {
    return viewport.leftPad + (viewport.plotW * 0.5);
  }
  if (Number.isFinite(clientX)) {
    const rect = miniChartCanvas.getBoundingClientRect();
    return clamp(clientX - rect.left, viewport.leftPad, viewport.width - viewport.rightPad);
  }
  if (isDesktopPointerLayout() && chartCrosshairState?.active) {
    return clamp(chartCrosshairState.x, viewport.leftPad, viewport.width - viewport.rightPad);
  }
  return viewport.leftPad + (viewport.plotW * 0.5);
}

function setChartHorizontalPoints(nextPointsRaw, anchorClientX = null) {
  const built = getBuiltCandles();
  if (!miniChartCanvas || !built.length) {
    renderMiniChart(built);
    return;
  }
  if (!chartViewportState) renderMiniChart(built);
  const viewport = chartViewportState;
  if (!viewport) return;
  const maxPoints = Math.max(10, Math.min(MAX_CANDLES, built.length + MAX_FUTURE_BARS));
  const nextPoints = clamp(Math.round(nextPointsRaw), 10, maxPoints);
  if (nextPoints === chartPoints) return;

  const anchorX = getChartHorizontalZoomAnchor(anchorClientX);
  const anchorRatio = anchorX == null
    ? 0.5
    : clamp((anchorX - viewport.leftPad) / Math.max(1, viewport.plotW), 0, 1);
  const currentSlot = Math.floor(anchorRatio * Math.max(1, viewport.visibleSlotCount));
  const anchorIndex = clamp(
    viewport.start + currentSlot,
    0,
    Math.max(0, built.length - 1),
  );

  chartPoints = nextPoints;
  const anchorSlot = Math.round(anchorRatio * Math.max(1, chartPoints));
  const desiredEnd = anchorIndex + (chartPoints - anchorSlot);
  const { min, max } = getChartOffsetBounds(built);
  chartOffset = clamp(built.length - desiredEnd, min, max);

  if (chartCrosshairState?.active) {
    chartCrosshairState = {
      ...chartCrosshairState,
      x: anchorX ?? chartCrosshairState.x,
      candleIndex: anchorIndex,
    };
  }
  renderMiniChart(built);
}

function zoomChartHorizontallyByFactor(factor, anchorClientX = null) {
  if (!Number.isFinite(factor) || factor <= 0) return;
  setChartHorizontalPoints(chartPoints * factor, anchorClientX);
}

function zoomChartHorizontallyByWheel(delta, anchorClientX = null) {
  if (!Number.isFinite(delta) || delta === 0) return;
  const limitedDelta = clamp(delta, -120, 120);
  zoomChartHorizontallyByFactor(Math.exp(limitedDelta * 0.0028), anchorClientX);
}

function zoomChartHorizontallyByTimeAxisDrag(deltaX, anchorClientX = null) {
  if (!Number.isFinite(deltaX) || deltaX === 0) return;
  const limitedDelta = clamp(deltaX, -80, 80);
  zoomChartHorizontallyByFactor(Math.exp(-limitedDelta * 0.006), anchorClientX);
}

function zoomChartHorizontally(pointsDelta, anchorClientX = null) {
  const direction = Math.sign(pointsDelta);
  if (!direction) return;
  zoomChartHorizontallyByFactor(direction > 0 ? 1.08 : 1 / 1.08, anchorClientX);
}

function panChartVertically(deltaY, options = {}) {
  const built = getBuiltCandles();
  if (!miniChartCanvas || !built.length) {
    renderMiniChart(built);
    return false;
  }
  const { points } = getVisibleChartWindow(built);
  if (!points.length) return false;
  const lows = points.map((c) => c.low);
  const highs = points.map((c) => c.high);
  const range = Math.max(0.0000001, Math.max(...highs) - Math.min(...lows));
  const plotHeight = Math.max(1, chartViewportState?.plotH || miniChartCanvas.clientHeight - 40);
  chartVerticalOffset += (deltaY / plotHeight) * range;
  if (options.render !== false) renderMiniChart(built);
  return true;
}

function panChartFreely(deltaX, deltaY) {
  const movedX = panChartByPixels(deltaX, { render: false });
  const movedY = panChartVertically(deltaY, { render: false });
  if (movedX || movedY) {
    renderMiniChart(getBuiltCandles());
  }
}

function scaleChartVertically(deltaY, anchorClientY = null) {
  const built = getBuiltCandles();
  if (!miniChartCanvas || !built.length) {
    renderMiniChart(built);
    return;
  }
  const viewport = chartViewportState;
  const anchorY = Number.isFinite(anchorClientY) && miniChartCanvas
    ? anchorClientY - miniChartCanvas.getBoundingClientRect().top
    : viewport
      ? viewport.topPad + (viewport.plotH * 0.5)
      : null;
  const anchorRatio = viewport && Number.isFinite(anchorY)
    ? clamp((viewport.height - viewport.bottomPad - anchorY) / Math.max(1, viewport.plotH), 0, 1)
    : 0.5;
  const anchorPrice = viewport
    ? viewport.min + (anchorRatio * (viewport.max - viewport.min))
    : null;
  const sensitivity = 0.0048;
  const nextScale = chartVerticalScale * Math.exp((-deltaY) * sensitivity);
  chartVerticalScale = clamp(nextScale, 0.25, 12);
  if (viewport && Number.isFinite(anchorPrice)) {
    const lows = viewport.points.map((c) => c.low);
    const highs = viewport.points.map((c) => c.high);
    const rawMin = Math.min(...lows);
    const rawMax = Math.max(...highs);
    const range = Math.max(0.0000001, rawMax - rawMin);
    const rangePadding = Math.max(range * 0.08, Math.abs(rawMax) * 0.0002, 0.0000001);
    const baseSpan = range + (rangePadding * 2);
    const scaledSpan = baseSpan / chartVerticalScale;
    const baseCenter = (rawMax + rawMin) / 2;
    const desiredCenter = anchorPrice + (0.5 - anchorRatio) * scaledSpan;
    chartVerticalOffset = desiredCenter - baseCenter;
  }
  renderMiniChart(built);
}

function resetChartView() {
  chartOffset = 0;
  chartDragX = null;
  chartDragY = null;
  chartDragMode = null;
  chartPanDragRemainderX = 0;
  chartTimeScaleDragRemainder = 0;
  chartVerticalOffset = 0;
  chartVerticalScale = 1;
  renderMiniChart(getBuiltCandles());
}

function resetChartViewportState({ render = true } = {}) {
  chartOffset = 0;
  chartDragX = null;
  chartDragY = null;
  chartDragMode = null;
  chartPanDragRemainderX = 0;
  chartTimeScaleDragRemainder = 0;
  chartGestureMoved = false;
  chartVerticalOffset = 0;
  chartVerticalScale = 1;
  if (render) renderMiniChart(getBuiltCandles());
}

function getBacktestChartOffsetBounds(candles) {
  const built = Array.isArray(candles) ? candles : [];
  return {
    min: 0,
    max: Math.max(0, built.length - backtestChartPoints),
  };
}

function getVisibleBacktestChartWindow(candles) {
  const built = Array.isArray(candles) ? candles : [];
  const { min, max } = getBacktestChartOffsetBounds(built);
  backtestChartOffset = clamp(backtestChartOffset, min, max);
  const end = built.length - backtestChartOffset;
  const start = Math.max(0, end - Math.max(1, backtestChartPoints));
  const points = built.slice(start, end);
  return { points, start, end, visibleSlotCount: Math.max(points.length, 1) };
}

function rerenderBacktestAnalysisChart() {
  if (!backtestChartRenderState) return;
  renderBacktestAnalysisChart(
    backtestChartRenderState.prediction,
    backtestChartRenderState.candles,
    backtestChartRenderState.options,
  );
}

function panBacktestChartByPixels(deltaX) {
  const candles = backtestChartRenderState?.candles;
  const viewport = backtestChartViewportState;
  if (!Array.isArray(candles) || !candles.length || !viewport) return;
  const pixelsPerCandle = viewport.plotW / Math.max(1, viewport.points.length || backtestChartPoints);
  const candleShift = Math.round(deltaX / Math.max(1, pixelsPerCandle));
  if (!candleShift) return;
  const { min, max } = getBacktestChartOffsetBounds(candles);
  backtestChartOffset = clamp(backtestChartOffset + candleShift, min, max);
  rerenderBacktestAnalysisChart();
}

function panBacktestChartVertically(deltaY) {
  const viewport = backtestChartViewportState;
  if (!viewport || !viewport.points?.length) return;
  const lows = viewport.points.map((c) => c.low);
  const highs = viewport.points.map((c) => c.high);
  const range = Math.max(0.0000001, Math.max(...highs) - Math.min(...lows));
  const plotHeight = Math.max(1, viewport.plotH);
  backtestChartVerticalOffset += (deltaY / plotHeight) * range;
  rerenderBacktestAnalysisChart();
}

function scaleBacktestChartVertically(deltaY) {
  const candles = backtestChartRenderState?.candles;
  if (!Array.isArray(candles) || !candles.length) return;
  const sensitivity = 0.012;
  const nextScale = backtestChartVerticalScale * Math.exp((-deltaY) * sensitivity);
  backtestChartVerticalScale = clamp(nextScale, 0.5, 8);
  rerenderBacktestAnalysisChart();
}

function setStatus(msg, isError = false) {
  if (!statusEl) return;
  statusEl.textContent = msg;
  statusEl.style.color = isError ? "#e15b64" : "#9aa7b8";
}

function ensureSignalToastLayer() {
  if (signalToastLayerEl || !phoneEl) return;
  signalToastLayerEl = document.createElement("div");
  signalToastLayerEl.className = "signal-toast-layer hidden";
  signalToastLayerEl.innerHTML = `
    <div class="signal-toast toast-neutral" role="status" aria-live="polite" aria-atomic="true">
      <div class="signal-toast-title"></div>
      <div class="signal-toast-body"></div>
    </div>
  `;
  phoneEl.appendChild(signalToastLayerEl);
}

function showSignalToast({ title, body, tone = "neutral" }) {
  ensureSignalToastLayer();
  if (!signalToastLayerEl) return;
  const toastEl = signalToastLayerEl.querySelector(".signal-toast");
  const titleEl = signalToastLayerEl.querySelector(".signal-toast-title");
  const bodyEl = signalToastLayerEl.querySelector(".signal-toast-body");
  if (!toastEl || !titleEl || !bodyEl) return;

  toastEl.classList.remove("toast-buy", "toast-sell", "toast-neutral");
  toastEl.classList.add(tone === "buy" ? "toast-buy" : tone === "sell" ? "toast-sell" : "toast-neutral");
  titleEl.textContent = title;
  bodyEl.textContent = body;
  signalToastLayerEl.classList.remove("hidden");

  if (signalToastTimer) clearTimeout(signalToastTimer);
  signalToastTimer = setTimeout(() => {
    signalToastLayerEl?.classList.add("hidden");
  }, 4200);
}

function getTimeframeLabel(seconds) {
  const value = Number(seconds);
  const configured = TIMEFRAME_OPTIONS.find((option) => option.seconds === value)?.label;
  if (configured) return configured;
  if (value >= 86400 && value % 86400 === 0) return `${value / 86400}d`;
  if (value >= 3600 && value % 3600 === 0) return `${value / 3600}h`;
  if (value >= 60 && value % 60 === 0) return `${value / 60}m`;
  return `${value}s`;
}

function getChartIndicatorLabel(value) {
  return CHART_INDICATOR_OPTIONS.find((option) => option.value === value)?.label || value;
}

function buildIndicatorSignalAlerts(candles) {
  if (!Array.isArray(candles) || candles.length < 3 || !activeChartIndicators.size) return [];
  const recentMinIndex = Math.max(0, candles.length - 2);
  const alerts = [];
  const alertCandlesFor = (indicator) => getChartIndicatorAnalysisCandles(indicator, candles);
  const addAlert = (indicator, entryIndex, direction, kind, sourceCount = candles.length) => {
    const sourceRecentMinIndex = Math.max(0, sourceCount - 2);
    if (!Number.isInteger(entryIndex) || entryIndex < sourceRecentMinIndex || entryIndex >= sourceCount) return;
    alerts.push({ indicator, entryIndex, direction, kind });
  };

  if (activeChartIndicators.has("SMC_SETUP_08")) {
    const source = alertCandlesFor("SMC_SETUP_08");
    const smc = buildSMCSetup08(source, 5);
    [...smc.bullish, ...smc.bearish].forEach((setup) => {
      const entryIndex = setup.triggerIndex != null && setup.triggerIndex + 1 < candles.length
        ? setup.triggerIndex + 1
        : setup.triggerIndex;
      addAlert("SMC_SETUP_08", entryIndex, setup.direction === "BULL" ? "BUY" : "SELL", "setup", source.length);
    });
  }

  if (activeChartIndicators.has("SMC_WELO_TRADES")) {
    const source = alertCandlesFor("SMC_WELO_TRADES");
    const smc = buildWeloSmartMoneyConcepts(source, { pivotLen: 4, lookback: 260 });
    smc.signals.forEach((signal) => {
      addAlert("SMC_WELO_TRADES", signal.entryIndex, signal.direction, signal.reason || `${signal.confidence}% SMC confluence`, source.length);
    });
  }

  if (activeChartIndicators.has("INSTITUTIONAL_SMC_ENGINE")) {
    const engine = buildInstitutionalSmcEngine(candles, {
      symbol: currentSymbol,
      baseSeconds: getChartTimeframeSeconds(),
    });
    if (engine.signal?.direction) {
      addAlert("INSTITUTIONAL_SMC_ENGINE", candles.length - 1, engine.signal.direction, engine.signal.reason || engine.summary, candles.length);
    }
  }

  if (activeChartIndicators.has("INST_EXECUTION_MODEL")) {
    const source = alertCandlesFor("INST_EXECUTION_MODEL");
    const iem = buildInstitutionalExecutionModel(source, {});
    iem.signals.forEach((signal) => addAlert("INST_EXECUTION_MODEL", signal.entryIndex, signal.direction, signal.result.toLowerCase(), source.length));
  }

  if (activeChartIndicators.has("INST_LEVEL_BEHAVIOR")) {
    const source = alertCandlesFor("INST_LEVEL_BEHAVIOR");
    const ilb = buildInstitutionalLevelBehaviorModel(source, {});
    ilb.signals.forEach((signal) => addAlert("INST_LEVEL_BEHAVIOR", signal.entryIndex, signal.direction, signal.behavior, source.length));
  }

  if (activeChartIndicators.has("INSTITUTIONAL_FOREX_ENGINE")) {
    const source = alertCandlesFor("INSTITUTIONAL_FOREX_ENGINE");
    const engine = buildInstitutionalForexSignalEngine(source, {
      baseSeconds: getChartIndicatorTimeframe("INSTITUTIONAL_FOREX_ENGINE"),
      expirySeconds: INSTITUTIONAL_EXPIRY_SECONDS,
    });
    if (engine.direction) {
      addAlert("INSTITUTIONAL_FOREX_ENGINE", source.length - 1, engine.direction === "CALL" ? "BUY" : "SELL", `${engine.confidence}% ${engine.confirmationStatus}`, source.length);
    }
  }

  if (activeChartIndicators.has("SMC_PRO_COMBO")) {
    const source = alertCandlesFor("SMC_PRO_COMBO");
    const smc = buildSMCProCombo(source, {
      leftLen: 5,
      rightLen: 5,
      atrLen: 14,
      atrMult: 0.1,
      volLen: 20,
      minBodyPct: 55,
      useAtrBuffer: true,
      useBodyFilter: true,
    });
    smc.signals.forEach((signal) => {
      addAlert("SMC_PRO_COMBO", signal.entryIndex, signal.type.includes("BUY") ? "BUY" : "SELL", signal.type, source.length);
    });
  }

  if (activeChartIndicators.has("ADX_VOL_WAVES")) {
    const waves = buildADXVolatilityWaves(candles, {
      bbLength: 20,
      bbMult: 1.5,
      adxLength: 14,
      adxSmooth: 14,
      adxInfluence: 0.8,
      zoneOffset: 1,
      zoneExpansion: 1,
      smoothLength: 50,
      signalCooldown: 20,
    });
    waves.signals.forEach((signal) => addAlert("ADX_VOL_WAVES", signal.entryIndex, signal.type, "zone"));
  }

  if (activeChartIndicators.has("BREAKOUT_TARGETS")) {
    const breakout = buildBreakoutTargets(candles, {
      len: 99,
      preventOverlap: true,
      atrPeriod: 14,
      slMultiplier: 5,
      tp1Multiplier: 0.5,
      tp2Multiplier: 1,
      tp3Multiplier: 1.5,
    });
    breakout.breakouts.forEach((signal) => addAlert("BREAKOUT_TARGETS", signal.entryIndex, signal.direction === "UP" ? "BUY" : "SELL", "breakout"));
  }

  if (activeChartIndicators.has("DYNAMIC_Z_DIVERGENCE")) {
    const dzd = buildDynamicZDivergence(candles, {});
    dzd.buySignals.forEach((signal) => addAlert("DYNAMIC_Z_DIVERGENCE", signal.entryIndex, "BUY", "mean reversion"));
    dzd.sellSignals.forEach((signal) => addAlert("DYNAMIC_Z_DIVERGENCE", signal.entryIndex, "SELL", "mean reversion"));
  }

  if (activeChartIndicators.has("LIQUIDITY_TRENDLINE")) {
    const lt = buildLiquidityTrendlineSignals(candles, {
      len: 5,
      space: 2,
      colorUp: "#0044ff",
      colorDown: "#ff2b00",
    });
    lt.signals.forEach((signal) => addAlert("LIQUIDITY_TRENDLINE", signal.entryIndex, signal.type === "UP" ? "BUY" : "SELL", "break"));
  }

  if (activeChartIndicators.has("STRUCTURE_PULLBACK")) {
    const spc = buildStructurePullbackContinuation(candles, {
      pivotLen: 4,
      pullbackLookback: 4,
      weakBodyRatio: 0.4,
      rejectionWickRatio: 0.45,
      maxTrendFlips: 4,
      flipLookback: 30,
    });
    spc.signals.forEach((signal) => addAlert("STRUCTURE_PULLBACK", signal.entryIndex, signal.direction, signal.reason));
  }

  if (activeChartIndicators.has("SR_SIGNALS_MTF")) {
    const sr = buildSupportResistanceSignalsMTF(candles, {
      length: 6,
      zoneAtrMult: 0.5,
      securityAtrMult: 0,
      manipulationMult: 1.3,
      maxActive: 5,
      showBroken: true,
      extendActive: true,
    });
    sr.signals.forEach((signal) => addAlert("SR_SIGNALS_MTF", signal.entryIndex, signal.direction, signal.kind));
  }

  if (activeChartIndicators.has("TICK_REJECTION")) {
    const rejection = buildTickRejectionMicrostructure(candles, {
      ticksLookback: 5,
      minRejectionRatio: 0.5,
      minRange: Math.max(currentPip || 0.0001, 0.0001),
    });
    rejection.signals.forEach((signal) => addAlert("TICK_REJECTION", signal.entryIndex, signal.type === "lower" ? "BUY" : "SELL", "rejection"));
  }

  if (activeChartIndicators.has("CHART_PATTERNS")) {
    const cp = buildChartPatternsSignals(candles, {
      pivotLen: 3,
      toleranceMult: 0.45,
      maxPatternAge: 60,
    });
    cp.signals.forEach((signal) => addAlert("CHART_PATTERNS", signal.entryIndex, signal.direction, signal.label));
  }

  if (activeChartIndicators.has("CHANNELS_PATTERNS")) {
    const cwp = buildChannelsWithPatterns(candles, {});
    cwp.labels.forEach((label) => {
      addAlert("CHANNELS_PATTERNS", label.index, label.side === "bottom" ? "BUY" : "SELL", label.kind);
    });
    cwp.breaks.forEach((signal) => {
      addAlert("CHANNELS_PATTERNS", signal.index, signal.direction === "UP" ? "BUY" : "SELL", "channel break");
    });
  }

  if (activeChartIndicators.has("ALGO_BEHAVIOR_ENGINE")) {
    const abe = buildAlgoBehaviorEngine(candles, {});
    abe.signals.forEach((signal) => addAlert("ALGO_BEHAVIOR_ENGINE", signal.entryIndex, signal.direction, `score-${signal.score}`));
  }

  if (activeChartIndicators.has("PRICE_ACTION_TOOLKIT")) {
    const pa = buildPriceActionToolkit(candles, {});
    pa.actionableSignals.forEach((signal) => addAlert("PRICE_ACTION_TOOLKIT", signal.entryIndex, signal.direction, signal.kind));
  }

  if (activeChartIndicators.has("LIQ_SWEEP_OB")) {
    const lq = buildLiquiditySweepOrderBlockSystem(candles, {
      pivotLen: 3,
      sweepLookahead: 10,
      pullbackLookahead: 12,
    });
    lq.setups.forEach((setup) => addAlert("LIQ_SWEEP_OB", setup.entryIndex, setup.direction, setup.liquidityKind));
  }

  if (activeChartIndicators.has("LDMSS")) {
    const ldmss = buildLiquidityDrivenMarketStructureSystem(candles, {
      pivotLen: 3,
      sweepLookahead: 10,
      pullbackLookahead: 12,
    });
    ldmss.setups
      .filter((setup) => setup.sessionAllowed)
      .forEach((setup) => addAlert("LDMSS", setup.entryIndex, setup.direction, setup.liquidityKind));
  }

  return alerts.sort((a, b) => a.entryIndex - b.entryIndex);
}

function maybeNotifyIndicatorSignals(candles) {
  const alerts = buildIndicatorSignalAlerts(candles);
  if (!alerts.length) return;

  const unseen = alerts.filter((alert) => {
    const key = `${currentSymbol || "symbol"}|${candleBuilder.timeframe}|${alert.indicator}|${alert.entryIndex}|${alert.direction}|${alert.kind}`;
    alert.key = key;
    return !shownIndicatorSignalKeys.has(key);
  });
  if (!unseen.length) return;

  const latest = unseen[unseen.length - 1];
  shownIndicatorSignalKeys.add(latest.key);
  if (shownIndicatorSignalKeys.size > 250) {
    const oldestKey = shownIndicatorSignalKeys.values().next().value;
    if (oldestKey) shownIndicatorSignalKeys.delete(oldestKey);
  }

  const indicatorLabel = getChartIndicatorLabel(latest.indicator);
  const marketLabel = symbolName?.textContent?.trim() || currentSymbol || "Current market";
  const timeframeLabel = getTimeframeLabel(candleBuilder.timeframe);
  showSignalToast({
    title: `${indicatorLabel}: ${latest.direction}`,
    body: `${marketLabel} • ${timeframeLabel}${latest.kind ? ` • ${latest.kind}` : ""}`,
    tone: latest.direction === "BUY" ? "buy" : latest.direction === "SELL" ? "sell" : "neutral",
  });
}

