function scheduleChartResize() {
  if (currentAppTab !== "chart" && currentAppTab !== "chart_2") return;
  requestAnimationFrame(() => {
    requestAnimationFrame(() => {
      renderMiniChart(getBuiltCandles());
    });
  });
  setTimeout(() => {
    if (currentAppTab === "chart" || currentAppTab === "chart_2") {
      renderMiniChart(getBuiltCandles());
    }
  }, 120);
}

function base64UrlEncode(bytes) {
  const binary = Array.from(new Uint8Array(bytes), (byte) => String.fromCharCode(byte)).join("");
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function randomBase64Url(byteLength = 32) {
  const bytes = new Uint8Array(byteLength);
  crypto.getRandomValues(bytes);
  return base64UrlEncode(bytes);
}

async function createCodeChallenge(verifier) {
  const encoded = new TextEncoder().encode(verifier);
  const digest = await crypto.subtle.digest("SHA-256", encoded);
  return base64UrlEncode(digest);
}

async function beginDerivLogin() {
  const codeVerifier = randomBase64Url(48);
  const codeChallenge = await createCodeChallenge(codeVerifier);
  const state = randomBase64Url(24);
  const redirectUri = getCurrentRedirectUri();
  sessionStorage.setItem(DERIV_AUTH_STATE_KEY, JSON.stringify({
    state,
    code_verifier: codeVerifier,
    redirect_uri: redirectUri,
    created_at: Date.now(),
  }));

  const url = new URL(DERIV_AUTH_URL);
  url.searchParams.set("client_id", DERIV_OAUTH_APP_ID);
  url.searchParams.set("redirect_uri", redirectUri);
  url.searchParams.set("response_type", "code");
  url.searchParams.set("scope", DERIV_OAUTH_SCOPE);
  url.searchParams.set("code_challenge", codeChallenge);
  url.searchParams.set("code_challenge_method", "S256");
  url.searchParams.set("state", state);
  window.location.href = url.toString();
}

function findFirstWssUrl(value) {
  if (typeof value === "string" && value.startsWith("wss://")) return value;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = findFirstWssUrl(item);
      if (found) return found;
    }
    return "";
  }
  if (value && typeof value === "object") {
    for (const item of Object.values(value)) {
      const found = findFirstWssUrl(item);
      if (found) return found;
    }
  }
  return "";
}

function findAccountArray(value) {
  if (Array.isArray(value) && value.some((item) => item && typeof item === "object")) return value;
  if (!value || typeof value !== "object") return [];
  const preferred = [value.accounts, value.data, value.account_list, value.trading_accounts, value.wallets];
  for (const item of preferred) {
    const found = findAccountArray(item);
    if (found.length) return found;
  }
  for (const item of Object.values(value)) {
    const found = findAccountArray(item);
    if (found.length) return found;
  }
  return [];
}

function normalizeOAuthAccount(account, token) {
  const loginid = account.loginid || account.login_id || account.account_id || account.accountId || account.id || account.login;
  if (!loginid) return null;
  return {
    token,
    loginid: String(loginid),
    account_id: String(account.account_id || account.accountId || loginid),
    currency: account.currency || account.currency_code || account.wallet_currency || "",
    account_type: account.account_type || account.type || account.category || "",
    auth_type: "oauth2",
  };
}

function getAccountKind(account) {
  const text = [
    account?.loginid,
    account?.account_id,
    account?.account_type,
    account?.type,
    account?.category,
  ].filter(Boolean).join(" ").toLowerCase();
  if (text.includes("demo") || text.includes("virtual") || text.startsWith("vrtc") || text.startsWith("dot")) return "demo";
  return "real";
}

async function derivApi(path, options = {}) {
  const headers = { ...(options.headers || {}) };
  if (options.token) headers.authorization = `Bearer ${options.token}`;
  const res = await fetch(path, {
    ...options,
    headers: {
      "content-type": "application/json",
      ...headers,
    },
    body: options.body && typeof options.body !== "string" ? JSON.stringify(options.body) : options.body,
  });
  const data = await res.json().catch(() => ({}));
  if (!res.ok) throw new Error(data?.error || data?.message || "Deriv API request failed");
  return data;
}

async function fetchOAuthAccounts(token) {
  const data = await derivApi("/api/deriv/accounts", { token });
  const accounts = findAccountArray(data)
    .map((account) => normalizeOAuthAccount(account, token))
    .filter(Boolean);
  if (!accounts.length) throw new Error("No Deriv accounts returned for this login.");
  return accounts;
}

async function getAuthenticatedWsUrl(account) {
  const data = await derivApi("/api/deriv/ws-auth", {
    method: "POST",
    token: activeToken || account.token,
    body: { account_id: account.account_id || account.loginid },
  });
  const url = findFirstWssUrl(data);
  if (!url) throw new Error("Deriv did not return an authenticated WebSocket URL.");
  return url;
}

async function activateDerivAccount(account, options = {}) {
  if (!account) return false;
  activeToken = account.token;
  activeLoginId = account.loginid;
  activeAccountCurrency = account.currency || "";
  localStorage.setItem(DERIV_ACCESS_TOKEN_KEY, activeToken);
  activeAuthWsUrl = await getAuthenticatedWsUrl(account);
  isAuthorized = true;
  balanceSubscriptionLoginId = null;
  balanceSubscribeInFlightLoginId = null;
  if (privateWs) {
    try { privateWs.close(); } catch {}
    privateWs = null;
  }
  connectPrivateWS({ subscribeBalance: options.subscribeBalance !== false });
  renderAccountList();
  if (!options.silent) setStatus(`Logged in as ${activeLoginId}`);
  return true;
}

async function parseOAuthTokens() {
  const searchParams = new URLSearchParams(window.location.search);
  const hashParams = new URLSearchParams(window.location.hash.replace(/^#/, ""));
  const params = searchParams.has("code") || searchParams.has("token1") ? searchParams : hashParams;

  if (params.has("error")) {
    setStatus(params.get("error_description") || params.get("error") || "Deriv login failed", true);
    window.history.replaceState({}, document.title, window.location.pathname);
    return;
  }

  if (params.has("code")) {
    try {
      const saved = JSON.parse(sessionStorage.getItem(DERIV_AUTH_STATE_KEY) || "{}");
      if (saved.state && params.get("state") && saved.state !== params.get("state")) {
        throw new Error("Deriv login state mismatch. Please try logging in again.");
      }
      const tokenData = await derivApi("/api/deriv/token", {
        method: "POST",
        body: {
          code: params.get("code"),
          code_verifier: saved.code_verifier,
          redirect_uri: saved.redirect_uri || getCurrentRedirectUri(),
        },
      });
      const token = tokenData.access_token;
      if (!token) throw new Error("Deriv did not return an access token.");
      localStorage.setItem(DERIV_ACCESS_TOKEN_KEY, token);
      const accounts = await fetchOAuthAccounts(token);
      localStorage.setItem("deriv_accounts", JSON.stringify(accounts));
      storedAccounts = accounts;
      sessionStorage.removeItem(DERIV_AUTH_STATE_KEY);
      window.history.replaceState({}, document.title, window.location.pathname);
      await activateDerivAccount(accounts[0]);
    } catch (err) {
      setStatus(err?.message || "Deriv login failed", true);
      window.history.replaceState({}, document.title, window.location.pathname);
    }
    return;
  }

  const accounts = [];
  if (params.has("token1")) {
    for (let i = 1; i < 50; i++) {
      const token = params.get(`token${i}`);
      const loginid = params.get(`acct${i}`);
      const currency = params.get(`cur${i}`);
      if (!token || !loginid) break;
      accounts.push({ token, loginid, account_id: loginid, currency: currency || "", auth_type: "legacy" });
    }
  }
  if (!accounts.length) return;
  localStorage.setItem("deriv_accounts", JSON.stringify(accounts));
  storedAccounts = accounts;
  activeToken = accounts[0].token;
  activeLoginId = accounts[0].loginid;
  window.history.replaceState({}, document.title, window.location.pathname);
}

function loadStoredAccounts() {
  const raw = localStorage.getItem("deriv_accounts");
  if (!raw) return;
  try {
    storedAccounts = JSON.parse(raw) || [];
  } catch {
    storedAccounts = [];
  }
  if (storedAccounts.length) {
    activeToken = storedAccounts[0].token;
    activeLoginId = storedAccounts[0].loginid;
  }
}

async function restoreOAuthSession() {
  if (storedAccounts.length) return false;
  const token = localStorage.getItem(DERIV_ACCESS_TOKEN_KEY);
  if (!token) return false;
  setStatus("Restoring Deriv session...");
  try {
    const accounts = await fetchOAuthAccounts(token);
    localStorage.setItem("deriv_accounts", JSON.stringify(accounts));
    storedAccounts = accounts;
    await activateDerivAccount(accounts[0], { silent: true });
    return true;
  } catch (err) {
    setStatus(err?.message || "Could not restore Deriv login. Please log in again.", true);
    return false;
  }
}

function renderAccountList() {
  if (!accountListEl) return;
  if (!storedAccounts.length) {
    accountListEl.innerHTML = "<div class=\"trade-meta\">Not logged in</div>";
    return;
  }
  document.querySelectorAll("[data-account-filter]").forEach((button) => {
    button.classList.toggle("active", button.getAttribute("data-account-filter") === activeAccountFilter);
  });
  const visibleAccounts = activeAccountFilter === "all"
    ? storedAccounts
    : storedAccounts.filter((acc) => getAccountKind(acc) === activeAccountFilter);
  accountListEl.innerHTML = visibleAccounts.length ? visibleAccounts.map((acc) => {
    const label = `${acc.loginid} ${acc.currency || ""}`.trim();
    const active = acc.loginid === activeLoginId ? "active" : "";
    return `<button class="account-item ${active}" data-loginid="${acc.loginid}">${label}</button>`;
  }).join("") : `<div class="trade-meta">No ${activeAccountFilter} accounts found</div>`;

  if (accountSummary && activeLoginId) {
    const current = storedAccounts.find((acc) => acc.loginid === activeLoginId);
    if (current) {
      accountSummary.innerHTML = `<span class="acct-label">${current.loginid}</span><span>${current.currency || ""}</span>`;
    }
  }

  if (autoAccountSelect) {
    autoAccountSelect.innerHTML = `<option value="">Select account</option>` + storedAccounts
      .map((acc) => `<option value="${acc.loginid}">${acc.loginid} ${acc.currency || ""}</option>`)
      .join("");
    if (autoTradeLoginId) {
      autoAccountSelect.value = autoTradeLoginId;
    }
  }
}

function subscribeOpenContract(contractId) {
  if (!contractId) return;
  privateWsRequest({ proposal_open_contract: 1, contract_id: contractId, subscribe: 1 }).catch((err) => {
    setStatus(err?.message || "Could not subscribe to contract updates.", true);
  });
}

function handleOpenContractUpdate(contract, subscriptionId) {
  const contractId = contract.contract_id;
  if (!contractId) return;
  if (subscriptionId) {
    openContractSubs.set(contractId, subscriptionId);
  }

  const index = tradeResults.findIndex((t) => String(t.contractId || "") === String(contractId));
  const autoIndex = autoTradeResults.findIndex((t) => String(t.contractId || "") === String(contractId));
  if (index === -1 && autoIndex === -1) return;

  const previousTrade = index !== -1 ? tradeResults[index] : autoIndex !== -1 ? autoTradeResults[autoIndex] : null;
  const buyPrice = contract.buy_price ?? previousTrade?.price ?? null;
  const sellPrice = contract.sell_price ?? null;
  const profit = contract.profit ?? (sellPrice != null && buyPrice != null ? sellPrice - buyPrice : previousTrade?.profit ?? null);
  const isSold = contract.is_sold ?? contract.status === "sold";
  const expiry = contract.date_expiry ?? previousTrade?.expiry ?? null;
  upsertTradeChartMarkerFromContract(contract, previousTrade);

  if (index !== -1) {
    tradeResults[index] = {
      ...tradeResults[index],
      price: buyPrice,
      profit,
      isSold,
      expiry,
      success: isSold ? (profit != null ? profit >= 0 : tradeResults[index].success) : tradeResults[index].success,
    };
  }
  if (autoIndex !== -1) {
    autoTradeResults[autoIndex] = {
      ...autoTradeResults[autoIndex],
      price: buyPrice,
      profit,
      isSold,
      expiry,
      success: isSold ? (profit != null ? profit >= 0 : autoTradeResults[autoIndex].success) : autoTradeResults[autoIndex].success,
    };
    if (isSold && String(autoOpenContractId || "") === String(contractId)) {
      autoOpenContractId = null;
      clearAutoContractCloseTimer();
      if (autoTradeEnabled) {
        scheduleAutoScanner(AUTO_SCANNER_AFTER_CLOSE_MS);
      }
    }
  }

  if (isSold && subscriptionId) {
    privateWsRequest({ forget: subscriptionId }).catch(() => {});
    openContractSubs.delete(contractId);
  }

  renderTradeResults();
  renderAutoTradeResults();
}

async function subscribeBalance() {
  if (!activeAuthWsUrl || !activeLoginId) return null;
  if (balanceSubscriptionLoginId === activeLoginId) return null;
  if (balanceSubscribeInFlightLoginId === activeLoginId) return null;
  balanceSubscribeInFlightLoginId = activeLoginId;
  try {
    const res = await privateWsRequest({ balance: 1, subscribe: 1 });
    balanceSubscriptionLoginId = activeLoginId;
    return res.balance;
  } catch (err) {
    const message = err?.message || "";
    if (!message.toLowerCase().includes("already subscribed to balance")) throw err;
    balanceSubscriptionLoginId = activeLoginId;
    return null;
  } finally {
    balanceSubscribeInFlightLoginId = null;
  }
}

async function authorizeWithToken(token, options = {}) {
  const account = storedAccounts.find((acc) => acc.loginid === activeLoginId)
    || storedAccounts.find((acc) => acc.token === token);
  if (!account) return null;
  await activateDerivAccount(account, { silent: true, subscribeBalance: options.subscribeBalance !== false });
  if (options.subscribeBalance === false) return account;
  await subscribeBalance();
  return account;
}

function updateAccountSummary(balance) {
  if (!accountSummary) return;
  const login = activeLoginId ? `${activeLoginId}` : "Account";
  const amount = balance.balance != null ? balance.balance.toFixed(2) : "--";
  const cur = balance.currency || "";
  accountSummary.innerHTML = `<span class="acct-label">${login}</span><span>${amount} ${cur}</span>`;
}

function isDerivedMarket(symbol) {
  const market = (symbol.market || "").toLowerCase();
  const marketName = (symbol.market_display_name || "").toLowerCase();
  const submarketName = (symbol.submarket_display_name || "").toLowerCase();
  return (
    market === "synthetic_index" ||
    marketName.includes("derived") ||
    marketName.includes("synthetic") ||
    submarketName.includes("derived") ||
    submarketName.includes("synthetic")
  );
}

function isAllowedSymbol(symbol) {
  const name = (symbol.display_name || "").toLowerCase();
  return name.includes("volatility") || name.includes("bull") || name.includes("bear");
}

function isTradableActiveSymbol(symbol) {
  if (!symbol?.symbol) return false;
  const exchangeIsOpen = symbol.exchange_is_open;
  if (exchangeIsOpen === 0 || exchangeIsOpen === false) return false;
  if (symbol.is_trading_suspended === 1 || symbol.is_trading_suspended === true) return false;
  return true;
}

function isRiseFallEligibleSymbol(symbol) {
  if (!symbol?.symbol) return false;
  const text = [
    symbol.symbol,
    symbol.display_name,
    symbol.market_display_name,
    symbol.submarket_display_name,
  ].filter(Boolean).join(" ").toLowerCase();

  // Boom/Crash-style instruments are multiplier-only in this app's workflow.
  if (/\bboom\b|\bcrash\b/.test(text)) return false;
  return true;
}

function getActiveSymbolInfo(symbolCode = currentSymbol || symbolSelect?.value) {
  if (!symbolCode) return null;
  return activeSymbols.find((symbol) => symbol.symbol === symbolCode) || null;
}

function isForexSymbol(symbol) {
  const text = [
    symbol?.symbol,
    symbol?.display_name,
    symbol?.market,
    symbol?.market_display_name,
    symbol?.submarket_display_name,
  ].filter(Boolean).join(" ").toLowerCase();
  return text.includes("forex") || text.includes(" fx ") || symbol?.market === "forex";
}

function isCryptoSymbol(symbol) {
  const text = [
    symbol?.symbol,
    symbol?.display_name,
    symbol?.market,
    symbol?.market_display_name,
    symbol?.submarket_display_name,
  ].filter(Boolean).join(" ").toLowerCase();
  return text.includes("crypto") || symbol?.market === "cryptocurrency";
}

function getInstrumentScannerScope(symbol) {
  if (isForexSymbol(symbol)) return "__forex";
  if (isCryptoSymbol(symbol)) return "__crypto";
  if (isDerivedMarket(symbol)) return "__deriv";
  return "__rise_fall";
}

function symbolSupportsHigherLower(symbolCode = currentSymbol || symbolSelect?.value) {
  if (!symbolCode) return false;
  return Array.from(symbolsByTradeMode.higher_lower?.values?.() || [])
    .some((entry) => entry.symbols?.some((symbol) => symbol.symbol === symbolCode));
}

function setSelectValueIfAvailable(selectEl, value) {
  if (!selectEl || !value) return false;
  const hasValue = Array.from(selectEl.options || []).some((option) => option.value === value);
  if (!hasValue) return false;
  selectEl.value = value;
  return true;
}

function setMinimumTimeframe(seconds) {
  const minSeconds = Math.max(1, Number(seconds) || DEFAULT_TIMEFRAME_SEC);
  const targetSeconds = TIMEFRAME_OPTIONS.find((option) => option.seconds >= minSeconds)?.seconds || minSeconds;
  if (getChartTimeframeSeconds() < targetSeconds) {
    setChartTimeframe(targetSeconds).catch(() => {});
  }
  if (autoTimeframeSelectEl && getAutoTradeTimeframeSeconds() < targetSeconds) {
    autoTimeframeSelectEl.value = String(targetSeconds);
    autoTradeTimeframeSeconds = targetSeconds;
  }
}

function syncTimeframeAvailability(minSeconds = DEFAULT_TIMEFRAME_SEC) {
  const minValue = Math.max(1, Number(minSeconds) || DEFAULT_TIMEFRAME_SEC);
  [chartTfSelectEl, autoTimeframeSelectEl].forEach((selectEl) => {
    Array.from(selectEl?.options || []).forEach((option) => {
      option.disabled = Number(option.value) < minValue;
    });
  });
  if (chartTfLabelEl && minValue >= 900 && getChartTimeframeSeconds() < minValue) {
    chartTfLabelEl.textContent = getTimeframeLabel(minValue);
  }
}

function syncInstrumentDrivenControls(symbol = getActiveSymbolInfo()) {
  if (!symbol) return;
  const supportsHL = symbolSupportsHigherLower(symbol.symbol);
  const scope = getInstrumentScannerScope(symbol);
  const minSignalSeconds = isForexSymbol(symbol) ? 900 : 1;

  tabs?.forEach((tab) => {
    if (tab.dataset.tab === "higher_lower") {
      tab.disabled = !supportsHL;
      tab.hidden = !supportsHL;
      tab.classList.toggle("disabled", !supportsHL);
    }
  });
  [desktopTradeTypeSelectEl, sidebarTradeTypeSelectEl].forEach((selectEl) => {
    const option = selectEl?.querySelector?.('option[value="higher_lower"]');
    if (option) {
      option.disabled = !supportsHL;
      option.hidden = !supportsHL;
    }
  });

  if (!supportsHL && getActiveTradeMode() === "higher_lower") {
    setActiveTab("rise_fall", { preserveSelection: true });
  }

  setSelectValueIfAvailable(marketScannerScopeSelectEl, scope);
  setSelectValueIfAvailable(autoMarketScopeSelectEl, scope);
  if (setSelectValueIfAvailable(askAiGroupSelectEl, scope)) {
    populateAskAiSymbols();
    setSelectValueIfAvailable(askAiSymbolSelectEl, symbol.symbol);
    refreshAskAiTimeframeRules().catch(() => {});
  }
  syncTimeframeAvailability(minSignalSeconds);
  if (isForexSymbol(symbol)) {
    setMinimumTimeframe(minSignalSeconds);
  }
}

function buildSymbolsByMarket(symbols, fallbackDisplay = "Markets") {
  const grouped = new Map();
  symbols.forEach((s) => {
    const key = s.market || s.market_display_name || "markets";
    if (!grouped.has(key)) {
      grouped.set(key, {
        market: key,
        display: s.market_display_name || fallbackDisplay,
        symbols: [],
      });
    }
    grouped.get(key).symbols.push(s);
  });
  return grouped;
}

function updateChartMarketButton() {
  if (!chartMarketButtonEl) return;
  const nameEl = document.getElementById("chartMarketName");
  const priceEl = document.getElementById("chartMarketPrice");
  if (nameEl) nameEl.textContent = symbolSelect?.selectedOptions?.[0]?.textContent || currentSymbol || "--";
  if (priceEl) priceEl.textContent = Number.isFinite(lastSpot) ? formatPrice(lastSpot, currentPip) : "--";
}

function getChartMarketMenuMap() {
  const tradeable = activeSymbols.filter(isTradableActiveSymbol).filter(isRiseFallEligibleSymbol);
  return buildSymbolsByMarket(tradeable, "Markets");
}

function renderChartMarketMenu() {
  if (!chartMarketMenuEl) return;
  const modeMap = getChartMarketMenuMap();
  const baseEntries = Array.from(modeMap.values()).sort((a, b) => a.display.localeCompare(b.display));
  if (!baseEntries.length) {
    chartMarketMenuEl.innerHTML = "<div class=\"chart-market-main\"><div class=\"trade-meta\">Markets are still loading.</div></div>";
    return;
  }
  const favoriteSymbols = baseEntries
    .flatMap((entry) => entry.symbols || [])
    .filter((symbol, index, list) => chartMarketFavorites.has(symbol.symbol) && list.findIndex((item) => item.symbol === symbol.symbol) === index);
  const entries = favoriteSymbols.length
    ? [{ market: "__favorites", display: "Favorites", symbols: favoriteSymbols }, ...baseEntries]
    : baseEntries;
  if (!chartMarketMenuMarket || !modeMap.has(chartMarketMenuMarket)) {
    chartMarketMenuMarket = chartMarketMenuMarket === "__favorites" && favoriteSymbols.length
      ? "__favorites"
      : marketSelect?.value && modeMap.has(marketSelect.value)
      ? marketSelect.value
      : baseEntries[0].market;
  }
  const activeEntry = modeMap.get(chartMarketMenuMarket) || entries[0];
  const search = chartMarketMenuSearch.trim().toLowerCase();
  const symbols = (activeEntry.symbols || [])
    .slice()
    .sort((a, b) => String(a.display_name || a.symbol).localeCompare(String(b.display_name || b.symbol)))
    .filter((symbol) => !search || [symbol.display_name, symbol.symbol, symbol.market_display_name, symbol.submarket_display_name].filter(Boolean).join(" ").toLowerCase().includes(search));

  chartMarketMenuEl.innerHTML = `
    <div class="chart-market-sidebar">
      ${entries.map((entry) => `
        <button class="chart-market-tab ${entry.market === activeEntry.market ? "active" : ""}" type="button" data-chart-market-tab="${escapeHtml(entry.market)}">
          ${escapeHtml(entry.display)}
        </button>
      `).join("")}
    </div>
    <div class="chart-market-main">
      <input class="field-input chart-market-search" type="search" placeholder="Search..." value="${escapeHtml(chartMarketMenuSearch)}" />
      <div class="chart-market-list">
        <div class="chart-market-group-title">${escapeHtml(activeEntry.display)}</div>
        ${symbols.map((symbol) => {
          const symbolMarket = activeEntry.market === "__favorites" ? symbol.market || symbol.market_display_name || marketSelect?.value || "" : activeEntry.market;
          return `
          <button class="chart-market-item ${symbol.symbol === currentSymbol ? "active" : ""}" type="button" data-chart-symbol="${escapeHtml(symbol.symbol)}" data-chart-market="${escapeHtml(symbolMarket)}">
            <span class="chart-market-icon"></span>
            <span>
              <span class="chart-market-item-name">${escapeHtml(symbol.display_name || symbol.symbol)}</span>
              <span class="chart-market-item-meta">${escapeHtml(symbol.symbol)}</span>
            </span>
            <span class="chart-market-star ${chartMarketFavorites.has(symbol.symbol) ? "active" : ""}" data-chart-favorite="${escapeHtml(symbol.symbol)}" title="Toggle favorite">${chartMarketFavorites.has(symbol.symbol) ? "★" : "☆"}</span>
          </button>
        `;
        }).join("") || "<div class=\"trade-meta\">No markets match this search.</div>"}
      </div>
    </div>
  `;
}

function setChartMarketMenuOpen(open) {
  if (!chartMarketMenuEl || !chartMarketButtonEl) return;
  if (open) {
    closePeerChartPopupMenus("market");
    collapseSidebarsForPopupMenu();
    renderChartMarketMenu();
  }
  chartMarketMenuEl.classList.toggle("hidden", !open);
  chartMarketButtonEl.setAttribute("aria-expanded", open ? "true" : "false");
  if (!open) restoreSidebarsAfterPopupMenu();
}

function rebuildSymbolsForTradeMode({ preserveSelection = true } = {}) {
  if (!marketSelect || !symbolSelect) return;
  const mode = getActiveTradeMode();
  const nextSymbolsByMarket = symbolsByTradeMode[mode] || new Map();
  const previousMarket = preserveSelection ? marketSelect.value : "";
  const previousSymbol = preserveSelection ? symbolSelect.value : "";

  symbolsByMarket = nextSymbolsByMarket;
  marketSelect.innerHTML = "";
  const entries = Array.from(symbolsByMarket.values()).sort((a, b) => a.display.localeCompare(b.display));
  entries.forEach((entry) => {
    const opt = document.createElement("option");
    opt.value = entry.market;
    opt.textContent = entry.display;
    marketSelect.appendChild(opt);
  });

  if (previousMarket && symbolsByMarket.has(previousMarket)) {
    marketSelect.value = previousMarket;
  } else if (previousSymbol) {
    const matchingEntry = entries.find((entry) => entry.symbols.some((symbol) => symbol.symbol === previousSymbol));
    if (matchingEntry) marketSelect.value = matchingEntry.market;
  }

  updateSymbols({ preferredSymbol: previousSymbol });
}

async function fetchAllActiveSymbols() {
  const requests = [
    { active_symbols: "full" },
  ];
  const bySymbol = new Map();
  let lastError = null;

  for (const payload of requests) {
    try {
      const res = await wsRequest({ ...payload });
      (res.active_symbols || []).forEach((symbol) => {
        if (symbol?.symbol) bySymbol.set(symbol.symbol, { ...bySymbol.get(symbol.symbol), ...symbol });
      });
    } catch (err) {
      lastError = err;
    }
  }

  if (!bySymbol.size && lastError) throw lastError;
  return [...bySymbol.values()];
}

async function loadActiveSymbols() {
  setStatus("Loading markets...");
  try {
    activeSymbols = await fetchAllActiveSymbols();
  } catch (err) {
    setStatus(`Load failed: ${err.message}`, true);
    return;
  }

  const tradeableSymbols = activeSymbols.filter(isTradableActiveSymbol);
  const riseFallSymbols = activeSymbols.filter(isRiseFallEligibleSymbol);
  const derivedSymbols = tradeableSymbols.filter(isDerivedMarket).filter(isAllowedSymbol);
  symbolsByTradeMode = {
    rise_fall: buildSymbolsByMarket(riseFallSymbols, "Markets"),
    higher_lower: buildSymbolsByMarket(derivedSymbols, "Derived"),
    touch_no_touch: buildSymbolsByMarket(riseFallSymbols, "Markets"),
    multipliers: buildSymbolsByMarket(tradeableSymbols, "Markets"),
    vanillas: buildSymbolsByMarket(riseFallSymbols, "Markets"),
  };

  populateMarketScannerScopeSelect();
  populateAutoMarketScopeSelect();
  syncAskAiControls();
  rebuildSymbolsForTradeMode({ preserveSelection: false });
  setStatus(`Markets loaded (${riseFallSymbols.length} Rise/Fall symbols)`);
}

function updateSymbols({ preferredSymbol = "", awaitHistory = false } = {}) {
  const market = marketSelect.value;
  const entry = symbolsByMarket.get(market);
  symbolSelect.innerHTML = "";
  if (!entry) return;

  const symbols = entry.symbols
    .slice()
    .sort((a, b) => a.display_name.localeCompare(b.display_name));

  for (const s of symbols) {
    const opt = document.createElement("option");
    opt.value = s.symbol;
    opt.textContent = s.display_name;
    opt.dataset.pip = s.pip ?? s.pip_size ?? "";
    symbolSelect.appendChild(opt);
  }

  if (preferredSymbol && symbols.some((s) => s.symbol === preferredSymbol)) {
    symbolSelect.value = preferredSymbol;
  }

  chartMarketMenuMarket = marketSelect.value;
  renderChartMarketMenu();
  return onSymbolChange({ awaitHistory });
}

function findSymbolMarketEntry(symbol, mode = getActiveTradeMode()) {
  if (!symbol) return null;
  const map = symbolsByTradeMode[mode] || new Map();
  return Array.from(map.values())
    .find((entry) => entry.symbols?.some((item) => item.symbol === symbol)) || null;
}

async function selectChartMarketSymbol(symbol, options = {}) {
  if (!symbol || !marketSelect || !symbolSelect) return false;
  let marketEntry = findSymbolMarketEntry(symbol, getActiveTradeMode());
  if (!marketEntry) {
    marketEntry = findSymbolMarketEntry(symbol, "rise_fall");
    if (!marketEntry) return false;
    setActiveTab("rise_fall", { preserveSelection: false });
  }
  if (!symbolsByMarket.has(marketEntry.market)) {
    marketEntry = findSymbolMarketEntry(symbol, "rise_fall");
    if (!marketEntry) return false;
    setActiveTab("rise_fall", { preserveSelection: false });
  }
  marketSelect.value = marketEntry.market;
  chartMarketMenuMarket = marketEntry.market;
  await updateSymbols({
    preferredSymbol: symbol,
    awaitHistory: Boolean(options.awaitHistory),
  });
  return symbolSelect.value === symbol;
}

function subscribeToCurrentSymbol({ force = false } = {}) {
  const symbol = currentSymbol || symbolSelect?.value;
  if (!symbol || !ws || ws.readyState !== WebSocket.OPEN) return;
  if (replayEngine.isReplayMode()) return;

  if (tickStreamId) {
    ws.send(JSON.stringify({ forget: tickStreamId }));
    tickStreamId = null;
  } else if (!force && lastTickAt && Date.now() - lastTickAt < 1500) {
    return;
  }

  lastTickAt = 0;
  ws.send(JSON.stringify({ ticks: symbol, subscribe: 1 }));
}

function onSymbolChange(options = {}) {
  if (replayEngine.isReplayMode()) {
    replayEngine.disableReplay({ restoreLive: false, silent: true });
  }
  const symbol = symbolSelect.value;
  const display = symbolSelect.selectedOptions[0]?.textContent || "--";
  const pip = Number(symbolSelect.selectedOptions[0]?.dataset?.pip || "0");
  const defaultBarrier = getDefaultBarrierForDisplay(display);

  symbolName.textContent = display;
  symbolPrice.textContent = "--";
  currentSymbol = symbol;
  currentPip = pip;
  syncInstrumentDrivenControls(getActiveSymbolInfo(symbol));
  lastSpot = null;
  updateChartMarketButton();
  resetChartViewportState({ render: false });
  maybePrimeTopDownTimeframeCache(symbol, candleBuilder.timeframe, { force: true });
  resetBacktestPanel(`Ready for ${display}.`);
  if (defaultBarrier != null) {
    if (barrierInput) barrierInput.value = defaultBarrier;
    if (sidebarBarrierInputEl) sidebarBarrierInputEl.value = defaultBarrier;
    syncBarrierControls();
  }

  subscribeToCurrentSymbol({ force: true });

  candleBuilder.reset();
  chartOffset = 0;
  shownIndicatorSignalKeys.clear();
  signalToastLayerEl?.classList.add("hidden");
  updateSignalUI({ trend: "BUILDING 0%", divergence: "--", sweep: "--", confidence: null, signal: "--", setup: "--", time: null });
  const historyPromise = loadTickHistory(symbol);
  const contractsPromise = loadContractsFor(symbol);
  if (options.awaitHistory) {
    return Promise.allSettled([historyPromise, contractsPromise]);
  }
  historyPromise.catch(() => {});
  contractsPromise.catch(() => {});
  return null;
}

async function loadTickHistory(symbol) {
  if (!symbol) return;
  try {
    let built = [];
    const requestedTimeframe = candleBuilder.timeframe;

    if (!NATIVE_CANDLE_GRANULARITIES.has(requestedTimeframe)) {
      built = await loadAggregatedTickHistory(symbol);
    } else {
      built = await loadCandleHistory(symbol);
    }

    if (symbol !== currentSymbol || requestedTimeframe !== candleBuilder.timeframe) return;
    setCachedCandles(symbol, requestedTimeframe, built);
    maybePrimeTopDownTimeframeCache(symbol, requestedTimeframe);
    if (replayEngine.isReplayMode()) {
      const anchorTime = replayPendingTimeframeAnchor;
      replayPendingTimeframeAnchor = null;
      replayEngine.reloadFromLiveHistory({ anchorTime });
    } else {
      updateSignalFromCandles(built);
    }
  } catch (err) {
    setStatus(err?.message || "History load failed", true);
  }
}

function rebuildCandlesFromHistory(prices, times) {
  candleBuilder.reset();
  const len = Math.min(prices.length, times.length);
  for (let i = 0; i < len; i++) {
    candleBuilder.update({ epoch: Number(times[i]), quote: Number(prices[i]) });
  }
  return candleBuilder.currentCandle
    ? [...candleBuilder.candles, candleBuilder.currentCandle]
    : candleBuilder.candles;
}

async function loadCandleHistory(symbol) {
  const requestedTimeframe = candleBuilder.timeframe;
  const res = await wsRequest({
    ticks_history: symbol,
    end: "latest",
    count: MAX_CANDLES,
    style: "candles",
    granularity: requestedTimeframe,
  });

  const candleHistory = Array.isArray(res.candles)
    ? res.candles
    : Array.isArray(res.history?.candles)
      ? res.history.candles
      : [];

  if (candleHistory.length) {
    candleBuilder.setHistory(candleHistory);
    const built = candleBuilder.currentCandle
      ? [...candleBuilder.candles, candleBuilder.currentCandle]
      : candleBuilder.candles;
    setCachedCandles(symbol, requestedTimeframe, built);
    return built;
  }

  const history = res.history || {};
  const built = rebuildCandlesFromHistory(history.prices || [], history.times || []);
  setCachedCandles(symbol, requestedTimeframe, built);
  return built;
}

async function loadAggregatedTickHistory(symbol) {
  const requestedTimeframe = candleBuilder.timeframe;
  const targetCandles = Math.min(
    MAX_CANDLES,
    Math.max(MICRO_TIMEFRAME_INITIAL_CANDLES, chartPoints * 12)
  );
  const built = await loadAggregatedTickHistoryForGranularity(symbol, requestedTimeframe, targetCandles);
  if (symbol === currentSymbol && requestedTimeframe === candleBuilder.timeframe && built.length) {
    candleBuilder.setHistory(built);
  }
  setCachedCandles(symbol, requestedTimeframe, built);
  return built;
}

function parseDurationToSeconds(value) {
  if (value == null) return null;
  if (typeof value === "number") return value;
  const text = String(value).trim();
  const match = text.match(/^(\d+(?:\.\d+)?)([smhdw]|t)$/i);
  if (!match) return null;
  const amount = Number(match[1]);
  const unit = match[2].toLowerCase();
  const mult = unit === "s" ? 1 : unit === "m" ? 60 : unit === "h" ? 3600 : unit === "d" ? 86400 : unit === "w" ? 604800 : 1;
  return Math.round(amount * mult);
}

function parseApiDuration(value) {
  if (value == null) return null;
  const text = String(value).trim();
  const match = text.match(/^(\d+(?:\.\d+)?)([tsmhdw])$/i);
  if (!match) return null;
  const amount = Number(match[1]);
  const unit = match[2].toLowerCase();
  if (!Number.isFinite(amount) || amount <= 0) return null;
  const seconds = unit === "t" ? null : parseDurationToSeconds(text);
  return { amount, unit, seconds };
}

function buildRiseFallDurationRules(contracts) {
  const list = Array.isArray(contracts) ? contracts : [];
  const rules = {
    minByUnit: {},
    maxByUnit: {},
  };

  list.forEach((item) => {
    if (item?.contract_type !== "CALL" && item?.contract_type !== "PUT") return;
    const min = parseApiDuration(item.min_contract_duration ?? item.min_duration ?? item.minimum_duration);
    const max = parseApiDuration(item.max_contract_duration ?? item.max_duration ?? item.maximum_duration);
    if (min) {
      const value = min.unit === "t" ? min.amount : min.seconds;
      if (Number.isFinite(value)) {
        rules.minByUnit[min.unit] = Number.isFinite(rules.minByUnit[min.unit])
          ? Math.min(rules.minByUnit[min.unit], value)
          : value;
      }
    }
    if (max) {
      const value = max.unit === "t" ? max.amount : max.seconds;
      if (Number.isFinite(value)) {
        rules.maxByUnit[max.unit] = Number.isFinite(rules.maxByUnit[max.unit])
          ? Math.max(rules.maxByUnit[max.unit], value)
          : value;
      }
    }
  });

  return Object.keys(rules.minByUnit).length || Object.keys(rules.maxByUnit).length ? rules : null;
}

async function loadContractsFor(symbol) {
  if (!symbol) return;
  const requestSymbol = symbol;
  try {
    const res = await wsRequest({ contracts_for: symbol });
    if (requestSymbol !== currentSymbol) return;
    const list = res.contracts_for?.available || res.contracts_for?.contracts || res.contracts_for?.available_contracts || [];
    riseFallDurationRules = buildRiseFallDurationRules(list);
    let mins = [];
    for (const item of list) {
      if (item.contract_type !== "CALL" && item.contract_type !== "PUT") continue;
      const candidate = item.min_contract_duration ?? item.min_duration ?? item.minimum_duration;
      const sec = parseDurationToSeconds(candidate);
      if (sec) mins.push(sec);
    }
    if (mins.length) {
      minDurationSec = Math.min(...mins);
    }
    syncTimeframeAvailability(minDurationSec);
    setMinimumTimeframe(minDurationSec);
    refreshAskAiTimeframeRules().catch(() => {});
    populateRiseFallExpiryOptions();
  } catch {
    if (requestSymbol !== currentSymbol) return;
    riseFallDurationRules = null;
    populateRiseFallExpiryOptions();
    // keep fallback
  }

  buildExpiries();
}

function setExpiryMinutes(minutes) {
  baseMinutes = minutes;
  if (btn1m && btn2m) {
    btn1m.classList.toggle("active", minutes === 1);
    btn2m.classList.toggle("active", minutes === 2);
  }
  buildExpiries();
}

function isCandleEndTradeExpiry() {
  return getTradeExpiryChoice().mode === "candle_end";
}

function shouldAutoQuoteProposals() {
  return isCandleEndTradeExpiry() && getActiveTradeMode() !== "multipliers";
}

function buildCandleEndExpiries(now, step) {
  let firstAligned = Math.ceil(now / step) * step;
  if (firstAligned <= now) firstAligned += step;
  while (firstAligned - now <= minDurationSec) {
    firstAligned += step;
  }
  return Array.from({ length: 3 }, (_, i) => firstAligned + step * i);
}

function buildExpiries() {
  const now = Math.floor(Date.now() / 1000);
  const step = isCandleEndTradeExpiry()
    ? Math.max(1, getChartTimeframeSeconds())
    : baseMinutes * 60;
  if (isCandleEndTradeExpiry()) {
    proposalExpiries = buildCandleEndExpiries(now, step);
  } else {
    const minHold = Math.max(minDurationSec, step);
    const firstAligned = Math.ceil((now + minHold) / step) * step;
    proposalExpiries = Array.from({ length: 3 }, (_, i) => firstAligned + step * i);
  }
  if (!shouldAutoQuoteProposals()) {
    proposals = [];
    quickDirectionQuotes = { CALL: null, PUT: null };
    updateProposalDirectionButtons();
    updateTradeProfitSummary();
    renderTradeList();
    scheduleProposalRefresh(true);
  } else {
    renderTradeList();
    scheduleProposalRefresh(true);
  }
}

function rollExpiries() {
  if (!proposalExpiries.length) return false;
  const now = Math.floor(Date.now() / 1000);
  let changed = false;
  while (proposalExpiries.length && proposalExpiries[0] - now <= minDurationSec) {
    proposalExpiries.shift();
    const last = proposalExpiries[proposalExpiries.length - 1] || now;
    const step = isCandleEndTradeExpiry()
      ? Math.max(1, getChartTimeframeSeconds())
      : baseMinutes * 60;
    proposalExpiries.push(last + step);
    changed = true;
  }
  return changed;
}

function getApiProposalContractType(contractType, barrier = null, tradeMode = getActiveTradeMode()) {
  if (tradeMode === "touch_no_touch") return contractType === "PUT" ? "NOTOUCH" : "ONETOUCH";
  if (tradeMode === "multipliers") return contractType === "PUT" ? "MULTDOWN" : "MULTUP";
  if (tradeMode === "vanillas") return contractType === "PUT" ? "VANILLALONGPUT" : "VANILLALONGCALL";
  const hasBarrier = barrier != null && barrier !== "";
  if (hasBarrier && contractType === "CALL") return "HIGHER";
  if (hasBarrier && contractType === "PUT") return "LOWER";
  return contractType;
}

function getMultiplierSettings() {
  const multiplier = Math.max(1, Math.floor(parseTradeNumber(multiplierValueInputEl?.value, 50)));
  const takeProfit = parseTradeNumber(multiplierTpInputEl?.value, 0);
  const stopLoss = parseTradeNumber(multiplierSlInputEl?.value, 0);
  const cancellation = String(multiplierCancelSelectEl?.value || "").trim();
  const limitOrder = {};
  if (takeProfit > 0) limitOrder.take_profit = Number(takeProfit.toFixed(2));
  if (stopLoss > 0) limitOrder.stop_loss = Number(stopLoss.toFixed(2));
  return {
    multiplier,
    cancellation,
    limitOrder: Object.keys(limitOrder).length ? limitOrder : null,
  };
}

async function getProposal({ symbol, contractType, barrier, stake, durationSec, durationUnit = "s", tradeMode = getActiveTradeMode(), extraPayload = {} }) {
  const numericStake = Number(stake);
  const apiContractType = getApiProposalContractType(contractType, barrier, tradeMode);
  const payload = {
    proposal: 1,
    amount: numericStake,
    basis: "stake",
    contract_type: apiContractType,
    underlying_symbol: symbol,
    currency: activeAccountCurrency || "USD",
    ...extraPayload,
  };
  if (tradeMode !== "multipliers") {
    payload.duration = Math.max(1, Math.floor(durationSec));
    payload.duration_unit = durationUnit;
  }
  if (barrier != null && barrier !== "") {
    payload.barrier = barrier;
  }
  const request = activeToken && isAuthorized && activeAuthWsUrl ? privateWsRequest : wsRequest;
  const res = await request(payload);
  const proposal = res.proposal || {};
  const payout = Number(proposal.payout);
  const askPrice = Number(proposal.ask_price);
  const buyPrice = Number(proposal.buy_price);
  return {
    ...proposal,
    payout: Number.isFinite(payout) ? payout : proposal.payout,
    ask_price: Number.isFinite(askPrice) ? askPrice : proposal.ask_price,
    buy_price: Number.isFinite(buyPrice) ? buyPrice : proposal.buy_price,
  };
}

async function getTradeModeProposal({ symbol, direction, stake, durationSec, durationUnit = "s", tradeMode = getActiveTradeMode() }) {
  if (tradeMode === "higher_lower") {
    const barrierInfo = getHigherLowerBarrier(direction);
    if (!barrierInfo) throw new Error("Enter a valid barrier offset first");
    const proposal = await getBarrierProposal({
      symbol,
      direction,
      barrier: barrierInfo.barrier,
      fallbackBarrier: formatPrice(barrierInfo.display, currentPip),
      stake,
      durationSec,
      durationUnit,
    });
    return { proposal, barrierInfo };
  }
  if (tradeMode === "touch_no_touch") {
    const barrierInfo = getAdvancedBarrierInfo();
    if (!barrierInfo) throw new Error("Enter a valid touch barrier first");
    const proposal = await getProposal({
      symbol,
      contractType: direction,
      barrier: barrierInfo.barrier,
      stake,
      durationSec,
      durationUnit,
      tradeMode,
    });
    return { proposal, barrierInfo };
  }
  if (tradeMode === "multipliers") {
    const settings = getMultiplierSettings();
    const extraPayload = { multiplier: settings.multiplier };
    if (settings.limitOrder) extraPayload.limit_order = settings.limitOrder;
    if (settings.cancellation) extraPayload.cancellation = settings.cancellation;
    const proposal = await getProposal({
      symbol,
      contractType: direction,
      barrier: null,
      stake,
      durationSec: 1,
      durationUnit: "s",
      tradeMode,
      extraPayload,
    });
    return { proposal, barrierInfo: null };
  }
  const proposal = await getProposal({
    symbol,
    contractType: direction,
    barrier: null,
    stake,
    durationSec,
    durationUnit,
    tradeMode,
  });
  return { proposal, barrierInfo: null };
}

async function getBarrierProposal({ symbol, direction, barrier, fallbackBarrier, stake, durationSec, durationUnit = "s" }) {
  try {
    return await getProposal({
      symbol,
      contractType: direction,
      barrier,
      stake,
      durationSec,
      durationUnit,
    });
  } catch (err) {
    const canRetryAbsoluteBarrier = fallbackBarrier != null && /barrier/i.test(err?.message || "");
    if (!canRetryAbsoluteBarrier) throw err;
    return getProposal({
      symbol,
      contractType: direction,
      barrier: fallbackBarrier,
      stake,
      durationSec,
      durationUnit,
    });
  }
}

function scheduleProposalRefresh(force = false) {
  if (!currentSymbol || !lastSpot) return;
  if (getTradeExpiryChoice().mode === "fixed" || getActiveTradeMode() === "multipliers") {
    if (calcInFlight) return;
    if (Date.now() < rateLimitUntil) return;
    const now = Date.now();
    if (!force && now - lastCalcAt < MIN_REFRESH_MS) return;
    lastCalcAt = now;
    refreshFixedExpiryButtonQuotes().catch((err) => {
      setStatus(err.message, true);
    });
    return;
  }
  if (!shouldAutoQuoteProposals()) {
    proposals = [];
    quickDirectionQuotes = { CALL: null, PUT: null };
    proposalLoadingDirection = null;
    lastProposalError = null;
    renderTradeList();
    return;
  }
  if (calcInFlight) return;
  if (Date.now() < rateLimitUntil) return;
  const now = Date.now();
  if (!force && now - lastCalcAt < MIN_REFRESH_MS) return;
  lastCalcAt = now;
  const isRiseFall = getActiveTradeMode() === "rise_fall";
  proposalLoadingDirection = isRiseFall ? null : currentDirection;
  renderTradeList();
  refreshProposals().catch((err) => {
    setStatus(err.message, true);
  });
}

async function refreshFixedExpiryButtonQuotes() {
  if (calcInFlight) return;
  if (!currentSymbol || !lastSpot) return;
  const expiryChoice = getTradeExpiryChoice();
  const tradeMode = getActiveTradeMode();
  if (expiryChoice.mode !== "fixed" && tradeMode !== "multipliers") return;

  calcInFlight = true;
  lastProposalError = null;
  renderTradeList();
  try {
    const stake = parseTradeNumber(stakeInput?.value ?? sidebarStakeInputEl?.value, 0);
    if (!stake) {
      quickDirectionQuotes = { CALL: null, PUT: null };
      updateProposalDirectionButtons();
      updateTradeProfitSummary();
      return;
    }

    const effectiveExpiry = tradeMode === "multipliers"
      ? { seconds: 1, unit: "s", label: `x${getMultiplierSettings().multiplier}` }
      : getEffectiveRiseFallSignalExpiry();
    const nextQuotes = { CALL: null, PUT: null };

    for (const direction of ["CALL", "PUT"]) {
      try {
        const { proposal, barrierInfo } = await getTradeModeProposal({
          symbol: currentSymbol,
          direction,
          stake,
          durationSec: effectiveExpiry.seconds,
          durationUnit: effectiveExpiry.unit,
          tradeMode,
        });

        const payout = Number(proposal.payout);
        const askPrice = Number(proposal.ask_price ?? proposal.buy_price ?? stake);
        nextQuotes[direction] = {
          payout: Number.isFinite(payout) ? payout : null,
          profitPct: Number.isFinite(payout) && stake ? ((payout - stake) / stake) * 100 : null,
          proposalId: null,
          askPrice: Number.isFinite(askPrice) ? askPrice : null,
          barrier: barrierInfo?.display ?? null,
          offset: barrierInfo?.offset ?? null,
          expiry: null,
          expiryLabel: effectiveExpiry.label,
        };
      } catch (err) {
        lastProposalError = err?.message || "Proposal error";
        if (lastProposalError.toLowerCase().includes("rate limit")) {
          rateLimitUntil = Date.now() + RATE_LIMIT_COOLDOWN_MS;
        }
        nextQuotes[direction] = null;
      }
    }

    quickDirectionQuotes = nextQuotes;
    updateProposalDirectionButtons();
    updateTradeProfitSummary();
    renderTradeList();
  } finally {
    calcInFlight = false;
    updateProposalDirectionButtons();
  }
}

async function refreshProposals() {
  if (calcInFlight) return;
  if (!currentSymbol || !lastSpot) return;
  if (!shouldAutoQuoteProposals()) {
    proposals = [];
    quickDirectionQuotes = { CALL: null, PUT: null };
    proposalLoadingDirection = null;
    lastProposalError = null;
    renderTradeList();
    return;
  }

  calcInFlight = true;
  const loadingDirectionAtStart = proposalLoadingDirection;
  try {
    const spot = lastSpot;
    const results = [];
    let ok = 0;
    lastProposalError = null;
    const tradeMode = getActiveTradeMode();
    const isRiseFall = tradeMode === "rise_fall";
    const isDurationDirectional = ["rise_fall", "touch_no_touch", "vanillas"].includes(tradeMode);
    const stake = parseTradeNumber(stakeInput?.value ?? sidebarStakeInputEl?.value, 0);
    const primaryExpiry = proposalExpiries[0];
    quickDirectionQuotes = { CALL: null, PUT: null };

    if (tradeMode === "multipliers") {
      proposals = [];
      await refreshFixedExpiryButtonQuotes();
      return;
    }

    if (isDurationDirectional) {
      const expiryChoice = getTradeExpiryChoice();
      proposals = [];
      if (expiryChoice.mode === "candle_end") {
        const visibleExpiries = proposalExpiries.slice(0, 2);
        for (const expiry of visibleExpiries) {
          const nowSec = Math.floor(Date.now() / 1000);
          const durationSec = Math.max(minDurationSec, expiry - nowSec);
          const isPrimaryExpiry = expiry === primaryExpiry;
          const directions = isPrimaryExpiry ? ["CALL", "PUT"] : [currentDirection];
          const expiryLabel = isPrimaryExpiry ? "Current candle end" : "Next candle end";
          for (const direction of directions) {
            if (!stake || durationSec <= 0) {
              if (direction === currentDirection) {
                proposals.push({ expiry, direction, payout: null, profitPct: null, proposalId: null, askPrice: null, expiryLabel });
              }
              continue;
            }
            try {
              const { proposal, barrierInfo } = await getTradeModeProposal({
                symbol: currentSymbol,
                direction,
                stake,
                durationSec,
                durationUnit: "s",
                tradeMode,
              });
              const payout = proposal.payout;
              const askPrice = proposal.ask_price ?? proposal.buy_price ?? stake;
              const item = {
                expiry,
                direction,
                payout,
                profitPct: stake ? ((payout - stake) / stake) * 100 : null,
                proposalId: proposal.id,
                askPrice,
                barrier: barrierInfo?.display ?? null,
                offset: barrierInfo?.offset ?? null,
                expiryLabel,
              };
              if (direction === currentDirection) proposals.push(item);
              if (isPrimaryExpiry) quickDirectionQuotes[direction] = item;
              ok += 1;
            } catch (err) {
              lastProposalError = err?.message || "Proposal error";
              if (lastProposalError.toLowerCase().includes("rate limit")) {
                rateLimitUntil = Date.now() + RATE_LIMIT_COOLDOWN_MS;
              }
              if (direction === currentDirection) {
                proposals.push({ expiry, direction, payout: null, profitPct: null, proposalId: null, askPrice: null, expiryLabel });
              }
            }
          }
        }
      }
    } else {
      const offsetVal = getBarrierOffsetValue();
      for (const expiry of proposalExpiries) {
        const nowSec = Math.floor(Date.now() / 1000);
        const durationSec = Math.max(minDurationSec, expiry - nowSec);
        if (durationSec <= 0) {
          results.push({ expiry, barrier: null, payout: null, profitPct: null, offset: null });
          continue;
        }
        if (!stake || !offsetVal) {
          results.push({ expiry, barrier: null, payout: null, profitPct: null, offset: null });
          continue;
        }
        const signedOffset = currentDirection === "CALL" ? offsetVal : -offsetVal;
        const barrier = formatOffset(signedOffset, currentPip);
        try {
          const proposal = await getBarrierProposal({
            symbol: currentSymbol,
            direction: currentDirection,
            barrier,
            fallbackBarrier: formatPrice(spot + signedOffset, currentPip),
            stake,
            durationSec,
          });
          const payout = proposal.payout;
          const askPrice = proposal.ask_price ?? proposal.buy_price ?? stake;
          const profitPct = ((payout - stake) / stake) * 100;
          results.push({
            expiry,
            barrier: spot + signedOffset,
            payout,
            profitPct,
            offset: signedOffset,
            proposalId: proposal.id,
            askPrice,
          });
          ok += 1;
        } catch (err) {
          lastProposalError = err?.message || "Proposal error";
          if (lastProposalError.toLowerCase().includes("rate limit")) {
            rateLimitUntil = Date.now() + RATE_LIMIT_COOLDOWN_MS;
          }
          results.push({ expiry, barrier: null, payout: null, profitPct: null, offset: null });
        }
      }
      proposals = results;
      const firstProposal = results[0];
      quickDirectionQuotes[currentDirection] = firstProposal && Number.isFinite(firstProposal.payout) ? {
        payout: firstProposal.payout,
        profitPct: firstProposal.profitPct,
        proposalId: firstProposal.proposalId,
        askPrice: firstProposal.askPrice,
        barrier: firstProposal.barrier,
        offset: firstProposal.offset,
        expiry: firstProposal.expiry,
      } : null;
    }
    proposalLoadingDirection = null;
    renderTradeList();
    if (proposalExpiries.length) {
      const riseFallChoice = isRiseFall ? parseRiseFallExpiryChoice(getRiseFallExpiryValue()) : null;
      const totalExpected = isRiseFall
        ? riseFallChoice?.mode === "candle_end" ? Math.min(3, proposalExpiries.length + 1) : 2
        : proposalExpiries.length;
      if (ok === 0 && lastProposalError) {
        setStatus(`Proposals: 0/${totalExpected} (${lastProposalError})`, true);
      } else {
        setStatus(`Proposals: ${ok}/${totalExpected}`);
      }
    }
  } finally {
    calcInFlight = false;
    if (proposalLoadingDirection === loadingDirectionAtStart) {
      proposalLoadingDirection = null;
    }
  }
}

async function findBarrierForTarget({ spot, stake, targetPct, durationSec }) {
  let offset = spot * 0.001;
  let lastBelow = null;
  let lastAbove = null;
  const minOffset = Math.max(currentPip || 0, 0.0001);

  for (let i = 0; i < 12; i++) {
    const signed = currentDirection === "CALL" ? offset : -offset;
    const barrier = formatOffset(signed, currentPip);
    try {
      const proposal = await getProposal({
        symbol: currentSymbol,
        contractType: currentDirection,
        barrier,
        stake,
        durationSec,
      });
      const payout = proposal.payout;
      const profitPct = ((payout - stake) / stake) * 100;
      if (profitPct >= targetPct) {
        lastAbove = { offset, payout, profitPct };
        if (lastBelow) break;
        offset = Math.max(minOffset, offset / 1.6);
      } else {
        lastBelow = { offset, payout, profitPct };
        if (lastAbove) break;
        offset *= 1.6;
      }
    } catch (err) {
      lastProposalError = err?.message || "Proposal error";
      if (!lastBelow) lastBelow = { offset, payout: 0, profitPct: 0 };
      offset *= 1.6;
    }
  }

  if (!lastAbove || !lastBelow) return null;

  let low = lastBelow.offset;
  let high = lastAbove.offset;
  let best = null;

  for (let i = 0; i < 8; i++) {
    const mid = (low + high) / 2;
    const signed = currentDirection === "CALL" ? mid : -mid;
    const barrier = formatOffset(signed, currentPip);
    try {
      const proposal = await getProposal({
        symbol: currentSymbol,
        contractType: currentDirection,
        barrier,
        stake,
        durationSec,
      });
      const payout = proposal.payout;
      const profitPct = ((payout - stake) / stake) * 100;
      if (profitPct >= targetPct) {
        best = { payout, profitPct, offset: mid };
        high = mid;
      } else {
        low = mid;
      }
    } catch (err) {
      lastProposalError = err?.message || "Proposal error";
      low = mid;
    }
  }

  return best;
}

function formatCountdown(expiry) {
  const now = Math.floor(Date.now() / 1000);
  let diff = Math.max(0, expiry - now);
  const min = Math.floor(diff / 60);
  const sec = diff % 60;
  return `${min}:${sec.toString().padStart(2, "0")}`;
}

function renderTradeList() {
  if (!tradeListEl) return;
  updateProposalDirectionButtons();
  updateTradeProfitSummary();
  const tradeMode = getActiveTradeMode();
  const isRiseFall = tradeMode === "rise_fall";
  const isProposalListMode = ["rise_fall", "touch_no_touch", "vanillas"].includes(tradeMode);

  if (!isProposalListMode && calcInFlight && proposalLoadingDirection === currentDirection && !proposals.length) {
    tradeListEl.innerHTML = `<div class="trade-meta">Loading ${getDirectionLabel(currentDirection)} proposals...</div>`;
    return;
  }

  if (tradeMode === "multipliers") {
    const quote = getQuoteForDirection(currentDirection);
    const settings = getMultiplierSettings();
    const payoutText = quote?.payout == null ? "--" : Number(quote.payout).toFixed(2);
    const tpText = settings.limitOrder?.take_profit ? `TP ${settings.limitOrder.take_profit}` : "TP off";
    const slText = settings.limitOrder?.stop_loss ? `SL ${settings.limitOrder.stop_loss}` : "SL off";
    const cancelText = settings.cancellation ? `Cancel ${settings.cancellation}` : "Cancel off";
    tradeListEl.innerHTML = `
      <div class="trade-meta">Multiplier ${settings.multiplier}x - ${tpText} - ${slText} - ${cancelText}</div>
      <div class="trade-meta">Expected payout: ${payoutText}</div>
    `;
    return;
  }

  if (!proposalExpiries.length) {
    tradeListEl.innerHTML = "<div class=\"trade-meta\">No proposals yet</div>";
    return;
  }

  const stake = parseTradeNumber(stakeInput?.value ?? sidebarStakeInputEl?.value, 0);
  const errorBanner = lastProposalError ? `<div class="trade-meta">Error: ${lastProposalError}</div>` : "";

  const expiryChoice = getTradeExpiryChoice();
  if (expiryChoice.mode === "fixed") {
    tradeListEl.innerHTML = errorBanner;
    return;
  }
  const listItems = isProposalListMode
    ? proposals
    : proposalExpiries.map((expiry, idx) => ({ ...(proposals[idx] || {}), expiry }));

  if (isProposalListMode && calcInFlight && !listItems.length) {
    tradeListEl.innerHTML = "";
    return;
  }

  tradeListEl.innerHTML = errorBanner + listItems.map((item) => {
    const itemDirection = item.direction || currentDirection;
    const itemDirectionLabel = getDirectionLabel(itemDirection);
    const itemDirClass = itemDirection === "CALL" ? "higher" : "lower";
    const countdown = item.expiry ? formatCountdown(item.expiry) : item.expiryLabel || "--";
    const fallbackBarrier = !isProposalListMode && item.barrier == null ? getHigherLowerBarrier(itemDirection) : null;
    const barrierText = item.barrier == null
      ? fallbackBarrier?.display == null ? "--" : formatPrice(fallbackBarrier.display, currentPip)
      : formatPrice(item.barrier, currentPip);
    const offsetText = item.offset == null
      ? fallbackBarrier?.offset == null ? "--" : formatOffset(fallbackBarrier.offset, currentPip)
      : formatOffset(item.offset, currentPip);
    const profit = item.payout == null || !stake ? null : item.payout - stake;
    const profitText = profit == null ? "--" : profit.toFixed(2);
    const pctText = item.profitPct == null ? "--" : item.profitPct.toFixed(1);
    const proposalId = item.proposalId ? `data-proposal=\"${item.proposalId}\"` : "";
    const priceAttr = item.askPrice != null ? `data-price=\"${item.askPrice}\"` : "";
    const directionAttr = itemDirection ? `data-direction=\"${itemDirection}\"` : "";
    const expiryText = `Expiry: ${item.expiryLabel || "Candle end"}${item.expiry ? ` (${countdown})` : ""}`;
    const metaText = isRiseFall || tradeMode === "vanillas"
      ? expiryText
      : `${expiryText} - Barrier: ${barrierText} (offset ${offsetText})`;
    const titleTimeText = item.expiry ? `ends in ${countdown}` : item.expiryLabel || "on click";
    return `
      <div class="trade-row">
        <button class="trade-btn ${itemDirClass}" data-expiry="${item.expiry || ""}" ${directionAttr} ${proposalId} ${priceAttr}>
          <div class="trade-title"><span class="trade-tag">${itemDirectionLabel}</span> - ${titleTimeText}</div>
          <div class="trade-meta">Profit: ${profitText} (${pctText}%)</div>
          <div class="trade-meta">${metaText}</div>
        </button>
        <button class="buy-btn" data-expiry="${item.expiry || ""}" ${directionAttr} ${proposalId} ${priceAttr}>Buy</button>
      </div>
    `;
  }).join("");

  if (currentAppTab === "backtest" && backtestCommittedSignal?.direction && backtestReadyTradeEl) {
    renderBacktestReadyTradeFromSharedState(backtestCommittedSignal.direction);
  }
}

function renderTradeResults() {
  if (!tradeResultsEl) return;
  if (!tradeResults.length) {
    tradeResultsEl.innerHTML = "<div class=\"trade-meta\">No trades yet</div>";
    return;
  }
  tradeResultsEl.innerHTML = tradeResults.map((item) => {
    const time = new Date(item.time).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const status = item.success ? "Success" : "Failed";
    const profitText = item.profit != null ? item.profit.toFixed(2) : "--";
    const priceText = item.price != null ? item.price.toFixed(2) : "--";
    const timeLeft = item.expiry && !item.isSold ? ` • Time left: ${formatCountdown(item.expiry)}` : "";
    return `
      <div class="trade-btn ${item.direction === "CALL" ? "higher" : "lower"}">
        <div class="trade-title">${status} • ${time}${timeLeft}</div>
        <div class="trade-meta">Market: ${escapeHtml(item.symbol || "--")}</div>
        <div class="trade-meta">Contract: ${item.contractId || "--"}</div>
        <div class="trade-meta">Price: ${priceText} • Profit: ${profitText}</div>
      </div>
    `;
  }).join("");
}

function renderAutoTradeResults() {
  if (!autoResultsEl) return;
  if (!autoTradeResults.length) {
    autoResultsEl.innerHTML = "<div class=\"trade-meta\">No auto trades yet</div>";
    return;
  }
  autoResultsEl.innerHTML = autoTradeResults.map((item) => {
    const time = new Date(item.time).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
    const status = item.success ? "Success" : "Failed";
    const profitText = item.profit != null ? item.profit.toFixed(2) : "--";
    const priceText = item.price != null ? item.price.toFixed(2) : "--";
    const timeLeft = item.expiry && !item.isSold ? ` • Time left: ${formatCountdown(item.expiry)}` : "";
    return `
      <div class="trade-btn ${item.direction === "CALL" ? "higher" : "lower"}">
        <div class="trade-title">${status} • ${time}${timeLeft}</div>
        <div class="trade-meta">Contract: ${item.contractId || "--"}</div>
        <div class="trade-meta">Price: ${priceText} • Profit: ${profitText}</div>
      </div>
    `;
  }).join("");
}

function startCountdowns() {
  if (countdownTimer) clearInterval(countdownTimer);
  countdownTimer = setInterval(() => {
    const changed = rollExpiries();
    renderTradeList();
    renderTradeResults();
    if (changed && shouldAutoQuoteProposals()) {
      scheduleProposalRefresh(true);
    }
  }, 1000);
}

function ensureOpen() {
  return new Promise((resolve, reject) => {
    connectWS();
    if (ws.readyState === WebSocket.OPEN) return resolve();
    const t = setTimeout(() => reject(new Error("WebSocket timeout")), 5000);
    ws.addEventListener("open", () => {
      clearTimeout(t);
      resolve();
    }, { once: true });
  });
}

function ensurePrivateOpen() {
  return new Promise((resolve, reject) => {
    if (!activeAuthWsUrl) {
      reject(new Error("Please log in to your Deriv account."));
      return;
    }
    connectPrivateWS();
    if (privateWs?.readyState === WebSocket.OPEN) return resolve();
    const t = setTimeout(() => reject(new Error("Account WebSocket timeout")), 8000);
    privateWs?.addEventListener("open", () => {
      clearTimeout(t);
      resolve();
    }, { once: true });
    privateWs?.addEventListener("error", () => {
      clearTimeout(t);
      reject(new Error("Account WebSocket error"));
    }, { once: true });
  });
}

